do
    local originalNotify = rawget(Library, 'Notify')
    if type(originalNotify) == 'function' and not rawget(Library, '__LH_NotifyBridge') then
        Library.__LH_NotifyBridge = true
        Library.Notify = function(self, message, ...)
            if type(message) == 'table' then
                local title = tostring(message.Title or 'Notification')
                local desc = tostring(message.Description or '')
                local text = desc ~= '' and (title .. ': ' .. desc) or title
                return originalNotify(self, text, tonumber(message.Time) or 5)
            end
            return originalNotify(self, message, ...)
        end
    end
end

do
    local unloadCallbacks = rawget(Library, '__LH_UnloadCallbacks')
    if type(unloadCallbacks) ~= 'table' then
        unloadCallbacks = {}
        Library.__LH_UnloadCallbacks = unloadCallbacks
    end

    if type(Library.OnUnload) ~= 'function' then
        local originalUnload = Library.Unload
        function Library:OnUnload(callback)
            if type(callback) ~= 'function' then return end
            table.insert(unloadCallbacks, callback)
        end
        if type(originalUnload) == 'function' and not rawget(Library, '__LH_LuaHookUnloadWrapped') then
            Library.__LH_LuaHookUnloadWrapped = true
            Library.Unload = function(self, ...)
                for i = #unloadCallbacks, 1, -1 do
                    local callback = unloadCallbacks[i]
                    unloadCallbacks[i] = nil
                    pcall(callback)
                end
                return originalUnload(self, ...)
            end
        end
    end

    if type(Library.GiveSignal) ~= 'function' then
        local signals = rawget(Library, '__LH_Signals')
        if type(signals) ~= 'table' then
            signals = {}
            Library.__LH_Signals = signals
        end
        function Library:GiveSignal(signal)
            if signal ~= nil then
                table.insert(signals, signal)
                self:OnUnload(function()
                    pcall(function()
                        if signal.Connected then signal:Disconnect() end
                    end)
                end)
            end
            return signal
        end
    end
end

local function ResolveGlobalEnv()
    local candidates = {}
    if type(getgenv) == 'function' then
        local ok, env = pcall(getgenv)
        if ok and type(env) == 'table' then
            table.insert(candidates, env)
        end
    end
    if type(getfenv) == 'function' then
        local ok, env = pcall(getfenv, 0)
        if ok and type(env) == 'table' then
            table.insert(candidates, env)
        end
    end
    for _, env in ipairs(candidates) do
        local wrote = pcall(function() env.__LH_EnvProbe = true end)
        local seen = __LH_EnvProbe == true
        pcall(function() env.__LH_EnvProbe = nil end)
        if wrote and seen then
            return env
        end
    end
    return _G
end
