local function undergroundRigStable(char)
    if not char or char.Parent ~= Workspace then return false end
    local hum = char:FindFirstChildOfClass('Humanoid')
    local root = char:FindFirstChild('HumanoidRootPart')
    local head = char:FindFirstChild('Head') or char:FindFirstChild('HitboxHead')
    local torso = char:FindFirstChild('UpperTorso') or char:FindFirstChild('Torso')
    if not hum or hum.Health <= 0 or not root or not head or not torso then return false end
    local rootJoint = char:FindFirstChild('RootJoint', true) or char:FindFirstChild('Root', true)
    if rootJoint and rootJoint:IsA('Motor6D') then
        if rootJoint.Part0 == nil or rootJoint.Part1 == nil
            or typeof(rootJoint.C0) ~= 'CFrame' or typeof(rootJoint.C1) ~= 'CFrame' then
            return false
        end
    elseif rootJoint == nil then
        local waist = char:FindFirstChild('Waist', true)
        if not waist then return false end
    end
    local neck = char:FindFirstChild('Neck', true)
    if neck and neck:IsA('Motor6D') then
        if neck.Part0 == nil or neck.Part1 == nil
            or typeof(neck.C0) ~= 'CFrame' or typeof(neck.C1) ~= 'CFrame' then
            return false
        end
    end
    return true
end

local function undergroundGetClientCFrame(root)
    if undergroundDesync and root ~= nil and undergroundDesync._rootPart == root then
        local ok, cf = pcall(function() return undergroundDesync:GetClientCFrame() end)
        if ok and typeof(cf) == 'CFrame' and typeof(cf.Position) == 'Vector3' then
            return cf
        end
    end
    local fallback = root and root.CFrame or nil
    if typeof(fallback) == 'CFrame' and typeof(fallback.Position) == 'Vector3' then
        return fallback
    end
    return nil
end

local function undergroundCharacterBounds(char)
    if not char or char.Parent == nil then
        return nil
    end
    local ok, boxCFrame, boxSize = pcall(function()
        return char:GetBoundingBox()
    end)
    if not ok or typeof(boxCFrame) ~= 'CFrame' or typeof(boxSize) ~= 'Vector3' then
        return nil
    end
    local minY = math.huge
    local maxY = -math.huge
    for x = -1, 1, 2 do
        for y = -1, 1, 2 do
            for z = -1, 1, 2 do
                local corner = boxCFrame:PointToWorldSpace(Vector3.new(
                    boxSize.X * 0.5 * x,
                    boxSize.Y * 0.5 * y,
                    boxSize.Z * 0.5 * z
                ))
                minY = math.min(minY, corner.Y)
                maxY = math.max(maxY, corner.Y)
            end
        end
    end
    if minY == math.huge or maxY == -math.huge then
        return nil
    end
    return {
        boxCFrame,
        boxSize,
        minY,
        maxY,
    }
end

