                        end
                        if enemyController.ObjectRemoved and type(enemyController.ObjectRemoved.Connect) == 'function' then
                            Connections:register('Aimbot_EnemyObjectRemoved', enemyController.ObjectRemoved:Connect(GuardLuaHookCallback('Aimbot_EnemyObjectRemoved', UnregisterAimbotEnemy)))
