                if fighterController.ObjectAdded and type(fighterController.ObjectAdded.Connect) == 'function' then
                    Connections:register('WeaponInfo_FighterObjectAdded', fighterController.ObjectAdded:Connect(GuardLuaHookCallback('WeaponInfo_FighterObjectAdded', RegisterWeaponInfoFighter)))
                end
                if fighterController.ObjectRemoved and type(fighterController.ObjectRemoved.Connect) == 'function' then
                    Connections:register('WeaponInfo_FighterObjectRemoved', fighterController.ObjectRemoved:Connect(GuardLuaHookCallback('WeaponInfo_FighterObjectRemoved', UnregisterWeaponInfoFighter)))
