            function LuaHookWeaponState.LuaHookGrenadeFusePrototype.new(inputBinding, playerContext)
                local grenadeFuse = setmetatable({
                    _inputBinding = inputBinding,
                    _playerContext = playerContext,
                    _explodeOn = 'Impact',
                    _removeFuse = false,
                    _trajectoryVisual = nil,
                    _startThrowReplacerInstalled = false,
                    _throwablePrototype = nil,
                    _originalStartThrow = nil,
                }, LuaHookWeaponState.LuaHookGrenadeFusePrototype)
                inputBinding:SetHandler(function(packet)
                    grenadeFuse:_HandleInput(packet)
                end)
                return grenadeFuse
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:SetEnabled(enabled)
                self._inputBinding:SetEnabled(enabled)
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:SetExplodeOn(explodeOn)
                self._explodeOn = explodeOn
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:SetRemoveFuse(removeFuse)
                self._removeFuse = removeFuse
                if removeFuse then
                    self:_EnsureStartThrowReplacer()
                else
                    self:_RestoreStartThrowReplacer()
                end
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:_EnsureStartThrowReplacer()
                if self._startThrowReplacerInstalled then
                    return
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local itemTypes = modules and modules:FindFirstChild('ItemTypes')
                local throwableModule = itemTypes and itemTypes:FindFirstChild('Throwable')
                if not throwableModule then
                    return
                end
                local ok, throwable = pcall(require, throwableModule)
                if not ok or type(throwable) ~= 'table' then
                    return
                end
                local original = rawget(throwable, '_StartThrow')
                if type(original) ~= 'function' then
                    return
                end
                self._throwablePrototype = throwable
                self._originalStartThrow = original
                local controller = self
                rawset(throwable, '_StartThrow', function(item, ...)
                    if controller._removeFuse then
                        rawset(item, '_cook_detonate_delay', nil)
                    end
                    return original(item, ...)
                end)
                self._startThrowReplacerInstalled = true
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:_RestoreStartThrowReplacer()
                if not self._startThrowReplacerInstalled then
                    return
                end
                if self._throwablePrototype and self._originalStartThrow then
                    rawset(self._throwablePrototype, '_StartThrow', self._originalStartThrow)
                end
                self._startThrowReplacerInstalled = false
                self._throwablePrototype = nil
                self._originalStartThrow = nil
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:_ComputeImpactTime(trajectoryVisual)
                if type(trajectoryVisual) ~= 'table' then
                    return nil
                end
                local lastArgs = rawget(trajectoryVisual, '_last_args')
                if type(lastArgs) ~= 'table' then
                    return nil
                end
                local step = tonumber(lastArgs[4]) or 0.05
                local cap = tonumber(lastArgs[6]) or math.huge
                local impactSphere = rawget(trajectoryVisual, '_impact_sphere')
                local impactCFrame = impactSphere and impactSphere.CFrame or nil
                local segments = rawget(trajectoryVisual, '_segments')
                if impactCFrame == nil or type(segments) ~= 'table' then
                    return nil
                end
                local key
                while true do
                    local segment
                    key, segment = next(segments, key)
                    if key == nil then
                        break
                    end
                    if type(segment) == 'table' and segment.CFrame == impactCFrame then
                        return math.min(cap, (key - 2) * step)
                    end
                end
                return nil
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:_HandleInput(packet)
                if type(packet) ~= 'table' or type(packet.args) ~= 'table' then
                    return
                end
                local packetType = packet.type
                local isStart = packetType == 'StartShooting' or packetType == 'StartAiming'
                local isFinish = packetType == 'FinishShooting' or packetType == 'FinishAiming'
                if not (isStart or isFinish) then
                    return
                end
                local context = self._playerContext
                local inner = context and context.inner
                local fighterState = inner and inner.fighterState
                if type(fighterState) ~= 'table' or type(fighterState.GetItemById) ~= 'function' then
                    return
                end
                local item = fighterState:GetItemById(packet.objectId)
                if item == nil then
                    return
                end
                local info = rawget(item, 'Info')
                if type(info) ~= 'table' or info.CanCook ~= true then
                    return
                end
                if isStart then
                    self._trajectoryVisual = rawget(item, '_trajectory_visual')
                    if self._removeFuse then
                        rawset(item, '_cook_detonate_delay', nil)
                    end
                    return
                end
                if self._explodeOn == 'Throw' then
                    packet.args['\3'] = 0
                else
                    local trajectoryVisual = self._trajectoryVisual
                    if trajectoryVisual then
                        trajectoryVisual = self:_ComputeImpactTime(trajectoryVisual)
                    end
                    packet.args['\3'] = trajectoryVisual
                end
                self._trajectoryVisual = nil
            end
            function LuaHookWeaponState.LuaHookGrenadeFusePrototype:Destroy()
                self:_RestoreStartThrowReplacer()
                self._inputBinding:Destroy()
            end
            LuaHookWeaponState.LuaHookLocalFighterState = {}
            LuaHookWeaponState.LuaHookLocalFighterState.__index = LuaHookWeaponState.LuaHookLocalFighterState
            function LuaHookWeaponState.LuaHookLocalFighterState.new()
                return setmetatable({}, LuaHookWeaponState.LuaHookLocalFighterState)
            end
            function LuaHookWeaponState.LuaHookLocalFighterState:GetItems()
                local fighter = ResolveLocalFighter()
                local items = type(fighter) == 'table' and rawget(fighter, 'Items') or nil
                if type(items) == 'table' then
                    return items
                end
                return {}
            end
            function LuaHookWeaponState.LuaHookLocalFighterState:GetItemById(objectId)
                for _, item in next, self:GetItems() do
                    if objectId == rawget(rawget(item, 'Data'), 'ObjectID') then
                        return item
                    end
                end
                return nil
            end
            function LuaHookWeaponState.ResolveNoSpreadClientItem()
                local state = LuaHookWeaponState
                if state.NoSpreadClientItem then
                    return state.NoSpreadClientItem
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local replicated = modules and modules:FindFirstChild('ClientReplicatedClasses')
                local fighter = replicated and replicated:FindFirstChild('ClientFighter')
                local clientItemModule = fighter and fighter:FindFirstChild('ClientItem')
                if not clientItemModule then
                    return nil
                end
                local ok, clientItem = pcall(require, clientItemModule)
                if not ok or type(clientItem) ~= 'table' then
                    return nil
                end
                state.NoSpreadClientItem = clientItem
                return clientItem
            end
            function LuaHookWeaponState.ResolveNoSpreadRemote()
                local state = LuaHookWeaponState
                if state.NoSpreadRemote then
                    return state.NoSpreadRemote
                end
                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local replication = remotes and remotes:FindFirstChild('Replication')
                local fighter = replication and replication:FindFirstChild('Fighter')
                local remote = fighter and fighter:FindFirstChild('UseItem')
                if not remote or not remote:IsA('RemoteEvent') then
                    return nil
                end
                state.NoSpreadRemote = cloneref(remote)
                return state.NoSpreadRemote
            end
            function LuaHookWeaponState.EnsureLuaHookInputHook()
                local state = LuaHookWeaponState
                if state.LuaHookInputHook and state.NoSpreadController and state.GrenadeFuseController then
                    return true
                end
                if type(setrawmetatable) ~= 'function'
                    or type(clonefunction) ~= 'function'
                    or type(debug.getupvalues) ~= 'function'
                    or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local clientItem = LuaHookWeaponState.ResolveNoSpreadClientItem()
                local remote = LuaHookWeaponState.ResolveNoSpreadRemote()
                local enumLibrary = ResolveEnumLibrary()
                local fromEnum = type(enumLibrary) == 'table' and rawget(enumLibrary, '_from_enum') or nil
                if type(clientItem) ~= 'table' or not remote or type(fromEnum) ~= 'table' then
                    return false
                end
                local playerContext = {
                    inner = {
                        fighterState = LuaHookWeaponState.LuaHookLocalFighterState.new(),
                    },
                }
                local ok, inputHookOrError = pcall(function()
                    local inputHookPrototype = state.LuaHookInputHookPrototype
                    if inputHookPrototype == nil then
                        inputHookPrototype = LuaHookWeaponState.CreateLuaHookInputHookPrototype(
                            clientItem,
                            remote,
                            function(encodedType)
                                return rawget(fromEnum, encodedType)
                            end
                        )
                        state.LuaHookInputHookPrototype = inputHookPrototype
                    end
                    local inputHook = inputHookPrototype.new()
                    state.LuaHookInputHook = inputHook
                    state.NoSpreadPlayerContext = playerContext
                    state.NoSpreadController = LuaHookWeaponState.LuaHookNoSpreadPrototype.new(
                        inputHook:Reserve(),
                        playerContext
                    )
                    state.GrenadeFuseController = LuaHookWeaponState.LuaHookGrenadeFusePrototype.new(
                        inputHook:Reserve(),
                        playerContext
                    )
                    return inputHook
                end)
                if not ok then
                    ReportLuaHookRuntimeLifecycleIssue('mods_no_spread_input_hook_initialize', inputHookOrError)
                    return false
                end
                return inputHookOrError ~= nil
            end
            function LuaHookWeaponState.SyncNoSpreadEnabled()
                local state = LuaHookWeaponState
                local controller = state.NoSpreadController
                if not controller then
                    return false
                end
                local enabled = IsRivalsModToggleEnabled('LH_P4S1T3')
                if controller._inputBinding.enabled ~= enabled then
                    controller:SetEnabled(enabled)
                end
                return true
            end
            function LuaHookWeaponState.SyncGrenadeFuse()
                local state = LuaHookWeaponState
                local controller = state.GrenadeFuseController
                if not controller then
                    return false
                end
                local enabled = IsRivalsModToggleEnabled('LH_P4S1T6')
                local explodeOn = Options and Options.LH_P4S1D1 and Options.LH_P4S1D1.Value
                controller:SetExplodeOn(type(explodeOn) == 'string' and explodeOn or 'Impact')
                controller:SetRemoveFuse(IsRivalsModToggleEnabled('LH_P4S1T7'))
                if controller._inputBinding.enabled ~= enabled then
                    controller:SetEnabled(enabled)
                end
                return true
            end
            function LuaHookWeaponState.RestoreLuaHookInputHook()
