                        gunbladeModule.StartShooting = state.OriginalGunbladeStartShooting
                    end
                end
                state.GunModule = nil
                state.MeleeModule = nil
                state.KnifeModule = nil
                state.GunbladeModule = nil
                state.OriginalGunStartShooting = nil
                state.OriginalMeleeStartShooting = nil
                state.OriginalKnifeStartAiming = nil
                state.OriginalGunbladeStartShooting = nil
