                LuaHookAimRuntime.SyncAimbotToggleKeypickerToUi = function(toggle, keypicker)
                    if not toggle or not keypicker then
                        return function() end
                    end
                    local applyingToggleState = false
                    local applyingKeypickerState = false
                    local lastMode = keypicker.Mode
                    local function syncKeypickerFromToggle(value)
                        if keypicker.Mode ~= 'Toggle' then
                            lastMode = keypicker.Mode
                            return
                        end
                        local nextState = value == true
                        if keypicker.Toggled == nextState then
                            lastMode = keypicker.Mode
                            return
                        end
                        applyingToggleState = true
                        keypicker.Toggled = nextState
                        if type(keypicker.Update) == 'function' then
                            keypicker:Update()
                        end
                        applyingToggleState = false
                        lastMode = keypicker.Mode
                    end
                    if type(toggle.OnChanged) == 'function' then
                        toggle:OnChanged(function(value)
                            if applyingKeypickerState then
                                return
                            end
                            syncKeypickerFromToggle(value)
                        end)
                    end
                    if type(keypicker.OnClick) == 'function' then
                        keypicker:OnClick(function(state)
                            if applyingToggleState or keypicker.Mode ~= 'Toggle' then
                                lastMode = keypicker.Mode
                                return
                            end
                            local nextValue = state == true
                            if toggle.Value == nextValue then
                                lastMode = keypicker.Mode
                                return
                            end
                            applyingKeypickerState = true
                            toggle:SetValue(nextValue)
                            applyingKeypickerState = false
                            lastMode = keypicker.Mode
                        end)
                    end
                    syncKeypickerFromToggle(toggle.Value)
                    return function()
                        if keypicker.Mode == 'Toggle' and lastMode ~= 'Toggle' then
                            syncKeypickerFromToggle(toggle.Value)
                        else
                            lastMode = keypicker.Mode
                        end
                    end
                end
                LuaHookAimRuntime.IsRagebotForcingCombat = function()
