                    if type(window) == 'number' and window > 0 then
                        cacheWindow = math.min(cacheWindow, window)
                    end
                end
                consider(info and info.ShootBurstCooldown)
                consider(info and info.QuickShotCooldown)
                consider(info and info.ShootCooldown)
