            function LuaHookRuntime.WorldVisuals.ApplyWorldPreset(name)
                local world = LuaHookRuntime.WorldVisuals
                local preset = world.WorldPresets[name]
                if not preset then
                    return
                end
                local wanted = preset.Toggles or {}
                for _, toggleId in ipairs(world.WorldPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] ~= true and toggle.Value then
                        toggle:SetValue(false)
                    end
                end
                for optionId, value in pairs(preset.Options or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValue) == 'function' then
                        option:SetValue(value)
                    end
                end
                for optionId, rgb in pairs(preset.Colors or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValueRGB) == 'function' then
                        option:SetValueRGB(Color3.fromRGB(rgb[1], rgb[2], rgb[3]))
                    end
                end
                for _, toggleId in ipairs(world.WorldPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] == true and not toggle.Value then
                        toggle:SetValue(true)
                    end
                end
                world.RefreshAll()
            end
            function LuaHookRuntime.WorldVisuals.RefreshSkyDropdowns()
                local world = LuaHookRuntime.WorldVisuals
                local presetOption = Options.LH_P1S12D1
                local savedOption = Options.LH_P1S12D2
                if presetOption and type(presetOption.SetValues) == 'function' then
                    pcall(function()
                        presetOption:SetValues(world.ResolveSkyPresetNames())
                    end)
                end
                if savedOption and type(savedOption.SetValues) == 'function' then
                    pcall(function()
                        savedOption:SetValues(world.ResolveCustomSkyNames())
                    end)
                end
            end
            function LuaHookRuntime.WorldVisuals.AddCustomSkybox(name, faces)
                local world = LuaHookRuntime.WorldVisuals
                world.LoadCustomSkyboxes()
                name = type(name) == 'string' and (name:match('^%s*(.-)%s*$') or '') or ''
                if name == '' or world.SkyPresets[name] ~= nil or world.CustomSkyboxes[name] ~= nil then
                    return false
                end
                local normalized = {}
                for property in pairs(world.SkyFaceInputs) do
                    normalized[property] = world.NormalizeAssetId(faces[property])
                    if not normalized[property] then
                        return false
                    end
                end
                world.CustomSkyboxes[name] = normalized
                if not world.SaveCustomSkyboxes() then
                    world.CustomSkyboxes[name] = nil
                    return false
                end
                world.RefreshSkyDropdowns()
                return true
            end
            function LuaHookRuntime.WorldVisuals.AddCustomSkyboxFromOptions()
                local world = LuaHookRuntime.WorldVisuals
                local faces = {}
                for property, optionId in pairs(world.SkyFaceInputs) do
                    faces[property] = world.ReadOption(optionId, '')
                end
                local added = world.AddCustomSkybox(world.ReadOption('LH_P1S12I7', ''), faces)
                if added then
                    local nameOption = Options.LH_P1S12I7
                    if nameOption and type(nameOption.SetValue) == 'function' then
                        nameOption:SetValue('')
                    end
                    for _, optionId in pairs(world.SkyFaceInputs) do
                        local option = Options[optionId]
                        if option and type(option.SetValue) == 'function' then
                            option:SetValue('')
                        end
                    end
                end
                return added
            end
            function LuaHookRuntime.WorldVisuals.RemoveSelectedCustomSkybox()
                local world = LuaHookRuntime.WorldVisuals
                local name = world.ReadOption('LH_P1S12D2', nil)
                if type(name) ~= 'string' or world.CustomSkyboxes[name] == nil then
                    return false
                end
                local removed = world.CustomSkyboxes[name]
                world.CustomSkyboxes[name] = nil
                if not world.SaveCustomSkyboxes() then
                    world.CustomSkyboxes[name] = removed
                    return false
                end
                world.RefreshSkyDropdowns()
                local presetOption = Options.LH_P1S12D1
                if presetOption and presetOption.Value == name and type(presetOption.SetValue) == 'function' then
                    presetOption:SetValue(nil)
                end
                local savedOption = Options.LH_P1S12D2
                if savedOption and savedOption.Value == name and type(savedOption.SetValue) == 'function' then
                    savedOption:SetValue(nil)
                end
                world.RefreshSky()
                return true
            end
            function LuaHookRuntime.WorldVisuals.RestoreSky()
                local world = LuaHookRuntime.WorldVisuals
                local owned = world.OwnedSky
                world.OwnedSky = nil
                world.ActiveSkyName = nil
                if owned then
                    pcall(function()
                        owned:Destroy()
                    end)
                end
                for sky, guard in pairs(world.NativeSkyGuards) do
                    world.DestroyGuard(guard)
                    world.NativeSkyGuards[sky] = nil
                end
            end
            function LuaHookRuntime.WorldVisuals.GuardNativeSky(sky, preset)
                local world = LuaHookRuntime.WorldVisuals
                if not sky or sky == world.OwnedSky then
                    return
                end
                local guard = world.NativeSkyGuards[sky]
                if not guard then
                    guard = world.NewGuard(sky)
                    world.NativeSkyGuards[sky] = guard
                end
                world.ReconcileGuard(guard, world.SkyProperties, preset or {})
            end
            function LuaHookRuntime.WorldVisuals.RefreshSky()
                local world = LuaHookRuntime.WorldVisuals
                local presetName = world.ReadOption('LH_P1S12D1', '')
                local preset = world.ReadToggle('LH_P1S12T1', false) and world.ResolveSkyPreset(presetName) or nil
                if not preset then
                    world.RestoreSky()
                    return
                end
                local nativeSkies = {}
                for _, child in ipairs(world.Lighting:GetChildren()) do
                    if child:IsA('Sky') and child ~= world.OwnedSky then
                        nativeSkies[#nativeSkies + 1] = child
                    end
                end
                if #nativeSkies > 0 then
                    local owned = world.OwnedSky
                    world.OwnedSky = nil
                    world.ActiveSkyName = nil
                    if owned then
                        pcall(function()
                            owned:Destroy()
                        end)
                    end
                    for _, sky in ipairs(nativeSkies) do
                        world.GuardNativeSky(sky, preset)
                    end
                    return
                end
                if not world.OwnedSky or world.OwnedSky.Parent == nil or world.ActiveSkyName ~= presetName then
                    local previous = world.OwnedSky
                    world.OwnedSky = nil
                    if previous then
                        pcall(function()
                            previous:Destroy()
                        end)
                    end
                    local sky = Instance.new('Sky')
                    sky.Name = 'LuaHookHookWorldVisuals_Sky'
                    for property, value in pairs(preset) do
                        pcall(function()
                            sky[property] = value
                        end)
                    end
                    world.OwnedSky = sky
                    world.ActiveSkyName = presetName
                    sky.Parent = world.Lighting
                end
            end
            function LuaHookRuntime.WorldVisuals.ResolveAtmosphereValues()
                local world = LuaHookRuntime.WorldVisuals
                return {
                    Color = world.ReadOption('LH_P1S13C1', Color3.new(0.7843, 0.6667, 0.4235)),
                    Decay = world.ReadOption('LH_P1S13C2', Color3.new(0.3608, 0.2353, 0.0549)),
                    Density = world.ReadOption('LH_P1S13S1', 0.395),
                    Offset = world.ReadOption('LH_P1S13S2', 0),
                    Glare = world.ReadOption('LH_P1S13S3', 0),
                    Haze = world.ReadOption('LH_P1S13S4', 0),
                }
            end
            function LuaHookRuntime.WorldVisuals.RestoreAtmosphere()
                local world = LuaHookRuntime.WorldVisuals
                local owned = world.OwnedAtmosphere
                world.OwnedAtmosphere = nil
                if owned then
                    pcall(function()
                        owned:Destroy()
                    end)
                end
                for atmosphere, guard in pairs(world.NativeAtmosphereGuards) do
                    world.DestroyGuard(guard)
                    world.NativeAtmosphereGuards[atmosphere] = nil
                end
            end
            function LuaHookRuntime.WorldVisuals.GuardNativeAtmosphere(atmosphere, desired)
                local world = LuaHookRuntime.WorldVisuals
                if not atmosphere or atmosphere == world.OwnedAtmosphere then
                    return
                end
                local guard = world.NativeAtmosphereGuards[atmosphere]
                if not guard then
                    guard = world.NewGuard(atmosphere)
                    world.NativeAtmosphereGuards[atmosphere] = guard
                end
                world.ReconcileGuard(guard, world.AtmosphereProperties, desired)
            end
            function LuaHookRuntime.WorldVisuals.RefreshAtmosphere()
                local world = LuaHookRuntime.WorldVisuals
                if not world.ReadToggle('LH_P1S13T1', false) then
                    world.RestoreAtmosphere()
                    return
                end
                local desired = world.ResolveAtmosphereValues()
                local nativeAtmospheres = {}
                for _, child in ipairs(world.Lighting:GetChildren()) do
                    if child:IsA('Atmosphere') and child ~= world.OwnedAtmosphere then
                        nativeAtmospheres[#nativeAtmospheres + 1] = child
                    end
                end
                if #nativeAtmospheres > 0 then
                    local owned = world.OwnedAtmosphere
                    world.OwnedAtmosphere = nil
                    if owned then
                        pcall(function()
                            owned:Destroy()
                        end)
                    end
                    for _, atmosphere in ipairs(nativeAtmospheres) do
                        world.GuardNativeAtmosphere(atmosphere, desired)
                    end
                    return
                end
                local atmosphere = world.OwnedAtmosphere
                if not atmosphere or atmosphere.Parent == nil then
                    atmosphere = Instance.new('Atmosphere')
                    atmosphere.Name = 'LuaHookHookWorldVisuals_Atmosphere'
                    world.OwnedAtmosphere = atmosphere
                    atmosphere.Parent = world.Lighting
                end
                for property, value in pairs(desired) do
                    atmosphere[property] = value
                end
            end
            function LuaHookRuntime.WorldVisuals.OnLightingDescendantAdded(descendant)
                local world = LuaHookRuntime.WorldVisuals
                local className = descendant.ClassName
                local definition = world.PostEffects[className]
                if definition and world.ReadToggle(definition.Toggle, false) then
                    world.GuardNativeEffect(className, descendant)
                elseif descendant:IsA('Sky') and world.ReadToggle('LH_P1S12T1', false) then
                    world.RefreshSky()
                elseif descendant:IsA('Atmosphere') and world.ReadToggle('LH_P1S13T1', false) then
                    world.RefreshAtmosphere()
                end
            end
            function LuaHookRuntime.WorldVisuals.OnLightingDescendantRemoving(descendant)
                local world = LuaHookRuntime.WorldVisuals
                local shouldRefresh = false
                local effectGuards = world.NativeEffectGuards[descendant.ClassName]
                local effectGuard = effectGuards and effectGuards[descendant]
                if effectGuard then
                    world.DestroyGuard(effectGuard)
                    effectGuards[descendant] = nil
                end
                local skyGuard = world.NativeSkyGuards[descendant]
                if skyGuard then
                    world.DestroyGuard(skyGuard)
                    world.NativeSkyGuards[descendant] = nil
                    shouldRefresh = true
                end
                local atmosphereGuard = world.NativeAtmosphereGuards[descendant]
                if atmosphereGuard then
                    world.DestroyGuard(atmosphereGuard)
                    world.NativeAtmosphereGuards[descendant] = nil
                    shouldRefresh = true
                end
                for className, owned in pairs(world.OwnedEffects) do
                    if descendant == owned then
                        world.OwnedEffects[className] = nil
                        shouldRefresh = true
                    end
                end
                if descendant == world.OwnedSky then
                    world.OwnedSky = nil
                    shouldRefresh = true
                elseif descendant == world.OwnedAtmosphere then
                    world.OwnedAtmosphere = nil
                    shouldRefresh = true
                end
                if shouldRefresh and world.Initialized then
                    task.defer(function()
                        if world.Initialized then
                            world.RefreshAll()
                        end
                    end)
                end
            end
            function LuaHookRuntime.WorldVisuals.EnsureInitialized()
                local world = LuaHookRuntime.WorldVisuals
                if world.Initialized then
                    return
                end
                world.Initialized = true
                world.LoadCustomSkyboxes()
                world.LightingGuard = world.NewGuard(world.Lighting)
                world.Connections.DescendantAdded = world.Lighting.DescendantAdded:Connect(world.OnLightingDescendantAdded)
                world.Connections.DescendantRemoving = world.Lighting.DescendantRemoving:Connect(world.OnLightingDescendantRemoving)
                local preRenderSignal = RunService.PreRender or RunService.RenderStepped
                world.Connections.PreRender = preRenderSignal:Connect(world.UpdateFrame)
            end
            function LuaHookRuntime.WorldVisuals.RefreshAll()
                local world = LuaHookRuntime.WorldVisuals
                world.EnsureInitialized()
                world.RefreshLighting()
                for className in pairs(world.PostEffects) do
                    world.RefreshPostEffect(className)
                end
                world.RefreshAmbience()
                world.RefreshWeather()
                world.RefreshStretchedResolution()
                world.RefreshSky()
                world.RefreshAtmosphere()
            end
            function LuaHookRuntime.WorldVisuals.Destroy()
                local world = LuaHookRuntime.WorldVisuals
                if not world.Initialized then
                    return
                end
                world.Initialized = false
                for _, connection in pairs(world.Connections) do
                    connection:Disconnect()
                end
                world.Connections = {}
                world.DestroyGuard(world.LightingGuard)
                world.LightingGuard = nil
                for className in pairs(world.PostEffects) do
                    world.RestorePostEffect(className)
                end
                local ambience = world.OwnedAmbience
                world.OwnedAmbience = nil
                world.ActiveAmbienceSource = nil
                if ambience then
                    pcall(function()
                        ambience:Destroy()
                    end)
                end
                world.DestroyWeather()
                world.RestoreStretchedResolution()
                world.RestoreSky()
                world.RestoreAtmosphere()
            end
            LuaHookRuntime.ViewmodelVisuals = {
                AppearanceSnapshots = setmetatable({}, { __mode = 'k' }),
                TextureSnapshots = {},
                Highlights = {},
                Crosshair = nil,
                LastReconcileAt = 0,
                FollowPosition = nil,
                MaterialMap = {
                    Ghost = Enum.Material.ForceField,
                    Flat = Enum.Material.Neon,
                    Foil = Enum.Material.Foil,
                    Custom = Enum.Material.SmoothPlastic,
                    Reflective = Enum.Material.Glass,
                },
                MaterialNames = {'Original', 'Ghost', 'Flat', 'Foil', 'Custom', 'Reflective'},
                FontMap = {
                    Inconsolata = Enum.Font.Code,
                    Gotham = Enum.Font.Gotham,
                    ['Source Sans'] = Enum.Font.SourceSans,
                    ['Roboto Mono'] = Enum.Font.RobotoMono,
                },
            }
            function LuaHookRuntime.ViewmodelVisuals.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end
            function LuaHookRuntime.ViewmodelVisuals.ReadOption(optionId, fallback)
                local option = Options and Options[optionId]
                if option == nil or option.Value == nil then
                    return fallback
                end
                return option.Value
            end
            function LuaHookRuntime.ViewmodelVisuals.AppendUniqueRoot(roots, seen, root)
                if typeof(root) ~= 'Instance' or root.Parent == nil or seen[root] then
                    return
                end
                seen[root] = true
                roots[#roots + 1] = root
            end
            function LuaHookRuntime.ViewmodelVisuals.ResolveScopes()
                local visuals = LuaHookRuntime.ViewmodelVisuals
                local scopes = { Character = {}, Arms = {}, Item = {} }
                local seen = { Character = {}, Arms = {}, Item = {} }
                visuals.AppendUniqueRoot(scopes.Character, seen.Character, LP.Character)
                local fighter = ResolveLocalFighter()
                local equippedItem = fighter and fighter.EquippedItem or nil
                local clientViewModel = type(equippedItem) == 'table'
                    and (rawget(equippedItem, '_ViewModel') or rawget(equippedItem, 'ViewModel')) or nil
                if type(clientViewModel) == 'table' then
                    visuals.AppendUniqueRoot(scopes.Item, seen.Item, rawget(clientViewModel, 'ItemModel'))
                    visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, rawget(clientViewModel, '_left_arm'))
                    visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, rawget(clientViewModel, '_right_arm'))
                end
                local viewModels = Workspace:FindFirstChild('ViewModels')
                local firstPerson = viewModels and viewModels:FindFirstChild('FirstPerson') or nil
                for _, model in ipairs(firstPerson and firstPerson:GetChildren() or {}) do
                    if model:IsA('Model') then
                        visuals.AppendUniqueRoot(scopes.Item, seen.Item, model:FindFirstChild('ItemVisual'))
                        visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, model:FindFirstChild('LeftArm'))
                        visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, model:FindFirstChild('RightArm'))
                    end
                end
                return scopes
            end
            function LuaHookRuntime.ViewmodelVisuals.CaptureAppearance(part)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                local snapshot = visuals.AppearanceSnapshots[part]
                if snapshot then
                    return snapshot
                end
                snapshot = {
                    Material = part.Material,
                    Color = part.Color,
                    Transparency = part.Transparency,
                    Reflectance = part.Reflectance,
                }
                visuals.AppearanceSnapshots[part] = snapshot
                return snapshot
            end
            function LuaHookRuntime.ViewmodelVisuals.RestoreAppearance(part, snapshot)
                if not part or part.Parent == nil or type(snapshot) ~= 'table' then
                    return
                end
                pcall(function()
                    part.Material = snapshot.Material
                    part.Color = snapshot.Color
                    part.Transparency = snapshot.Transparency
                    part.Reflectance = snapshot.Reflectance
                end)
            end
            function LuaHookRuntime.ViewmodelVisuals.CaptureTexture(instance, property, root)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                local snapshot = visuals.TextureSnapshots[instance]
                if snapshot then
                    return snapshot
                end
                snapshot = { Property = property, Root = root }
                if property == 'Parent' then
                    snapshot.Value = instance.Parent
                else
                    snapshot.Value = instance[property]
                end
                visuals.TextureSnapshots[instance] = snapshot
                return snapshot
            end
            function LuaHookRuntime.ViewmodelVisuals.StripTextures(root, activeTextures)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    if snapshot.Root == root and snapshot.Property == 'Parent' and instance.Parent == nil then
                        activeTextures[instance] = true
                    end
                end
                local descendants = root:GetDescendants()
                if root:IsA('BasePart') then
                    table.insert(descendants, root)
                end
                for _, descendant in ipairs(descendants) do
                    local property = nil
                    local replacement = nil
                    if descendant:IsA('MeshPart') then
                        property = 'TextureID'
                        replacement = ''
                    elseif descendant:IsA('SpecialMesh') then
                        property = 'TextureId'
                        replacement = ''
                    elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                        property = 'Transparency'
                        replacement = 1
                    elseif descendant:IsA('SurfaceAppearance')
                        or descendant:IsA('Clothing') or descendant:IsA('ShirtGraphic') then
                        property = 'Parent'
                    end
                    if property then
                        visuals.CaptureTexture(descendant, property, root)
                        activeTextures[descendant] = true
                        pcall(function()
                            if property == 'Parent' then
                                descendant.Parent = nil
                            else
                                descendant[property] = replacement
                            end
                        end)
                    end
                end
            end
            function LuaHookRuntime.ViewmodelVisuals.RestoreTexture(instance, snapshot)
                if not instance or type(snapshot) ~= 'table' then
                    return
                end
                pcall(function()
                    instance[snapshot.Property] = snapshot.Value
                end)
            end
            function LuaHookRuntime.ViewmodelVisuals.ApplyChamScope(roots, optionPrefix, activeParts, activeTextures)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                if not visuals.ReadToggle(optionPrefix .. 'T1') then
                    return
                end
                local materialName = visuals.ReadOption(optionPrefix .. 'D1', 'Ghost')
                local material = visuals.MaterialMap[materialName]
                local color = visuals.ReadOption(optionPrefix .. 'C1', Color3.new(1, 1, 1))
                local transparency = math.clamp(visuals.ReadOption(optionPrefix .. 'S1', 0), 0, 1)
                local stripTextures = visuals.ReadToggle(optionPrefix .. 'T2')
                for _, root in ipairs(roots) do
                    local descendants = root:GetDescendants()
                    if root:IsA('BasePart') then
                        table.insert(descendants, root)
                    end
                    for _, descendant in ipairs(descendants) do
                        if descendant:IsA('BasePart') then
                            local snapshot = visuals.CaptureAppearance(descendant)
                            activeParts[descendant] = true
                            pcall(function()
                                descendant.Material = material or snapshot.Material
                                descendant.Color = color
                                descendant.Transparency = snapshot.Transparency < 1 and transparency or snapshot.Transparency
                            end)
                        end
                    end
                    if stripTextures then
                        visuals.StripTextures(root, activeTextures)
                    end
                end
            end
            function LuaHookRuntime.ViewmodelVisuals.ReconcileHighlights(scopeName, roots, optionPrefix)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                local entries = visuals.Highlights[scopeName] or {}
                visuals.Highlights[scopeName] = entries
                local active = {}
                if visuals.ReadToggle(optionPrefix .. 'T1') then
                    local fillColor = visuals.ReadOption(optionPrefix .. 'C1', Color3.new(1, 1, 1))
                    local fillTransparency = math.clamp(visuals.ReadOption(optionPrefix .. 'S1', 0.5), 0, 1)
                    local outlineColor = visuals.ReadOption(optionPrefix .. 'C2', Color3.new(1, 1, 1))
                    local outlineTransparency = math.clamp(visuals.ReadOption(optionPrefix .. 'S2', 0), 0, 1)
                    for _, root in ipairs(roots) do
                        active[root] = true
                        local highlight = entries[root]
                        if not highlight or highlight.Parent == nil then
                            highlight = Instance.new('Highlight')
                            highlight.Name = 'LuaHookHookViewmodelHighlight_' .. scopeName
                            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                            highlight.Adornee = root
                            highlight.Parent = root
                            entries[root] = highlight
                        end
                        highlight.FillColor = fillColor
                        highlight.FillTransparency = fillTransparency
                        highlight.OutlineColor = outlineColor
                        highlight.OutlineTransparency = outlineTransparency
                    end
                end
                for root, highlight in pairs(entries) do
                    if not active[root] then
                        pcall(function() highlight:Destroy() end)
                        entries[root] = nil
                    end
                end
            end
            function LuaHookRuntime.ViewmodelVisuals.ReconcileModels()
                local visuals = LuaHookRuntime.ViewmodelVisuals
                local scopes = visuals.ResolveScopes()
                local activeParts = {}
                local activeTextures = {}
                visuals.ApplyChamScope(scopes.Character, 'P1S19', activeParts, activeTextures)
                visuals.ApplyChamScope(scopes.Arms, 'P1S20', activeParts, activeTextures)
                visuals.ApplyChamScope(scopes.Item, 'P1S21', activeParts, activeTextures)
                for part, snapshot in pairs(visuals.AppearanceSnapshots) do
                    if not activeParts[part] then
                        visuals.RestoreAppearance(part, snapshot)
                        visuals.AppearanceSnapshots[part] = nil
                    end
                end
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    if not activeTextures[instance] then
                        visuals.RestoreTexture(instance, snapshot)
                        visuals.TextureSnapshots[instance] = nil
                    end
                end
                visuals.ReconcileHighlights('Arms', scopes.Arms, 'P1S22')
                visuals.ReconcileHighlights('Item', scopes.Item, 'P1S23')
            end
            function LuaHookRuntime.ViewmodelVisuals.ShimmerColorAt(elapsed, fraction, baseColor, fadeColor)
                local offset = ((1 - math.abs((elapsed * 0.5) % 2 - 1)) * 2 - 1) * 0.5
                local alpha = math.clamp(fraction - offset, 0, 1)
                if alpha <= 0.5 then
                    return fadeColor:Lerp(baseColor, alpha * 2)
                end
                return baseColor:Lerp(fadeColor, (alpha - 0.5) * 2)
            end
            function LuaHookRuntime.ViewmodelVisuals.PerimeterColorAt(elapsed, fraction, firstColor, secondColor)
                local alpha = ((elapsed * 0.5) + fraction) % 1
                return firstColor:Lerp(secondColor, alpha)
            end
            function LuaHookRuntime.ViewmodelVisuals.PingPongColorAt(elapsed, fraction, backgroundColor, mainColor, rotation)
                local wave = math.sin(elapsed * math.pi) + 1
                local rotationOffset = rotation / 90
                local firstBand = (wave + rotationOffset) % 4
                local secondBand = (4 - wave + rotationOffset) % 4
                local position = (fraction * 4) % 4
                local firstDistance = math.abs(position - firstBand) % 4
                firstDistance = math.min(firstDistance, 4 - firstDistance)
                local secondDistance = math.abs(position - secondBand) % 4
                secondDistance = math.min(secondDistance, 4 - secondDistance)
                local influence = math.max(
                    1 - firstDistance / 0.4,
                    1 - secondDistance / 0.4,
                    0
                )
                return backgroundColor:Lerp(mainColor, math.clamp(influence, 0, 1))
            end
            function LuaHookRuntime.ViewmodelVisuals.ResolveLineColor(baseColor, fraction, elapsed)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                if not visuals.ReadToggle('LH_P1S26T10') then
                    return baseColor
                end
                local speed = visuals.ReadOption('LH_P1S26S12', 1)
                local animationTime = elapsed * speed
                local kind = visuals.ReadOption('LH_P1S26D3', 'Shimmer')
                if kind == 'Perimeter' then
                    return visuals.PerimeterColorAt(
                        animationTime, fraction,
                        visuals.ReadOption('LH_P1S26C7', Color3.fromRGB(255, 0, 0)),
                        visuals.ReadOption('LH_P1S26C8', Color3.fromRGB(0, 0, 255))
                    )
                elseif kind == 'PingPong' then
                    return visuals.PingPongColorAt(
                        animationTime, fraction,
                        visuals.ReadOption('LH_P1S26C9', Color3.new(0, 0, 0)),
                        visuals.ReadOption('LH_P1S26C10', Color3.new(1, 1, 1)),
                        visuals.ReadOption('LH_P1S26S13', 0)
                    )
                end
                return visuals.ShimmerColorAt(
                    animationTime, fraction, baseColor,
                    visuals.ReadOption('LH_P1S26C6', Color3.fromRGB(40, 40, 40))
                )
            end
            function LuaHookRuntime.ViewmodelVisuals.ResolveTextGradient(elapsed, baseColor)
                local visuals = LuaHookRuntime.ViewmodelVisuals
                if not visuals.ReadToggle('LH_P1S26T13') then
                    return ColorSequence.new(baseColor), Vector2.zero, 0
                end
                local speed = visuals.ReadOption('LH_P1S26S17', 1)
                local animationTime = elapsed * speed
                if visuals.ReadOption('LH_P1S26D5', 'Shimmer') == 'PingPong' then
                    local colors = {}
                    for index = 0, 8 do
                        local fraction = index / 8
                        colors[#colors + 1] = ColorSequenceKeypoint.new(
                            fraction,
                            visuals.PingPongColorAt(
                                animationTime, fraction,
                                visuals.ReadOption('LH_P1S26C14', Color3.new(0, 0, 0)),
                                visuals.ReadOption('LH_P1S26C15', Color3.new(1, 1, 1)),
                                visuals.ReadOption('LH_P1S26S18', 0)
                            )
                        )
                    end
                    return ColorSequence.new(colors), Vector2.zero, visuals.ReadOption('LH_P1S26S18', 0)
                end
                local fadeColor = visuals.ReadOption('LH_P1S26C13', Color3.fromRGB(40, 40, 40))
                return ColorSequence.new({
                    ColorSequenceKeypoint.new(0, fadeColor),
                    ColorSequenceKeypoint.new(0.5, baseColor),
                    ColorSequenceKeypoint.new(1, fadeColor),
                }), Vector2.new(((1 - math.abs((animationTime * 0.5) % 2 - 1)) * 2 - 1) * 0.5, 0), 45
            end
            function LuaHookRuntime.ViewmodelVisuals.CreateCrosshairArm(parent, name)
                local outline = Instance.new('Frame')
                outline.Name = name .. 'Outline'
                outline.AnchorPoint = Vector2.new(0.5, 0.5)
                outline.BorderSizePixel = 0
                outline.Parent = parent
                local fill = Instance.new('Frame')
                fill.Name = name
