            function LuaHookRuntime.NativeRemovals.ApplyCrosshairFrames()
                local crosshair = LuaHookRuntime.NativeRemovals.Crosshair
                LuaHookRuntime.NativeRemovals.EachItemCrosshair(function(object)
                    local frame = rawget(object, 'Frame')
                    if typeof(frame) ~= 'Instance' then
