            LuaHookRuntime.ReplicateHook = {
                BindingsByEnum = {},
                Restore = nil,
            }
            function LuaHookRuntime.ReplicateHook.ResolveController()
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local module = modules and modules:FindFirstChild('ReplicatedController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                return controller
            end
            function LuaHookRuntime.ReplicateHook.Reserve(enumNames)
                local hook = LuaHookRuntime.ReplicateHook
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.ToEnum) ~= 'function' then
                    return nil
                end
                local tokens = {}
                for _, enumName in ipairs(enumNames) do
                    local ok, token = pcall(enumLibrary.ToEnum, enumLibrary, enumName)
                    if not ok or type(token) ~= 'string' then
                        return nil
                    end
                    tokens[#tokens + 1] = token
                end
                local binding = { enabled = false, handler = nil, tokens = tokens }
                function binding:SetHandler(handler)
                    self.handler = handler
                end
                function binding:SetEnabled(enabled)
                    self.enabled = enabled and true or false
                    if self.enabled then
                        LuaHookRuntime.ReplicateHook.Load()
                    end
                end
                function binding:Destroy()
                    self.handler = nil
                    self.enabled = false
                    for _, token in ipairs(self.tokens) do
                        local list = hook.BindingsByEnum[token]
                        if list then
                            for index = #list, 1, -1 do
                                if list[index] == self then
                                    table.remove(list, index)
                                end
                            end
                            if #list == 0 then
                                hook.BindingsByEnum[token] = nil
                            end
                        end
                    end
                end
                for _, token in ipairs(tokens) do
                    local list = hook.BindingsByEnum[token]
                    if not list then
                        list = {}
                        hook.BindingsByEnum[token] = list
                    end
                    table.insert(list, binding)
                end
                return binding
            end
            function LuaHookRuntime.ReplicateHook.Load()
                local hook = LuaHookRuntime.ReplicateHook
                if hook.Restore ~= nil then
                    return true
                end
                local controller = hook.ResolveController()
                local original = controller and rawget(controller, '_ObjectChanged') or nil
                if type(original) ~= 'function' then
                    return false
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return false
                end
                local bindingsByEnum = hook.BindingsByEnum
                local wrapped = function(...)
                    local packed = table.pack(...)
                    local offset = (type(packed[1]) == 'table') and 1 or 0
                    local objectId = packed[offset + 1]
                    local token = packed[offset + 2]
                    local bindings = type(token) == 'string' and bindingsByEnum[token] or nil
                    if bindings == nil or type(objectId) ~= 'string' then
                        return (coroutine.wrap(original)(...))
                    end
                    local args = { n = math.max(packed.n - offset - 2, 0) }
                    for index = 1, args.n do
                        args[index] = packed[offset + 2 + index]
                    end
                    local decoded
                    local decodeOk, decodeValue = pcall(enumLibrary.FromEnum, enumLibrary, token)
                    if decodeOk then
                        decoded = decodeValue
                    end
                    local packet = {
                        block = false,
                        objectId = objectId,
                        enumName = decoded,
                        args = args,
                    }
                    local identity
                    if type(getthreadidentity) == 'function' then
                        identity = getthreadidentity()
                    end
                    if type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, 8)
                    end
                    for _, binding in ipairs(bindings) do
                        if binding.enabled and binding.handler then
                            pcall(binding.handler, packet)
                            if packet.block then
                                break
                            end
                        end
                    end
                    if identity ~= nil and type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, identity)
                    end
                    if packet.block then
                        return
                    end
                    return (coroutine.wrap(original)(...))
                end
                rawset(controller, '_ObjectChanged', wrapped)
                hook.Restore = { controller = controller, original = original }
                return true
            end
            function LuaHookRuntime.ReplicateHook.Revert()
                local hook = LuaHookRuntime.ReplicateHook
                local restore = hook.Restore
                if not restore then
                    return
                end
                hook.Restore = nil
                rawset(restore.controller, '_ObjectChanged', restore.original)
            end
            function LuaHookRuntime.ReplicateHook.RevertIfIdle()
                local hook = LuaHookRuntime.ReplicateHook
                if hook.Restore == nil then
                    return
                end
                for _, list in pairs(hook.BindingsByEnum) do
                    for _, binding in ipairs(list) do
                        if binding.enabled then
                            return
                        end
                    end
                end
                hook.Revert()
            end
            function LuaHookRuntime.ReplicateHook.Destroy()
                local hook = LuaHookRuntime.ReplicateHook
                hook.Revert()
                hook.BindingsByEnum = {}
            end
            function LuaHookRuntime.ReplicateHook.DecodeArg(value)
                if type(value) ~= 'string' then
                    return nil
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return nil
                end
                local ok, name = pcall(enumLibrary.FromEnum, enumLibrary, value)
                if not ok or type(name) ~= 'string' then
                    return nil
                end
                return name
            end

            -- LuaHook-native Auto Respawn. This keeps the feature on LuaHook's
            -- replication-hook/runtime instead of depending on the removed legacy Ragebot.
            LuaHookRuntime.AutoRespawn = {
                Binding = nil,
                LastRequestAt = 0,
                RequestInterval = 1,
                BurstCount = 5,
                BurstDelay = 0.1,
            }
            function LuaHookRuntime.RegisterAutoRespawnSignals()
                local state = LuaHookRuntime.AutoRespawn
                local enabled = Toggles and Toggles.AutoRespawn and Toggles.AutoRespawn.Value == true
                local hook = LuaHookRuntime.ReplicateHook
                if not state.Binding then
                    local binding = hook.Reserve({ 'RespawnNowAnimation' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if packet.enumName ~= 'RespawnNowAnimation' then return end
                            if packet.args[1] ~= LP then return end
                            if not (Toggles and Toggles.AutoRespawn and Toggles.AutoRespawn.Value == true) then return end
                            task.defer(GuardLuaHookCallback('AutoRespawn_Request', function()
                                local now = tick()
                                if now - state.LastRequestAt < state.RequestInterval then return end
                                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                                local duels = remotes and remotes:FindFirstChild('Duels')
                                local remote = duels and duels:FindFirstChild('RespawnNow')
                                if not remote or not remote:IsA('RemoteEvent') then return end
                                state.LastRequestAt = now
                                task.spawn(GuardLuaHookCallback('AutoRespawn_Burst', function()
                                    for index = 1, state.BurstCount do
                                        safe_fire_server(remote)
                                        if index < state.BurstCount then task.wait(state.BurstDelay) end
                                    end
                                end))
                            end))
                        end)
                        state.Binding = binding
                    end
                end
                if state.Binding then
                    state.Binding:SetEnabled(enabled)
                end
                hook.RevertIfIdle()
            end
            function LuaHookRuntime.ResetAutoRespawnState()
                local state = LuaHookRuntime.AutoRespawn
                if state.Binding then
                    pcall(state.Binding.Destroy, state.Binding)
                    state.Binding = nil
                end
                state.LastRequestAt = 0
                LuaHookRuntime.ReplicateHook.RevertIfIdle()
            end

            LuaHookRuntime.ReplicationRemovals = {
                Flashbang = nil,
                Burn = nil,
            }
            function LuaHookRuntime.ReplicationRemovals.EnsureBindings()
                local removals = LuaHookRuntime.ReplicationRemovals
                local hook = LuaHookRuntime.ReplicateHook
                if not removals.Flashbang then
                    local binding = hook.Reserve({ 'ItemChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[2]) == 'BlindEffect' then
                                packet.block = true
                            end
                        end)
                        removals.Flashbang = binding
                    end
                end
                if not removals.Burn then
                    local binding = hook.Reserve({ 'EntityChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[1]) ~= 'BurnEffect' then
                                return
                            end
                            local fighter = ResolveLocalFighter()
                            if not fighter then
                                return
                            end
                            local entity = rawget(fighter, 'Entity')
                            local objectId = type(entity) == 'table' and rawget(entity, 'ObjectID') or nil
                            objectId = objectId
                                or LuaHookRuntime.CombatFeedback.ResolveFighterObjectId(fighter)
                            if objectId == nil or objectId ~= packet.objectId then
                                return
                            end
                            packet.block = true
                        end)
                        removals.Burn = binding
                    end
                end
            end
            function LuaHookRuntime.ReplicationRemovals.RefreshAll()
                local removals = LuaHookRuntime.ReplicationRemovals
                local native = LuaHookRuntime.NativeRemovals
                local wantFlash = native.ReadToggle('LH_P1S27T1')
                local wantBurn = native.ReadToggle('LH_P1S27T2')
                if wantFlash or wantBurn then
                    removals.EnsureBindings()
                end
                if removals.Flashbang then
                    removals.Flashbang:SetEnabled(wantFlash)
                end
                if removals.Burn then
                    removals.Burn:SetEnabled(wantBurn)
                end
                LuaHookRuntime.ReplicateHook.RevertIfIdle()
            end
            function LuaHookRuntime.ReplicationRemovals.Destroy()
