            function LuaHookRuntime.Movement.ReplaceJumpPowerConstants(target)
                local movement = LuaHookRuntime.Movement
                for index, value in pairs(debug.getupvalues(target)) do
                    if type(value) == 'table' then
                        local metatable = getmetatable(value)
                        local metaIndex = type(metatable) == 'table'
                            and rawget(metatable, '__index') or nil
                        local original = nil
                        if type(metaIndex) == 'function' then
                            local ok, wrapped = pcall(function()
                                return value['meow\0d67']
                            end)
                            original = ok and wrapped or nil
                        elseif rawget(value, 'BASE_JUMPPOWER') ~= nil then
                            original = value
                        end
                        if original ~= nil then
                            local upvalueIndex = index
                            debug.setupvalue(target, upvalueIndex, setmetatable({}, {
                                __index = function(_, key)
                                    if key == 'meow\0d67' then
                                        return original
                                    end
                                    if movement.JumpPowerHookDestroyed then
                                        debug.setupvalue(target, upvalueIndex, original)
                                        return rawget(original, key)
                                    end
                                    if key ~= 'BASE_JUMPPOWER' then
                                        return rawget(original, key)
                                    end
                                    return rawget(original, 'BASE_JUMPPOWER')
                                        * (movement.JumpPowerEnabled and movement.JumpPowerMultiplier or 1)
                                end,
                            }))
                            break
                        end
                    end
                end
            end
            function LuaHookRuntime.Movement.AttemptLoadJumpPowerHook()
                local movement = LuaHookRuntime.Movement
                if movement.JumpPowerHookLoaded then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function'
                    or type(debug.getconstants) ~= 'function' or type(debug.getprotos) ~= 'function'
                    or type(debug.getproto) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local hookFighter = type(classIndex) == 'table' and rawget(classIndex, '_HookFighter') or nil
                if type(hookFighter) ~= 'function' then
                    return false
                end
                local localFighter = rawget(mechanics, 'LocalFighter')
                if localFighter == nil then
                    return false
                end
                movement.ReplaceJumpPowerConstants(hookFighter)
                local entityAdded = rawget(localFighter, 'EntityAdded')
                local handler = type(entityAdded) == 'table' and rawget(entityAdded, '_handlerListHead') or nil
                local entityCallback = nil
                while type(handler) == 'table' and entityCallback == nil do
                    local fn = rawget(handler, '_fn')
                    if type(fn) == 'function' then
                        for _, constant in pairs(debug.getconstants(fn)) do
                            if constant == 'CustomGravity' then
                                entityCallback = fn
                                break
                            end
                        end
                    end
                    handler = rawget(handler, '_next')
                end
                if entityCallback == nil then
                    LP:Kick('JumpPower error: ent')
                    return false
                end
                movement.ReplaceJumpPowerConstants(entityCallback)
                for protoIndex in pairs(debug.getprotos(entityCallback)) do
                    local activated = debug.getproto(entityCallback, protoIndex, true)
                    local instance = type(activated) == 'table' and activated[1] or nil
                    if instance ~= nil then
                        movement.ReplaceJumpPowerConstants(instance)
                    end
                end
                movement.JumpPowerHookDestroyed = false
                movement.JumpPowerHookLoaded = true
                return true
            end
            function LuaHookRuntime.Movement.ClearNoclipCharacter()
                local movement = LuaHookRuntime.Movement
                if movement.NoclipConnections then
                    for _, connection in ipairs(movement.NoclipConnections) do
                        connection:Disconnect()
                    end
                end
                movement.NoclipConnections = nil
                movement.NoclipCharacter = nil
                table.clear(movement.CollidableParts)
            end
            function LuaHookRuntime.Movement.BindNoclipCharacter(character)
                local movement = LuaHookRuntime.Movement
                movement.ClearNoclipCharacter()
                movement.NoclipCharacter = character
                for _, descendant in ipairs(character:GetDescendants()) do
                    if descendant:IsA('BasePart') and descendant.CanCollide then
                        movement.CollidableParts[descendant] = true
                    end
                end
                movement.NoclipConnections = {
                    character.DescendantAdded:Connect(function(descendant)
                        if descendant:IsA('BasePart') and descendant.CanCollide then
                            movement.CollidableParts[descendant] = true
                        end
                    end),
                    character.DescendantRemoving:Connect(function(descendant)
                        if descendant:IsA('BasePart') then
                            movement.CollidableParts[descendant] = nil
                        end
                    end),
                }
            end
            function LuaHookRuntime.Movement.SetNoclipEnabled(enabled)
                local movement = LuaHookRuntime.Movement
                if movement.NoclipEnabled and not enabled then
                    for part in pairs(movement.CollidableParts) do
                        part.CanCollide = true
                    end
                end
                movement.NoclipEnabled = enabled == true
            end
            function LuaHookRuntime.Movement.DestroyFlight()
                local movement = LuaHookRuntime.Movement
                local flight = movement.Flight
                movement.Flight = nil
                if flight then
                    pcall(function() flight.Velocity:Destroy() end)
                    pcall(function() flight.Attachment:Destroy() end)
                end
            end
            function LuaHookRuntime.Movement.ResolveCharacter()
                local movement = LuaHookRuntime.Movement
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                local rootPart = character and character:FindFirstChild('HumanoidRootPart') or nil
                if character ~= movement.Character or humanoid ~= movement.Humanoid or rootPart ~= movement.RootPart then
                    movement.ClearNoclipCharacter()
                    movement.DestroyFlight()
                    movement.Character = character
                    movement.Humanoid = humanoid
                    movement.RootPart = rootPart
                    movement.LongJumpPressed = false
                end
                return character, humanoid, rootPart
            end
            function LuaHookRuntime.Movement.ResolveControlsMoveVector()
                local movement = LuaHookRuntime.Movement
                if movement.PlayerModule == nil then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local moduleScript = playerScripts and playerScripts:FindFirstChild('PlayerModule')
                    if moduleScript then
                        local ok, playerModule = pcall(require, moduleScript)
                        if ok and type(playerModule) == 'table'
                            and type(playerModule.GetControls) == 'function' then
                            movement.PlayerModule = playerModule
                        end
                    end
                end
                local playerModule = movement.PlayerModule
                if playerModule then
                    local ok, moveVector = pcall(function()
                        return playerModule:GetControls():GetMoveVector()
                    end)
                    if ok and typeof(moveVector) == 'Vector3' then
                        return moveVector
                    end
                end
                return Vector3.zero
            end
            function LuaHookRuntime.Movement.FlightMoveDirection()
                local movement = LuaHookRuntime.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                if UserInputService.KeyboardEnabled then
                    local look = cframe.LookVector
                    local flatLook = Vector3.new(look.X, 0, look.Z)
                    if flatLook.Magnitude > 0 then
                        flatLook = flatLook.Unit
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                        direction = direction + Vector3.new(0, 1, 0)
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
                        or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                        direction = direction - Vector3.new(0, 1, 0)
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + cframe.LookVector * -moveVector.Z
                        direction = direction + cframe.RightVector * moveVector.X
                    end
                end
                return direction
            end
            function LuaHookRuntime.Movement.FlattenDirection(vector)
                local flat = Vector3.new(vector.X, 0, vector.Z)
                return flat.Magnitude > 0 and flat.Unit or Vector3.zero
            end
            function LuaHookRuntime.Movement.StrafeMoveDirection()
                local movement = LuaHookRuntime.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                local look = movement.FlattenDirection(cframe.LookVector)
                local right = movement.FlattenDirection(cframe.RightVector)
                if UserInputService.KeyboardEnabled then
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + right
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - right
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + look * -moveVector.Z
                        direction = direction + right * moveVector.X
                    end
                end
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                return direction
            end
            function LuaHookRuntime.Movement.UpdateFlight(active)
                local movement = LuaHookRuntime.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or rootPart.Parent == nil
                    or not movement.Humanoid or movement.Humanoid.Health <= 0 then
                    movement.DestroyFlight()
                    return
                end
                local direction = movement.FlightMoveDirection()
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                local velocityVector = direction * movement.ReadNumber('LH_P10S3S4', 100)
                local flight = movement.Flight
                if flight and flight.RootPart ~= rootPart then
                    movement.DestroyFlight()
                    flight = nil
                end
                if flight then
                    flight.Velocity.VectorVelocity = velocityVector
                    return
                end
                local attachment = Instance.new('Attachment')
                attachment.Parent = rootPart
                local velocity = Instance.new('LinearVelocity')
                velocity.RelativeTo = Enum.ActuatorRelativeTo.World
                velocity.MaxForce = math.huge
                velocity.VectorVelocity = velocityVector
                velocity.Attachment0 = attachment
                velocity.Parent = rootPart
                movement.Flight = { RootPart = rootPart, Attachment = attachment, Velocity = velocity }
            end
            function LuaHookRuntime.Movement.BlankFlightVelocity()
                local movement = LuaHookRuntime.Movement
                if movement.Flight and movement.RootPart and movement.RootPart.Parent then
                    movement.RootPart.AssemblyLinearVelocity = Vector3.zero
                end
            end
            function LuaHookRuntime.Movement.UpdateNoclip(active)
                local movement = LuaHookRuntime.Movement
                local character = movement.Character
                local alive = character ~= nil and movement.Humanoid ~= nil and movement.Humanoid.Health > 0
                if not alive then
                    movement.ClearNoclipCharacter()
                elseif movement.NoclipCharacter ~= character then
                    movement.BindNoclipCharacter(character)
                end
                movement.SetNoclipEnabled(active == true and alive)
                if not movement.NoclipEnabled then
                    return
                end
                for part in pairs(movement.CollidableParts) do
                    part.CanCollide = false
                end
            end
            function LuaHookRuntime.Movement.UpdateAutoStrafe(deltaTime, active)
                local movement = LuaHookRuntime.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or not movement.Humanoid or movement.Humanoid.Health <= 0
                    or not UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                    return
                end
                local speed = movement.ReadNumber('LH_P10S3S5', 50)
                rootPart.CFrame = rootPart.CFrame + movement.StrafeMoveDirection() * (speed / 100) * deltaTime * 60
                rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)
            end
            function LuaHookRuntime.Movement.ResolveMechanicsController()
                local movement = LuaHookRuntime.Movement
                if movement.MechanicsController then
                    return movement.MechanicsController
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local mechanicsModule = controllers and controllers:FindFirstChild('MechanicsController')
                if mechanicsModule then
                    local ok, controller = pcall(require, mechanicsModule)
                    movement.MechanicsController = ok and type(controller) == 'table' and controller or nil
                end
                return movement.MechanicsController
            end
            function LuaHookRuntime.Movement.AttemptLoadWalkSpeedHook()
                local movement = LuaHookRuntime.Movement
                if movement.WalkSpeedHookLoaded then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local getWalkSpeed = type(classIndex) == 'table' and rawget(classIndex, '_GetWalkSpeed') or nil
                if type(getWalkSpeed) ~= 'function' then
                    return false
                end
                local upvalueIndex, oldUpvalue
                for index, value in pairs(debug.getupvalues(getWalkSpeed)) do
                    if type(value) == 'table' and rawget(value, 'BASE_WALKSPEED') ~= nil then
                        upvalueIndex = index
                        oldUpvalue = value
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                movement.WalkSpeedHookGetter = getWalkSpeed
                movement.WalkSpeedHookUpvalueIndex = upvalueIndex
                movement.WalkSpeedHookOldUpvalue = oldUpvalue
                debug.setupvalue(getWalkSpeed, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        if key ~= 'BASE_WALKSPEED' then
                            LP:Kick('Unexpected behavior (client physics 1)')
                            return nil
                        end
                        local baseWalkSpeed = rawget(oldUpvalue, 'BASE_WALKSPEED')
                        if movement.SlidingMultiplierEnabled and debug.info(3, 'n') == 'Slide' then
                            return baseWalkSpeed * movement.SlidingMultiplier
                        end
                        if movement.WalkMultiplierEnabled then
                            return baseWalkSpeed * movement.WalkMultiplier
                        end
                        return baseWalkSpeed
                    end,
                }))
                movement.WalkSpeedHookLoaded = true
                return true
            end
            function LuaHookRuntime.Movement.UpdateWalkSpeed(active)
                local movement = LuaHookRuntime.Movement
                movement.WalkMultiplier = movement.ReadNumber('LH_P10S3S1', 2)
                movement.WalkMultiplierEnabled = active == true
                if active == true or movement.WalkSpeedHookLoaded then
                    movement.AttemptLoadWalkSpeedHook()
                end
            end
            function LuaHookRuntime.Movement.UpdateSliding(active)
                local movement = LuaHookRuntime.Movement
                movement.SlidingMultiplier = movement.ReadNumber('LH_P10S3S2', 10)
                movement.SlidingMultiplierEnabled = active == true
                if active == true or movement.WalkSpeedHookLoaded then
                    movement.AttemptLoadWalkSpeedHook()
                end
            end
            function LuaHookRuntime.Movement.UpdateJumpPower(active)
                local movement = LuaHookRuntime.Movement
                movement.JumpPowerMultiplier = movement.ReadNumber('LH_P10S3S3', 2)
                movement.JumpPowerEnabled = active == true
                if active == true or movement.JumpPowerHookLoaded then
                    movement.AttemptLoadJumpPowerHook()
                end
            end
            function LuaHookRuntime.Movement.LaunchLongJump()
                local movement = LuaHookRuntime.Movement
                local fighter = ResolveLocalFighter()
                local entity = type(fighter) == 'table' and rawget(fighter, 'Entity') or nil
                if not entity and fighter and type(fighter.GetEntity) == 'function' then
                    local ok, value = pcall(fighter.GetEntity, fighter)
                    entity = ok and value or nil
                end
                local rootPart = movement.RootPart
                local camera = Workspace.CurrentCamera
                if type(entity) ~= 'table' or not rootPart or not camera or not movement.Humanoid
                    or movement.Humanoid.Health <= 0 then
                    return false
                end
                local lookVector = camera.CFrame.LookVector
                local direction = Vector3.new(lookVector.X, 0, lookVector.Z)
                if direction.Magnitude < 0.001 then
                    local rootLook = rootPart.CFrame.LookVector
                    direction = Vector3.new(rootLook.X, 0, rootLook.Z)
                end
                direction = direction.Unit
                if Options.LH_P10S3D1 and Options.LH_P10S3D1.Value == 'Under Feet' then
                    direction = (direction * movement.ReadNumber('LH_P10S3S8', 8) + Vector3.new(0, 4, 0)).Unit
                end
                local velocity = direction * movement.ReadNumber('LH_P10S3S6', 60)
                    + Vector3.new(0, movement.ReadNumber('LH_P10S3S7', 20), 0)
                if type(entity.AirborneCancel) ~= 'function' or type(entity.AirborneTrigger) ~= 'function' then
                    return false
                end
                pcall(entity.AirborneCancel, entity)
                local ok = pcall(entity.AirborneTrigger, entity, velocity, 4)
                return ok
            end
            function LuaHookRuntime.Movement.UpdateLongJump(active)
                local movement = LuaHookRuntime.Movement
                if active and not movement.LongJumpPressed then
                    movement.LaunchLongJump()
                end
                movement.LongJumpPressed = active
            end
            function LuaHookRuntime.Movement.Update(deltaTime)
                local movement = LuaHookRuntime.Movement
                movement.ResolveCharacter()
                movement.UpdateWalkSpeed(
                    movement.ReadToggle('LH_P10S3T1') and movement.IsKeyActive('LH_P10S3T1K'))
                movement.UpdateSliding(
                    movement.ReadToggle('LH_P10S3T2') and movement.IsKeyActive('LH_P10S3T2K'))
                movement.UpdateJumpPower(movement.ReadToggle('LH_P10S3T3'))
                movement.UpdateAutoStrafe(
                    deltaTime,
                    movement.ReadToggle('LH_P10S3T6') and movement.IsKeyActive('LH_P10S3T6K'))
                movement.UpdateFlight(
                    movement.ReadToggle('LH_P10S3T4') and movement.IsKeyActive('LH_P10S3T4K'))
                movement.UpdateNoclip(
                    movement.ReadToggle('LH_P10S3T5') and movement.IsKeyActive('LH_P10S3T5K'))
                movement.UpdateLongJump(
                    movement.ReadToggle('LH_P10S3T7') and movement.IsKeyActive('LH_P10S3T7K'))
            end
            function LuaHookRuntime.Movement.RefreshAll()
                local movement = LuaHookRuntime.Movement
                local caps = __luahook_hook_genv.LuaHookHookCaps
                if movement.ReadToggle('LH_P10S3T1') or movement.ReadToggle('LH_P10S3T2') then
                    caps.gate('WalkSpeed / Sliding Speed', 'debug.getupvalues', 'debug.setupvalue')
                end
                if movement.ReadToggle('LH_P10S3T3') then
                    caps.gate('Jump Power', 'debug.getupvalues', 'debug.setupvalue', 'debug.getconstants', 'debug.getprotos', 'debug.getproto')
                end
                LuaHookRuntime.Movement.Update(0)
            end
            function LuaHookRuntime.Movement.Destroy()
                local movement = LuaHookRuntime.Movement
                movement.SetNoclipEnabled(false)
                movement.ClearNoclipCharacter()
                movement.DestroyFlight()
                if movement.WalkSpeedHookLoaded and movement.WalkSpeedHookGetter
                    and movement.WalkSpeedHookUpvalueIndex ~= nil and movement.WalkSpeedHookOldUpvalue ~= nil then
                    pcall(debug.setupvalue, movement.WalkSpeedHookGetter,
                        movement.WalkSpeedHookUpvalueIndex, movement.WalkSpeedHookOldUpvalue)
                end
                movement.WalkSpeedHookLoaded = false
                movement.WalkSpeedHookGetter = nil
                movement.WalkSpeedHookUpvalueIndex = nil
                movement.WalkSpeedHookOldUpvalue = nil
                movement.WalkMultiplierEnabled = false
                movement.SlidingMultiplierEnabled = false
                movement.JumpPowerHookDestroyed = true
                movement.JumpPowerHookLoaded = false
                movement.JumpPowerEnabled = false
                movement.MechanicsController = nil
                movement.PlayerModule = nil
                movement.Character = nil
                movement.Humanoid = nil
                movement.RootPart = nil
                movement.LongJumpPressed = false
            end
            LuaHookRuntime.DeviceSpoof = {
                Hook = nil,
                Controller = nil,
                ControlsMap = {
                    Desktop = 'MouseKeyboard',
                    Mobile = 'Touch',
                    Console = 'Gamepad',
                    VR = 'VR',
                },
            }
            function LuaHookRuntime.DeviceSpoof.ResolveControlsController()
                local spoof = LuaHookRuntime.DeviceSpoof
                if spoof.Controller then
                    return spoof.Controller
                end
                if not ReplicatedStateReady then
                    BeginReplicatedStateBoot()
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local module = controllers and controllers:FindFirstChild('ControlsController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if ok and type(controller) == 'table' then
                    spoof.Controller = controller
                end
                return spoof.Controller
            end
            function LuaHookRuntime.DeviceSpoof.ReadEnabled()
                return Toggles and Toggles.LH_P10S7T1 and Toggles.LH_P10S7T1.Value == true
            end
            function LuaHookRuntime.DeviceSpoof.ReadSpoofType()
                local option = Options and Options.LH_P10S7D1
                local value = option and option.Value
                return type(value) == 'string' and value or 'VR'
            end
            function LuaHookRuntime.DeviceSpoof.ResolveReplicateControls()
                local fighterController = ResolveFighterController()
                if type(fighterController) ~= 'table' then
                    return nil, nil
                end
                local metatable = getmetatable(fighterController)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local replicateControls = type(classIndex) == 'table'
                    and rawget(classIndex, '_ReplicateControls') or nil
                if type(replicateControls) ~= 'function' then
                    return nil, fighterController
                end
                return replicateControls, fighterController
            end
            function LuaHookRuntime.DeviceSpoof.ForceReplicate()
                local replicateControls, fighterController =
                    LuaHookRuntime.DeviceSpoof.ResolveReplicateControls()
                if replicateControls and fighterController then
                    pcall(replicateControls, fighterController)
                end
            end
            function LuaHookRuntime.DeviceSpoof.AttemptLoadHook()
                local spoof = LuaHookRuntime.DeviceSpoof
                if spoof.Hook then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local controlsController = spoof.ResolveControlsController()
                if type(controlsController) ~= 'table' then
                    return false
                end
                local replicateControls = spoof.ResolveReplicateControls()
                if type(replicateControls) ~= 'function' then
                    return false
                end
                local upvalueIndex
                for index, value in pairs(debug.getupvalues(replicateControls)) do
                    if value == controlsController then
                        upvalueIndex = index
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                local originalValue = debug.getupvalue(replicateControls, upvalueIndex)
                debug.setupvalue(replicateControls, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        if key ~= 'CurrentControls' then
                            LP:Kick('Unexpected behavior (client misc 2)')
                            return nil
                        end
                        local value = spoof.ControlsMap[spoof.ReadSpoofType()]
                        if value == nil then
                            LP:Kick('Unexpected behavior (client misc 1)')
                        end
                        return value
                    end,
                }))
                spoof.Hook = {
                    Getter = replicateControls,
                    UpvalueIndex = upvalueIndex,
                    OriginalValue = originalValue,
                }
                return true
            end
            function LuaHookRuntime.DeviceSpoof.AttemptUnloadHook()
                local spoof = LuaHookRuntime.DeviceSpoof
                local hook = spoof.Hook
                if not hook then
                    return
                end
                spoof.Hook = nil
                pcall(debug.setupvalue, hook.Getter, hook.UpvalueIndex, hook.OriginalValue)
            end
            function LuaHookRuntime.DeviceSpoof.RefreshAll()
                local spoof = LuaHookRuntime.DeviceSpoof
                if spoof.ReadEnabled() then
                    __luahook_hook_genv.LuaHookHookCaps.gate('Device Spoof', 'debug.getupvalues', 'debug.setupvalue')
                    if spoof.AttemptLoadHook() then
                        spoof.ForceReplicate()
                    end
                elseif spoof.Hook then
                    spoof.AttemptUnloadHook()
                    spoof.ForceReplicate()
                end
            end
            function LuaHookRuntime.DeviceSpoof.Destroy()
                local spoof = LuaHookRuntime.DeviceSpoof
                if spoof.Hook then
                    spoof.AttemptUnloadHook()
                    spoof.ForceReplicate()
                end
            end
            LuaHookRuntime.PlayerSpoofer = {
                Binders = setmetatable({}, { __mode = 'k' }),
                LifecycleConnections = {},
                Started = false,
                Scopes = { 'You', 'Oth' },
                AttributeFields = {
                    { key = 'Winstreak', attribute = 'StatisticDuelsWinStreak', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'Level', attribute = 'Level', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'RankedElo', attribute = 'DisplayELO', control = 'number',
                        youDefault = '3600', othDefault = '0' },
                    { key = 'NametagStatus', attribute = 'PlayerStatus', control = 'text',
                        youDefault = 'Prime', othDefault = 'Prime' },
                    { key = 'Influencer', attribute = 'IsInfluencer', control = 'const', constValue = true },
                    { key = 'RobloxEmployee', attribute = 'IsRobloxEmployee', control = 'const', constValue = true },
                    { key = 'NosniyTeam', attribute = 'GroupRank', control = 'const', constValue = 255 },
                },
            }
            function LuaHookRuntime.PlayerSpoofer.CreateBinder(instance, attribute)
                local binder = {
                    Instance = instance,
                    Attribute = attribute,
                    Original = instance:GetAttribute(attribute),
                    IsWriting = false,
                    Spoofed = nil,
                    Connection = nil,
                }
                binder.Connection = instance:GetAttributeChangedSignal(attribute):Connect(function()
                    if binder.IsWriting then
                        return
                    end
                    binder.Original = instance:GetAttribute(attribute)
                    binder.IsWriting = true
                    if binder.Spoofed ~= nil then
                        instance:SetAttribute(attribute, binder.Spoofed.value)
                    end
                    binder.IsWriting = false
                end)
                return binder
            end
            function LuaHookRuntime.PlayerSpoofer.BinderSet(binder, spoofed)
                binder.Spoofed = spoofed
                binder.IsWriting = true
                if spoofed == nil then
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                else
                    binder.Instance:SetAttribute(binder.Attribute, spoofed.value)
                end
                binder.IsWriting = false
            end
            function LuaHookRuntime.PlayerSpoofer.BinderDestroy(binder)
                if binder.Connection then
                    binder.Connection:Disconnect()
                end
                pcall(function()
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                end)
            end
            function LuaHookRuntime.PlayerSpoofer.Bind(player, attribute)
                local spoofer = LuaHookRuntime.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    entries = {}
                    spoofer.Binders[player] = entries
                end
                local binder = entries[attribute]
                if binder == nil then
                    binder = spoofer.CreateBinder(player, attribute)
                    entries[attribute] = binder
                end
                return binder
            end
            function LuaHookRuntime.PlayerSpoofer.Unbind(player, attribute)
                local spoofer = LuaHookRuntime.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                local binder = entries[attribute]
                if binder ~= nil then
                    spoofer.BinderDestroy(binder)
                    entries[attribute] = nil
                end
            end
            function LuaHookRuntime.PlayerSpoofer.SetAttributeSpoof(player, attribute, enabled, value)
                local spoofer = LuaHookRuntime.PlayerSpoofer
                if enabled then
                    spoofer.BinderSet(spoofer.Bind(player, attribute), { value = value })
                else
                    spoofer.Unbind(player, attribute)
                end
            end
            function LuaHookRuntime.PlayerSpoofer.ScopeSuffix(player)
                return player == LP and 'You' or 'Oth'
            end
            function LuaHookRuntime.PlayerSpoofer.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end
            function LuaHookRuntime.PlayerSpoofer.ReadOption(optionId)
                local option = Options and Options[optionId]
                return option and option.Value
            end
            function LuaHookRuntime.PlayerSpoofer.Apply(player)
                local spoofer = LuaHookRuntime.PlayerSpoofer
                if not player or player.Parent == nil then
                    return
                end
                local suffix = spoofer.ScopeSuffix(player)
                for _, field in ipairs(spoofer.AttributeFields) do
                    local enabled = spoofer.ReadToggle('PSpoof' .. suffix .. field.key .. 'T')
                    if field.control == 'const' then
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled, field.constValue)
                    else
                        local raw = spoofer.ReadOption('PSpoof' .. suffix .. field.key .. 'V')
                        local value = raw
                        if field.control == 'number' then
                            value = tonumber(raw)
                        elseif type(raw) == 'string' and raw == '' then
                            value = nil
                        end
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled and value ~= nil, value)
                    end
                end
            end
            function LuaHookRuntime.PlayerSpoofer.Cleanup(player)
                local spoofer = LuaHookRuntime.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                for _, binder in pairs(entries) do
                    spoofer.BinderDestroy(binder)
                end
                spoofer.Binders[player] = nil
            end
            function LuaHookRuntime.PlayerSpoofer.RefreshAll()
                local spoofer = LuaHookRuntime.PlayerSpoofer
                spoofer.Start()
                for _, player in ipairs(Players:GetPlayers()) do
                    spoofer.Apply(player)
                end
            end
            function LuaHookRuntime.PlayerSpoofer.Start()
                local spoofer = LuaHookRuntime.PlayerSpoofer
                if spoofer.Started then
                    return
                end
                spoofer.Started = true
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerAdded:Connect(GuardLuaHookCallback('PlayerSpoofer_PlayerAdded', function(player)
                        spoofer.Apply(player)
                    end))
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerRemoving:Connect(GuardLuaHookCallback('PlayerSpoofer_PlayerRemoving', function(player)
                        spoofer.Cleanup(player)
                    end))
            end
            function LuaHookRuntime.PlayerSpoofer.Destroy()
                local spoofer = LuaHookRuntime.PlayerSpoofer
                for _, connection in ipairs(spoofer.LifecycleConnections) do
                    pcall(function() connection:Disconnect() end)
                end
                spoofer.LifecycleConnections = {}
                spoofer.Started = false
                for player in pairs(spoofer.Binders) do
                    spoofer.Cleanup(player)
                end
            end
            LuaHookRuntime.AnimationPlayer = {
                Character = nil,
                Humanoid = nil,
                Track = nil,
                AnimatorWait = nil,
                AwaitingOwnership = false,
                LastLoadFailure = nil,
            }
            function LuaHookRuntime.AnimationPlayer.ReadEnabled()
                return Toggles and Toggles.LH_P10S6T1 and Toggles.LH_P10S6T1.Value == true
            end
            function LuaHookRuntime.AnimationPlayer.ReadSpeed()
                local option = Options and Options.LH_P10S6S1
                return option and type(option.Value) == 'number' and option.Value or 1
            end
            function LuaHookRuntime.AnimationPlayer.ResolveAnimationId()
                local option = Options and Options.LH_P10S6I1
                local value = option and option.Value
                if type(value) ~= 'string' then
                    return nil
                end
                return value:match('%d+')
            end
            function LuaHookRuntime.AnimationPlayer.Stop()
                local player = LuaHookRuntime.AnimationPlayer
                if player.AnimatorWait then
                    player.AnimatorWait:Disconnect()
                    player.AnimatorWait = nil
                end
                local track = player.Track
                player.Track = nil
                if track then
                    pcall(track.Stop, track)
                    pcall(track.Destroy, track)
                end
            end
            function LuaHookRuntime.AnimationPlayer.Apply(awaitOwnership)
                local player = LuaHookRuntime.AnimationPlayer
                player.Stop()
                player.AwaitingOwnership = false
                if not player.ReadEnabled() then
                    return
                end
                local humanoid = player.Humanoid
                if not humanoid or humanoid.Parent == nil then
                    return
                end
                local animator = humanoid:FindFirstChildOfClass('Animator')
                if not animator then
                    player.AnimatorWait = humanoid.ChildAdded:Connect(function(child)
                        if child:IsA('Animator') and player.Humanoid == humanoid then
                            player.Apply(true)
                        end
                    end)
                    return
                end
                local animationId = player.ResolveAnimationId()
                if not animationId then
                    return
                end
                local animation = Instance.new('Animation')
                animation.AnimationId = 'rbxassetid://' .. animationId
                local ok, track = pcall(animator.LoadAnimation, animator, animation)
                animation:Destroy()
                if not ok or not track then
                    if player.LastLoadFailure ~= animationId then
                        player.LastLoadFailure = animationId
                        if Library and type(Library.Notify) == 'function' then
                            Library:Notify({
                                Title = 'Animation Player',
                                Description = 'Animation ' .. animationId .. ' could not be loaded.',
                                Time = 3,
                            })
                        end
                    end
                    return
                end
                player.LastLoadFailure = nil
                track.Priority = Enum.AnimationPriority.Action4
                track.Looped = true
                player.Track = track
                track:Play()
                track:AdjustSpeed(player.ReadSpeed())
                player.AwaitingOwnership = awaitOwnership == true
            end
            function LuaHookRuntime.AnimationPlayer.AdjustSpeed()
                local player = LuaHookRuntime.AnimationPlayer
                if player.Track then
                    pcall(player.Track.AdjustSpeed, player.Track, player.ReadSpeed())
                end
            end
            function LuaHookRuntime.AnimationPlayer.EnforceWindow(track)
                local length = track.Length
                if type(length) ~= 'number' or length <= 0 then
                    return
                end
                local startOption = Options and Options.LH_P10S6S2
                local endOption = Options and Options.LH_P10S6S3
                local startPercent = startOption and tonumber(startOption.Value) or 0
                local endPercent = endOption and tonumber(endOption.Value) or 100
                local windowStart = math.clamp(startPercent, 0, 100) / 100 * length
                local windowEnd = math.clamp(endPercent, 0, 100) / 100 * length
                if windowEnd <= windowStart then
                    return
                end
                if track.TimePosition >= windowEnd or track.TimePosition < windowStart then
                    track.TimePosition = windowStart
                end
            end
            function LuaHookRuntime.AnimationPlayer.Update()
                local player = LuaHookRuntime.AnimationPlayer
                if not player.ReadEnabled() and not player.Track and not player.AnimatorWait then
                    return
                end
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                if character ~= player.Character or humanoid ~= player.Humanoid then
                    player.Stop()
                    player.Character = character
                    player.Humanoid = humanoid
                    player.Apply(true)
                    return
                end
                local track = player.Track
                if not track then
                    return
                end
                if not track.IsPlaying then
                    player.Track = nil
                    pcall(track.Destroy, track)
                    player.Apply(false)
                    return
                end
                if player.AwaitingOwnership and humanoid and humanoid.RootPart then
                    player.AwaitingOwnership = false
                    player.Apply(false)
                    return
                end
                player.EnforceWindow(track)
            end
            function LuaHookRuntime.AnimationPlayer.RefreshAll()
                LuaHookRuntime.AnimationPlayer.Apply(false)
            end
            function LuaHookRuntime.AnimationPlayer.Destroy()
                local player = LuaHookRuntime.AnimationPlayer
                player.Stop()
                player.Character = nil
                player.Humanoid = nil
                player.AwaitingOwnership = false
                player.LastLoadFailure = nil
            end
            LuaHookRuntime.MovementRecorder = {
                SavePath = 'LuaHookHook/RIVALS Movement Recordings.json',
                Version = 1,
                Mode = 'Idle',
                PendingKind = nil,
                Recording = nil,
                Replay = nil,
                LastRecording = nil,
                RecordsByName = {},
                RecordsByMap = {},
                PersistenceLoaded = false,
                RefreshingOptions = false,
                InputConnections = {},
                PlayerControls = nil,
                InputLibrary = nil,
                MechanicsController = nil,
                RoundActive = nil,
                RoundToken = nil,
                RoundBindingPending = false,
                RoundBindingGeneration = 0,
                WaypointDirty = true,
                WaypointMapName = nil,
                WaypointMapModel = nil,
                WaypointAnchor = nil,
                Markers = {},
                Routes = {},
                SelectedRecording = nil,
                ActivatedRecording = nil,
            }
            function LuaHookRuntime.MovementRecorder.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end
            function LuaHookRuntime.MovementRecorder.ReadNumber(optionId, fallback)
                local option = Options and Options[optionId]
                return option and type(option.Value) == 'number' and option.Value or fallback
            end
            function LuaHookRuntime.MovementRecorder.Notify(message)
                local recorder = LuaHookRuntime.MovementRecorder
                if recorder.ReadToggle('LH_P10S4T3') then
                    return
                end
                if Library and type(Library.Notify) == 'function' then
                    Library:Notify({Title = 'Movement Recorder', Description = message, Time = 3})
                end
            end
            function LuaHookRuntime.MovementRecorder.SetToggle(optionId, value)
                local toggle = Toggles and Toggles[optionId]
                if not toggle or toggle.Value == value or type(toggle.SetValue) ~= 'function' then
                    return
                end
                task.defer(function()
                    if Toggles and Toggles[optionId] == toggle and toggle.Value ~= value then
                        toggle:SetValue(value)
                    end
                end)
            end
            function LuaHookRuntime.MovementRecorder.EncodeVector3(value)
                return {value.X, value.Y, value.Z}
            end
            function LuaHookRuntime.MovementRecorder.DecodeVector3(value)
                if type(value) ~= 'table' then
                    return nil
                end
                local x, y, z = tonumber(value[1]), tonumber(value[2]), tonumber(value[3])
                if not x or not y or not z then
                    return nil
                end
                return Vector3.new(x, y, z)
            end
            function LuaHookRuntime.MovementRecorder.EncodeCFrame(value)
                return {value:GetComponents()}
            end
            function LuaHookRuntime.MovementRecorder.DecodeCFrame(value)
                if type(value) ~= 'table' or #value ~= 12 then
                    return nil
                end
                local components = table.create(12)
                for index = 1, 12 do
                    components[index] = tonumber(value[index])
                    if components[index] == nil then
                        return nil
                    end
                end
                return CFrame.new(table.unpack(components))
            end
            function LuaHookRuntime.MovementRecorder.EncodeAction(action)
                local encoded = {kind = action.kind}
                if action.kind == 'Move' then
                    encoded.direction = LuaHookRuntime.MovementRecorder.EncodeVector3(action.direction)
                elseif action.kind == 'Look' then
                    encoded.cframe = LuaHookRuntime.MovementRecorder.EncodeCFrame(action.cframe)
                elseif action.kind == 'Equip' then
                    encoded.index = action.index
                elseif action.kind == 'ItemInput' then
                    encoded.inputType = action.inputType
                elseif action.kind == 'QuickAttack' then
                    encoded.attackType = action.attackType
                elseif action.kind == 'Crouch' then
                    encoded.crouching = action.crouching == true
                end
                return encoded
            end
            function LuaHookRuntime.MovementRecorder.DecodeAction(action)
                if type(action) ~= 'table' or type(action.kind) ~= 'string' then
                    return nil
                end
                local decoded = {kind = action.kind}
                if action.kind == 'Move' then
                    decoded.direction = LuaHookRuntime.MovementRecorder.DecodeVector3(action.direction)
                    return decoded.direction and decoded or nil
                elseif action.kind == 'Look' then
                    decoded.cframe = LuaHookRuntime.MovementRecorder.DecodeCFrame(action.cframe)
                    return decoded.cframe and decoded or nil
                elseif action.kind == 'Equip' then
                    decoded.index = tonumber(action.index)
                    return decoded.index and decoded or nil
                elseif action.kind == 'ItemInput' then
                    decoded.inputType = type(action.inputType) == 'string' and action.inputType or nil
                    return decoded.inputType and decoded or nil
                elseif action.kind == 'QuickAttack' then
                    decoded.attackType = type(action.attackType) == 'string' and action.attackType or nil
                    return decoded.attackType and decoded or nil
                elseif action.kind == 'Crouch' then
                    decoded.crouching = action.crouching == true
                elseif action.kind ~= 'Jump' and action.kind ~= 'Slide' then
                    return nil
                end
                return decoded
            end
            function LuaHookRuntime.MovementRecorder.EncodeRecording(recording)
                local encoded = {
                    mapName = recording.mapName,
                    startCFrame = LuaHookRuntime.MovementRecorder.EncodeCFrame(recording.startCFrame),
                    displayPosition = LuaHookRuntime.MovementRecorder.EncodeVector3(recording.displayPosition),
                    startEquippedIndex = recording.startEquippedIndex,
                    startEquipCooldown = recording.startEquipCooldown,
                    loadoutRequirements = {},
                    keypoints = {},
                    positions = {},
                }
                for itemName in pairs(recording.loadoutRequirements or {}) do
                    encoded.loadoutRequirements[#encoded.loadoutRequirements + 1] = itemName
                end
                table.sort(encoded.loadoutRequirements)
                for _, keypoint in ipairs(recording.keypoints or {}) do
                    encoded.keypoints[#encoded.keypoints + 1] = {
                        offset = keypoint.offset,
                        action = LuaHookRuntime.MovementRecorder.EncodeAction(keypoint.action),
                    }
                end
                for _, position in ipairs(recording.positions or {}) do
                    encoded.positions[#encoded.positions + 1] = {
                        offset = position.offset,
                        position = LuaHookRuntime.MovementRecorder.EncodeVector3(position.position),
                    }
                end
                return encoded
            end
            function LuaHookRuntime.MovementRecorder.DecodeRecording(encoded)
                if type(encoded) ~= 'table' or type(encoded.mapName) ~= 'string' then
                    return nil
                end
                local recording = {
                    mapName = encoded.mapName,
                    startCFrame = LuaHookRuntime.MovementRecorder.DecodeCFrame(encoded.startCFrame),
                    displayPosition = LuaHookRuntime.MovementRecorder.DecodeVector3(encoded.displayPosition),
                    startEquippedIndex = tonumber(encoded.startEquippedIndex),
                    startEquipCooldown = tonumber(encoded.startEquipCooldown),
                    loadoutRequirements = {},
                    keypoints = {},
                    positions = {},
                }
                if not recording.startCFrame or not recording.displayPosition then
                    return nil
                end
                for _, itemName in ipairs(type(encoded.loadoutRequirements) == 'table'
                    and encoded.loadoutRequirements or {}) do
                    if type(itemName) == 'string' and itemName ~= '' then
                        recording.loadoutRequirements[itemName] = true
                    end
                end
                for _, keypoint in ipairs(type(encoded.keypoints) == 'table' and encoded.keypoints or {}) do
                    local action = LuaHookRuntime.MovementRecorder.DecodeAction(keypoint.action)
                    local offset = tonumber(keypoint.offset)
                    if action and offset then
                        recording.keypoints[#recording.keypoints + 1] = {offset = offset, action = action}
                    end
                end
                for _, position in ipairs(type(encoded.positions) == 'table' and encoded.positions or {}) do
                    local value = LuaHookRuntime.MovementRecorder.DecodeVector3(position.position)
                    local offset = tonumber(position.offset)
                    if value and offset then
                        recording.positions[#recording.positions + 1] = {offset = offset, position = value}
                    end
                end
                if #recording.keypoints == 0 then
                    return nil
                end
                table.sort(recording.keypoints, function(left, right) return left.offset < right.offset end)
                table.sort(recording.positions, function(left, right) return left.offset < right.offset end)
                return recording
            end
            function LuaHookRuntime.MovementRecorder.ReindexRecordings()
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.RecordsByMap = {}
                for name, recording in pairs(recorder.RecordsByName) do
                    recording.name = name
                    local names = recorder.RecordsByMap[recording.mapName]
                    if not names then
                        names = {}
                        recorder.RecordsByMap[recording.mapName] = names
                    end
                    names[#names + 1] = name
                end
                for _, names in pairs(recorder.RecordsByMap) do
                    table.sort(names)
                end
                recorder.WaypointDirty = true
            end
            function LuaHookRuntime.MovementRecorder.LoadPersistence()
                local recorder = LuaHookRuntime.MovementRecorder
                if recorder.PersistenceLoaded then
                    return true
                end
                recorder.RecordsByName = {}
                local hasFilesystem = type(isfile) == 'function' and type(readfile) == 'function'
                if not hasFilesystem then
                    recorder.PersistenceLoaded = false
                    recorder.ReindexRecordings()
                    return false
                end
                local pathExists = false
                local existsOk = pcall(function()
                    pathExists = isfile(recorder.SavePath) == true
                end)
                if not existsOk then
                    recorder.PersistenceLoaded = false
                    recorder.ReindexRecordings()
                    return false
                end
                if pathExists then
                    local readOk, raw = pcall(readfile, recorder.SavePath)
                    if readOk and type(raw) == 'string' and raw ~= '' then
                        local decodeOk, decoded = pcall(function()
                            return game:GetService('HttpService'):JSONDecode(raw)
                        end)
                        if decodeOk and type(decoded) == 'table'
                            and tonumber(decoded.version) == recorder.Version
                            and type(decoded.recordings) == 'table' then
                            for name, encoded in pairs(decoded.recordings) do
                                local recording = type(name) == 'string' and recorder.DecodeRecording(encoded) or nil
                                if recording then
                                    recorder.RecordsByName[name] = recording
                                end
                            end
                        else
                            recorder.Notify('Recording file is invalid; using an empty list')
                        end
                    elseif not readOk then
                        recorder.PersistenceLoaded = false
                        recorder.ReindexRecordings()
                        return false
                    end
                end
                recorder.PersistenceLoaded = true
                recorder.ReindexRecordings()
                return true
            end
            function LuaHookRuntime.MovementRecorder.WritePersistence()
                local recorder = LuaHookRuntime.MovementRecorder
                if type(writefile) ~= 'function' then
                    return false
                end
                local http = game:GetService('HttpService')
                local encoded = {}
                local encodeOk = pcall(function()
                    for name, recording in pairs(recorder.RecordsByName) do
                        encoded[name] = recorder.EncodeRecording(recording)
                    end
                end)
                if not encodeOk then
                    return false
                end
                local jsonOk, json = pcall(function()
                    return http:JSONEncode({
                        version = recorder.Version,
                        recordings = encoded,
                    })
                end)
                if not jsonOk or type(json) ~= 'string' or json == '' then
                    return false
                end
                local folderReady = true
                if type(isfolder) == 'function' and type(makefolder) == 'function' then
                    local ok, exists = pcall(isfolder, 'LuaHook')
                    if not ok then
                        folderReady = false
                    elseif not exists then
                        local mkOk = pcall(makefolder, 'LuaHook')
                        if not mkOk then
                            local verifyOk, verifyExists = pcall(isfolder, 'LuaHook')
                            folderReady = verifyOk and verifyExists == true
                        end
                    end
                end
                if not folderReady then
                    return false
                end

                local path = recorder.SavePath
                local tempPath = path .. '.tmp'
                local oldRaw = nil
                if type(isfile) == 'function' and type(readfile) == 'function' then
                    pcall(function()
                        if isfile(path) then
                            oldRaw = readfile(path)
                        end
                    end)
                end

                local function verify(pathToCheck)
                    if type(isfile) ~= 'function' or type(readfile) ~= 'function' then
                        return true
                    end
                    local existsOk, exists = pcall(isfile, pathToCheck)
                    if not existsOk or not exists then
                        return false
                    end
                    local readOk, raw = pcall(readfile, pathToCheck)
                    if not readOk or type(raw) ~= 'string' or raw == '' then
                        return false
                    end
                    local decodeOk, decoded = pcall(function()
                        return http:JSONDecode(raw)
                    end)
                    return decodeOk and type(decoded) == 'table'
                        and tonumber(decoded.version) == recorder.Version
                        and type(decoded.recordings) == 'table'
                end

                local tempOk = pcall(writefile, tempPath, json)
                if not tempOk or not verify(tempPath) then
                    pcall(function() if type(delfile) == 'function' and isfile(tempPath) then delfile(tempPath) end end)
                    return false
                end
                local finalOk = pcall(writefile, path, json)
                local verified = finalOk and verify(path)
                if type(delfile) == 'function' then
                    pcall(function() if isfile(tempPath) then delfile(tempPath) end end)
                end
                if not verified then
                    if oldRaw ~= nil then
                        pcall(writefile, path, oldRaw)
                    end
                    return false
                end
                return true
            end
            function LuaHookRuntime.MovementRecorder.GetMapNames()
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                local maps = {}
                for mapName in pairs(recorder.RecordsByMap) do
                    maps[#maps + 1] = mapName
                end
                table.sort(maps)
                return maps
            end
            function LuaHookRuntime.MovementRecorder.GetRecordingNames(mapName)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                return table.clone(recorder.RecordsByMap[mapName] or {})
            end
            function LuaHookRuntime.MovementRecorder.RefreshRecordingOptions()
                local recorder = LuaHookRuntime.MovementRecorder
                if recorder.RefreshingOptions then
                    return
                end
                local mapOption = Options and Options.LH_P10S4D1
                local recordingOption = Options and Options.LH_P10S4D2
                if not mapOption or not recordingOption then
                    return
                end
                recorder.RefreshingOptions = true
                local maps = recorder.GetMapNames()
                local currentMap = mapOption.Value
                if type(mapOption.SetValues) == 'function' then
                    mapOption:SetValues(maps)
                end
                if type(currentMap) ~= 'string' or table.find(maps, currentMap) == nil then
                    currentMap = maps[1]
                    if type(mapOption.SetValue) == 'function' then
                        mapOption:SetValue(currentMap)
                    end
                end
                local names = recorder.GetRecordingNames(currentMap)
                local selectedName = recordingOption.Value
                if type(recordingOption.SetValues) == 'function' then
                    recordingOption:SetValues(names)
                end
                if type(selectedName) ~= 'string' or table.find(names, selectedName) == nil then
                    if type(recordingOption.SetValue) == 'function' then
                        recordingOption:SetValue(names[1])
                    end
                end
                recorder.RefreshingOptions = false
            end
            function LuaHookRuntime.MovementRecorder.SaveLastRecording(name)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                name = type(name) == 'string' and name:match('^%s*(.-)%s*$') or ''
                if name == '' then
                    recorder.Notify('Enter a recording name first')
                    return false
                end
                if #name > 64 then
                    name = name:sub(1, 64)
                end
                if name:find('[/\\]') then
                    recorder.Notify('Recording name cannot contain / or \\')
                    return false
                end
                if not recorder.LastRecording then
                    recorder.Notify('No recording to save')
                    return false
                end
                local previous = recorder.RecordsByName[name]
                recorder.RecordsByName[name] = recorder.LastRecording
                recorder.ReindexRecordings()
                if not recorder.WritePersistence() then
                    recorder.RecordsByName[name] = previous
                    recorder.ReindexRecordings()
                    recorder.Notify('Failed to save recording (filesystem write/verify failed)')
                    return false
                end
                recorder.PersistenceLoaded = true
                recorder.LastRecording = nil
                recorder.RefreshRecordingOptions()
                recorder.Notify('Recording saved: ' .. name)
                return true
            end
            function LuaHookRuntime.MovementRecorder.DeleteRecording(name)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                if type(name) ~= 'string' or name == '' or not recorder.RecordsByName[name] then
                    recorder.Notify('Select a recording to delete')
                    return false
                end
                local previous = recorder.RecordsByName[name]
                recorder.RecordsByName[name] = nil
                recorder.ReindexRecordings()
                if not recorder.WritePersistence() then
                    recorder.RecordsByName[name] = previous
                    recorder.ReindexRecordings()
                    recorder.Notify('Failed to delete recording')
                    return false
                end
                recorder.RefreshRecordingOptions()
                recorder.Notify('Recording deleted')
                return true
            end
            function LuaHookRuntime.MovementRecorder.ResolveMapContext()
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                local rootPart = character and character:FindFirstChild('HumanoidRootPart') or nil
                if not character or not humanoid or humanoid.Health <= 0 or not rootPart then
                    return nil
                end
                local environmentId = character:GetAttribute('EnvironmentID')
                if environmentId == nil then
                    local fighter = ResolveLocalFighter()
                    local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                    environmentId = type(data) == 'table' and rawget(data, 'EnvironmentID') or nil
                end
                if environmentId == nil then
                    return nil
                end
                local tagged = game:GetService('CollectionService'):GetTagged('RaycastWhitelist' .. tostring(environmentId))
                local mapModel = tagged[1]
                while mapModel and mapModel ~= Workspace
                    and not (mapModel:IsA('Model') or mapModel:GetAttribute('EnvironmentID') == environmentId) do
                    mapModel = mapModel.Parent
                end
                if not mapModel or mapModel == Workspace or not mapModel:IsA('PVInstance') then
                    return nil
                end
                local mapName
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local duelModule = controllers and controllers:FindFirstChild('DuelController')
                if duelModule and IsReplicatedStateReady() then
                    local ok, duelController = pcall(require, duelModule)
                    local duel = ok and type(duelController) == 'table' and duelController.CurrentObject or nil
                    if duel and type(duel.GetMapName) == 'function' then
                        local mapOk, value = pcall(duel.GetMapName, duel)
                        mapName = mapOk and type(value) == 'string' and value ~= '' and value or nil
                    end
                    if not mapName and duel and type(duel.Get) == 'function' then
                        for _, key in ipairs({'MapName', 'Map'}) do
                            local mapOk, value = pcall(duel.Get, duel, key)
                            if mapOk and type(value) == 'string' and value ~= '' then
                                mapName = value
                                break
                            end
                        end
                    end
                end
                if not mapName then
                    for _, attributeName in ipairs({'MapName', 'MatchMap'}) do
                        local value = Workspace:GetAttribute(attributeName)
                        if type(value) == 'string' and value ~= '' then
                            mapName = value
                            break
                        end
                    end
                end
                mapName = mapName or mapModel.Name
                return {
                    Character = character,
                    Humanoid = humanoid,
                    RootPart = rootPart,
                    MapModel = mapModel,
                    MapAnchor = mapModel:GetPivot(),
                    MapName = mapName,
                    EnvironmentId = environmentId,
                }
            end
            function LuaHookRuntime.MovementRecorder.IsRoundActive()
                local recorder = LuaHookRuntime.MovementRecorder
                local fighter = ResolveLocalFighter()
                local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                if type(data) == 'table' and rawget(data, 'IsInShootingRange') == true then
                    return true
                end
                if recorder.RoundActive ~= nil then
                    return recorder.RoundActive == true
                end
                return FighterDataCache.LocalDuel.IsInDuel == true
            end
            function LuaHookRuntime.MovementRecorder.ResolveDependencies()
                local recorder = LuaHookRuntime.MovementRecorder
                if not recorder.PlayerControls then
                    local playerModule = LP:FindFirstChild('PlayerScripts')
                        and LP.PlayerScripts:FindFirstChild('PlayerModule')
                    if playerModule then
                        local ok, module = pcall(require, playerModule)
                        if ok and type(module) == 'table' and type(module.GetControls) == 'function' then
                            local controlsOk, controls = pcall(module.GetControls, module)
                            recorder.PlayerControls = controlsOk and controls or nil
                        end
                    end
                end
                if not recorder.InputLibrary then
                    local modules = ReplicatedStorage:FindFirstChild('Modules')
                    local inputModule = modules and modules:FindFirstChild('InputLibrary')
                    if inputModule then
                        local ok, library = pcall(require, inputModule)
                        recorder.InputLibrary = ok and type(library) == 'table' and library or nil
                    end
                end
                if not recorder.MechanicsController and IsReplicatedStateReady() then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                    local mechanicsModule = controllers and controllers:FindFirstChild('MechanicsController')
                    if mechanicsModule then
                        local ok, controller = pcall(require, mechanicsModule)
                        recorder.MechanicsController = ok and type(controller) == 'table' and controller or nil
                    end
                end
                return recorder.PlayerControls ~= nil and recorder.InputLibrary ~= nil
            end
            function LuaHookRuntime.MovementRecorder.ResolveEquippedItem(fighter)
                if type(fighter) ~= 'table' then
                    return nil
                end
                return rawget(fighter, 'EquippedItem')
            end
            function LuaHookRuntime.MovementRecorder.ResolveItemIndex(item, fighter)
                local data = type(item) == 'table' and rawget(item, 'Data') or nil
                local index = type(data) == 'table' and tonumber(rawget(data, 'ItemIndex')) or nil
                if index then
                    return index
                end
                for slotIndex, candidate in ipairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    if candidate == item then
                        return slotIndex
                    end
                end
                return nil
            end
            function LuaHookRuntime.MovementRecorder.ResolveItemName(item)
                if type(item) ~= 'table' then
                    return nil
                end
                local name = rawget(item, 'Name')
                if type(name) == 'string' and name ~= '' then
                    return name
                end
                local data = rawget(item, 'Data')
                name = type(data) == 'table' and rawget(data, 'Name') or nil
                return type(name) == 'string' and name ~= '' and name or nil
            end
            function LuaHookRuntime.MovementRecorder.GetOffset()
                local active = LuaHookRuntime.MovementRecorder.Recording
                return active and math.max(0, os.clock() - active.StartTime) or 0
            end
            function LuaHookRuntime.MovementRecorder.RecordAction(action)
                local recorder = LuaHookRuntime.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                active.Data.keypoints[#active.Data.keypoints + 1] = {
                    offset = recorder.GetOffset(),
                    action = action,
                }
            end
            function LuaHookRuntime.MovementRecorder.DiscardUnusedStartItem()
                local active = LuaHookRuntime.MovementRecorder.Recording
                if not active or active.StartItemUsed or active.Data.startEquippedIndex == nil then
                    return
                end
                active.Data.startEquippedIndex = nil
                active.Data.startEquipCooldown = nil
            end
            function LuaHookRuntime.MovementRecorder.RecordItemInput(inputType)
                local recorder = LuaHookRuntime.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local itemName = recorder.ResolveItemName(item)
                if itemName then
                    active.Data.loadoutRequirements[itemName] = true
                end
                if recorder.ResolveItemIndex(item, fighter) == active.StartItemIndex then
                    active.StartItemUsed = true
                end
                recorder.RecordAction({kind = 'ItemInput', inputType = inputType})
            end
            function LuaHookRuntime.MovementRecorder.InputMatches(input, inputName)
                local library = LuaHookRuntime.MovementRecorder.InputLibrary
                if not library or type(library.InputIs) ~= 'function' then
                    return false
                end
                local ok, matches = pcall(library.InputIs, library, input, inputName)
                return ok and matches == true
            end
            function LuaHookRuntime.MovementRecorder.HandleInput(input, gameProcessed, began)
                local recorder = LuaHookRuntime.MovementRecorder
                if recorder.Mode ~= 'Recording' or gameProcessed then
                    return
                end
                if began and recorder.InputMatches(input, 'Jump') then
                    recorder.RecordAction({kind = 'Jump'})
                    return
                end
                if began and recorder.InputMatches(input, 'QuickMelee') then
                    recorder.RecordAction({kind = 'QuickAttack', attackType = 'Melee'})
                    return
                end
                if began and recorder.InputMatches(input, 'QuickUtility') then
                    recorder.RecordAction({kind = 'QuickAttack', attackType = 'Utility'})
                    return
                end
                local library = recorder.InputLibrary
                for _, inputName in ipairs(type(library) == 'table' and library.ItemInputs or {}) do
                    local definition = type(library.Inputs) == 'table' and library.Inputs[inputName] or nil
                    if definition and recorder.InputMatches(input, inputName) then
                        local inputType = began and definition.StartName or definition.FinishName
                        if type(inputType) == 'string' then
                            recorder.RecordItemInput(inputType)
                        end
                        return
                    end
                end
            end
            function LuaHookRuntime.MovementRecorder.DisconnectRecordingInputs()
                local recorder = LuaHookRuntime.MovementRecorder
                for _, connection in ipairs(recorder.InputConnections) do
                    connection:Disconnect()
                end
                recorder.InputConnections = {}
            end
            function LuaHookRuntime.MovementRecorder.ConnectRecordingInputs()
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.DisconnectRecordingInputs()
                recorder.InputConnections = {
                    UserInputService.InputBegan:Connect(GuardLuaHookCallback(
                        'MovementRecorder_InputBegan', function(input, gameProcessed)
                            recorder.HandleInput(input, gameProcessed, true)
                        end)),
                    UserInputService.InputEnded:Connect(GuardLuaHookCallback(
                        'MovementRecorder_InputEnded', function(input, gameProcessed)
                            recorder.HandleInput(input, gameProcessed, false)
                        end)),
                }
            end
            function LuaHookRuntime.MovementRecorder.SampleRecording()
                local recorder = LuaHookRuntime.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                local controls = recorder.PlayerControls
                local moveVector = Vector3.zero
                if controls and type(controls.GetMoveVector) == 'function' then
                    local ok, value = pcall(controls.GetMoveVector, controls)
                    if ok and typeof(value) == 'Vector3' then
                        moveVector = value
                    end
                end
                if moveVector ~= active.LastMoveVector then
                    active.LastMoveVector = moveVector
                    recorder.RecordAction({kind = 'Move', direction = moveVector})
                end
                local camera = Workspace.CurrentCamera
                if camera then
                    local pitch, yaw = camera.CFrame:ToOrientation()
                    local cameraRotation = Vector2.new(pitch, yaw)
                    if (cameraRotation - active.LastCameraRotation).Magnitude > 0.0001 then
                        active.LastCameraRotation = cameraRotation
                        recorder.RecordAction({
                            kind = 'Look',
                            cframe = active.AnchorInverse * CFrame.fromOrientation(pitch, yaw, 0),
                        })
                    end
                end
                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local equippedIndex = recorder.ResolveItemIndex(item, fighter)
                if equippedIndex ~= active.LastEquippedIndex then
                    active.LastEquippedIndex = equippedIndex
                    recorder.DiscardUnusedStartItem()
                    if equippedIndex ~= nil then
                        recorder.RecordAction({kind = 'Equip', index = equippedIndex})
                    end
                end
                local mechanics = recorder.MechanicsController
                local crouching = mechanics and rawget(mechanics, 'IsCrouching') == true or false
                if crouching ~= active.LastCrouching then
                    active.LastCrouching = crouching
                    recorder.RecordAction({kind = 'Crouch', crouching = crouching})
                end
                local sliding = mechanics and rawget(mechanics, 'IsSliding') == true or false
                if sliding ~= active.LastSliding then
                    active.LastSliding = sliding
                    if sliding then
                        recorder.RecordAction({kind = 'Slide'})
                    end
                end
                local now = os.clock()
                if now - active.LastPositionSampleTime >= 0.1 then
                    active.LastPositionSampleTime = now
                    active.Data.positions[#active.Data.positions + 1] = {
                        offset = recorder.GetOffset(),
                        position = active.AnchorInverse * active.RootPart.Position,
                    }
                end
            end
            function LuaHookRuntime.MovementRecorder.StartRecording()
                local recorder = LuaHookRuntime.MovementRecorder
                local context = recorder.ResolveMapContext()
                if not context or not recorder.ResolveDependencies() then
                    recorder.Notify('You need to be alive and in a match')
                    return false
                end
                if recorder.Mode ~= 'Idle' then
                    recorder.Notify(recorder.Mode == 'Recording' and 'Already recording' or "Can't record while replaying")
                    return false
                end
                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local equippedIndex = recorder.ResolveItemIndex(item, fighter)
                local equipCooldown = type(item) == 'table' and tonumber(rawget(item, '_equip_cooldown')) or nil
                if equipCooldown then
                    equipCooldown = math.max(0, equipCooldown - tick())
                end
                local camera = Workspace.CurrentCamera
                local pitch, yaw = camera and camera.CFrame:ToOrientation() or 0, 0
                if camera then
                    pitch, yaw = camera.CFrame:ToOrientation()
                end
                local anchorInverse = context.MapAnchor:Inverse()
                local displayPosition = context.RootPart.Position
                if camera then
                    local center = camera.ViewportSize / 2
                    local ray = camera:ViewportPointToRay(center.X, center.Y)
                    displayPosition = ray.Origin + ray.Direction * 100
                end
                recorder.Recording = {
                    Data = {
                        mapName = context.MapName,
                        displayPosition = anchorInverse * displayPosition,
                        startCFrame = anchorInverse * context.RootPart.CFrame,
                        startEquippedIndex = equippedIndex,
                        startEquipCooldown = equipCooldown,
                        keypoints = {{
                            offset = 0,
                            action = {
                                kind = 'Look',
                                cframe = anchorInverse * CFrame.fromOrientation(pitch, yaw, 0),
                            },
                        }},
                        loadoutRequirements = {},
                        positions = {},
                    },
                    AnchorInverse = anchorInverse,
                    RootPart = context.RootPart,
                    Character = context.Character,
                    StartTime = os.clock(),
                    StartItemIndex = equippedIndex,
                    StartItemUsed = false,
                    LastMoveVector = Vector3.zero,
                    LastCameraRotation = Vector2.new(pitch, yaw),
                    LastEquippedIndex = equippedIndex,
                    LastCrouching = false,
                    LastSliding = false,
                    LastPositionSampleTime = 0,
                }
                recorder.Mode = 'Recording'
                recorder.ConnectRecordingInputs()
                recorder.SampleRecording()
                recorder.Notify('Now recording')
                return true
            end
            function LuaHookRuntime.MovementRecorder.StopRecording(saveLast, notify)
                local recorder = LuaHookRuntime.MovementRecorder
                local active = recorder.Recording
                if recorder.Mode ~= 'Recording' or not active then
                    return
                end


                if active.RootPart and active.RootPart.Parent then
                    pcall(recorder.SampleRecording)
                end
                recorder.DiscardUnusedStartItem()
                if saveLast then
                    local data = active.Data
                    local normalized = nil
                    local ok = pcall(function()
                        normalized = recorder.DecodeRecording(recorder.EncodeRecording(data))
                    end)
                    if ok and normalized then
                        recorder.LastRecording = normalized
                    else
                        recorder.LastRecording = data
                    end
                end
                recorder.DisconnectRecordingInputs()
                recorder.Recording = nil
                recorder.Mode = 'Idle'
                if notify then
                    recorder.Notify('Recording stopped')
                end
            end
            function LuaHookRuntime.MovementRecorder.ResolveStartLook(mapAnchor, keypoints)
                for _, keypoint in ipairs(keypoints or {}) do
                    local action = keypoint.action
                    if action and action.kind == 'Look' then
                        local pitch, yaw = (mapAnchor * action.cframe):ToOrientation()
                        return Vector2.new(pitch, yaw)
                    end
                end
                return nil
            end
            function LuaHookRuntime.MovementRecorder.LoadoutFulfilled(recording)
                local owned = {}
                local fighter = ResolveLocalFighter()
                for _, item in ipairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    local itemName = LuaHookRuntime.MovementRecorder.ResolveItemName(item)
                    if itemName then
                        owned[itemName] = true
                    end
                end
                for itemName in pairs(recording.loadoutRequirements or {}) do
                    if not owned[itemName] then
                        return false
                    end
                end
                return true
            end
            function LuaHookRuntime.MovementRecorder.StartReplay(recording)
                local recorder = LuaHookRuntime.MovementRecorder
                local context = recorder.ResolveMapContext()
                if not context or not recorder.ResolveDependencies() then
                    recorder.Notify('You need to be alive and in a match')
                    return false
                end
                if recorder.Mode ~= 'Idle' then
                    recorder.Notify(recorder.Mode == 'Recording' and "Can't replay while recording" or 'Already replaying')
                    return false
                end
                if not recording or recording.mapName ~= context.MapName then
                    recorder.Notify('Stand near a recording marker first')
                    return false
                end
                if not recorder.LoadoutFulfilled(recording) then
                    recorder.Notify('Your loadout does not meet this recording')
                    return false
                end
                local fighter = ResolveLocalFighter()
                if recording.startEquippedIndex ~= nil and fighter and type(fighter.EquipItem) == 'function' then
                    task.spawn(function()
                        pcall(fighter.EquipItem, fighter, recording.startEquippedIndex)
                    end)
                end
                local controls = recorder.PlayerControls
                local activeController = type(controls) == 'table'
                    and rawget(controls, 'activeController') or nil
                local controlsWereEnabled = type(activeController) ~= 'table' or rawget(activeController, 'enabled') ~= false
                if controls and type(controls.Disable) == 'function' then
                    pcall(controls.Disable, controls)
                end
                recorder.Replay = {
                    Data = recording,
                    Character = context.Character,
                    Humanoid = context.Humanoid,
                    RootPart = context.RootPart,
                    Fighter = fighter,
                    MapAnchor = context.MapAnchor,
                    State = 'Aligning',
                    AlignElapsed = 0,
                    StuckTime = 0,
                    BestDistance = math.huge,
                    LookAligned = false,
                    StartLook = recorder.ResolveStartLook(context.MapAnchor, recording.keypoints),
                    TargetLook = nil,
                    MoveVector = Vector3.zero,
                    Offset = 0,
                    KeypointIndex = 1,
                    PositionIndex = 1,
                    Controls = controls,
                    ControlsWereEnabled = controlsWereEnabled,
                }
                recorder.Mode = 'Aligning'
                recorder.ActivatedRecording = recording
                recorder.SelectedRecording = recording
                LuaHookRuntime.ResetFlickbot()
                recorder.Notify('Now replaying')
                return true
            end
            function LuaHookRuntime.MovementRecorder.StopReplay(reason, notify)
                local recorder = LuaHookRuntime.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if replay.Humanoid and replay.Humanoid.Parent then
                    pcall(replay.Humanoid.Move, replay.Humanoid, Vector3.zero, false)
                end
                if replay.ControlsWereEnabled and replay.Controls and type(replay.Controls.Enable) == 'function' then
                    pcall(replay.Controls.Enable, replay.Controls)
                end
                local mechanics = recorder.MechanicsController
                if mechanics and type(mechanics.SetCrouching) == 'function' then
                    pcall(mechanics.SetCrouching, mechanics, false)
                end
                recorder.Replay = nil
                recorder.Mode = 'Idle'
                recorder.ActivatedRecording = nil
                if notify then
                    if reason == 'Diverged' then
                        recorder.Notify('Replay stopped (off course)')
                    elseif reason == 'Completed' then
                        recorder.Notify('Finished replaying')
                    else
                        recorder.Notify('Stopped replaying')
                    end
                end
            end
            function LuaHookRuntime.MovementRecorder.IsStartItemReady()
                local replay = LuaHookRuntime.MovementRecorder.Replay
                if not replay or replay.Data.startEquippedIndex == nil then
                    return true
                end
                local fighter = replay.Fighter
                local item = LuaHookRuntime.MovementRecorder.ResolveEquippedItem(fighter)
                if LuaHookRuntime.MovementRecorder.ResolveItemIndex(item, fighter)
                    ~= replay.Data.startEquippedIndex then
                    return false
                end
                local cooldown = type(item) == 'table' and rawget(item, '_equip_cooldown') or nil
                return type(cooldown) ~= 'number' or cooldown <= tick()
            end
            function LuaHookRuntime.MovementRecorder.StepAlign(deltaTime)
                local recorder = LuaHookRuntime.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if not recorder.IsRoundActive() then
                    replay.Humanoid:Move(Vector3.zero, false)
                    return
                end
                replay.AlignElapsed = replay.AlignElapsed + deltaTime
                local targetPosition = (replay.MapAnchor * replay.Data.startCFrame).Position
                local difference = targetPosition - replay.RootPart.Position
                local planar = Vector3.new(difference.X, 0, difference.Z)
                local distance = planar.Magnitude
                local snapped = distance <= recorder.ReadNumber('LH_P10S4S5', 0.2)
                if snapped then
                    replay.Humanoid:Move(Vector3.zero, false)
                else
                    replay.Humanoid:Move(planar.Unit, false)
                end
                if distance < replay.BestDistance - 0.1 then
                    replay.BestDistance = distance
                    replay.StuckTime = 0
                else
                    replay.StuckTime = replay.StuckTime + deltaTime
                end
                local aligned = (snapped and (replay.StartLook == nil or replay.LookAligned))
                    or replay.StuckTime >= 1
                if not aligned then
                    return
                end
                replay.Humanoid:Move(Vector3.zero, false)
                if not recorder.IsStartItemReady() and replay.AlignElapsed < 3 then
                    return
                end
                replay.State = 'Playing'
                recorder.Mode = 'Playing'
            end
            function LuaHookRuntime.MovementRecorder.HasDiverged(offset)
                local replay = LuaHookRuntime.MovementRecorder.Replay
                local positions = replay and replay.Data.positions or nil
                if not positions or #positions == 0 then
                    return false
                end
                while replay.PositionIndex < #positions
                    and positions[replay.PositionIndex + 1].offset <= offset do
                    replay.PositionIndex = replay.PositionIndex + 1
                end
                local first = positions[replay.PositionIndex]
                local second = positions[replay.PositionIndex + 1]
                local expected = first.position
                if second then
                    local span = second.offset - first.offset
                    local alpha = span > 0 and math.clamp((offset - first.offset) / span, 0, 1) or 0
                    expected = first.position:Lerp(second.position, alpha)
                end
                return (replay.MapAnchor:PointToWorldSpace(expected) - replay.RootPart.Position).Magnitude > 15
            end
            function LuaHookRuntime.MovementRecorder.ApplyReplayAction(action)
                local recorder = LuaHookRuntime.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if action.kind == 'Move' then
                    replay.MoveVector = action.direction
                elseif action.kind == 'Look' then
                    local pitch, yaw = (replay.MapAnchor * action.cframe):ToOrientation()
                    replay.TargetLook = Vector2.new(pitch, yaw)
                elseif action.kind == 'Equip' and replay.Fighter and type(replay.Fighter.EquipItem) == 'function' then
                    task.spawn(function() pcall(replay.Fighter.EquipItem, replay.Fighter, action.index) end)
                elseif action.kind == 'ItemInput' and replay.Fighter and type(replay.Fighter.Input) == 'function' then
                    task.spawn(function() pcall(replay.Fighter.Input, replay.Fighter, action.inputType) end)
                elseif action.kind == 'QuickAttack' and replay.Fighter
                    and type(replay.Fighter.QuickAttackDown) == 'function' then
                    task.spawn(function()
                        pcall(replay.Fighter.QuickAttackDown, replay.Fighter, action.attackType)
                        task.wait(0.05)
                        if replay.Fighter and type(replay.Fighter.QuickAttackUp) == 'function' then
                            pcall(replay.Fighter.QuickAttackUp, replay.Fighter, action.attackType)
                        end
                    end)
                elseif action.kind == 'Jump' then
                    local mechanics = recorder.MechanicsController
                    if mechanics then
                        if rawget(mechanics, 'IsSliding') == true and type(mechanics.HighJump) == 'function' then
                            pcall(mechanics.HighJump, mechanics)
                        else
                            if type(mechanics.DoubleJumpRequest) == 'function' then
                                pcall(mechanics.DoubleJumpRequest, mechanics)
                            end
                            if type(mechanics.JumpRequest) == 'function' then
                                pcall(mechanics.JumpRequest, mechanics)
                            end
                        end
                    end
                elseif action.kind == 'Crouch' then
                    local mechanics = recorder.MechanicsController
                    if mechanics and type(mechanics.SetCrouching) == 'function' then
                        pcall(mechanics.SetCrouching, mechanics, action.crouching)
                    end
                elseif action.kind == 'Slide' then
                    local mechanics = recorder.MechanicsController
                    if mechanics and type(mechanics.Slide) == 'function' then
                        task.spawn(function() pcall(mechanics.Slide, mechanics) end)
                    end
                end
            end
            function LuaHookRuntime.MovementRecorder.StepPlaying(deltaTime)
                local recorder = LuaHookRuntime.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                replay.Offset = replay.Offset + deltaTime
                if recorder.HasDiverged(replay.Offset) then
                    recorder.StopReplay('Diverged', true)
                    recorder.SetToggle('LH_P10S4T5', false)
                    return
                end
                local keypoints = replay.Data.keypoints
                while replay.KeypointIndex <= #keypoints do
                    local keypoint = keypoints[replay.KeypointIndex]
                    if replay.Offset < keypoint.offset then
                        break
                    end
                    recorder.ApplyReplayAction(keypoint.action)
                    replay.KeypointIndex = replay.KeypointIndex + 1
                end
                replay.Humanoid:Move(replay.MoveVector, true)
                if replay.KeypointIndex > #keypoints then
                    recorder.StopReplay('Completed', true)
                    recorder.SetToggle('LH_P10S4T5', false)
                end
            end
            function LuaHookRuntime.MovementRecorder.WrapAngle(value)
                return (value + math.pi) % (2 * math.pi) - math.pi
            end
            function LuaHookRuntime.MovementRecorder.SmoothingAlpha(deltaTime)
                local tau = LuaHookRuntime.MovementRecorder.ReadNumber('LH_P10S4S4', 35) / 100 * 0.3
                return tau <= 0 and 1 or 1 - math.exp(-deltaTime / tau)
            end
            function LuaHookRuntime.MovementRecorder.ReadCameraRotation()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end
                local pitch, yaw = camera.CFrame:ToOrientation()
                return Vector2.new(pitch, yaw)
            end
            function LuaHookRuntime.MovementRecorder.WriteCameraRotation(rotation)
                local camera = Workspace.CurrentCamera
                if camera and rotation then
                    camera.CFrame = CFrame.new(camera.CFrame.Position)
                        * CFrame.fromOrientation(rotation.X, rotation.Y, 0)
                end
            end
            function LuaHookRuntime.MovementRecorder.UpdateReplayCamera(deltaTime)
                local recorder = LuaHookRuntime.MovementRecorder
                local replay = recorder.Replay
                local current = replay and recorder.ReadCameraRotation() or nil
                if not replay or not current then
                    return
                end
                if replay.State == 'Aligning' and replay.StartLook then
                    local difference = Vector2.new(
                        replay.StartLook.X - current.X,
                        recorder.WrapAngle(replay.StartLook.Y - current.Y)
                    )
                    local magnitude = difference.Magnitude
                    if magnitude <= math.rad(0.1) then
                        current = replay.StartLook
                        replay.LookAligned = true
                    else
                        local step = math.min(
                            magnitude * recorder.SmoothingAlpha(deltaTime),
                            math.rad(recorder.ReadNumber('LH_P10S4S3', 180)) * deltaTime
                        )
                        current = current + difference.Unit * step
                        replay.LookAligned = false
                    end
                    recorder.WriteCameraRotation(current)
                elseif replay.State == 'Playing' and replay.TargetLook then
                    local alpha = recorder.SmoothingAlpha(deltaTime)
                    recorder.WriteCameraRotation(Vector2.new(
                        current.X + (replay.TargetLook.X - current.X) * alpha,
                        current.Y + recorder.WrapAngle(replay.TargetLook.Y - current.Y) * alpha
                    ))
                end
            end
            function LuaHookRuntime.MovementRecorder.DestroyWaypoints()
                local recorder = LuaHookRuntime.MovementRecorder
                for _, marker in ipairs(recorder.Markers) do
                    pcall(function() marker.Gui:Destroy() end)
                    pcall(function() marker.Attachment:Destroy() end)
                end
                for _, route in ipairs(recorder.Routes) do
                    pcall(function() route.Gui:Destroy() end)
                    pcall(function() route.Attachment:Destroy() end)
                end
                recorder.Markers = {}
                recorder.Routes = {}
                recorder.SelectedRecording = nil
                recorder.WaypointMapName = nil
                recorder.WaypointMapModel = nil
                recorder.WaypointAnchor = nil
            end
            function LuaHookRuntime.MovementRecorder.ResolveGuiParent()
                if type(gethui) == 'function' then
                    local ok, parent = pcall(gethui)
                    if ok and typeof(parent) == 'Instance' then
                        return parent
                    end
                end
                return game:GetService('CoreGui')
            end
            function LuaHookRuntime.MovementRecorder.CreateWaypointGui(name, position, isRoute)
                local attachment = Instance.new('Attachment')
                attachment.Name = isRoute and 'LuaHookHookMovementRoute' or 'LuaHookHookMovementMarker'
                attachment.WorldPosition = position
                attachment.Parent = Workspace.Terrain
                local gui = Instance.new('BillboardGui')
                gui.Name = attachment.Name
                gui.Adornee = attachment
                gui.AlwaysOnTop = true
                gui.LightInfluence = 0
                gui.MaxDistance = math.huge
                gui.Size = UDim2.fromOffset(isRoute and math.max(90, #name * 8 + 24) or 110, 26)
                gui.Enabled = false
                local label = Instance.new('TextLabel')
                label.Name = 'Label'
                label.BackgroundColor3 = Color3.fromRGB(18, 20, 26)
                label.BackgroundTransparency = 0.2
                label.BorderSizePixel = 0
                label.Size = UDim2.fromScale(1, 1)
                label.Font = Enum.Font.GothamSemibold
                label.TextSize = 14
                label.TextColor3 = Color3.new(1, 1, 1)
                label.Text = name
                label.Parent = gui
                local corner = Instance.new('UICorner')
                corner.CornerRadius = UDim.new(0, 6)
                corner.Parent = label
                gui.Parent = LuaHookRuntime.MovementRecorder.ResolveGuiParent()
                return {Attachment = attachment, Gui = gui, Label = label, Position = position}
            end
            function LuaHookRuntime.MovementRecorder.RebuildWaypoints(context)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.DestroyWaypoints()
                recorder.WaypointDirty = false
                recorder.WaypointMapName = context.MapName
                recorder.WaypointMapModel = context.MapModel
                recorder.WaypointAnchor = context.MapAnchor
                local grouped = {}
                for _, name in ipairs(recorder.RecordsByMap[context.MapName] or {}) do
                    local recording = recorder.RecordsByName[name]
                    if recording then
                        local position = recording.startCFrame.Position
                        local key = math.floor(position.X / 8) .. ','
                            .. math.floor(position.Y / 8) .. ',' .. math.floor(position.Z / 8)
                        local group = grouped[key]
                        if not group then
                            group = {Recordings = {}, Position = Vector3.zero}
                            grouped[key] = group
                        end
                        group.Recordings[#group.Recordings + 1] = recording
                        group.Position = group.Position + position
                    end
                end
                for _, group in pairs(grouped) do
                    local worldPosition = context.MapAnchor:PointToWorldSpace(
                        group.Position / #group.Recordings)
                    local text = #group.Recordings == 1 and '1 recording'
                        or tostring(#group.Recordings) .. ' recordings'
                    local marker = recorder.CreateWaypointGui(text, worldPosition, false)
                    marker.Recordings = group.Recordings
                    recorder.Markers[#recorder.Markers + 1] = marker
                    for _, recording in ipairs(group.Recordings) do
                        local route = recorder.CreateWaypointGui(
                            recording.name,
                            context.MapAnchor:PointToWorldSpace(recording.displayPosition),
                            true
                        )
                        route.Recording = recording
                        route.Marker = marker
                        recorder.Routes[#recorder.Routes + 1] = route
                    end
                end
            end
            function LuaHookRuntime.MovementRecorder.UpdateWaypoints()
                local recorder = LuaHookRuntime.MovementRecorder
                for _, marker in ipairs(recorder.Markers) do marker.Gui.Enabled = false end
                for _, route in ipairs(recorder.Routes) do route.Gui.Enabled = false end
                if not recorder.ReadToggle('LH_P10S4T1') then
                    recorder.SelectedRecording = nil
                    return
                end
                local context = recorder.ResolveMapContext()
                if not context then
                    recorder.SelectedRecording = nil
                    return
                end
                if recorder.WaypointDirty or recorder.WaypointMapName ~= context.MapName
                    or recorder.WaypointMapModel ~= context.MapModel
                    or recorder.WaypointAnchor ~= context.MapAnchor then
                    recorder.RebuildWaypoints(context)
                end
                local hideUi = recorder.ReadToggle('LH_P10S4T2')
                if recorder.ActivatedRecording then
                    recorder.SelectedRecording = recorder.ActivatedRecording
                    if not hideUi then
                        for _, route in ipairs(recorder.Routes) do
                            if route.Recording == recorder.ActivatedRecording then
                                route.Label.TextColor3 = Color3.new(0, 1, 0)
                                route.Gui.Enabled = true
                                break
                            end
                        end
                    end
                    return
                end
                local nearest, nearestDistance = nil, math.huge
                for _, marker in ipairs(recorder.Markers) do
                    local distance = (marker.Position - context.RootPart.Position).Magnitude
                    if distance < recorder.ReadNumber('LH_P10S4S1', 3) and distance < nearestDistance then
                        nearest, nearestDistance = marker, distance
                    end
                end
                if nearest then
                    local camera = Workspace.CurrentCamera
                    local bestDistance = math.huge
                    recorder.SelectedRecording = nil
                    for _, route in ipairs(recorder.Routes) do
                        if route.Marker == nearest then
                            route.Fulfillable = recorder.LoadoutFulfilled(route.Recording)
                            local point, visible = camera and camera:WorldToViewportPoint(route.Position) or nil, false
                            if point then visible = point.Z >= 0 end
                            if route.Fulfillable and visible then
                                local screenDistance = (Vector2.new(point.X, point.Y) - camera.ViewportSize / 2).Magnitude
                                if screenDistance < bestDistance then
                                    bestDistance = screenDistance
                                    recorder.SelectedRecording = route.Recording
                                end
                            end
                        end
                    end
                    for _, route in ipairs(recorder.Routes) do
                        if route.Marker == nearest then
                            route.Label.TextColor3 = not route.Fulfillable and Color3.new(1, 0, 0)
                                or route.Recording == recorder.SelectedRecording and Color3.new(1, 1, 0)
                                or Color3.new(1, 1, 1)
                            route.Gui.Enabled = not hideUi
                        end
                    end
                    return
                end
                recorder.SelectedRecording = nil
                if not hideUi then
                    local renderDistance = recorder.ReadNumber('LH_P10S4S2', 50)
                    for _, marker in ipairs(recorder.Markers) do
                        local distance = (marker.Position - context.RootPart.Position).Magnitude
                        if distance < renderDistance then
                            marker.Label.Text = string.format('%s  %.0fm',
                                #marker.Recordings == 1 and '1 recording'
                                    or tostring(#marker.Recordings) .. ' recordings',
                                distance)
                            marker.Gui.Enabled = true
                        end
                    end
                end
            end
            function LuaHookRuntime.MovementRecorder.Begin(kind)
                local recorder = LuaHookRuntime.MovementRecorder
                if not recorder.ReadToggle('LH_P10S4T1') then
                    recorder.SetToggle(kind == 'Record' and 'LH_P10S4T4' or 'LH_P10S4T5', false)
                    return false
                end
                if recorder.IsRoundActive() then
                    return kind == 'Record' and recorder.StartRecording()
                        or recorder.StartReplay(recorder.SelectedRecording)
                end
                if not recorder.ResolveMapContext() then
                    recorder.Notify('You need to be in a match')
                    recorder.SetToggle(kind == 'Record' and 'LH_P10S4T4' or 'LH_P10S4T5', false)
                    return false
                end
                recorder.PendingKind = kind
                recorder.Notify(kind .. ' will start when the round begins')
                return true
            end
            function LuaHookRuntime.MovementRecorder.OnRecordToggled(value)
                local recorder = LuaHookRuntime.MovementRecorder
                if value then
                    if recorder.Mode ~= 'Idle' or recorder.PendingKind then
                        recorder.Notify((recorder.Mode == 'Playing' or recorder.Mode == 'Aligning')
                            and "Can't record while replaying" or 'Already recording')
                        recorder.SetToggle('LH_P10S4T4', false)
                        return
                    end
                    if not recorder.Begin('Record') then
                        recorder.SetToggle('LH_P10S4T4', false)
                    end
                else
                    if recorder.PendingKind == 'Record' then recorder.PendingKind = nil end
                    recorder.StopRecording(true, true)
                end
            end
            function LuaHookRuntime.MovementRecorder.OnReplayToggled(value)
                local recorder = LuaHookRuntime.MovementRecorder
                if value then
                    if recorder.Mode ~= 'Idle' or recorder.PendingKind then
                        recorder.Notify(recorder.Mode == 'Recording'
                            and "Can't replay while recording" or 'Already replaying')
                        recorder.SetToggle('LH_P10S4T5', false)
                        return
                    end
                    if not recorder.SelectedRecording then
                        recorder.Notify('Stand near a recording marker first')
                        recorder.SetToggle('LH_P10S4T5', false)
                        return
                    end
                    if not recorder.Begin('Replay') then
                        recorder.SetToggle('LH_P10S4T5', false)
                    end
                else
                    if recorder.PendingKind == 'Replay' then recorder.PendingKind = nil end
                    recorder.StopReplay('Stopped', true)
                end
            end
            function LuaHookRuntime.MovementRecorder.OnEnabledToggled(value)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                recorder.WaypointDirty = true
                if value then
                    return
                end
                recorder.PendingKind = nil
                recorder.StopRecording(false, false)
                recorder.StopReplay('Stopped', false)
                recorder.SetToggle('LH_P10S4T4', false)
                recorder.SetToggle('LH_P10S4T5', false)
                recorder.DestroyWaypoints()
            end
            function LuaHookRuntime.MovementRecorder.HandleReplicate(_, objectId, enumToken, ...)
                local recorder = LuaHookRuntime.MovementRecorder
                if enumToken ~= recorder.RoundToken then
                    return
                end
                local fighter = ResolveLocalFighter()
                local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                if type(data) == 'table' and rawget(data, 'ObjectID') ~= objectId then
                    return
                end
                local status = ...
                recorder.RoundActive = status == 'RoundStarted'
            end
            function LuaHookRuntime.MovementRecorder.BindRoundSignal()
                local recorder = LuaHookRuntime.MovementRecorder
                if recorder.RoundBindingPending or not Connections then
                    return
                end
                recorder.RoundBindingPending = true
                recorder.RoundBindingGeneration = recorder.RoundBindingGeneration + 1
                local generation = recorder.RoundBindingGeneration
                BeginReplicatedStateBoot()
                task.spawn(GuardLuaHookCallback('MovementRecorder_BindRound', function()
                    local deadline = tick() + 30
                    while generation == recorder.RoundBindingGeneration and not ReplicatedStateReady
                        and tick() < deadline do
                        task.wait(0.1)
                    end
                    local enumLibrary = ResolveEnumLibrary()
                    local tokenOk, token = false, nil
                    if enumLibrary and enumLibrary._enum_builder_complete == true
                        and type(enumLibrary.ToEnum) == 'function' then
                        tokenOk, token = pcall(enumLibrary.ToEnum, enumLibrary, 'Status')
                    end
                    local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                    local replication = remotes and remotes:FindFirstChild('Replication')
                    local fighter = replication and replication:FindFirstChild('Fighter')
                    local replicate = fighter and fighter:FindFirstChild('Replicate')
                    if generation == recorder.RoundBindingGeneration and tokenOk and type(token) == 'string'
                        and replicate and replicate:IsA('RemoteEvent') then
                        recorder.RoundToken = token
                        Connections:disconnect({'MovementRecorder_RoundReplicate'})
                        Connections:register('MovementRecorder_RoundReplicate', replicate.OnClientEvent:Connect(
                            GuardLuaHookCallback('MovementRecorder_RoundReplicate', recorder.HandleReplicate)))
                    end
                    recorder.RoundBindingPending = false
                end))
            end
            function LuaHookRuntime.MovementRecorder.Update(deltaTime)
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.LoadPersistence()
                if not recorder.ReadToggle('LH_P10S4T1') then
                    return
                end
                local context = recorder.ResolveMapContext()
                local activeCharacter = recorder.Recording and recorder.Recording.Character
                    or recorder.Replay and recorder.Replay.Character or nil
                if activeCharacter and (not context or context.Character ~= activeCharacter) then


                    recorder.StopRecording(true, false)
                    recorder.StopReplay('Stopped', false)
                    recorder.SetToggle('LH_P10S4T4', false)
                    recorder.SetToggle('LH_P10S4T5', false)
                    return
                end
                if recorder.PendingKind and recorder.IsRoundActive() then
                    local kind = recorder.PendingKind
                    recorder.PendingKind = nil
                    local started = kind == 'Record' and recorder.StartRecording()
                        or recorder.StartReplay(recorder.SelectedRecording)
                    if not started then
                        recorder.SetToggle(kind == 'Record' and 'LH_P10S4T4' or 'LH_P10S4T5', false)
                    end
                end
                if recorder.Mode == 'Recording' then
                    recorder.SampleRecording()
                elseif recorder.Mode == 'Aligning' then
                    recorder.StepAlign(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                elseif recorder.Mode == 'Playing' then
                    recorder.StepPlaying(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                end
            end
            function LuaHookRuntime.MovementRecorder.UpdateRender(deltaTime)
                local recorder = LuaHookRuntime.MovementRecorder
                if not recorder.ReadToggle('LH_P10S4T1') then
                    return
                end
                recorder.UpdateReplayCamera(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                recorder.UpdateWaypoints()
            end
            function LuaHookRuntime.MovementRecorder.IsCameraClaimed()
                local recorder = LuaHookRuntime.MovementRecorder
                return recorder.Replay ~= nil
                    and (recorder.Mode == 'Aligning' or recorder.Mode == 'Playing')
            end
            function LuaHookRuntime.MovementRecorder.Destroy()
                local recorder = LuaHookRuntime.MovementRecorder
                recorder.RoundBindingGeneration = recorder.RoundBindingGeneration + 1
                recorder.RoundBindingPending = false
                if Connections then
                    Connections:disconnect({'MovementRecorder_RoundReplicate'})
                end
                recorder.PendingKind = nil
                recorder.StopRecording(false, false)
                recorder.StopReplay('Stopped', false)
                recorder.DisconnectRecordingInputs()
                recorder.DestroyWaypoints()
                recorder.RoundActive = nil
                recorder.RoundToken = nil
                recorder.PlayerControls = nil
                recorder.InputLibrary = nil
                recorder.MechanicsController = nil
                recorder.Mode = 'Idle'
            end
