            function LuaHookAutoLoadout.ResolveItemLibrary()
                local cachedItemLibrary = LuaHookAutoLoadout.Catalog.ItemLibrary
                if cachedItemLibrary then
                    return cachedItemLibrary
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local itemLibraryModule = modules and modules:FindFirstChild('ItemLibrary')
                if not itemLibraryModule then
                    return nil
                end
                local ok, itemLibrary = pcall(require, itemLibraryModule)
                if not ok or type(itemLibrary) ~= 'table' then
                    return nil
                end
                LuaHookAutoLoadout.Catalog.ItemLibrary = itemLibrary
                return itemLibrary
            end
            function LuaHookAutoLoadout.IsAllowedWeaponName(slotName, weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                if LuaHookAutoLoadout.ExcludedWeaponNames[weaponName] == true then
                    return false
                end
                local slotExclusions = LuaHookAutoLoadout.ExcludedWeaponsBySlot[slotName]
                return not slotExclusions or slotExclusions[weaponName] ~= true
            end
            function LuaHookAutoLoadout.ResolveSeedWeaponValues(slotName)
                local cacheKey = string.format('SeedWeaponValues_%s', slotName)
                local cachedValues = LuaHookAutoLoadout.Catalog[cacheKey]
                if cachedValues then
                    return cachedValues
                end
                local values = {}
                local slotIndex = nil
                for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                    if slotConfig.Name == slotName then
                        slotIndex = slotConfig.SlotIndex
                        break
                    end
                end
                local itemLibrary = LuaHookAutoLoadout.ResolveItemLibrary()
                local slotToClass = itemLibrary and itemLibrary.SlotToClass or nil
                local itemsAlphabetized = itemLibrary and itemLibrary.ItemsAlphabetized or nil
                local items = itemLibrary and itemLibrary.Items or nil
                local classData = type(slotToClass) == 'table' and slotIndex and slotToClass[slotIndex] or nil
                local className = classData and classData.Name or slotName
                if type(itemsAlphabetized) == 'table' and type(items) == 'table' then
                    for _, weaponName in ipairs(itemsAlphabetized) do
                        local weaponData = items[weaponName]
                        if weaponData and weaponData.Class == className and LuaHookAutoLoadout.IsAllowedWeaponName(slotName, weaponName) then
                            values[#values + 1] = weaponName
                        end
                    end
                end
                LuaHookAutoLoadout.Catalog[cacheKey] = values
                return values
            end
            function LuaHookAutoLoadout.ResolveWeaponValues(slotName)
                return LuaHookAutoLoadout.ResolveSeedWeaponValues(slotName)
            end
            function LuaHookAutoLoadout.ResolveMapValues()
                local cachedValues = LuaHookAutoLoadout.Catalog.MapValues
                if cachedValues then
                    return cachedValues
                end
                local values = {}
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local duelLibraryModule = modules and modules:FindFirstChild('DuelLibrary')
                if duelLibraryModule then
                    local ok, duelLibrary = pcall(require, duelLibraryModule)
                    if ok and type(duelLibrary) == 'table' and type(duelLibrary.MapOrder) == 'table' then
                        for _, mapName in ipairs(duelLibrary.MapOrder) do
                            if type(mapName) == 'string' and mapName ~= '' then
                                values[#values + 1] = mapName
                            end
                        end
                    end
                end
                LuaHookAutoLoadout.Catalog.MapValues = values
                return values
            end
            function LuaHookAutoLoadout.ResolveDefaultWeapons()
                local cachedDefaults = LuaHookAutoLoadout.Catalog.DefaultWeapons
                if cachedDefaults then
                    return cachedDefaults
                end
                local defaults = {}
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local constantsModule = modules and modules:FindFirstChild('Constants')
                if constantsModule then
                    local ok, constants = pcall(require, constantsModule)
                    local configuredDefaults = ok and type(constants) == 'table' and constants.DEFAULT_WEAPONS or nil
                    if type(configuredDefaults) == 'table' then
                        for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                            local weaponName = configuredDefaults[slotConfig.SlotIndex]
                                or configuredDefaults[slotConfig.Name]
                            if LuaHookAutoLoadout.IsAllowedWeaponName(slotConfig.Name, weaponName) then
                                defaults[slotConfig.Name] = weaponName
                            end
                        end
                    end
                end
                for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                    if not defaults[slotConfig.Name] then
                        defaults[slotConfig.Name] = LuaHookAutoLoadout.ResolveWeaponValues(slotConfig.Name)[1]
                            or LuaHookAutoLoadout.Unselected
                    end
                end
                LuaHookAutoLoadout.Catalog.DefaultWeapons = defaults
                return defaults
            end
            function LuaHookAutoLoadout.ResolveActiveProfileKeys()
                local mapKey = 'Default'
                if Toggles.LH_P8S5T3 and Toggles.LH_P8S5T3.Value == true then
                    local mapOption = Options.LH_P8S5D7
                    if mapOption and type(mapOption.Value) == 'string' and mapOption.Value ~= '' then
                        mapKey = mapOption.Value
                    end
                end
                local priority = '1'
                if Toggles.LH_P8S5T4 and Toggles.LH_P8S5T4.Value == true then
                    local priorityOption = Options.LH_P8S5D8
                    if priorityOption and table.find(LuaHookAutoLoadout.Priorities, priorityOption.Value) then
                        priority = priorityOption.Value
                    end
                end
                return mapKey, priority
            end
            function LuaHookAutoLoadout.ResolveProfile(mapKey, priority, create)
                mapKey = type(mapKey) == 'string' and mapKey ~= '' and mapKey or 'Default'
                priority = table.find(LuaHookAutoLoadout.Priorities, priority) and priority or '1'
                local mapProfiles = LuaHookAutoLoadoutState.Profiles[mapKey]
                if not mapProfiles and create then
                    mapProfiles = {}
                    LuaHookAutoLoadoutState.Profiles[mapKey] = mapProfiles
                end
                local profile = mapProfiles and mapProfiles[priority] or nil
                if not profile and create then
                    profile = {}
                    local defaultWeapons = LuaHookAutoLoadout.ResolveDefaultWeapons()
                    for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                        profile[slotConfig.Name] = mapKey == 'Default' and priority == '1'
                            and defaultWeapons[slotConfig.Name]
                            or LuaHookAutoLoadout.Unselected
                    end
                    mapProfiles[priority] = profile
                end
                return profile
            end
            function LuaHookAutoLoadout.ResolveActiveProfile(create)
                local mapKey, priority = LuaHookAutoLoadout.ResolveActiveProfileKeys()
                return LuaHookAutoLoadout.ResolveProfile(mapKey, priority, create), mapKey, priority
            end
            function LuaHookAutoLoadout.NormalizeSelection(slotConfig, selection, allowUnselected)
                local values = LuaHookAutoLoadout.ResolveWeaponValues(slotConfig.Name)
                if type(selection) == 'string' then
                    if allowUnselected and selection == LuaHookAutoLoadout.Unselected then
                        return selection
                    end
                    if table.find(values, selection) then
                        return selection
                    end
                elseif type(selection) == 'table' then
                    for _, weaponName in ipairs(values) do
                        if selection[weaponName] == true or table.find(selection, weaponName) then
                            return weaponName
                        end
                    end
                end
                if allowUnselected then
                    return LuaHookAutoLoadout.Unselected
                end
                return LuaHookAutoLoadout.ResolveDefaultWeapons()[slotConfig.Name]
                    or values[1]
                    or LuaHookAutoLoadout.Unselected
            end
            function LuaHookAutoLoadout.ResetState()
                LuaHookAutoLoadoutState.HasRunThisOpen = false
                LuaHookAutoLoadoutState.OpenNonce = LuaHookAutoLoadoutState.OpenNonce + 1
            end
            function LuaHookAutoLoadout.ResolvePagesFrame()
                local playerGui = LP:FindFirstChild('PlayerGui')
                local mainGui = playerGui and playerGui:FindFirstChild('MainGui')
                local mainFrame = mainGui and mainGui:FindFirstChild('MainFrame')
                return mainFrame and mainFrame:FindFirstChild('Pages') or nil
            end
            function LuaHookAutoLoadout.ResolvePageFrame(pageName)
                if type(pageName) ~= 'string' or pageName == '' then
                    return nil
                end
                local pagesFrame = LuaHookAutoLoadout.ResolvePagesFrame()
                local pageFrame = pagesFrame and pagesFrame:FindFirstChild(pageName)
                if pageFrame and pageFrame:IsA('GuiObject') then
                    return pageFrame
                end
                return nil
            end
            function LuaHookAutoLoadout.IsPageFrameVisible(pageFrame)
                return pageFrame and pageFrame.Visible == true and pageFrame.AbsoluteSize.X > 0 and pageFrame.AbsoluteSize.Y > 0
            end
            function LuaHookAutoLoadout.ResolveSavedSelection(slotConfig)
                if not slotConfig then
                    return nil
                end
                local profile, mapKey, priority = LuaHookAutoLoadout.ResolveActiveProfile(true)
                local allowUnselected = mapKey ~= 'Default' or priority ~= '1'
                local savedSelection = LuaHookAutoLoadout.NormalizeSelection(
                    slotConfig,
                    profile[slotConfig.Name],
                    allowUnselected
                )
                profile[slotConfig.Name] = savedSelection
                return savedSelection
            end
            function LuaHookAutoLoadout.SyncSavedSelection(slotConfig)
                if not slotConfig then
                    return
                end
                local option = Options[slotConfig.OptionId]
                if not option then
                    return
                end
                local profile, mapKey, priority = LuaHookAutoLoadout.ResolveActiveProfile(true)
                local allowUnselected = mapKey ~= 'Default' or priority ~= '1'
                profile[slotConfig.Name] = LuaHookAutoLoadout.NormalizeSelection(
                    slotConfig,
                    option.Value,
                    allowUnselected
                )
            end
            function LuaHookAutoLoadout.ResolveVisibleSelectionValues(slotConfig, values)
                local savedSelection = LuaHookAutoLoadout.ResolveSavedSelection(slotConfig)
                if table.find(values or {}, savedSelection) then
                    return savedSelection
                end
                return (values or {})[1]
            end
            function LuaHookAutoLoadout.ResolvePageController(pageName)
                if type(pageName) ~= 'string' or pageName == '' then
                    return nil
                end
                local cachedPageController = LuaHookAutoLoadout.Catalog[pageName]
                if cachedPageController then
                    return cachedPageController
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local pages = modules and modules:FindFirstChild('Pages')
                local pageModule = pages and pages:FindFirstChild(pageName)
                if not pageModule then
                    return nil
                end
                local ok, pageController = pcall(require, pageModule)
                if not ok or type(pageController) ~= 'table' then
                    return nil
                end
                LuaHookAutoLoadout.Catalog[pageName] = pageController
                return pageController
            end
            function LuaHookAutoLoadout.ResolveOpenPageController()
                for _, pageName in ipairs(LuaHookAutoLoadout.PageNames) do
                    local pageFrame = LuaHookAutoLoadout.ResolvePageFrame(pageName)
                    if LuaHookAutoLoadout.IsPageFrameVisible(pageFrame) then
                        local pageController = LuaHookAutoLoadout.ResolvePageController(pageName)
                        if pageController then
                            return pageName, pageController
                        end
                    end
                end
                return nil, nil
            end
            function LuaHookAutoLoadout.ReadVisibleWeaponValues(pageController)
                if not pageController then
                    return nil, nil
                end
                local slotConfig = LuaHookAutoLoadout.SlotOrder[pageController._current_slot]
                if not slotConfig then
                    return nil, nil
                end
                local listFrame = pageController.List
                local container = listFrame and listFrame:FindFirstChild('Container')
                if not container then
                    return slotConfig, nil
                end
                local orderedValues = {}
                for _, child in ipairs(container:GetChildren()) do
                    if child.Name == 'WeaponSlot' and child.Visible ~= false then
                        local button = child:FindFirstChild('Button')
                        local title = button and button:FindFirstChild('Title')
                        local locked = button and button:FindFirstChild('Locked')
                        local banned = button and button:FindFirstChild('Banned')
                        local weaponName = title and title.Text or nil
                        if type(weaponName) == 'string' then
                            weaponName = weaponName:match('^%s*(.-)%s*$')
                        end
                        if LuaHookAutoLoadout.IsAllowedWeaponName(slotConfig.Name, weaponName) and (not locked or locked.Visible ~= true) and (not banned or banned.Visible ~= true) then
                            orderedValues[#orderedValues + 1] = {
                                Name = weaponName,
                                Order = child.LayoutOrder,
                            }
                        end
                    end
                end
                table.sort(orderedValues, function(left, right)
                    if left.Order == right.Order then
                        return left.Name < right.Name
                    end
                    return left.Order < right.Order
                end)
                local seen = {}
                local values = {}
                for _, entry in ipairs(orderedValues) do
                    if seen[entry.Name] ~= true then
                        seen[entry.Name] = true
                        values[#values + 1] = entry.Name
                    end
                end
                return slotConfig, values
            end
            function LuaHookAutoLoadout.RefreshDropdownOption(slotConfig)
                if not slotConfig then
                    return
                end
                local option = Options[slotConfig.OptionId]
                if not option or type(option.SetValues) ~= 'function' then
                    return
                end
                local sourceValues = LuaHookAutoLoadout.ResolveWeaponValues(slotConfig.Name)
                local _, mapKey, priority = LuaHookAutoLoadout.ResolveActiveProfile(true)
                local values = {}
                if mapKey ~= 'Default' or priority ~= '1' then
                    values[#values + 1] = LuaHookAutoLoadout.Unselected
                end
                for _, weaponName in ipairs(sourceValues) do
                    values[#values + 1] = weaponName
                end
                local visibleSelectionValue = LuaHookAutoLoadout.ResolveVisibleSelectionValues(slotConfig, values)
                LuaHookAutoLoadoutState.RefreshingDropdownValues = LuaHookAutoLoadoutState.RefreshingDropdownValues + 1
                pcall(function()
                    option:SetValues(values)
                end)
                if type(option.SetValue) == 'function' then
                    pcall(function()
                        option:SetValue(visibleSelectionValue)
                    end)
                end
                LuaHookAutoLoadoutState.RefreshingDropdownValues = LuaHookAutoLoadoutState.RefreshingDropdownValues - 1
            end
            function LuaHookAutoLoadout.RefreshDropdownOptions()
                for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                    LuaHookAutoLoadout.RefreshDropdownOption(slotConfig)
                end
            end
            function LuaHookAutoLoadout.CapturePageWeaponValues(pageController)
                local slotConfig, values = LuaHookAutoLoadout.ReadVisibleWeaponValues(pageController)
                if not slotConfig or type(values) ~= 'table' or #values <= 0 then
                    return false
                end
                local previousValues = LuaHookAutoLoadout.LiveValuesBySlot[slotConfig.Name]
                local hasChanged = type(previousValues) ~= 'table' or #previousValues ~= #values
                if not hasChanged and previousValues then
                    for index, weaponName in ipairs(values) do
                        if previousValues[index] ~= weaponName then
                            hasChanged = true
                            break
                        end
                    end
                end
                if not hasChanged then
                    return false
                end
                LuaHookAutoLoadout.LiveValuesBySlot[slotConfig.Name] = values
                LuaHookAutoLoadout.RefreshDropdownOption(slotConfig)
                return true
            end
            function LuaHookAutoLoadout.BindChosenSlotInputs(pageName, pageController)
                local chosenWeaponSlots = pageController and pageController._chosen_weapon_slots
                if type(chosenWeaponSlots) ~= 'table' then
                    return
                end
                for slotIndex, chosenSlot in ipairs(chosenWeaponSlots) do
                    local button = chosenSlot and chosenSlot:FindFirstChild('Button')
                    if button and button:IsA('GuiButton') then
                        Connections:register(string.format('AutoLoadout_%s_ChosenSlot_%d', pageName, slotIndex), button.Activated:Connect(GuardLuaHookCallback(string.format('AutoLoadout_%s_ChosenSlot_%d', pageName, slotIndex), function()
                            task.defer(function()
                                LuaHookAutoLoadout.CapturePageWeaponValues(pageController)
                            end)
                        end)))
                    end
                end
            end
            function LuaHookAutoLoadout.ResolveSlotSelection(slotConfig)
                if not slotConfig then
                    return nil
                end
                local selectedWeaponName = LuaHookAutoLoadout.ResolveSavedSelection(slotConfig)
                return selectedWeaponName ~= LuaHookAutoLoadout.Unselected and selectedWeaponName or nil
            end
            function LuaHookAutoLoadout.IsWeaponSelected(slotConfig, weaponName)
                if not slotConfig or type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                local savedSelection = LuaHookAutoLoadout.ResolveSavedSelection(slotConfig)
                return savedSelection == weaponName
            end
            function LuaHookAutoLoadout.ResolveCurrentMapName()
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local duelControllerModule = controllers and controllers:FindFirstChild('DuelController')
                if duelControllerModule and IsReplicatedStateReady() then
                    local ok, duelController = pcall(require, duelControllerModule)
                    local duel = ok and type(duelController) == 'table' and duelController.CurrentObject or nil
                    if duel then
                        if type(duel.GetMapName) == 'function' then
                            local mapOk, mapName = pcall(duel.GetMapName, duel)
                            if mapOk and type(mapName) == 'string' and mapName ~= '' then
                                return mapName
                            end
                        end
                        if type(duel.Get) == 'function' then
                            for _, key in ipairs({'MapName', 'Map'}) do
                                local mapOk, mapName = pcall(duel.Get, duel, key)
                                if mapOk and type(mapName) == 'string' and mapName ~= '' then
                                    return mapName
                                end
                            end
                        end
                        local mapName = duel.MapName or duel.Map
                        if type(mapName) == 'string' and mapName ~= '' then
                            return mapName
                        end
                    end
                end
                for _, attributeName in ipairs({'MapName', 'MatchMap'}) do
                    local mapName = Workspace:GetAttribute(attributeName)
                    if type(mapName) == 'string' and mapName ~= '' then
                        return mapName
                    end
                end
                return nil
            end
            function LuaHookAutoLoadout.ResolveRuntimeMapKey()
                if Toggles.LH_P8S5T3 and Toggles.LH_P8S5T3.Value == true then
                    return LuaHookAutoLoadout.ResolveCurrentMapName()
                end
                return 'Default'
            end
            function LuaHookAutoLoadout.IsRuntimeSelectionAvailable(slotConfig, weaponName)
                if not slotConfig or type(weaponName) ~= 'string' or weaponName == ''
                    or weaponName == LuaHookAutoLoadout.Unselected then
                    return false
                end
                local liveValues = LuaHookAutoLoadout.LiveValuesBySlot[slotConfig.Name]
                return type(liveValues) ~= 'table' or #liveValues == 0 or table.find(liveValues, weaponName) ~= nil
            end
            function LuaHookAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                if not slotConfig or type(profile) ~= 'table' then
                    return nil
                end
                local selectedWeaponName = LuaHookAutoLoadout.NormalizeSelection(slotConfig, profile[slotConfig.Name], true)
                return LuaHookAutoLoadout.IsRuntimeSelectionAvailable(slotConfig, selectedWeaponName)
                    and selectedWeaponName
                    or nil
            end
            function LuaHookAutoLoadout.BuildChosenWeapons(maxSlots)
                local mapKey = LuaHookAutoLoadout.ResolveRuntimeMapKey()
                if not mapKey then
                    return nil
                end
                local chosenWeapons = {}
                if Toggles.LH_P8S5T4 and Toggles.LH_P8S5T4.Value == true then
                    for priorityIndex = #LuaHookAutoLoadout.Priorities, 1, -1 do
                        local priority = LuaHookAutoLoadout.Priorities[priorityIndex]
                        local profile = LuaHookAutoLoadout.ResolveProfile(mapKey, priority, true)
                        for slotIndex = 1, maxSlots do
                            local slotConfig = LuaHookAutoLoadout.SlotOrder[slotIndex]
                            local selectedWeaponName = LuaHookAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                            if selectedWeaponName then
                                chosenWeapons[slotConfig.SlotIndex] = selectedWeaponName
                            end
                        end
                    end
                else
                    local profile = LuaHookAutoLoadout.ResolveProfile(mapKey, '1', true)
                    for slotIndex = 1, maxSlots do
                        local slotConfig = LuaHookAutoLoadout.SlotOrder[slotIndex]
                        local selectedWeaponName = LuaHookAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                        if not selectedWeaponName then
                            return nil
                        end
                        chosenWeapons[slotConfig.SlotIndex] = selectedWeaponName
                    end
                end
                for slotIndex = 1, maxSlots do
                    local slotConfig = LuaHookAutoLoadout.SlotOrder[slotIndex]
                    if not chosenWeapons[slotConfig.SlotIndex] then
                        return nil
                    end
                end
                return chosenWeapons
            end
            function LuaHookAutoLoadout.ApplyPageController(pageController)
                if not pageController or pageController._is_open ~= true then
                    return nil
                end
                local pageFrame = pageController.PageFrame
                if not pageFrame or pageFrame.Visible ~= true or pageFrame.AbsoluteSize.X <= 0 or pageFrame.AbsoluteSize.Y <= 0 then
                    return nil
                end
                local chosenWeaponSlots = pageController._chosen_weapon_slots
                if type(chosenWeaponSlots) ~= 'table' then
                    return nil
                end
                local maxSlots = math.min(#pageController._chosen_weapon_slots, #LuaHookAutoLoadout.SlotOrder)
                if maxSlots <= 0 then
                    return nil
                end
                LuaHookAutoLoadout.CapturePageWeaponValues(pageController)
                local chosenWeapons = LuaHookAutoLoadout.BuildChosenWeapons(maxSlots)
                if not chosenWeapons then
                    return false
                end
                pageController._chosen_weapons = chosenWeapons
                local ok, finishError = pcall(pageController.Finish, pageController)
                if not ok then
                    ReportLuaHookRuntimeLifecycleIssue('auto_loadout_finish', finishError)
                end
                return ok
            end
            function LuaHookAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, attempt)
                if not pageController then
                    return
                end
                if openNonce ~= LuaHookAutoLoadoutState.OpenNonce then
                    return
                end
                if not LuaHookAutoLoadout.IsEnabled() or LuaHookAutoLoadoutState.HasRunThisOpen then
                    return
                end
                local appliedPage = LuaHookAutoLoadout.ApplyPageController(pageController)
                if appliedPage == true then
                    LuaHookAutoLoadoutState.HasRunThisOpen = true
                    return
                end
                if attempt >= LuaHookAutoLoadout.OpenRetryLimit then
                    return
                end
                task.delay(LuaHookAutoLoadout.OpenRetryDelay, GuardLuaHookCallback(string.format('AutoLoadout_%s_Retry_%d', pageName, attempt), function()
                    LuaHookAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, attempt + 1)
                end))
            end
            function LuaHookAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
                if not pageController or not LuaHookAutoLoadout.IsEnabled() then
                    return
                end
                local openNonce = LuaHookAutoLoadoutState.OpenNonce + 1
                LuaHookAutoLoadoutState.OpenNonce = openNonce
                LuaHookAutoLoadoutState.HasRunThisOpen = false
                task.defer(GuardLuaHookCallback(string.format('AutoLoadout_%s_Open', pageName), function()
                    LuaHookAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, 1)
                end))
            end
            function LuaHookAutoLoadout.QueueVisiblePageSubmit()
                if not LuaHookAutoLoadout.IsEnabled() then
                    return
                end
                local pageName, pageController = LuaHookAutoLoadout.ResolveOpenPageController()
                if not pageController then
                    return
                end
                LuaHookAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
            end
            function LuaHookAutoLoadout.BindPageController(pageName, pageController)
                local boundPageControllers = LuaHookAutoLoadoutState.BoundPageControllers
                if boundPageControllers[pageName] == true then
                    return
                end
                pageController = pageController or LuaHookAutoLoadout.ResolvePageController(pageName)
                if not pageController then
                    return
                end
                boundPageControllers[pageName] = true
                LuaHookAutoLoadout.BindChosenSlotInputs(pageName, pageController)
            end
            function LuaHookAutoLoadout.HandlePageFrameVisibility(pageName)
                local pageFrame = LuaHookAutoLoadout.ResolvePageFrame(pageName)
                if not LuaHookAutoLoadout.IsPageFrameVisible(pageFrame) then
                    LuaHookAutoLoadout.ResetState()
                    return
                end
                local pageController = LuaHookAutoLoadout.ResolvePageController(pageName)
                if not pageController then
                    return
                end
                LuaHookAutoLoadout.BindPageController(pageName, pageController)
                LuaHookAutoLoadout.CapturePageWeaponValues(pageController)
                LuaHookAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
            end
            function LuaHookAutoLoadout.BindPageFrame(pageName, pageFrame)
                local boundPageFrames = LuaHookAutoLoadoutState.BoundPageFrames
                if boundPageFrames[pageName] == true then
                    return
                end
                pageFrame = pageFrame or LuaHookAutoLoadout.ResolvePageFrame(pageName)
                if not pageFrame then
                    return
                end
                boundPageFrames[pageName] = true
                Connections:register(string.format('AutoLoadout_%s_Visible', pageName), pageFrame:GetPropertyChangedSignal('Visible'):Connect(GuardLuaHookCallback(string.format('AutoLoadout_%s_Visible', pageName), function()
                    LuaHookAutoLoadout.HandlePageFrameVisibility(pageName)
                end)))
                if LuaHookAutoLoadout.IsPageFrameVisible(pageFrame) then
                    LuaHookAutoLoadout.HandlePageFrameVisibility(pageName)
                end
            end
            function LuaHookAutoLoadout.BindPageControllers()
                task.spawn(GuardLuaHookCallback('AutoLoadout_BindControllers', function()
                    local playerGui = LP:WaitForChild('PlayerGui')
                    local mainGui = playerGui:WaitForChild('MainGui')
                    local mainFrame = mainGui:WaitForChild('MainFrame')
                    local pagesFrame = mainFrame:WaitForChild('Pages')
                    Connections:register('AutoLoadout_PagesChildAdded', pagesFrame.ChildAdded:Connect(GuardLuaHookCallback('AutoLoadout_PagesChildAdded', function(child)
                        if not child or not child:IsA('GuiObject') then
                            return
                        end
                        local pageFrame = child
                        for _, pageName in ipairs(LuaHookAutoLoadout.PageNames) do
                            if pageName == pageFrame.Name then
                                LuaHookAutoLoadout.BindPageFrame(pageName, pageFrame)
                                break
                            end
                        end
                    end)))
                    for _, pageName in ipairs(LuaHookAutoLoadout.PageNames) do
                        LuaHookAutoLoadout.BindPageFrame(pageName)
                    end
                end))
            end
            function LuaHookAutoLoadout.NormalizeProfiles(profiles)
                local normalized = {}
                if type(profiles) == 'table' then
                    for mapKey, mapProfiles in pairs(profiles) do
                        if type(mapKey) == 'string' and mapKey ~= '' and type(mapProfiles) == 'table' then
                            local normalizedMap = {}
                            for _, priority in ipairs(LuaHookAutoLoadout.Priorities) do
                                local profile = mapProfiles[priority]
                                if type(profile) == 'table' then
                                    local normalizedProfile = {}
                                    for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                                        normalizedProfile[slotConfig.Name] = LuaHookAutoLoadout.NormalizeSelection(
                                            slotConfig,
                                            profile[slotConfig.Name] or profile[slotConfig.SlotIndex],
                                            mapKey ~= 'Default' or priority ~= '1'
                                        )
                                    end
                                    normalizedMap[priority] = normalizedProfile
                                end
                            end
                            if next(normalizedMap) ~= nil then
                                normalized[mapKey] = normalizedMap
                            end
                        end
                    end
                end
                LuaHookAutoLoadoutState.Profiles = normalized
                LuaHookAutoLoadout.ResolveProfile('Default', '1', true)
                return normalized
            end
            function LuaHookAutoLoadout.SetConfigName(configName)
                if type(configName) == 'string' and configName ~= '' then
                    LuaHookAutoLoadoutState.ConfigName = configName
                end
            end
            function LuaHookAutoLoadout.LoadProfilesFromConfig()
                local configName = LuaHookAutoLoadoutState.ConfigName
                if type(configName) ~= 'string' or configName == '' then
                    LuaHookAutoLoadout.NormalizeProfiles({})
                    LuaHookAutoLoadout.RefreshDropdownOptions()
                    return false
                end
                local configPath = ScriptPaths.config_path(configName)
                if not isfile(configPath) then
                    LuaHookAutoLoadout.NormalizeProfiles({})
                    LuaHookAutoLoadout.RefreshDropdownOptions()
                    return false
                end
                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                local objects = decodeOk and type(decoded) == 'table' and decoded.objects or nil
                if type(objects) ~= 'table' then
                    return false
                end
                local profiles = nil
                for _, object in ipairs(objects) do
                    if object and object.idx == LuaHookAutoLoadout.ConfigMetadataId then
                        profiles = object.value
                        break
                    end
                end
                LuaHookAutoLoadout.NormalizeProfiles(profiles or {})
                LuaHookAutoLoadout.RefreshDropdownOptions()
                return profiles ~= nil
            end
            function LuaHookAutoLoadout.SaveProfilesToConfig()
                local configName = LuaHookAutoLoadoutState.ConfigName
                if type(configName) ~= 'string' or configName == '' then
                    return false
                end
                local configPath = ScriptPaths.config_path(configName)
                if not isfile(configPath) then
                    return false
                end
                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                if not decodeOk or type(decoded) ~= 'table' then
                    return false
                end
                local existingObjects = type(decoded.objects) == 'table' and decoded.objects or {}
                local mergedObjects = {}
                for _, object in ipairs(existingObjects) do
                    if not object or object.idx ~= LuaHookAutoLoadout.ConfigMetadataId then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end
                mergedObjects[#mergedObjects + 1] = {
                    idx = LuaHookAutoLoadout.ConfigMetadataId,
                    type = 'LuaHookHookMetadata',
                    value = LuaHookAutoLoadout.NormalizeProfiles(LuaHookAutoLoadoutState.Profiles),
                }
                decoded.objects = mergedObjects
                return pcall(function()
                    writefile(configPath, HttpService:JSONEncode(decoded))
                end)
            end
            LuaHookRuntime.BindAutoLoadoutControllers = LuaHookAutoLoadout.BindPageControllers
            LuaHookRuntime.QueueAutoLoadoutSubmission = LuaHookAutoLoadout.QueueVisiblePageSubmit
            LuaHookRuntime.ResolveAutoLoadoutWeaponValues = LuaHookAutoLoadout.ResolveWeaponValues
            LuaHookRuntime.ResolveAutoLoadoutDefaultWeapon = function(slotName)
                return LuaHookAutoLoadout.ResolveDefaultWeapons()[slotName]
            end
            LuaHookRuntime.ResolveAutoLoadoutMapValues = LuaHookAutoLoadout.ResolveMapValues
            LuaHookRuntime.ResolveAutoLoadoutPriorities = function()
                return LuaHookAutoLoadout.Priorities
            end
            LuaHookRuntime.RefreshAutoLoadoutDropdownValues = LuaHookAutoLoadout.RefreshDropdownOptions
            LuaHookRuntime.SyncAutoLoadoutSelection = function(optionId)
                for _, slotConfig in ipairs(LuaHookAutoLoadout.SlotOrder) do
                    if slotConfig.OptionId == optionId then
                        LuaHookAutoLoadout.SyncSavedSelection(slotConfig)
                        break
                    end
                end
            end
            LuaHookRuntime.SetAutoLoadoutConfigName = LuaHookAutoLoadout.SetConfigName
            LuaHookRuntime.LoadAutoLoadoutProfiles = LuaHookAutoLoadout.LoadProfilesFromConfig
            LuaHookRuntime.SaveAutoLoadoutProfiles = LuaHookAutoLoadout.SaveProfilesToConfig
            LuaHookRuntime.ResetAutoLoadoutState = LuaHookAutoLoadout.ResetState
            end
            do
            local LuaHookAutoBan = {
                State = {
                    Controller = nil,
                    BoundDuel = nil,
                    LastVoteType = nil,
                    LastSubmitted = nil,
                },
            }
            function LuaHookAutoBan.IsEnabled()
                return Toggles.LH_P8S5T2 and Toggles.LH_P8S5T2.Value == true
            end
            function LuaHookAutoBan.IsMapVoteEnabled()
                return Toggles.LH_P8S5T5 and Toggles.LH_P8S5T5.Value == true
            end
            function LuaHookAutoBan.IsAnyEnabled()
                return LuaHookAutoBan.IsEnabled() or LuaHookAutoBan.IsMapVoteEnabled()
            end
            function LuaHookAutoBan.Read(object, key)
                if not object then
                    return nil
                end
                if type(object.Get) == 'function' then
                    local ok, value = pcall(object.Get, object, key)
                    if ok then
                        return value
                    end
                end
                return object[key]
            end
            function LuaHookAutoBan.ResolveController()
                if LuaHookAutoBan.State.Controller then
                    return LuaHookAutoBan.State.Controller
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local controllerModule = controllers and controllers:FindFirstChild('DuelController')
                if not controllerModule then
                    return nil
                end
                local ok, controller = pcall(require, controllerModule)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                LuaHookAutoBan.State.Controller = controller
                return controller
            end
            function LuaHookAutoBan.ResolveWeaponValues()
                local values = {}
                local seen = {}
                for _, slotName in ipairs({'Primary', 'Secondary', 'Melee', 'Utility'}) do
                    for _, weaponName in ipairs(LuaHookRuntime.ResolveAutoLoadoutWeaponValues(slotName)) do
                        if type(weaponName) == 'string' and weaponName ~= '' and not seen[weaponName] then
                            seen[weaponName] = true
                            table.insert(values, weaponName)
                        end
                    end
                end
                table.sort(values)
                return values
            end
            function LuaHookAutoBan.IsSelected(optionId, weaponName)
                local option = Options[optionId]
                local selected = option and option.Value
                if type(selected) ~= 'table' then
                    return false
                end
                if selected[weaponName] == true then
                    return true
                end
                for _, selectedName in ipairs(selected) do
                    if selectedName == weaponName then
                        return true
                    end
                end
                return false
            end
            function LuaHookAutoBan.ResolveMapValues()
                return LuaHookRuntime.ResolveAutoLoadoutMapValues()
            end
            function LuaHookAutoBan.IsMapSelected(mapName)
                return LuaHookAutoBan.IsSelected('LH_P8S5D9', mapName)
            end
            function LuaHookAutoBan.ResolveLocalDueler(duel)
                if type(duel.GetDueler) ~= 'function' then
                    return nil
                end
                local ok, dueler = pcall(duel.GetDueler, duel, LP)
                if ok and dueler then
                    return dueler
                end
                ok, dueler = pcall(duel.GetDueler, duel, LP.UserId)
                return ok and dueler or nil
            end
            function LuaHookAutoBan.IsOptionBanned(voteOptions, optionName)
                if type(voteOptions) ~= 'table' or optionName == nil then
                    return false
                end
                for _, option in pairs(voteOptions) do
                    if LuaHookAutoBan.Read(option, 'Name') == optionName then
                        return LuaHookAutoBan.Read(option, 'IsBanned') ~= nil
                    end
                end
                return false
            end
            function LuaHookAutoBan.BansRemaining(duel, voteType)
                local localDueler = LuaHookAutoBan.ResolveLocalDueler(duel)
                local teamId = LuaHookAutoBan.Read(localDueler, 'TeamID')
                if teamId == nil then
                    return 0
                end
                local maxKey = voteType == 'Weapons' and 'MaxWeaponBansPerTeam' or 'MaxMapBansPerTeam'
                local maxBans = tonumber(LuaHookAutoBan.Read(duel, maxKey)) or 0
                local bansByTeam = LuaHookAutoBan.Read(duel, 'VoteBansRemaining')
                local bansUsed = type(bansByTeam) == 'table' and tonumber(bansByTeam[teamId]) or 0
                return maxBans - bansUsed
            end
            function LuaHookAutoBan.TryVote()
                if not LuaHookAutoBan.IsAnyEnabled() then
                    return false, 'disabled'
                end
                local controller = LuaHookAutoBan.ResolveController()
                local duel = LuaHookAutoBan.State.BoundDuel or (controller and controller.CurrentObject)
                if not duel then
                    LuaHookAutoBan.State.LastVoteType = nil
                    LuaHookAutoBan.State.LastSubmitted = nil
                    return false, 'no_duel'
                end
                local voteType = LuaHookAutoBan.Read(duel, 'VoteOptionsType')
                if voteType ~= LuaHookAutoBan.State.LastVoteType then
                    LuaHookAutoBan.State.LastVoteType = voteType
                    LuaHookAutoBan.State.LastSubmitted = nil
                end
                if voteType == nil then
                    return false, 'no_vote'
                end
                local voteOptions = LuaHookAutoBan.Read(duel, 'VoteOptions')
                if type(voteOptions) ~= 'table' or next(voteOptions) == nil then
                    return false, 'no_vote'
                end
                if LuaHookAutoBan.State.LastSubmitted ~= nil
                    and not LuaHookAutoBan.IsOptionBanned(voteOptions, LuaHookAutoBan.State.LastSubmitted) then
                    return false, 'already_voted'
                end
                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local duels = remotes and remotes:FindFirstChild('Duels')
                local voteRemote = duels and duels:FindFirstChild('Vote')
                if not voteRemote or not voteRemote:IsA('RemoteEvent') then
                    return false, 'no_vote_remote'
                end
                if voteType == 'Maps' then
                    if not LuaHookAutoBan.IsMapVoteEnabled() then
                        return false, 'map_vote_disabled'
                    end
                    if not LuaHookAutoBan.ResolveLocalDueler(duel) then
                        return false, 'not_dueler'
                    end
                    if LuaHookAutoBan.Read(duel, 'MaxMapBansPerTeam') ~= nil
                        and LuaHookAutoBan.BansRemaining(duel, 'Maps') <= 0 then
                        return false, 'bans_complete'
                    end
                    for _, option in pairs(voteOptions) do
                        local mapName = LuaHookAutoBan.Read(option, 'Name')
                        if mapName and LuaHookAutoBan.Read(option, 'IsBanned') == nil
                            and LuaHookAutoBan.IsMapSelected(mapName) then
                            LuaHookAutoBan.State.LastSubmitted = mapName
                            local ok, err = pcall(voteRemote.FireServer, voteRemote, mapName)
                            if not ok then
                                LuaHookAutoBan.State.LastSubmitted = nil
                                return false, tostring(err)
                            end
                            return true
                        end
                    end
                    return false, 'no_selected_map'
                end
                if voteType ~= 'Weapons' or not LuaHookAutoBan.IsEnabled() then
                    return false, 'no_weapon_vote'
                end
                local bansRemaining = LuaHookAutoBan.BansRemaining(duel, 'Weapons')
                if bansRemaining <= 0 then
                    return false, 'bans_complete'
                end
                local selectionIds = { 'LH_P8S5D5', 'LH_P8S5D6' }
                local selectionId = selectionIds[#selectionIds - bansRemaining + 1]
                if not selectionId then
                    return false, 'no_ban_list'
                end
                for _, option in pairs(voteOptions) do
                    local weaponName = LuaHookAutoBan.Read(option, 'Name')
                    if weaponName and LuaHookAutoBan.Read(option, 'IsBanned') == nil
                        and LuaHookAutoBan.IsSelected(selectionId, weaponName) then
                        LuaHookAutoBan.State.LastSubmitted = weaponName
                        local ok, err = pcall(voteRemote.FireServer, voteRemote, weaponName)
                        if not ok then
                            LuaHookAutoBan.State.LastSubmitted = nil
                            return false, tostring(err)
                        end
                        return true
                    end
                end
                return false, 'no_selected_option'
            end
            function LuaHookAutoBan.BindDuel(duel)
                if not Connections then
                    return
                end
                Connections:disconnect({
                    'AutoBan_VoteOptionsType',
                    'AutoBan_VoteOptions',
                    'AutoBan_VoteBansRemaining',
                    'AutoBan_MaxWeaponBansPerTeam',
                    'AutoBan_MaxMapBansPerTeam',
                })
                LuaHookAutoBan.State.BoundDuel = duel
                LuaHookAutoBan.State.LastVoteType = nil
                LuaHookAutoBan.State.LastSubmitted = nil
                if not duel or type(duel.GetDataChangedSignal) ~= 'function' then
                    return
                end
                for _, key in ipairs({'VoteOptionsType', 'VoteOptions', 'VoteBansRemaining', 'MaxWeaponBansPerTeam', 'MaxMapBansPerTeam'}) do
                    local ok, signal = pcall(duel.GetDataChangedSignal, duel, key)
                    if ok and signal and type(signal.Connect) == 'function' then
                        Connections:register('AutoBan_' .. key, signal:Connect(GuardLuaHookCallback('AutoBan_' .. key, LuaHookAutoBan.TryVote)))
                    end
                end
                LuaHookAutoBan.TryVote()
            end
            function LuaHookAutoBan.RegisterSignals()
                if not Connections then
                    return
                end
                if not LuaHookAutoBan.IsAnyEnabled() then
                    LuaHookAutoBan.Reset()
                    return
                end
                local controller = LuaHookAutoBan.ResolveController()
                if not controller then
                    return
                end
                if controller.LocalPlayerJoinedDuel and type(controller.LocalPlayerJoinedDuel.Connect) == 'function' then
                    Connections:register('AutoBan_JoinedDuel', controller.LocalPlayerJoinedDuel:Connect(GuardLuaHookCallback('AutoBan_JoinedDuel', function(duel)
                        LuaHookAutoBan.BindDuel(duel or controller.CurrentObject)
                    end)))
                end
                if controller.LocalPlayerLeftDuel and type(controller.LocalPlayerLeftDuel.Connect) == 'function' then
                    Connections:register('AutoBan_LeftDuel', controller.LocalPlayerLeftDuel:Connect(GuardLuaHookCallback('AutoBan_LeftDuel', function()
                        LuaHookAutoBan.BindDuel(nil)
                    end)))
                end
                LuaHookAutoBan.BindDuel(controller.CurrentObject)
            end
            function LuaHookAutoBan.Reset()
                LuaHookAutoBan.State.BoundDuel = nil
                LuaHookAutoBan.State.LastVoteType = nil
                LuaHookAutoBan.State.LastSubmitted = nil
                if Connections then
                    Connections:disconnect({
                        'AutoBan_JoinedDuel',
                        'AutoBan_LeftDuel',
                        'AutoBan_VoteOptionsType',
                        'AutoBan_VoteOptions',
                        'AutoBan_VoteBansRemaining',
                        'AutoBan_MaxWeaponBansPerTeam',
                        'AutoBan_MaxMapBansPerTeam',
                    })
                end
            end
            LuaHookRuntime.ResolveAutoBanWeaponValues = LuaHookAutoBan.ResolveWeaponValues
            LuaHookRuntime.ResolveAutoVoteMapValues = LuaHookAutoBan.ResolveMapValues
            LuaHookRuntime.TryAutoBanVote = LuaHookAutoBan.TryVote
            LuaHookRuntime.RegisterAutoBanSignals = LuaHookAutoBan.RegisterSignals
            LuaHookRuntime.ResetAutoBanState = LuaHookAutoBan.Reset
            end
            do
            local RivalsTripmineAutomation = {
                Entries = setmetatable({}, { __mode = 'k' }),
                DestroyingConnections = setmetatable({}, { __mode = 'k' }),
            }
            function RivalsTripmineAutomation.IsEnabled()
                return Toggles.LH_P8S8T1 and Toggles.LH_P8S8T1.Value == true
            end
            function RivalsTripmineAutomation.Untrack(tripmine)
                local entry = RivalsTripmineAutomation.Entries[tripmine]
                if entry and entry.Hitbox then
                    RivalsTripmineAutomation.Entries[entry.Hitbox] = nil
                end
                RivalsTripmineAutomation.Entries[tripmine] = nil
                local connection = RivalsTripmineAutomation.DestroyingConnections[tripmine]
                if connection then
                    pcall(function() connection:Disconnect() end)
                end
                RivalsTripmineAutomation.DestroyingConnections[tripmine] = nil
            end
            function RivalsTripmineAutomation.Track(tripmine)
                if not tripmine or RivalsTripmineAutomation.Entries[tripmine] then
                    return
                end
                task.spawn(GuardLuaHookCallback('TripmineAutomation_Track', function()
                    local hitbox = tripmine:WaitForChild('Hitbox', 3)
                    if not hitbox or not hitbox:IsA('BasePart') or not tripmine.Parent then
                        return
                    end
                    local entry = {
                        Tripmine = tripmine,
                        Hitbox = hitbox,
                        EnvironmentId = tripmine:GetAttribute('EnvironmentID'),
                        PlacedBy = tripmine:GetAttribute('PlacedByUserID'),
                        TeamId = tripmine:GetAttribute('TeamID'),
                    }
                    RivalsTripmineAutomation.Entries[tripmine] = entry
                    RivalsTripmineAutomation.Entries[hitbox] = entry
                    RivalsTripmineAutomation.DestroyingConnections[tripmine] = hitbox.Destroying:Connect(
                        GuardLuaHookCallback('TripmineAutomation_Destroying', function()
                            RivalsTripmineAutomation.Untrack(tripmine)
                        end)
                    )
                end))
            end
            function RivalsTripmineAutomation.Bind()
                local collectionService = game:GetService('CollectionService')
                Connections:register('TripmineAutomation_Added', collectionService:GetInstanceAddedSignal('SubspaceTripmine'):Connect(
                    GuardLuaHookCallback('TripmineAutomation_Added', RivalsTripmineAutomation.Track)
                ))
                Connections:register('TripmineAutomation_Removed', collectionService:GetInstanceRemovedSignal('SubspaceTripmine'):Connect(
                    GuardLuaHookCallback('TripmineAutomation_Removed', RivalsTripmineAutomation.Untrack)
                ))
                for _, tripmine in ipairs(collectionService:GetTagged('SubspaceTripmine')) do
                    RivalsTripmineAutomation.Track(tripmine)
                end
            end
            function RivalsTripmineAutomation.Update()
                if not RivalsTripmineAutomation.IsEnabled() then
                    return
                end
                if not __luahook_hook_genv.LuaHookHookCaps.gate('Subspace Tripmine Auto Trigger', 'firetouchinterest') then
                    return
                end
                local activeChar = LuaHookRuntime.AcquireActiveCharacter()
                local touchPart = activeChar and (activeChar:FindFirstChild('HitboxBody') or activeChar:FindFirstChild('HumanoidRootPart')) or nil
                if not touchPart or not touchPart:IsA('BasePart') then
                    return
                end
                local fighter = ResolveLocalFighter()
                local localEnvironmentId = ReadFighterValue(fighter, 'EnvironmentID')
                    or activeChar:GetAttribute('EnvironmentID')
                local localTeamId = ReadFighterValue(fighter, 'TeamID')
                    or LP:GetAttribute('TeamID')
                for tripmine, entry in pairs(RivalsTripmineAutomation.Entries) do
                    if tripmine == entry.Tripmine then
                        local hitbox = entry.Hitbox
                        if not hitbox or not hitbox.Parent or not tripmine.Parent then
                            RivalsTripmineAutomation.Untrack(tripmine)
                        else
                            local friendly = entry.PlacedBy == LP.UserId
                            if not friendly and localTeamId ~= nil and entry.TeamId ~= nil then
                                friendly = localTeamId == entry.TeamId
                            end
                            local environmentMatches = localEnvironmentId == entry.EnvironmentId
                            local teamTrigger = Toggles.LH_P8S8T2 and Toggles.LH_P8S8T2.Value == true
                            local expectedTransparency = friendly and 0.5 or 1
                            if environmentMatches
                                and (not friendly or teamTrigger)
                                and hitbox.LocalTransparencyModifier == expectedTransparency then
                                firetouchinterest(hitbox, touchPart, 0)
                                firetouchinterest(hitbox, touchPart, 1)
                                return
                            end
                        end
                    end
                end
            end
            function RivalsTripmineAutomation.Reset()
                for tripmine, entry in pairs(RivalsTripmineAutomation.Entries) do
                    if tripmine == entry.Tripmine then
                        RivalsTripmineAutomation.Untrack(tripmine)
                    end
                end
                if Connections then
                    Connections:disconnect({'TripmineAutomation_Added', 'TripmineAutomation_Removed'})
                end
            end
            LuaHookRuntime.BindTripmineAutomation = RivalsTripmineAutomation.Bind
            LuaHookRuntime.UpdateTripmineAutomation = RivalsTripmineAutomation.Update
            LuaHookRuntime.ResetTripmineAutomation = RivalsTripmineAutomation.Reset
            end
            -- Cosmetic registry assignments live in this implementation block; the
            -- declarations themselves are in the enclosing initializer scope above.
            do
            local DEFAULT_RIVALS_COSMETIC_VALUE = 'Default'
            local RIVALS_COSMETIC_UNSELECTED = 'Unselected'
            local RIVALS_COSMETIC_NONE = 'None'
            local RIVALS_COSMETIC_RANDOM = 'Random'
            local RIVALS_COSMETIC_ALL_WEAPONS = 'All'
            local RIVALS_GET_WEAPON_DATA_SENTINEL = 'GetWeaponData\0ohaio'
            local RIVALS_COSMETIC_SLOT_FRAME_SENTINEL = 'Frame\0rahh'
            local RIVALS_RANK_CHARM_OFF = 'Off'
            local RIVALS_RANK_CHARM_STATE_OPTION_ID = 'P5RANK_STATE'
            local RIVALS_FAVORITES_STATE_OPTION_ID = 'P5FAVORITES_STATE'
            LuaHookCosmetics = {
                Catalog = {},
                SkinOptionIdsByWeapon = {},
                WrapOptionIdsByWeapon = {},
                CharmOptionIdsByWeapon = {},
                FinisherOptionIdsByWeapon = {},
                WrapInvertedOptionIdsByWeapon = {},
                EditorOptionIds = {
                    Weapon = 'P5EDITOR_WEAPON',
                    Skin = 'P5EDITOR_SKIN',
                    Wrap = 'P5EDITOR_WRAP',
                    WrapInverted = 'P5EDITOR_WRAPINV',
                    Charm = 'P5EDITOR_CHARM',
                    Finisher = 'P5EDITOR_FINISHER',
                    RankSeason = 'P5RANK_SEASON',
                    RankName = 'P5RANK_RANK',
                    RankLeaderboard = 'P5RANK_LEADERBOARD',
                },
                FavoriteKinds = {'Skin', 'Wrap', 'Charm'},
                CosmeticPresetPath = 'LuaHookHook/RIVALS Cosmetic Presets.json',
            }
            RivalsEmotes = {
                Catalog = {},
            }
            function LuaHookCosmetics.IsCosmeticValueSelected(value)
                return type(value) == 'string'
                    and value ~= ''
                    and value ~= DEFAULT_RIVALS_COSMETIC_VALUE
                    and value ~= RIVALS_COSMETIC_UNSELECTED
                    and value ~= RIVALS_COSMETIC_NONE
                    and value ~= RIVALS_COSMETIC_RANDOM
            end
            function LuaHookCosmetics.ResolveSentinelValues()
                return {RIVALS_COSMETIC_UNSELECTED, RIVALS_COSMETIC_NONE, RIVALS_COSMETIC_RANDOM}
            end
            function LuaHookCosmetics.NormalizeSelectionValue(value)
                if value == DEFAULT_RIVALS_COSMETIC_VALUE then
                    return RIVALS_COSMETIC_NONE
                end
                return value
            end
            function LuaHookCosmetics.IsCosmeticOptionId(optionId)
                if type(optionId) ~= 'string' then
                    return false
                end
                return optionId:sub(1, 7) == 'P5SKIN_'
                    or optionId:sub(1, 7) == 'P5WRAP_'
                    or optionId:sub(1, 8) == 'P5CHARM_'
                    or optionId:sub(1, 11) == 'P5FINISHER_'
                    or optionId:sub(1, 10) == 'P5WRAPINV_'
                    or optionId == 'P5COS_STATE'
                    or optionId == RIVALS_RANK_CHARM_STATE_OPTION_ID
                    or optionId == RIVALS_FAVORITES_STATE_OPTION_ID
                    or LuaHookCosmetics.IsEditorCosmeticOptionId(optionId)
            end
            function LuaHookCosmetics.IsEditorCosmeticOptionId(optionId)
                for _, editorOptionId in pairs(LuaHookCosmetics.EditorOptionIds) do
                    if optionId == editorOptionId then
                        return true
                    end
                end
                return false
            end
            function LuaHookCosmetics.ResolveEditorOptionId(kind)
                return LuaHookCosmetics.EditorOptionIds[kind]
            end
            function LuaHookCosmetics.IsPlaceholderCatalogName(name)
                return type(name) == 'string' and (name == 'MISSING_WEAPON' or name:match('^MISSING_') ~= nil)
            end
            function LuaHookCosmetics.IsEnabled()
                return Toggles.LH_P5S1T2 and Toggles.LH_P5S1T2.Value == true
            end
            function RivalsEmotes.IsEnabled()
                return LuaHookCosmetics.IsEnabled()
            end
            function LuaHookCosmetics.CloneConfigObject(object)
                if type(object) ~= 'table' then
                    return nil
                end
                local cloned = {}
                for key, value in pairs(object) do
                    cloned[key] = value
                end
                return cloned
            end
            function LuaHookCosmetics.BuildCosmeticData(data, name, cosmeticType)
                if LuaHookCosmetics.IsPlaceholderCatalogName(name) then
                    return nil
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local catalog = type(cosmeticLibrary) == 'table' and cosmeticLibrary.Cosmetics or nil
                local sourceData = type(catalog) == 'table' and catalog[name] or nil
                local nextData = {}
                if type(sourceData) == 'table' then
                    for key, value in pairs(sourceData) do
                        nextData[key] = value
                    end
                elseif type(data) == 'table' then
                    for key, value in pairs(data) do
                        nextData[key] = value
                    end
                end
                nextData.Name = name
                nextData.Type = nextData.Type or cosmeticType
                nextData.Seed = nextData.Seed or math.random(1, 1000000)
                local enumLibrary = ResolveEnumLibrary()
                if enumLibrary and type(enumLibrary.ToEnum) == 'function' then
                    local ok, enumValue = pcall(enumLibrary.ToEnum, enumLibrary, name)
                    if ok and enumValue ~= nil then
                        nextData.Enum = enumValue
                        nextData.ObjectID = enumValue
                    end
                end
                if nextData.Inverted == nil then
                    nextData.Inverted = false
                end
                return nextData
            end
            function LuaHookCosmetics.HasRenderableDescendant(instance)
                if not instance then
                    return false
                end
                if instance:IsA('BasePart') then
                    return true
                end
                return instance:FindFirstChildWhichIsA('BasePart', true) ~= nil
            end
            function LuaHookCosmetics.HasVisibleRenderableDescendant(instance)
                if not instance then
                    return false
                end
                if instance:IsA('BasePart') then
                    return instance.Transparency < 1
                end
                for _, descendant in ipairs(instance:GetDescendants()) do
                    if descendant:IsA('BasePart') and descendant.Transparency < 1 then
                        return true
                    end
                end
                return false
            end
            function LuaHookCosmetics.IsModelContainer(instance)
                return instance and (instance:IsA('Model') or instance:IsA('Folder')) and LuaHookCosmetics.HasRenderableDescendant(instance)
            end
            function LuaHookCosmetics.SafeClone(instance)
                if not instance then
                    return nil
                end
                local changedArchivableInstances = {}
                if instance.Archivable == false then
                    changedArchivableInstances[#changedArchivableInstances + 1] = instance
                    instance.Archivable = true
                end
                for _, descendant in ipairs(instance:GetDescendants()) do
                    if descendant.Archivable == false then
                        changedArchivableInstances[#changedArchivableInstances + 1] = descendant
                        descendant.Archivable = true
                    end
                end
                local ok, clone = pcall(function()
                    return instance:Clone()
                end)
                for _, changedInstance in ipairs(changedArchivableInstances) do
                    if changedInstance then
                        changedInstance.Archivable = false
                    end
                end
                if ok and clone then
                    return clone
                end
                return nil
            end
            function LuaHookCosmetics.AnchorPreviewDescendants(instance)
                if not instance then
                    return
                end
                if instance:IsA('BasePart') then
                    instance.Anchored = true
                end
                for _, descendant in ipairs(instance:GetDescendants()) do
                    if descendant:IsA('BasePart') then
                        descendant.Anchored = true
                    end
                end
            end
