            function LuaHookCosmetics.ResolveWeaponNames()
                local cachedWeaponNames = LuaHookCosmetics.Catalog.WeaponNames
                if cachedWeaponNames then
                    return cachedWeaponNames
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local weaponNames = {}
                local seenWeaponNames = {}
                if type(cosmetics) == 'table' then
                    for _, cosmeticData in pairs(cosmetics) do
                        local weaponName = type(cosmeticData) == 'table' and cosmeticData.ItemName or nil
                        if type(cosmeticData) == 'table' and cosmeticData.Type == 'Skin' and type(weaponName) == 'string' and weaponName ~= '' and not LuaHookCosmetics.IsPlaceholderCatalogName(weaponName) and seenWeaponNames[weaponName] ~= true and LuaHookCosmetics.ResolveWeaponTemplate(weaponName) then
                            seenWeaponNames[weaponName] = true
                            weaponNames[#weaponNames + 1] = weaponName
                        end
                    end
                end
                table.sort(weaponNames)
                LuaHookCosmetics.Catalog.WeaponNames = weaponNames
                return weaponNames
            end
            function LuaHookCosmetics.ResolveEditorWeaponNames()
