                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = LuaHookCosmetics.ResolveSentinelValues()
