                    local skinNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if type(cosmeticData) == 'table' and cosmeticData.Type == 'Skin' and cosmeticData.ItemName == weaponName and not LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            skinNames[#skinNames + 1] = cosmeticName
                        end
                    end
                    table.sort(skinNames)
                    for _, skinName in ipairs(skinNames) do
                        values[#values + 1] = skinName
                    end
                end
                LuaHookCosmetics.Catalog[cacheKey] = values
                return values
            end
