            function LuaHookCosmetics.ResolveCharmValues()
                local cachedCharmValues = LuaHookCosmetics.Catalog.CharmValues
                if cachedCharmValues then
                    return cachedCharmValues
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = LuaHookCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local charmNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if type(cosmeticData) == 'table' and cosmeticData.Type == 'Charm' and not LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            charmNames[#charmNames + 1] = cosmeticName
                        end
                    end
                    table.sort(charmNames)
                    for _, charmName in ipairs(charmNames) do
