                LuaHookCosmetics.Catalog.CharmValues = values
                return values
            end
            function LuaHookCosmetics.ResolveRankCharmCatalog()
                local cached = LuaHookCosmetics.Catalog.RankCharmCatalog
                if cached then
                    return cached
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local seasonLibraryModule = modules and modules:FindFirstChild('SeasonLibrary')
                if not seasonLibraryModule then
                    return nil
                end
                local ok, seasonLibrary = pcall(require, seasonLibraryModule)
                local currentSeason = ok and type(seasonLibrary) == 'table' and seasonLibrary.CurrentSeason or nil
                local rankProfile = type(currentSeason) == 'table' and currentSeason.RankProfile or nil
                local ranksOrder = type(rankProfile) == 'table' and rankProfile.RanksOrder or nil
                local ranks = type(rankProfile) == 'table' and rankProfile.Ranks or nil
                local seasonsByVersion = type(seasonLibrary) == 'table' and seasonLibrary.SeasonsByVersion or nil
                if type(ranksOrder) ~= 'table' or type(ranks) ~= 'table' or type(seasonsByVersion) ~= 'table' then
                    return nil
                end
                local rankNames = {}
                local ranksByName = {}
                for _, rankName in ipairs(ranksOrder) do
                    local rankData = ranks[rankName]
                    if type(rankName) == 'string' and type(rankData) == 'table' then
                        rankNames[#rankNames + 1] = rankName
                        ranksByName[rankName] = {
                            Name = rankName,
                            RequiredELO = rankData.RequiredELO,
                            RequiresLeaderboard = rankData.RequiredELOLeaderboardRanking ~= nil,
                        }
                    end
                end
                local versions = {}
                for version in pairs(seasonsByVersion) do
                    versions[#versions + 1] = version
                end
                table.sort(versions)
                local seasonEntries = {}
                local seasonLabels = {}
                local seasonByLabel = {}
                local seasonByCharmName = {}
                for _, version in ipairs(versions) do
                    local seasonData = seasonsByVersion[version]
                    if type(seasonData) == 'table' then
                        local charmName = string.format('Season %s', tostring(version))
                        local label = string.format('Season %s (%s)', tostring(version), tostring(seasonData.Name))
                        local entry = {
                            Version = version,
                            CharmName = charmName,
                            Label = label,
                        }
                        seasonEntries[#seasonEntries + 1] = entry
                        seasonLabels[#seasonLabels + 1] = label
                        seasonByLabel[label] = charmName
                        seasonByCharmName[charmName] = entry
                    end
                end
                local catalog = {
                    RankNames = rankNames,
                    RanksByName = ranksByName,
                    SeasonEntries = seasonEntries,
                    SeasonLabels = seasonLabels,
                    SeasonByLabel = seasonByLabel,
                    SeasonByCharmName = seasonByCharmName,
                }
                LuaHookCosmetics.Catalog.RankCharmCatalog = catalog
                return catalog
            end
            function LuaHookCosmetics.ResolveRankCharmSeasonValues()
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                return catalog and table.clone(catalog.SeasonLabels) or {}
            end
            function LuaHookCosmetics.ResolveRankCharmRankValues()
                local values = {RIVALS_RANK_CHARM_OFF}
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                for _, rankName in ipairs(catalog and catalog.RankNames or {}) do
                    values[#values + 1] = rankName
                end
                return values
            end
            function LuaHookCosmetics.IsSeasonRankCharm(charmName)
                return type(charmName) == 'string'
                    and #charmName >= 8
                    and charmName:sub(1, 7) == 'Season '
                    and tonumber(charmName:sub(8)) ~= nil
            end
            function LuaHookCosmetics.ParseRankCharmLeaderboardRank(value)
                local trimmed = tostring(value or ''):match('^%s*(.-)%s*$')
                if not trimmed or trimmed == '' then
                    return nil
                end
                local rank = tonumber(trimmed)
                if not rank or rank < 1 then
                    return nil
                end
                return math.floor(rank)
            end
            function LuaHookCosmetics.BuildRankCharmMetadata(charmName)
                if not LuaHookCosmetics.IsSeasonRankCharm(charmName) then
                    return nil
                end
                local override = LuaHookCosmeticsState.RankCharmOverridesBySeason[charmName]
                local catalog = type(override) == 'table' and LuaHookCosmetics.ResolveRankCharmCatalog() or nil
                local rank = catalog and catalog.RanksByName[override.rankName] or nil
                if not rank then
                    return nil
                end
                local leaderboardRank = override.leaderboardRank
                if rank.Name == 'Unranked' then
                    return {
                        SeasonELO = nil,
                        SeasonLeaderboardRank = leaderboardRank,
                    }
                end
                if rank.RequiresLeaderboard and leaderboardRank == nil then
                    leaderboardRank = 1
                end
                return {
                    SeasonELO = rank.RequiredELO,
                    SeasonLeaderboardRank = leaderboardRank,
                }
            end
            function LuaHookCosmetics.PatchRankCharmPayload(payload)
                if type(payload) ~= 'table' then
                    return nil
                end
                local metadata = LuaHookCosmetics.BuildRankCharmMetadata(payload.Name)
                if not metadata then
                    return nil
                end
                local patched = table.clone(payload)
                patched.Metadata = metadata
                return patched
            end
            function LuaHookCosmetics.NormalizeRankCharmOverrides(value)
                local normalized = {}
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                if type(value) ~= 'table' or not catalog then
                    return normalized
                end
                local function addOverride(charmName, override)
                    if not LuaHookCosmetics.IsSeasonRankCharm(charmName)
                        or not catalog.SeasonByCharmName[charmName]
                        or type(override) ~= 'table' then
                        return
                    end
                    local rankName = type(override.rankName) == 'string' and override.rankName or nil
                    if not rankName or not catalog.RanksByName[rankName] then
                        return
                    end
                    local leaderboardRank = LuaHookCosmetics.ParseRankCharmLeaderboardRank(override.leaderboardRank)
                    normalized[charmName] = {
                        rankName = rankName,
                        leaderboardRank = leaderboardRank,
                    }
                end
                if value.rankName ~= nil or value.leaderboardRank ~= nil then
                    for _, season in ipairs(catalog.SeasonEntries) do
                        addOverride(season.CharmName, value)
                    end
                    return normalized
                end
                for charmName, override in pairs(value) do
                    addOverride(charmName, override)
                end
                return normalized
            end
            function LuaHookCosmetics.ResolveSelectedRankCharmSeason()
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                if not catalog then
                    return nil
                end
                local charmName = LuaHookCosmeticsState.SelectedRankCharmSeason
                if catalog.SeasonByCharmName[charmName] then
                    return charmName
                end
                local firstSeason = catalog.SeasonEntries[1]
                charmName = firstSeason and firstSeason.CharmName or nil
                LuaHookCosmeticsState.SelectedRankCharmSeason = charmName
                return charmName
            end
            function LuaHookCosmetics.SyncRankCharmEditorFromState()
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                local charmName = catalog and LuaHookCosmetics.ResolveSelectedRankCharmSeason() or nil
                if not charmName then
                    return false
                end
                local season = catalog.SeasonByCharmName[charmName]
                local override = LuaHookCosmeticsState.RankCharmOverridesBySeason[charmName]
                local rankName = type(override) == 'table' and override.rankName or RIVALS_RANK_CHARM_OFF
                local leaderboardRank = type(override) == 'table' and override.leaderboardRank or nil
                LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('RankSeason'), catalog.SeasonLabels, season.Label)
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('RankName'), LuaHookCosmetics.ResolveRankCharmRankValues(), rankName)
                local leaderboardOption = Options[LuaHookCosmetics.ResolveEditorOptionId('RankLeaderboard')]
                if leaderboardOption and type(leaderboardOption.SetValue) == 'function' then
                    pcall(function()
                        leaderboardOption:SetValue(leaderboardRank ~= nil and tostring(leaderboardRank) or '')
                    end)
                end
                LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                return true
            end
            function LuaHookCosmetics.SetSelectedRankCharmSeason(value)
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                local charmName = catalog and (catalog.SeasonByLabel[value] or (catalog.SeasonByCharmName[value] and value)) or nil
                if not charmName then
                    return false
                end
                LuaHookCosmeticsState.SelectedRankCharmSeason = charmName
                LuaHookCosmetics.SyncRankCharmEditorFromState()
                return true
            end
            function LuaHookCosmetics.SetRankCharmOverrideForSeason(charmName, rankName, leaderboardValue)
                local catalog = LuaHookCosmetics.ResolveRankCharmCatalog()
                if not catalog or not LuaHookCosmetics.IsSeasonRankCharm(charmName) then
                    return false
                end
                local previous = LuaHookCosmeticsState.RankCharmOverridesBySeason[charmName]
                if rankName == nil or rankName == RIVALS_RANK_CHARM_OFF or not catalog.RanksByName[rankName] then
                    if previous == nil then
                        return false
                    end
                    LuaHookCosmeticsState.RankCharmOverridesBySeason[charmName] = nil
                    return true
                end
                local leaderboardRank = LuaHookCosmetics.ParseRankCharmLeaderboardRank(leaderboardValue)
                if type(previous) == 'table'
                    and previous.rankName == rankName
                    and previous.leaderboardRank == leaderboardRank then
                    return false
                end
                LuaHookCosmeticsState.RankCharmOverridesBySeason[charmName] = {
                    rankName = rankName,
                    leaderboardRank = leaderboardRank,
                }
                return true
            end
            function LuaHookCosmetics.RefreshRankCharmApplication()
                if type(LuaHookCosmetics.RestoreInjectedWeaponData) == 'function' then pcall(LuaHookCosmetics.RestoreInjectedWeaponData) end
                pcall(LuaHookCosmetics.UpdatePreviewViewport)
                return LuaHookCosmetics.ApplyAll()
            end
            function LuaHookCosmetics.UpdateSelectedRankCharmOverride(rankName, leaderboardValue)
                local charmName = LuaHookCosmetics.ResolveSelectedRankCharmSeason()
                if not charmName then
                    return false
                end
                local changed = LuaHookCosmetics.SetRankCharmOverrideForSeason(charmName, rankName, leaderboardValue)
                LuaHookCosmetics.SyncRankCharmEditorFromState()
                if changed then
                    LuaHookCosmetics.RefreshRankCharmApplication()
                    if type(LuaHookCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                        LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                    end
                end
                return changed
            end
            function LuaHookCosmetics.ResolveSkinOptionId(weaponName)
                local cachedOptionId = LuaHookCosmetics.SkinOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end
                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5SKIN_%s', sanitizedWeaponName)
                LuaHookCosmetics.SkinOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end
            function LuaHookCosmetics.ResolveWrapOptionId(weaponName)
                local cachedOptionId = LuaHookCosmetics.WrapOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end
                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5WRAP_%s', sanitizedWeaponName)
                LuaHookCosmetics.WrapOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end
            function LuaHookCosmetics.ResolveCharmOptionId(weaponName)
                local cachedOptionId = LuaHookCosmetics.CharmOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end
                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5CHARM_%s', sanitizedWeaponName)
                LuaHookCosmetics.CharmOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end
            function LuaHookCosmetics.ResolveWrapInvertedOptionId(weaponName)
                local cachedOptionId = LuaHookCosmetics.WrapInvertedOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end
                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5WRAPINV_%s', sanitizedWeaponName)
                LuaHookCosmetics.WrapInvertedOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end
            function LuaHookCosmetics.ResolveSelectionTable(kind)
                if kind == 'Skin' then
                    return LuaHookCosmeticsState.SelectedSkinByWeapon
                elseif kind == 'Wrap' then
                    return LuaHookCosmeticsState.SelectedWrapByWeapon
                elseif kind == 'Charm' then
                    return LuaHookCosmeticsState.SelectedCharmByWeapon
                elseif kind == 'Finisher' then
                    return LuaHookCosmeticsState.SelectedFinisherByWeapon
                elseif kind == 'WrapInverted' then
                    return LuaHookCosmeticsState.SelectedWrapInvertedByWeapon
                end
                return nil
            end
            function LuaHookCosmetics.IsFavoriteKind(kind)
                for _, availableKind in ipairs(LuaHookCosmetics.FavoriteKinds) do
                    if kind == availableKind then
                        return true
                    end
                end
                return false
            end
            function LuaHookCosmetics.NormalizeFavoritesState(value)
                local normalized = { favorites = {}, onlyUse = {} }
                if type(value) ~= 'table' then
                    return normalized
                end
                local favorites = type(value.favorites) == 'table' and value.favorites
                    or type(value.favoritedCosmetics) == 'table' and value.favoritedCosmetics or {}
                for weaponName, entries in pairs(favorites) do
                    if type(weaponName) == 'string' and weaponName ~= '' and type(entries) == 'table' then
                        local cleanEntries = {}
                        for cosmeticName, enabled in pairs(entries) do
                            if type(cosmeticName) == 'string' and cosmeticName ~= '' and enabled == true then
                                cleanEntries[cosmeticName] = true
                            end
                        end
                        if next(cleanEntries) ~= nil then
                            normalized.favorites[weaponName] = cleanEntries
                        end
                    end
                end
                local onlyUse = type(value.onlyUse) == 'table' and value.onlyUse
                    or type(value.onlyUseFavoritesSelections) == 'table' and value.onlyUseFavoritesSelections or {}
                for weaponName, entries in pairs(onlyUse) do
                    if type(weaponName) == 'string' and weaponName ~= '' and type(entries) == 'table' then
                        local cleanEntries = {}
                        for kind, enabled in pairs(entries) do
                            if LuaHookCosmetics.IsFavoriteKind(kind) and enabled == true then
                                cleanEntries[kind] = true
                            end
                        end
                        if next(cleanEntries) ~= nil then
                            normalized.onlyUse[weaponName] = cleanEntries
                        end
                    end
                end
                return normalized
            end
            function LuaHookCosmetics.ResolveFavoritesState()
                return LuaHookCosmetics.NormalizeFavoritesState({
                    favorites = LuaHookCosmeticsState.FavoritedCosmeticsByWeapon,
                    onlyUse = LuaHookCosmeticsState.OnlyUseFavoritesByWeapon,
                })
            end
            function LuaHookCosmetics.IsFavorited(weaponName, cosmeticName)
                local entries = LuaHookCosmeticsState.FavoritedCosmeticsByWeapon[weaponName]
                return type(entries) == 'table' and entries[cosmeticName] == true
            end
            function LuaHookCosmetics.SetFavorited(weaponName, cosmeticName, enabled)
                if not LuaHookCosmetics.IsKnownWeaponName(weaponName)
                    or not LuaHookCosmetics.IsCosmeticValueSelected(cosmeticName) then
                    return false
                end
                local entries = LuaHookCosmeticsState.FavoritedCosmeticsByWeapon[weaponName]
                if type(entries) ~= 'table' then
                    entries = {}
                    LuaHookCosmeticsState.FavoritedCosmeticsByWeapon[weaponName] = entries
                end
                if enabled then
                    entries[cosmeticName] = true
                else
                    entries[cosmeticName] = nil
                    if next(entries) == nil then
                        LuaHookCosmeticsState.FavoritedCosmeticsByWeapon[weaponName] = nil
                    end
                end
                return true
            end
            function LuaHookCosmetics.UsesOnlyFavorites(weaponName, kind)
                local entries = LuaHookCosmeticsState.OnlyUseFavoritesByWeapon[weaponName]
                return type(entries) == 'table' and entries[kind] == true
            end
            function LuaHookCosmetics.SetOnlyUseFavorites(weaponName, kind, enabled)
                if not LuaHookCosmetics.IsKnownWeaponName(weaponName) or not LuaHookCosmetics.IsFavoriteKind(kind) then
                    return false
                end
                local entries = LuaHookCosmeticsState.OnlyUseFavoritesByWeapon[weaponName]
                if type(entries) ~= 'table' then
                    entries = {}
                    LuaHookCosmeticsState.OnlyUseFavoritesByWeapon[weaponName] = entries
                end
                if enabled then
                    entries[kind] = true
                else
                    entries[kind] = nil
                    if next(entries) == nil then
                        LuaHookCosmeticsState.OnlyUseFavoritesByWeapon[weaponName] = nil
                    end
                end
                local randomByKind = LuaHookCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if randomByKind then
                    randomByKind[kind] = nil
                end
                return true
            end
            function LuaHookCosmetics.SetStoredSelection(weaponName, kind, value)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                local selectionTable = LuaHookCosmetics.ResolveSelectionTable(kind)
                if not selectionTable then
                    return false
                end
                if kind ~= 'WrapInverted' then
                    value = LuaHookCosmetics.NormalizeSelectionValue(value)
                end
                if value == nil or value == '' then
                    selectionTable[weaponName] = nil
                else
                    selectionTable[weaponName] = value
                end
                return true
            end
            local function isCatalogCosmeticOfType(cosmeticName, expectedType, expectedWeaponName)
                if not LuaHookCosmetics.IsCosmeticValueSelected(cosmeticName) then
                    return false
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = type(cosmeticLibrary) == 'table' and cosmeticLibrary.Cosmetics or nil
                local cosmeticData = type(cosmetics) == 'table' and cosmetics[cosmeticName] or nil
                if type(cosmeticData) ~= 'table' or cosmeticData.Type ~= expectedType then
                    return false
                end
                if expectedWeaponName ~= nil then
                    local itemName = cosmeticData.ItemName
                    return itemName == expectedWeaponName
                end
                return true
            end

            local function resolveLoadoutCosmeticName(value)
                if type(value) == 'string' then
                    return value
                end
                if type(value) ~= 'table' then
                    return nil
                end
                return value.Name or value.name or value.ItemName or value.itemName or value[1]
            end

            function LuaHookCosmetics.SyncSelectionsFromCurrentGameLoadout()
                local inventory = LuaHookCosmetics.ResolveOriginalPlayerDataField('WeaponInventory')
                if type(inventory) ~= 'table' then
                    return false
                end

                -- The native game loadout is the source of truth.  We mirror it into
                -- LuaHook's override state instead of asking the exploit UI for cosmetic
                -- choices.  This is the same conceptual split used by luahook stuff.lua:
                -- unlock ownership first, then let the active loadout decide what is
                -- equipped.
                local nextSkin = {}
                local nextWrap = {}
                local nextCharm = {}
                local nextFinisher = {}
                local nextWrapInverted = {}
                local synced = 0

                for _, item in pairs(inventory) do
                    if type(item) == 'table' then
                        local weaponName = item.Name or item.name
                        if LuaHookCosmetics.IsKnownWeaponName(weaponName) then
                            local skinName = resolveLoadoutCosmeticName(item.Skin or item.skin)
                            if LuaHookCosmetics.IsCosmeticValueSelected(skinName) then
                                if isCatalogCosmeticOfType(skinName, 'Skin', weaponName) then
                                    nextSkin[weaponName] = skinName
                                end
                            end

                            local wrapValue = item.Wrap or item.wrap
                            local wrapName = resolveLoadoutCosmeticName(wrapValue)
                            if isCatalogCosmeticOfType(wrapName, 'Wrap') then
                                nextWrap[weaponName] = wrapName
                                nextWrapInverted[weaponName] = type(wrapValue) == 'table'
                                    and wrapValue.Inverted == true
                                    or type(wrapValue) == 'table'
                                    and wrapValue.inverted == true
                            end

                            local charmName = resolveLoadoutCosmeticName(item.Charm or item.charm)
                            if isCatalogCosmeticOfType(charmName, 'Charm') then
                                nextCharm[weaponName] = charmName
                            end

                            local finisherName = resolveLoadoutCosmeticName(item.Finisher or item.finisher)
                            if isCatalogCosmeticOfType(finisherName, 'Finisher') then
                                nextFinisher[weaponName] = finisherName
                            end

                            if nextSkin[weaponName] ~= nil
                                or nextWrap[weaponName] ~= nil
                                or nextCharm[weaponName] ~= nil
                                or nextFinisher[weaponName] ~= nil then
                                synced = synced + 1
                            end
                        end
                    end
                end

                LuaHookCosmeticsState.SelectedSkinByWeapon = nextSkin
                LuaHookCosmeticsState.SelectedWrapByWeapon = nextWrap
                LuaHookCosmeticsState.SelectedCharmByWeapon = nextCharm
                LuaHookCosmeticsState.SelectedFinisherByWeapon = nextFinisher
                LuaHookCosmeticsState.SelectedWrapInvertedByWeapon = nextWrapInverted
                LuaHookCosmeticsState.StableRandomSelectionByWeapon = {}

                local equippedEmotes = LuaHookCosmetics.ResolveOriginalPlayerDataField('EquippedEmotes')
                local nextEmotes = {}
                local nextEmoteOrder = {}
                local slotCount = RivalsEmotes.ResolveEmoteSlotCount()
                if type(equippedEmotes) == 'table' then
                    for slotIndex = 1, slotCount do
                        local entry = equippedEmotes[slotIndex] or equippedEmotes[tostring(slotIndex)]
                        local emoteName = resolveLoadoutCosmeticName(entry)
                        if RivalsEmotes.IsCatalogEmoteName(emoteName) then
                            nextEmotes[emoteName] = true
                            nextEmoteOrder[#nextEmoteOrder + 1] = emoteName
                        end
                    end
                end
                LuaHookCosmeticsState.CosmeticMultiEmotes = nextEmotes
                LuaHookCosmeticsState.CosmeticMultiEmoteOrder = nextEmoteOrder
                LuaHookCosmeticsState.NativeEmoteAppliedBySlot = {}

                return synced > 0 or #nextEmoteOrder > 0
            end

            function LuaHookCosmetics.GetCurrentGameLoadoutSignature()
                local parts = {}
                local inventory = LuaHookCosmetics.ResolveOriginalPlayerDataField('WeaponInventory')
                if type(inventory) == 'table' then
                    local entries = {}
                    for _, item in pairs(inventory) do
                        if type(item) == 'table' and LuaHookCosmetics.IsKnownWeaponName(item.Name or item.name) then
                            local weaponName = item.Name or item.name
                            local skinName = resolveLoadoutCosmeticName(item.Skin or item.skin) or ''
                            local wrapValue = item.Wrap or item.wrap
                            local wrapName = resolveLoadoutCosmeticName(wrapValue) or ''
                            local wrapInv = type(wrapValue) == 'table'
                                and (wrapValue.Inverted == true or wrapValue.inverted == true)
                                or false
                            local charmName = resolveLoadoutCosmeticName(item.Charm or item.charm) or ''
                            local finisherName = resolveLoadoutCosmeticName(item.Finisher or item.finisher) or ''
                            entries[#entries + 1] = table.concat({
                                weaponName, skinName, wrapName, tostring(wrapInv), charmName, finisherName
                            }, '\31')
                        end
                    end
                    table.sort(entries)
                    for _, entry in ipairs(entries) do
                        parts[#parts + 1] = entry
                    end
                end
                local equippedEmotes = LuaHookCosmetics.ResolveOriginalPlayerDataField('EquippedEmotes')
                if type(equippedEmotes) == 'table' then
                    local slotCount = RivalsEmotes.ResolveEmoteSlotCount()
                    for slotIndex = 1, slotCount do
                        local entry = equippedEmotes[slotIndex] or equippedEmotes[tostring(slotIndex)]
                        parts[#parts + 1] = string.format('E%d\31%s', slotIndex, tostring(resolveLoadoutCosmeticName(entry) or ''))
                    end
                end
                return table.concat(parts, '\30')
            end

            function LuaHookCosmetics.StartCurrentLoadoutWatcher()
                if LuaHookCosmeticsState.CurrentLoadoutWatcherRunning then
                    return true
                end
                LuaHookCosmeticsState.CurrentLoadoutWatcherRunning = true
                local token = (LuaHookCosmeticsState.CurrentLoadoutWatcherToken or 0) + 1
                LuaHookCosmeticsState.CurrentLoadoutWatcherToken = token
                task.spawn(GuardLuaHookCallback('Cosmetics_CurrentLoadoutWatcher', function()
                    local lastSignature = nil
                    while LuaHookCosmeticsState.CurrentLoadoutWatcherRunning
                        and LuaHookCosmeticsState.CurrentLoadoutWatcherToken == token
                        and LuaHookCosmetics.IsEnabled() do
                        if ReplicatedStateReady then
                            local signature = LuaHookCosmetics.GetCurrentGameLoadoutSignature()
                            if signature ~= '' and signature ~= lastSignature then
                                lastSignature = signature
                                LuaHookCosmetics.SyncSelectionsFromCurrentGameLoadout()
                                if LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied then
                                    pcall(LuaHookCosmetics.ApplyNativeSkinChanger)
                                    pcall(LuaHookCosmetics.RefreshNativeCosmeticsScene)
                                end
                            end
                        end
                        task.wait(0.5)
                    end
                    return true
                end))
                return true
            end

            function LuaHookCosmetics.StopCurrentLoadoutWatcher()
                LuaHookCosmeticsState.CurrentLoadoutWatcherRunning = false
                LuaHookCosmeticsState.CurrentLoadoutWatcherToken = (LuaHookCosmeticsState.CurrentLoadoutWatcherToken or 0) + 1
                return true
            end

            function LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local selectionTable = LuaHookCosmetics.ResolveSelectionTable(kind)
                local storedValue = selectionTable and selectionTable[weaponName]
                if storedValue ~= nil then
                    return storedValue
                end
                if kind == 'Skin' then
                    local option = Options[LuaHookCosmetics.ResolveSkinOptionId(weaponName)]
                    return option and LuaHookCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Wrap' then
                    local option = Options[LuaHookCosmetics.ResolveWrapOptionId(weaponName)]
                    return option and LuaHookCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Charm' then
                    local option = Options[LuaHookCosmetics.ResolveCharmOptionId(weaponName)]
                    return option and LuaHookCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Finisher' then
                    local option = Options[LuaHookCosmetics.ResolveFinisherOptionId(weaponName)]
                    return option and LuaHookCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'WrapInverted' then
                    local toggle = Toggles[LuaHookCosmetics.ResolveWrapInvertedOptionId(weaponName)]
                    if toggle and toggle.Value ~= nil then
                        return toggle.Value == true
                    end
                end
                return nil
            end
            function LuaHookCosmetics.ResolveValidDropdownValue(value, values)
                if type(values) == 'table' then
                    for _, availableValue in ipairs(values) do
                        if availableValue == value then
                            return value
                        end
                    end
                    return values[1]
                end
                return nil
            end
            function LuaHookCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                if kind == 'Skin' then
                    return LuaHookCosmetics.ResolveWeaponSkinValues(weaponName)
                elseif kind == 'Wrap' then
                    return LuaHookCosmetics.ResolveWrapValues()
                elseif kind == 'Charm' then
                    return LuaHookCosmetics.ResolveCharmValues()
                elseif kind == 'Finisher' then
                    return LuaHookCosmetics.ResolveFinisherValues()
                end
                return nil
            end
            function LuaHookCosmetics.ResolveSelectionValues(weaponName, kind)
                local values = LuaHookCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                if not LuaHookCosmetics.UsesOnlyFavorites(weaponName, kind) then
                    return values
                end
                local filtered = {}
                for _, value in ipairs(values or {}) do
                    if not LuaHookCosmetics.IsCosmeticValueSelected(value)
                        or LuaHookCosmetics.IsFavorited(weaponName, value) then
                        filtered[#filtered + 1] = value
                    end
                end
                return filtered
            end
            function LuaHookCosmetics.ResolveEffectiveSelectionValue(weaponName, kind, value)
                value = LuaHookCosmetics.NormalizeSelectionValue(value)
                if LuaHookCosmetics.IsCosmeticValueSelected(value)
                    and LuaHookCosmetics.UsesOnlyFavorites(weaponName, kind)
                    and not LuaHookCosmetics.IsFavorited(weaponName, value) then
                    return RIVALS_COSMETIC_UNSELECTED
                end
                if value ~= RIVALS_COSMETIC_RANDOM then
                    return value
                end
                local randomByKind = LuaHookCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if not randomByKind then
                    randomByKind = {}
                    LuaHookCosmeticsState.StableRandomSelectionByWeapon[weaponName] = randomByKind
                end
                local values = LuaHookCosmetics.ResolveSelectionValues(weaponName, kind)
                local cachedValue = randomByKind[kind]
                if LuaHookCosmetics.ResolveValidDropdownValue(cachedValue, values) == cachedValue
                    and LuaHookCosmetics.IsCosmeticValueSelected(cachedValue) then
                    return cachedValue
                end
                local candidates = {}
                for _, candidate in ipairs(values or {}) do
                    if LuaHookCosmetics.IsCosmeticValueSelected(candidate) then
                        candidates[#candidates + 1] = candidate
                    end
                end
                if #candidates == 0 then
                    randomByKind[kind] = nil
                    return RIVALS_COSMETIC_UNSELECTED
                end
                cachedValue = candidates[math.random(1, #candidates)]
                randomByKind[kind] = cachedValue
                return cachedValue
            end
            function LuaHookCosmetics.ResolveWrapInvertedValue(weaponName)
                if not LuaHookCosmetics.IsEnabled() then
                    return false
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                local value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                return value == true
            end
            function LuaHookCosmetics.ResolveDefaultPreviewWeaponName()
                local weaponNames = LuaHookCosmetics.ResolveWeaponNames()
                for _, weaponName in ipairs(weaponNames) do
                    local value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                    if LuaHookCosmetics.IsCosmeticValueSelected(value) then
                        return weaponName
                    end
                end
                for _, weaponName in ipairs(weaponNames) do
                    local wrapValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                    local charmValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                    local finisherValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                    local invertedValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                    if LuaHookCosmetics.IsCosmeticValueSelected(wrapValue)
                        or LuaHookCosmetics.IsCosmeticValueSelected(charmValue)
                        or LuaHookCosmetics.IsCosmeticValueSelected(finisherValue)
                        or invertedValue == true then
                        return weaponName
                    end
                end
                return weaponNames[1]
            end
            function LuaHookCosmetics.SetPreviewWeaponName(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                for _, availableWeaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    if availableWeaponName == weaponName then
                        LuaHookCosmeticsState.PreviewWeaponName = weaponName
                        return true
                    end
                end
                return false
            end
            function LuaHookCosmetics.ResolvePreviewWeaponName()
                local previewWeaponName = LuaHookCosmeticsState.PreviewWeaponName
                if LuaHookCosmetics.SetPreviewWeaponName(previewWeaponName) then
                    return previewWeaponName
                end
                previewWeaponName = LuaHookCosmetics.ResolveDefaultPreviewWeaponName()
                LuaHookCosmeticsState.PreviewWeaponName = previewWeaponName
                return previewWeaponName
            end
            function LuaHookCosmetics.ResolveSkinSelectionValue(weaponName)
                if not LuaHookCosmetics.IsSkinEnabled() then
                    return nil
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local pendingSkinName = LuaHookCosmeticsState.PendingSkinSelectionByWeapon[weaponName]
                local value = pendingSkinName
                if value == nil then
                    value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                end
                return LuaHookCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Skin', value)
            end
            function LuaHookCosmetics.ResolveSelectedSkinName(weaponName)
                local value = LuaHookCosmetics.ResolveSkinSelectionValue(weaponName)
                if LuaHookCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end
                return nil
            end
            function LuaHookCosmetics.ResolveWrapSelectionValue(weaponName)
                if not LuaHookCosmetics.IsWrapEnabled() then
                    return nil
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local pendingWrapName = LuaHookCosmeticsState.PendingWrapSelectionByWeapon[weaponName]
                local value = pendingWrapName
                if value == nil then
                    value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                end
                return LuaHookCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Wrap', value)
            end
            function LuaHookCosmetics.ResolveSelectedWrapName(weaponName)
                local value = LuaHookCosmetics.ResolveWrapSelectionValue(weaponName)
                if LuaHookCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end
                return nil
            end
            function LuaHookCosmetics.ResolveCharmSelectionValue(weaponName)
                if not LuaHookCosmetics.IsEnabled() then
                    return nil
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local pendingCharmName = LuaHookCosmeticsState.PendingCharmSelectionByWeapon[weaponName]
                local value = pendingCharmName
                if value == nil then
                    value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                end
                return LuaHookCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Charm', value)
            end
            function LuaHookCosmetics.ResolveSelectedCharmName(weaponName)
                local value = LuaHookCosmetics.ResolveCharmSelectionValue(weaponName)
                if LuaHookCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end
                return nil
            end
            function LuaHookCosmetics.ResolveFinisherAssetsFolder()
                local cached = LuaHookCosmetics.Catalog.FinisherAssetsFolder
                if cached and cached.Parent then
                    return cached
                end
                local replicatedStorage = game:GetService('ReplicatedStorage')
                local modules = replicatedStorage:FindFirstChild('Modules')
                local finishersFolder = modules and modules:FindFirstChild('Finishers')
                if finishersFolder then
                    LuaHookCosmetics.Catalog.FinisherAssetsFolder = finishersFolder
                end
                return finishersFolder
            end
            function LuaHookCosmetics.ResolveFinisherValues()
                local cachedFinisherValues = LuaHookCosmetics.Catalog.FinisherValues
                if cachedFinisherValues then
                    return cachedFinisherValues
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = LuaHookCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local finisherNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if type(cosmeticData) == 'table' and cosmeticData.Type == 'Finisher' and not LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            finisherNames[#finisherNames + 1] = cosmeticName
                        end
                    end
                    table.sort(finisherNames)
                    for _, finisherName in ipairs(finisherNames) do
                        values[#values + 1] = finisherName
                    end
                end
                LuaHookCosmetics.Catalog.FinisherValues = values
                return values
            end
            function LuaHookCosmetics.ResolveFinisherOptionId(weaponName)
                local cachedOptionId = LuaHookCosmetics.FinisherOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end
                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5FINISHER_%s', sanitizedWeaponName)
                LuaHookCosmetics.FinisherOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end
            function LuaHookCosmetics.ResolveCosmeticOptionInfo(optionId)
                if type(optionId) ~= 'string' then
                    return nil
                end
                for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    if optionId == LuaHookCosmetics.ResolveSkinOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Skin', type = 'Dropdown' }
                    elseif optionId == LuaHookCosmetics.ResolveWrapOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Wrap', type = 'Dropdown' }
                    elseif optionId == LuaHookCosmetics.ResolveCharmOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Charm', type = 'Dropdown' }
                    elseif optionId == LuaHookCosmetics.ResolveFinisherOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Finisher', type = 'Dropdown' }
                    elseif optionId == LuaHookCosmetics.ResolveWrapInvertedOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'WrapInverted', type = 'Toggle' }
                    end
                end
                return nil
            end
            function LuaHookCosmetics.ResolveFinisherSelectionValue(weaponName)
                if not LuaHookCosmetics.IsEnabled() then
                    return nil
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local pendingFinisherName = LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[weaponName]
                local value = pendingFinisherName
                if value == nil then
                    value = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                end
                return LuaHookCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Finisher', value)
            end
            function LuaHookCosmetics.ResolveSelectedFinisherName(weaponName)
                local value = LuaHookCosmetics.ResolveFinisherSelectionValue(weaponName)
                if LuaHookCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end
                return nil
            end
            function LuaHookCosmetics.ResolveSelectedPlaybackFinisherName()
                if not LuaHookCosmetics.IsEnabled() then
                    return nil
                end
                local fighter = ResolveLocalFighter()
                local item = fighter and fighter.EquippedItem or nil
                local weaponName = item and item.Name or nil
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end
                local selectedFinisherName = LuaHookCosmetics.ResolveSelectedFinisherName(weaponName)
                if type(selectedFinisherName) == 'string' and selectedFinisherName ~= '' then
                    return selectedFinisherName
                end
                return nil
            end
            function LuaHookCosmetics.IsKnownWeaponName(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                for _, availableWeaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    if availableWeaponName == weaponName then
                        return true
                    end
                end
                return false
            end
            function LuaHookCosmetics.IsKnownEditorWeaponName(weaponName)
                return weaponName == RIVALS_COSMETIC_ALL_WEAPONS or LuaHookCosmetics.IsKnownWeaponName(weaponName)
            end
            function LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                local selectedWeaponName = LuaHookCosmeticsState.SelectedEditorWeaponName
                if LuaHookCosmetics.IsKnownEditorWeaponName(selectedWeaponName) then
                    return selectedWeaponName
                end
                local option = Options[LuaHookCosmetics.ResolveEditorOptionId('Weapon')]
                selectedWeaponName = option and option.Value or nil
                if LuaHookCosmetics.IsKnownEditorWeaponName(selectedWeaponName) then
                    LuaHookCosmeticsState.SelectedEditorWeaponName = selectedWeaponName
                    if selectedWeaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                        LuaHookCosmetics.SetPreviewWeaponName(selectedWeaponName)
                    end
                    return selectedWeaponName
                end
                LuaHookCosmeticsState.SelectedEditorWeaponName = RIVALS_COSMETIC_ALL_WEAPONS
                return RIVALS_COSMETIC_ALL_WEAPONS
            end
            function LuaHookCosmetics.SyncDropdownOption(optionId, values, value)
                local option = Options[optionId]
                if not option then
                    return false
                end
                if type(option.SetValues) == 'function' and type(values) == 'table' then
                    pcall(function()
                        option:SetValues(values)
                    end)
                end
                if type(option.SetValue) == 'function' then
                    pcall(function()
                        option:SetValue(value)
                    end)
                end
                return true
            end
            function LuaHookCosmetics.ResolveEditorSelectionValue(weaponName, kind, values)
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    local storedValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                    return LuaHookCosmetics.ResolveValidDropdownValue(storedValue, values) or RIVALS_COSMETIC_UNSELECTED
                end
                local commonValue = nil
                for _, availableWeaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    local storedValue = LuaHookCosmetics.ResolveStoredSelectionValue(availableWeaponName, kind)
                    storedValue = LuaHookCosmetics.ResolveValidDropdownValue(storedValue, values) or RIVALS_COSMETIC_UNSELECTED
                    if commonValue == nil then
                        commonValue = storedValue
                    elseif commonValue ~= storedValue then
                        return RIVALS_COSMETIC_UNSELECTED
                    end
                end
                return commonValue or RIVALS_COSMETIC_UNSELECTED
            end
            function LuaHookCosmetics.ResolveEditorWrapInvertedValue(weaponName)
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    return LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted') == true
                end
                local sawWeapon = false
                for _, availableWeaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    sawWeapon = true
                    if LuaHookCosmetics.ResolveStoredSelectionValue(availableWeaponName, 'WrapInverted') ~= true then
                        return false
                    end
                end
                return sawWeapon
            end
            function LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                local weaponName = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                if not weaponName then
                    return false
                end
                local weaponValues = LuaHookCosmetics.ResolveEditorWeaponNames()
                local skinValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and LuaHookCosmetics.ResolveSentinelValues()
                    or LuaHookCosmetics.ResolveSelectionValues(weaponName, 'Skin')
                local wrapValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and LuaHookCosmetics.ResolveWrapValues()
                    or LuaHookCosmetics.ResolveSelectionValues(weaponName, 'Wrap')
                local charmValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and LuaHookCosmetics.ResolveCharmValues()
                    or LuaHookCosmetics.ResolveSelectionValues(weaponName, 'Charm')
                local finisherValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and LuaHookCosmetics.ResolveFinisherValues()
                    or LuaHookCosmetics.ResolveSelectionValues(weaponName, 'Finisher')
                local skinValue = LuaHookCosmetics.ResolveEditorSelectionValue(weaponName, 'Skin', skinValues)
                local wrapValue = LuaHookCosmetics.ResolveEditorSelectionValue(weaponName, 'Wrap', wrapValues)
                local charmValue = LuaHookCosmetics.ResolveEditorSelectionValue(weaponName, 'Charm', charmValues)
                local finisherValue = LuaHookCosmetics.ResolveEditorSelectionValue(weaponName, 'Finisher', finisherValues)
                local invertedValue = LuaHookCosmetics.ResolveEditorWrapInvertedValue(weaponName)
                LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('Weapon'), weaponValues, weaponName)
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('Skin'), skinValues, skinValue)
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('Wrap'), wrapValues, wrapValue)
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('Charm'), charmValues, charmValue)
                LuaHookCosmetics.SyncDropdownOption(LuaHookCosmetics.ResolveEditorOptionId('Finisher'), finisherValues, finisherValue)
                local invertedToggle = Toggles[LuaHookCosmetics.ResolveEditorOptionId('WrapInverted')]
                if invertedToggle and type(invertedToggle.SetValue) == 'function' then
                    pcall(function()
                        invertedToggle:SetValue(invertedValue)
                    end)
                end
                LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                return true
            end
            function LuaHookCosmetics.ResolveSelectedFavoriteKind()
                local option = Options.P5FAVORITE_TYPE
                local kind = option and option.Value or LuaHookCosmetics.FavoriteKinds[1]
                return LuaHookCosmetics.IsFavoriteKind(kind) and kind or LuaHookCosmetics.FavoriteKinds[1]
            end
            function LuaHookCosmetics.SyncFavoriteEditorFromState()
                local weaponName = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                local kind = LuaHookCosmetics.ResolveSelectedFavoriteKind()
                local onlyUse = weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS
                    and LuaHookCosmetics.UsesOnlyFavorites(weaponName, kind) or false
                local toggle = Toggles.P5FAVORITE_ONLY
                if toggle and type(toggle.SetValue) == 'function' then
                    LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                    pcall(function()
                        toggle:SetValue(onlyUse)
                    end)
                    LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                end
                return weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS
            end
            function LuaHookCosmetics.SetSelectedFavoriteKind(kind)
                if not LuaHookCosmetics.IsFavoriteKind(kind) then
                    return false
                end
                LuaHookCosmetics.SyncFavoriteEditorFromState()
                return true
            end
            function LuaHookCosmetics.RefreshFavoriteApplication()
                LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                LuaHookCosmetics.SyncFavoriteEditorFromState()
                LuaHookCosmetics.RestoreAppliedCosmetics()
                pcall(LuaHookCosmetics.UpdatePreviewViewport)
                LuaHookCosmetics.ApplyAll()
                if type(LuaHookCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end
            function LuaHookCosmetics.ToggleSelectedFavorite()
                local weaponName = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                local kind = LuaHookCosmetics.ResolveSelectedFavoriteKind()
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS then
                    return false
                end
                local cosmeticName = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                if not LuaHookCosmetics.IsCosmeticValueSelected(cosmeticName) then
                    return false
                end
                if not LuaHookCosmetics.SetFavorited(
                    weaponName,
                    cosmeticName,
                    not LuaHookCosmetics.IsFavorited(weaponName, cosmeticName)
                ) then
                    return false
                end
                local randomByKind = LuaHookCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if randomByKind then
                    randomByKind[kind] = nil
                end
                return LuaHookCosmetics.RefreshFavoriteApplication()
            end
            function LuaHookCosmetics.SetSelectedOnlyUseFavorites(enabled)
                local weaponName = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                local kind = LuaHookCosmetics.ResolveSelectedFavoriteKind()
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS
                    or not LuaHookCosmetics.SetOnlyUseFavorites(weaponName, kind, enabled == true) then
                    return false
                end
                return LuaHookCosmetics.RefreshFavoriteApplication()
            end
            function LuaHookCosmetics.SetSelectedEditorWeapon(weaponName)
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    return false
                end
                if not LuaHookCosmetics.IsKnownEditorWeaponName(weaponName) then
                    return false
                end
                LuaHookCosmeticsState.SelectedEditorWeaponName = weaponName
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    LuaHookCosmetics.SetPreviewWeaponName(weaponName)
                end
                LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                LuaHookCosmetics.SyncFavoriteEditorFromState()
                pcall(LuaHookCosmetics.UpdatePreviewViewport)
                return true
            end
            function LuaHookCosmetics.IsValidEditorSelection(weaponName, kind, value)
                if kind == 'WrapInverted' then
                    return type(value) == 'boolean'
                end
                value = LuaHookCosmetics.NormalizeSelectionValue(value)
                local values = nil
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS and kind == 'Skin' then
                    values = LuaHookCosmetics.ResolveSentinelValues()
                else
                    values = LuaHookCosmetics.ResolveSelectionValues(weaponName, kind)
                end
                return LuaHookCosmetics.ResolveValidDropdownValue(value, values) == value
            end
            function LuaHookCosmetics.SetSelectionForSelectedEditorWeapon(kind, value)
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    return false
                end
                local previewWeaponName = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                if not previewWeaponName or not LuaHookCosmetics.IsValidEditorSelection(previewWeaponName, kind, value) then
                    return false
                end
                value = kind == 'WrapInverted' and value == true or LuaHookCosmetics.NormalizeSelectionValue(value)
                if previewWeaponName == RIVALS_COSMETIC_ALL_WEAPONS then
                    for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                        LuaHookCosmetics.SetStoredSelection(weaponName, kind, value)
                    end
                elseif not LuaHookCosmetics.SetStoredSelection(previewWeaponName, kind, value) then
                    return false
                end
                LuaHookCosmetics.RestoreAppliedCosmetics()
                pcall(LuaHookCosmetics.UpdatePreviewViewport)
                LuaHookCosmetics.ApplyAll()
                if type(LuaHookCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end
            function LuaHookCosmetics.RerollRandomSelections()
                LuaHookCosmeticsState.StableRandomSelectionByWeapon = {}
                LuaHookCosmetics.RestoreAppliedCosmetics()
                pcall(LuaHookCosmetics.UpdatePreviewViewport)
                LuaHookCosmetics.ApplyAll()
                return true
            end
            function LuaHookCosmetics.BuildLuaHookItemSelection(weaponName)
                local selection = {}
                local hasSelection = false
                local skin = LuaHookCosmetics.ResolveSkinSelectionValue(weaponName)
                local wrap = LuaHookCosmetics.ResolveWrapSelectionValue(weaponName)
                local charm = LuaHookCosmetics.ResolveCharmSelectionValue(weaponName)
                if skin ~= nil and skin ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.skin = skin
                    hasSelection = true
                end
                if wrap ~= nil and wrap ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.wrap = {
                        name = wrap,
                        inverted = LuaHookCosmetics.ResolveWrapInvertedValue(weaponName) == true,
                    }
                    hasSelection = true
                end
                if charm ~= nil and charm ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.charm = charm
                    hasSelection = true
                end
                local finisher = LuaHookCosmetics.ResolveFinisherSelectionValue(weaponName)
                if finisher ~= nil and finisher ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.finisher = finisher
                    hasSelection = true
                end
                return hasSelection and selection or nil
            end
            function LuaHookCosmetics.BuildLuaHookCosmeticPayload(cosmeticName, inverted)
                if cosmeticName == nil or cosmeticName == RIVALS_COSMETIC_NONE then
                    return nil
                end
                local payload = { Name = cosmeticName }
                if inverted ~= nil then
                    payload.Inverted = inverted == true and true or nil
                end
                return payload
            end
            function LuaHookCosmetics.OverrideWeaponData(weaponName, weaponData)
                if type(weaponData) ~= 'table' then
                    return weaponData
                end
                local selection = LuaHookCosmetics.BuildLuaHookItemSelection(weaponName)
                local patchedNaturalCharm = LuaHookCosmetics.PatchRankCharmPayload(weaponData.Charm)
                local hasOnlyUseFavoritesOverride = false
                for _, cosmeticType in ipairs(LuaHookCosmetics.FavoriteKinds) do
                    if LuaHookCosmetics.UsesOnlyFavorites(weaponName, cosmeticType) then
                        hasOnlyUseFavoritesOverride = true
                        break
                    end
                end
                if selection == nil and patchedNaturalCharm == nil and not hasOnlyUseFavoritesOverride then
                    return weaponData
                end
                local overriddenWeaponData = table.clone(weaponData)
                if selection ~= nil then
                    if selection.skin ~= nil then
                        overriddenWeaponData.Skin = LuaHookCosmetics.BuildLuaHookCosmeticPayload(selection.skin)
                    end
                    if selection.wrap ~= nil then
                        overriddenWeaponData.Wrap = LuaHookCosmetics.BuildLuaHookCosmeticPayload(
                            selection.wrap.name,
                            selection.wrap.inverted
                        )
                    end
                    if selection.charm ~= nil then
                        overriddenWeaponData.Charm = LuaHookCosmetics.BuildLuaHookCosmeticPayload(selection.charm)
                    end
                end
                overriddenWeaponData.Charm = LuaHookCosmetics.PatchRankCharmPayload(overriddenWeaponData.Charm)
                    or overriddenWeaponData.Charm
                for _, cosmeticType in ipairs(LuaHookCosmetics.FavoriteKinds) do
                    local cosmeticData = overriddenWeaponData[cosmeticType]
                    if LuaHookCosmetics.UsesOnlyFavorites(weaponName, cosmeticType)
                        and type(cosmeticData) == 'table'
                        and type(cosmeticData.Name) == 'string' then
                        cosmeticData = table.clone(cosmeticData)
                        cosmeticData.OnlyUseFavorites = true
                        overriddenWeaponData[cosmeticType] = cosmeticData
                    end
                end
                overriddenWeaponData.Level = rawget(weaponData, 'Level')
                overriddenWeaponData.Prestige = rawget(weaponData, 'Prestige')
                overriddenWeaponData.XP = rawget(weaponData, 'XP')
                return overriddenWeaponData
            end
            function LuaHookCosmetics.ResolveItemLibrary()
                local cached = LuaHookCosmetics.Catalog.ItemLibrary
                if cached then
                    return cached
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local itemLibraryModule = modules and modules:FindFirstChild('ItemLibrary')
                if not itemLibraryModule then
                    return nil
                end
                local ok, itemLibrary = pcall(require, itemLibraryModule)
                if not ok or type(itemLibrary) ~= 'table' then
                    return nil
                end
                LuaHookCosmetics.Catalog.ItemLibrary = itemLibrary
                return itemLibrary
            end
            function LuaHookCosmetics.ResolveEquipmentModule()
                local cached = LuaHookCosmetics.Catalog.EquipmentModule
                if cached then
                    return cached
                end
                local playerScripts = LuaHookCosmetics.ResolvePlayerScripts()
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local userInterface = modules and modules:FindFirstChild('UserInterface')
                local equipmentModule = userInterface and userInterface:FindFirstChild('Equipment')
                if not equipmentModule then
                    return nil
                end
                local ok, equipment = pcall(require, equipmentModule)
                if not ok or type(equipment) ~= 'table' then
                    return nil
                end
                LuaHookCosmetics.Catalog.EquipmentModule = equipment
                return equipment
            end
            function LuaHookCosmetics.IsNonFinisherUnlockCosmetic(cosmeticName, cosmeticData)
                if type(cosmeticName) ~= 'string' or cosmeticName == '' then
                    return false
                end
                if LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                    return false
                end
                if type(cosmeticData) ~= 'table' then
                    return false
                end
                -- Match the native Cosmetics catalog buckets exactly.
                local cosmeticType = cosmeticData.Type or cosmeticData.CosmeticType
                return cosmeticType == 'Skin'
                    or cosmeticType == 'Wrap'
                    or cosmeticType == 'Charm'
                    or cosmeticType == 'Finisher'
                    or cosmeticType == 'Emote'
            end
            function LuaHookCosmetics.BuildNativeUnlockedInventory()
                local cached = LuaHookCosmeticsState.NativeUnlockedInventory
                if type(cached) == 'table' then
                    return cached
                end

                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                if type(cosmetics) ~= 'table' then
                    return nil
                end

                local itemLibrary = LuaHookCosmetics.ResolveItemLibrary()
                local itemNames = itemLibrary and itemLibrary.Items or nil
                local allItemNames = {}
                if type(itemNames) == 'table' then
                    for itemName in pairs(itemNames) do
                        if type(itemName) == 'string' and itemName ~= '' then
                            allItemNames[itemName] = true
                        end
                    end
                end
                if next(allItemNames) == nil then
                    -- Last-resort fallback: derive usable item names from the catalog
                    -- itself. This keeps Wrap/Charm/Finisher ownership meaningful even
                    -- when ItemLibrary has not finished loading yet.
                    for _, cosmeticData in pairs(cosmetics) do
                        if type(cosmeticData) == 'table' then
                            local itemName = cosmeticData.ItemName
                            if type(itemName) == 'string' and itemName ~= '' then
                                allItemNames[itemName] = true
                            end
                        end
                    end
                end

                local inventory = {}
                for cosmeticName, cosmeticData in pairs(cosmetics) do
                    if type(cosmeticName) == 'string'
                        and cosmeticName ~= ''
                        and type(cosmeticData) == 'table'
                        and LuaHookCosmetics.IsNonFinisherUnlockCosmetic(cosmeticName, cosmeticData) then
                        local cosmeticType = cosmeticData.Type or cosmeticData.CosmeticType
                        if cosmeticType == 'Skin' or cosmeticType == 'Emote' then
                            inventory[cosmeticName] = true
                        elseif cosmeticType == 'Wrap'
                            or cosmeticType == 'Charm'
                            or cosmeticType == 'Finisher' then
                            inventory[cosmeticName] = allItemNames
                        end
                    end
                end
                LuaHookCosmeticsState.NativeUnlockedInventory = inventory
                return inventory
            end

            function LuaHookCosmetics.EnsureUnlockedOwnershipHooks()
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                if type(cosmeticLibrary) ~= 'table' then
                    return false
                end
                local hookState = LuaHookCosmeticsState.UnlockedOwnershipHooks
                if type(hookState) ~= 'table' then
                    hookState = {}
                    LuaHookCosmeticsState.UnlockedOwnershipHooks = hookState
                end
                local methods = {'OwnsCosmetic', 'OwnsCosmeticNormally', 'OwnsCosmeticUniversally', 'OwnsCosmeticForWeapon'}
                if hookState.Library == cosmeticLibrary and hookState.Active == true then
                    local intact = true
                    for _, methodName in ipairs(methods) do
                        local wrapper = hookState[methodName .. '_Wrapper']
                        local owner = hookState[methodName .. '_Owner'] or cosmeticLibrary
                        if wrapper ~= nil and (type(owner) ~= 'table' or rawget(owner, methodName) ~= wrapper) then
                            intact = false
                            break
                        end
                    end
                    if intact then return true end
                end

                if type(LuaHookCosmetics.RestoreUnlockedOwnershipHooks) == 'function' then pcall(LuaHookCosmetics.RestoreUnlockedOwnershipHooks) end
                hookState = LuaHookCosmeticsState.UnlockedOwnershipHooks
                hookState.Library = cosmeticLibrary

                local installed = 0
                local expected = 0
                for _, methodName in ipairs(methods) do
                    local owner, original = resolveDirectMethodOwner(cosmeticLibrary, methodName)
                    if type(owner) == 'table' and type(original) == 'function' then
                        expected = expected + 1
                        local wrapper = function(self, inventory, name, weapon)
                            local cosmetics = self and self.Cosmetics
                            local cosmeticData = type(cosmetics) == 'table' and cosmetics[name] or nil
                            if LuaHookCosmetics.IsNonFinisherUnlockCosmetic(name, cosmeticData) then
                                return true
                            end
                            return original(self, inventory, name, weapon)
                        end
                        local ok = pcall(function() rawset(owner, methodName, wrapper) end)
                        if ok and rawget(owner, methodName) == wrapper then
                            hookState[methodName] = original
                            hookState[methodName .. '_Wrapper'] = wrapper
                            hookState[methodName .. '_Owner'] = owner
                            installed = installed + 1
                        end
                    end
                end
                hookState.Expected = expected
                hookState.Installed = installed
                hookState.Active = expected > 0 and installed == expected
                if not hookState.Active then
                    LuaHookCosmetics.RestoreUnlockedOwnershipHooks()
                    return false
                end
                return true
            end

            function LuaHookCosmetics.RestoreUnlockedOwnershipHooks()
                local hookState = LuaHookCosmeticsState.UnlockedOwnershipHooks
                if type(hookState) ~= 'table' then
                    LuaHookCosmeticsState.UnlockedOwnershipHooks = {}
                    return true
                end
                local fullyRestored = true
                local library = hookState.Library
                if type(library) == 'table' then
                    for _, methodName in ipairs({'OwnsCosmetic', 'OwnsCosmeticNormally', 'OwnsCosmeticUniversally', 'OwnsCosmeticForWeapon'}) do
                        local original = hookState[methodName]
                        local wrapper = hookState[methodName .. '_Wrapper']
                        local owner = hookState[methodName .. '_Owner'] or library
                        if type(original) == 'function' and type(owner) == 'table' and rawget(owner, methodName) == wrapper then
                            local ok = pcall(function() rawset(owner, methodName, original) end)
                            if not ok or rawget(owner, methodName) ~= original then
                                fullyRestored = false
                            end
                        end
                    end
                end
                if fullyRestored then
                    LuaHookCosmeticsState.UnlockedOwnershipHooks = {}
                end
                return fullyRestored
            end

            function LuaHookCosmetics.CloneNativeFavorites(value)
                local cloned = {}
                if type(value) ~= 'table' then
                    return cloned
                end
                for itemName, entries in pairs(value) do
                    if type(itemName) == 'string' and type(entries) == 'table' then
                        local itemFavorites = {}
                        for cosmeticName, enabled in pairs(entries) do
                            if type(cosmeticName) == 'string' and enabled == true then
                                itemFavorites[cosmeticName] = true
                            end
                        end
                        if next(itemFavorites) ~= nil then
                            cloned[itemName] = itemFavorites
                        end
                    end
                end
                return cloned
            end
            function LuaHookCosmetics.SeedNativeFavorites(baseFavorites)
                if LuaHookCosmeticsState.NativeFavoritesSeeded then
                    return
                end
                if next(LuaHookCosmeticsState.FavoritedCosmeticsByWeapon) == nil then
                    LuaHookCosmeticsState.FavoritedCosmeticsByWeapon = LuaHookCosmetics.CloneNativeFavorites(baseFavorites)
                end
                LuaHookCosmeticsState.NativeFavoritesSeeded = true
            end
            function LuaHookCosmetics.ResolveNativeDataField(fieldName, originalValue)
                if not LuaHookCosmetics.IsEnabled() then
                    return originalValue
                end
                if fieldName == 'CosmeticInventory' then
                    local result = type(originalValue) == 'table' and table.clone(originalValue) or {}
                    local unlocked = LuaHookCosmetics.BuildNativeUnlockedInventory() or {}
                    for name in pairs(unlocked) do
                        result[name] = true
                    end
                    return result
                end
                if fieldName == 'FavoritedCosmetics' then
                    -- Favorites/loadout remain native state.
                    return originalValue
                end
                return originalValue
            end
            function LuaHookCosmetics.ResolveOriginalPlayerDataField(fieldName)
                local restore = LuaHookCosmeticsState.PlayerDataRestore
                local data = type(restore) == 'table' and restore.Inner or nil
                if type(data) ~= 'table' then
                    local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                    local currentData = playerDataController and rawget(playerDataController, 'CurrentData') or nil
                    data = type(currentData) == 'table' and rawget(currentData, 'Data') or nil
                end
                return type(data) == 'table' and rawget(data, fieldName) or nil
            end
            function LuaHookCosmetics.RestorePlayerDataProxy()
                local restore = LuaHookCosmeticsState.PlayerDataRestore
                if type(restore) ~= 'table' then
                    return true
                end
                LuaHookCosmeticsState.PlayerDataRestore = nil
                if type(restore.Current) == 'table' then
                    local currentDataValue = rawget(restore.Current, 'Data')
                    if currentDataValue == restore.Proxy then
                        rawset(restore.Current, 'Data', restore.Inner)
                    end
                end
                return true
            end
            function LuaHookCosmetics.LoadPlayerDataProxy(currentData)
                if type(currentData) ~= 'table' then
                    return false
                end
                local restore = LuaHookCosmeticsState.PlayerDataRestore
                if type(restore) == 'table' then
                    if restore.Current == currentData then
                        return true
                    end
                    LuaHookCosmetics.RestorePlayerDataProxy()
                end
                local inner = rawget(currentData, 'Data')
                if type(inner) ~= 'table' then
                    return false
                end
                local proxy = setmetatable({}, {
                    __index = function(_, fieldName)
                        return LuaHookCosmetics.ResolveNativeDataField(fieldName, rawget(inner, fieldName))
                    end,
                    __newindex = function(_, fieldName, value)
                        rawset(inner, fieldName, value)
                    end,
                })
                rawset(currentData, 'Data', proxy)
                LuaHookCosmeticsState.PlayerDataRestore = {
                    Current = currentData,
                    Inner = inner,
                    Proxy = proxy,
                }
                return true
            end
            resolveDirectMethodOwner = function(controller, methodName)
                if type(controller) ~= 'table' then return nil, nil end
                local direct = rawget(controller, methodName)
                if type(direct) == 'function' then
                    return controller, direct
                end
                local mt = getmetatable(controller)
                local index = type(mt) == 'table' and rawget(mt, '__index') or nil
                if type(index) == 'table' and type(rawget(index, methodName)) == 'function' then
                    return index, rawget(index, methodName)
                end
                return nil, nil
            end

            function LuaHookCosmetics.EnsureDirectDataHooks()
                local controller = LuaHookCosmetics.ResolvePlayerDataController()
                if type(controller) ~= 'table' then return false end

                local getOwner, originalGet = resolveDirectMethodOwner(controller, 'Get')
                if type(getOwner) == 'table' and type(originalGet) == 'function' then
                    local current = rawget(getOwner, 'Get')
                    if LuaHookCosmeticsState.DirectDataGetOwner == getOwner
                        and current == LuaHookCosmeticsState.DirectDataGetWrapper then
                        -- already installed
                    else
                        if LuaHookCosmeticsState.DirectDataGetOwner ~= nil then
                            LuaHookCosmetics.RestoreDirectDataHooks()
                            getOwner, originalGet = resolveDirectMethodOwner(controller, 'Get')
                        end
                        local wrapper = function(self, key)
                            local data = originalGet(self, key)
                            if key == 'CosmeticInventory' then
                                local result = type(data) == 'table' and table.clone(data) or {}
                                local unlocked = LuaHookCosmetics.BuildNativeUnlockedInventory() or {}
                                for name in pairs(unlocked) do result[name] = true end
                                return result
                            elseif key == 'FavoritedCosmetics' then
                                return data
                            end
                            return data
                        end
                        local ok = pcall(function() rawset(getOwner, 'Get', wrapper) end)
                        if ok and rawget(getOwner, 'Get') == wrapper then
                            LuaHookCosmeticsState.DirectDataGetOwner = getOwner
                            LuaHookCosmeticsState.DirectDataGetOriginal = originalGet
                            LuaHookCosmeticsState.DirectDataGetWrapper = wrapper
                        end
                    end
                end

                local weaponOwner, originalWeaponGet = resolveDirectMethodOwner(controller, 'GetWeaponData')
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    if LuaHookCosmeticsState.DirectGetWeaponDataOwner ~= nil then
                        LuaHookCosmetics.RestoreDirectDataHooks()
                    end
                    weaponOwner, originalWeaponGet = nil, nil
                end
                if type(weaponOwner) == 'table' and type(originalWeaponGet) == 'function' then
                    local current = rawget(weaponOwner, 'GetWeaponData')
                    if LuaHookCosmeticsState.DirectGetWeaponDataOwner ~= weaponOwner
                        or current ~= LuaHookCosmeticsState.DirectGetWeaponDataWrapper then
                        if LuaHookCosmeticsState.DirectGetWeaponDataOwner ~= nil then
                            LuaHookCosmetics.RestoreDirectDataHooks()
                            weaponOwner, originalWeaponGet = resolveDirectMethodOwner(controller, 'GetWeaponData')
                        end
                        local wrapper = function(self, weaponName)
                            local data = originalWeaponGet(self, weaponName)
                            if type(data) ~= 'table' or not LuaHookCosmetics.IsEnabled() then
                                return data
                            end
                            return LuaHookCosmetics.OverrideWeaponData(weaponName, data)
                        end
                        local ok = pcall(function() rawset(weaponOwner, 'GetWeaponData', wrapper) end)
                        if ok and rawget(weaponOwner, 'GetWeaponData') == wrapper then
                            LuaHookCosmeticsState.DirectGetWeaponDataOwner = weaponOwner
                            LuaHookCosmeticsState.DirectGetWeaponDataOriginal = originalWeaponGet
                            LuaHookCosmeticsState.DirectGetWeaponDataWrapper = wrapper
                        end
                    end
                end

                LuaHookCosmeticsState.DirectDataHooksInstalled =
                    LuaHookCosmeticsState.DirectDataGetOwner ~= nil
                    or LuaHookCosmeticsState.DirectGetWeaponDataOwner ~= nil
                return LuaHookCosmeticsState.DirectDataHooksInstalled == true
            end

            function LuaHookCosmetics.RestoreDirectDataHooks()
                local owner = LuaHookCosmeticsState.DirectDataGetOwner
                local wrapper = LuaHookCosmeticsState.DirectDataGetWrapper
                local original = LuaHookCosmeticsState.DirectDataGetOriginal
                if type(owner) == 'table' and type(wrapper) == 'function' and type(original) == 'function' then
                    if rawget(owner, 'Get') == wrapper then
                        pcall(function() rawset(owner, 'Get', original) end)
                    end
                end
                local weaponOwner = LuaHookCosmeticsState.DirectGetWeaponDataOwner
                local weaponWrapper = LuaHookCosmeticsState.DirectGetWeaponDataWrapper
                local weaponOriginal = LuaHookCosmeticsState.DirectGetWeaponDataOriginal
                if type(weaponOwner) == 'table' and type(weaponWrapper) == 'function' and type(weaponOriginal) == 'function' then
                    if rawget(weaponOwner, 'GetWeaponData') == weaponWrapper then
                        pcall(function() rawset(weaponOwner, 'GetWeaponData', weaponOriginal) end)
                    end
                end
                LuaHookCosmeticsState.DirectDataGetOwner = nil
                LuaHookCosmeticsState.DirectDataGetOriginal = nil
                LuaHookCosmeticsState.DirectDataGetWrapper = nil
                LuaHookCosmeticsState.DirectGetWeaponDataOwner = nil
                LuaHookCosmeticsState.DirectGetWeaponDataOriginal = nil
                LuaHookCosmeticsState.DirectGetWeaponDataWrapper = nil
                LuaHookCosmeticsState.DirectDataHooksInstalled = false
                return true
            end

            function LuaHookCosmetics.ResolvePlayerDataGetWeaponDataFunction()
                local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                local metatable = type(playerDataController) == 'table' and getmetatable(playerDataController) or nil
                local index = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                return type(index) == 'table' and rawget(index, 'GetWeaponData') or nil
            end
            function LuaHookCosmetics.FindOriginalWeaponData(weaponName)
                local inventory = LuaHookCosmetics.ResolveOriginalPlayerDataField('WeaponInventory')
                if type(inventory) ~= 'table' then
                    return nil
                end
                for _, weaponData in pairs(inventory) do
                    if type(weaponData) == 'table' and rawget(weaponData, 'Name') == weaponName then
                        return weaponData
                    end
                end
                return nil
            end
            function LuaHookCosmetics.EnsureItemDataHook()
                if LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantIndex ~= nil then
                    local hookedFunction = LuaHookCosmeticsState.PlayerDataGetWeaponDataFunction
                    local playerDataUtility = LuaHookCosmeticsState.PlayerDataUtility
                    local wrapper = LuaHookCosmeticsState.PlayerDataUtilityGetWeaponDataWrapper
                    local index = LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantIndex
                    local intact = false
                    if type(hookedFunction) == 'function' and type(playerDataUtility) == 'table'
                        and type(index) == 'number' and type(wrapper) == 'function'
                        and type(debug.getconstants) == 'function' then
                        local okConstants, constants = pcall(debug.getconstants, hookedFunction)
                        intact = okConstants and type(constants) == 'table'
                            and constants[index] == RIVALS_GET_WEAPON_DATA_SENTINEL
                            and rawget(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL) == wrapper
                    end
                    if intact then
                        return true
                    end
                    LuaHookCosmetics.RestoreItemDataHook()
                end
                local getWeaponData = LuaHookCosmetics.ResolvePlayerDataGetWeaponDataFunction()
                local playerDataUtility = LuaHookCosmetics.ResolvePlayerDataUtility()
                if type(getWeaponData) ~= 'function' or type(playerDataUtility) ~= 'table'
                    or type(debug.getconstants) ~= 'function' or type(debug.setconstant) ~= 'function' then
                    return false
                end
                local okConstants, constants = pcall(debug.getconstants, getWeaponData)
                if not okConstants or type(constants) ~= 'table' then
                    return false
                end
                local constantIndex = nil
                for index, value in pairs(constants) do
                    if value == 'GetWeaponData' then
                        constantIndex = index
                        break
                    end
                end
                if constantIndex == nil then
                    return false
                end
                local previousSentinel = rawget(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL)
                local okSet = pcall(debug.setconstant, getWeaponData, constantIndex, RIVALS_GET_WEAPON_DATA_SENTINEL)
                if not okSet then
                    return false
                end
                local verifyOk, verifyConstants = pcall(debug.getconstants, getWeaponData)
                if not verifyOk or type(verifyConstants) ~= 'table'
                    or verifyConstants[constantIndex] ~= RIVALS_GET_WEAPON_DATA_SENTINEL then
                    pcall(debug.setconstant, getWeaponData, constantIndex, 'GetWeaponData')
                    return false
                end
                local weaponDataWrapper = function(_, playerData, weaponName)
                    local originalWeaponData = LuaHookCosmetics.FindOriginalWeaponData(weaponName)
                    if originalWeaponData == nil then
                        return nil
                    end
                    local player = type(playerData) == 'table' and rawget(playerData, 'Player') or nil
                    if player == nil and type(playerData) == 'table' then
                        player = rawget(playerData, '_player_object')
                    end
                    if typeof(player) ~= 'Instance' or not player:IsA('Player') then
                        player = LP
                    end
                    if player ~= LP or not LuaHookCosmetics.IsEnabled() then
                        return originalWeaponData
                    end
                    return LuaHookCosmetics.OverrideWeaponData(weaponName, originalWeaponData)
                end
                local okRawSet = pcall(rawset, playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL, weaponDataWrapper)
                if not okRawSet or rawget(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL) ~= weaponDataWrapper then
                    pcall(debug.setconstant, getWeaponData, constantIndex, 'GetWeaponData')
                    return false
                end
                LuaHookCosmeticsState.PlayerDataUtility = playerDataUtility
                LuaHookCosmeticsState.PlayerDataUtilityGetWeaponData = previousSentinel
                LuaHookCosmeticsState.PlayerDataUtilityGetWeaponDataWrapper = weaponDataWrapper
                LuaHookCosmeticsState.PlayerDataGetWeaponDataFunction = getWeaponData
                LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantIndex = constantIndex
                LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantValue = 'GetWeaponData'
                return true
            end
            function LuaHookCosmetics.RestoreItemDataHook()
                local getWeaponData = LuaHookCosmeticsState.PlayerDataGetWeaponDataFunction
                local constantIndex = LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantIndex
                local originalConstant = LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantValue
                if type(getWeaponData) == 'function' and type(constantIndex) == 'number'
                    and type(debug.getconstants) == 'function' and type(debug.setconstant) == 'function' then
                    local okConstants, constants = pcall(debug.getconstants, getWeaponData)
                    if okConstants and type(constants) == 'table' and constants[constantIndex] == RIVALS_GET_WEAPON_DATA_SENTINEL then
                        pcall(debug.setconstant, getWeaponData, constantIndex, originalConstant)
                    end
                end
                local playerDataUtility = LuaHookCosmeticsState.PlayerDataUtility
                if type(playerDataUtility) == 'table' then
                    local wrapper = LuaHookCosmeticsState.PlayerDataUtilityGetWeaponDataWrapper
                    if rawget(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL) == wrapper then
                        rawset(
                            playerDataUtility,
                            RIVALS_GET_WEAPON_DATA_SENTINEL,
                            LuaHookCosmeticsState.PlayerDataUtilityGetWeaponData
                        )
                    end
                end
                LuaHookCosmeticsState.PlayerDataUtility = nil
                LuaHookCosmeticsState.PlayerDataUtilityGetWeaponData = nil
                LuaHookCosmeticsState.PlayerDataUtilityGetWeaponDataWrapper = nil
                LuaHookCosmeticsState.PlayerDataGetWeaponDataFunction = nil
                LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantIndex = nil
                LuaHookCosmeticsState.PlayerDataGetWeaponDataConstantValue = nil
                return true
            end
            function LuaHookCosmetics.EnsurePlayerDataHook()
                local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                local currentData = type(playerDataController) == 'table' and rawget(playerDataController, 'CurrentData') or nil
                if type(playerDataController) ~= 'table' or type(currentData) ~= 'table' then
                    return false
                end
                LuaHookCosmeticsState.PlayerDataController = playerDataController
                local dataLoaded = LuaHookCosmetics.LoadPlayerDataProxy(currentData)
                local directHooksLoaded = LuaHookCosmetics.EnsureDirectDataHooks()
                LuaHookCosmeticsState.ItemDataHooked = directHooksLoaded == true
                if dataLoaded == true and LuaHookCosmeticsState.PlayerDataAddedConnection == nil then
                    local playerDataAdded = rawget(playerDataController, 'PlayerDataAdded')
                    if type(playerDataAdded) == 'table' and type(playerDataAdded.Connect) == 'function' then
                        LuaHookCosmeticsState.PlayerDataAddedConnection = playerDataAdded:Connect(function()
                            task.defer(function()
                                local nextCurrentData = rawget(playerDataController, 'CurrentData')
                                LuaHookCosmetics.LoadPlayerDataProxy(nextCurrentData)
                                if LuaHookCosmetics.IsEnabled() and LuaHookCosmeticsState.ItemDataHooked ~= true then
                                    LuaHookCosmeticsState.ItemDataHooked = LuaHookCosmetics.EnsureDirectDataHooks() == true
                                end
                                LuaHookCosmetics.RefreshNativeCosmeticsScene()
                            end)
                        end)
                    end
                end
                LuaHookCosmeticsState.PlayerDataHooked = dataLoaded == true
                -- Player-data inventory/ownership is the core Unlock All path. Weapon-data
                -- overriding is optional because executor/runtime capabilities can differ.
                return dataLoaded == true
            end
            function LuaHookCosmetics.RestorePlayerDataHook()
                local playerDataAddedConnection = LuaHookCosmeticsState.PlayerDataAddedConnection
                if playerDataAddedConnection ~= nil then
                    playerDataAddedConnection:Disconnect()
                end
                LuaHookCosmeticsState.PlayerDataAddedConnection = nil
                LuaHookCosmetics.RestoreDirectDataHooks()
                LuaHookCosmetics.RestoreItemDataHook()
                LuaHookCosmetics.RestorePlayerDataProxy()
                LuaHookCosmeticsState.PlayerDataController = nil
                LuaHookCosmeticsState.PlayerDataHooked = false
                LuaHookCosmeticsState.ItemDataHooked = false
                return true
            end
            function LuaHookCosmetics.EncodeGameKey(key)
                local enumLibrary = ResolveEnumLibrary()
                local toEnum = type(enumLibrary) == 'table' and rawget(enumLibrary, '_to_enum') or nil
                local encoded = type(toEnum) == 'table' and rawget(toEnum, key) or nil
                return encoded ~= nil and encoded or key
            end
            function LuaHookCosmetics.ApplyLuaHookViewModelSelection(weaponName, viewModelData, selection)
                if type(viewModelData) ~= 'table' or type(selection) ~= 'table' then
                    return viewModelData
                end
                if selection.skin ~= nil then
                    viewModelData[LuaHookCosmetics.EncodeGameKey('Name')] = selection.skin == RIVALS_COSMETIC_NONE
                        and weaponName or selection.skin
                end
                if selection.wrap ~= nil then
                    local wrapKey = LuaHookCosmetics.EncodeGameKey('Wrap')
                    if selection.wrap.name == RIVALS_COSMETIC_NONE then
                        viewModelData[wrapKey] = nil
                    else
                        viewModelData[wrapKey] = {
                            Name = selection.wrap.name,
                            Inverted = selection.wrap.inverted == true,
                        }
                    end
                end
                if selection.charm ~= nil then
                    local charmKey = LuaHookCosmetics.EncodeGameKey('Charm')
                    if selection.charm == RIVALS_COSMETIC_NONE then
                        viewModelData[charmKey] = nil
                    else
                        local charm = { Name = selection.charm }
                        viewModelData[charmKey] = LuaHookCosmetics.PatchRankCharmPayload(charm) or charm
                    end
                end
                if selection.finisher ~= nil then
                    local finisherKey = LuaHookCosmetics.EncodeGameKey('Finisher')
                    if selection.finisher == RIVALS_COSMETIC_NONE then
                        viewModelData[finisherKey] = nil
                    else
                        viewModelData[finisherKey] = LuaHookCosmetics.BuildLuaHookCosmeticPayload(selection.finisher)
                    end
                end
                return viewModelData
            end
            function LuaHookCosmetics.GetClientItemRestoreData(player, weaponName)
                local byPlayer = LuaHookCosmeticsState.ClientItemRestoreData[player]
                return type(byPlayer) == 'table' and byPlayer[weaponName] or nil
            end
            -- Native cosmetic UI bindings were removed from this replacement build. Keep
            -- explicit no-op lifecycle functions so Apply/Restore cannot call a nil symbol.
            function LuaHookCosmetics.RefreshNativeCosmeticsScene()
                -- Native cosmetics refresh through their own StoresUpdated/runtime path.
                return true
            end
            function LuaHookCosmetics.EnsureNativeUiBindings()
                -- Native cosmetic slot bindings are not implemented in this replacement build.
                -- Do not report a successful live UI hook when the function is only a lifecycle stub.
                LuaHookCosmeticsState.NativeUiBound = false
                return false
            end
            function LuaHookCosmetics.RestoreNativeUiBindings()
                -- There is deliberately no exploit-side cosmetic picker in this build.
                LuaHookCosmeticsState.NativeUiBound = false
                return true
            end
            function LuaHookCosmetics.EnsureClientItemRestoreData(player, weaponName, viewModelData)
                if type(viewModelData) ~= 'table' then
                    return
                end
                local byPlayer = LuaHookCosmeticsState.ClientItemRestoreData[player]
                if type(byPlayer) ~= 'table' then
                    byPlayer = {}
                    LuaHookCosmeticsState.ClientItemRestoreData[player] = byPlayer
                end
                if byPlayer[weaponName] == nil then
                    byPlayer[weaponName] = table.clone(viewModelData)
                end
            end
            function LuaHookCosmetics.EnsureClientViewModelHook()
                if LuaHookCosmeticsState.ClientViewModelHooked then
                    local constructor = LuaHookCosmeticsState.ClientItemConstructor
                    local prototypeIndex = LuaHookCosmeticsState.ClientItemPrototypeIndex
                    local hookProxy = LuaHookCosmeticsState.ClientItemHookProxy
                    if type(constructor) == 'function' and type(prototypeIndex) == 'number'
                        and hookProxy ~= nil and type(debug.getupvalue) == 'function' then
                        local current = debug.getupvalue(constructor, prototypeIndex)
                        if current == hookProxy then
                            return true
                        end
                    end
                    LuaHookCosmetics.RestoreClientViewModelHook()
                end
                local clientItem = LuaHookCosmetics.ResolveClientItemClass()
                local constructor = type(clientItem) == 'table' and rawget(clientItem, 'new') or nil
                if type(constructor) ~= 'function' or type(debug.getupvalues) ~= 'function'
                    or type(debug.getstack) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local prototypeIndex = nil
                local prototype = nil
                for index, value in pairs(debug.getupvalues(constructor)) do
                    if type(value) == 'table' and rawget(value, 'CreateSpectatorSound') ~= nil then
                        prototypeIndex = index
                        prototype = value
                        break
                    end
                end
                if type(prototypeIndex) ~= 'number' or type(prototype) ~= 'table' then
                    return false
                end
                local proxy = {}
                proxy.__index = function(_, key)
                    local value = rawget(prototype, key)
                    if value == nil then
                        local metatable = getmetatable(prototype)
                        local index = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                        if type(index) == 'table' then
                            value = rawget(index, key)
                        elseif type(index) == 'function' then
                            value = index(prototype, key)
                        end
                    end
                    return value
                end
                proxy.__newindex = function(instance, key, value)
                    if key ~= 'Info' then
                        rawset(instance, key, value)
                        return
                    end
                    rawset(instance, 'Info', value)
                    setmetatable(instance, prototype)
                    local stack = debug.getstack(2, 1)
                    local viewModel = type(stack) == 'table' and rawget(stack, 'ViewModel') or nil
                    local clientFighter = rawget(instance, 'ClientFighter')
                    local player = type(clientFighter) == 'table' and rawget(clientFighter, 'Player') or nil
                    local weaponName = rawget(instance, 'Name')
                    local selection = player == LP and LuaHookCosmetics.BuildLuaHookItemSelection(weaponName) or nil
                    local dataKey = LuaHookCosmetics.EncodeGameKey('Data')
                    local viewModelData = type(viewModel) == 'table' and viewModel[dataKey] or nil
                    if type(selection) ~= 'table' or type(viewModelData) ~= 'table' then
                        return
                    end
                    LuaHookCosmetics.EnsureClientItemRestoreData(player, weaponName, viewModelData)
                    LuaHookCosmetics.ApplyLuaHookViewModelSelection(weaponName, viewModelData, selection)
                end
                debug.setupvalue(constructor, prototypeIndex, proxy)
                LuaHookCosmeticsState.ClientItemConstructor = constructor
                LuaHookCosmeticsState.ClientItemPrototype = prototype
                LuaHookCosmeticsState.ClientItemPrototypeIndex = prototypeIndex
                LuaHookCosmeticsState.ClientItemHookProxy = proxy
                LuaHookCosmeticsState.ClientViewModelHooked = true
                return true
            end
            function LuaHookCosmetics.RestoreClientViewModelHook()
                local constructor = LuaHookCosmeticsState.ClientItemConstructor
                local prototype = LuaHookCosmeticsState.ClientItemPrototype
                local prototypeIndex = LuaHookCosmeticsState.ClientItemPrototypeIndex
                local hookProxy = LuaHookCosmeticsState.ClientItemHookProxy
                if type(constructor) == 'function' and type(prototype) == 'table'
                    and type(prototypeIndex) == 'number' and type(debug.getupvalue) == 'function'
                    and type(debug.setupvalue) == 'function' then
                    local current = debug.getupvalue(constructor, prototypeIndex)
                    if current == hookProxy then
                        debug.setupvalue(constructor, prototypeIndex, prototype)
                    end
                end
                LuaHookCosmeticsState.ClientItemConstructor = nil
                LuaHookCosmeticsState.ClientItemPrototype = nil
                LuaHookCosmeticsState.ClientItemPrototypeIndex = nil
                LuaHookCosmeticsState.ClientItemHookProxy = nil
                LuaHookCosmeticsState.ClientViewModelHooked = false
                return true
            end
            local function getMethodFromObject(object, methodName)
                if type(object) ~= 'table' then
                    return nil
                end
                local direct = rawget(object, methodName)
                if type(direct) == 'function' then
                    return direct
                end
                local metatable = getmetatable(object)
                local index = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                if type(index) == 'table' then
                    local inherited = rawget(index, methodName)
                    if type(inherited) == 'function' then
                        return inherited
                    end
                end
                return nil
            end

            local NATIVE_COSMETICS_CONTROLLER_METHODS = {
                'SetRuntimeEnabled',
                'SetUnlockerEnabled',
                'SetUnlockedTypes',
                'SetUnlockedRarities',
                'SetSkinChangerChoice',
                'GetSkinChangerSelections',
                'SetEmote',
            }

            local function isNativeCosmeticsControllerShape(object)
                if type(object) ~= 'table'
                    or type(rawget(object, '_catalog')) ~= 'table'
                    or type(rawget(object, '_items')) ~= 'table'
                    or type(rawget(object, '_emotes')) ~= 'table'
                    or type(rawget(object, '_unlockerController')) ~= 'table' then
                    return false
                end
                for _, methodName in ipairs(NATIVE_COSMETICS_CONTROLLER_METHODS) do
                    if type(getMethodFromObject(object, methodName)) ~= 'function' then
                        return false
                    end
                end
                return true
            end

            local function isNativeCosmeticsConfigShape(object, controller)
                if type(object) ~= 'table' then
                    return false
                end
                local linkedController = rawget(object, '_cosmetics')
                if type(linkedController) ~= 'table'
                    or (type(controller) == 'table' and linkedController ~= controller) then
                    return false
                end
                if type(getMethodFromObject(object, 'SetRuntimeEnabled')) ~= 'function'
                    or type(getMethodFromObject(object, 'SetUnlockedTypes')) ~= 'function'
                    or type(getMethodFromObject(object, 'SetUnlockedRarities')) ~= 'function'
                    or type(getMethodFromObject(object, 'GetStateConfigState')) ~= 'function' then
                    return false
                end
                return isNativeCosmeticsControllerShape(linkedController)
            end

            local function nativeCosmeticsPairLooksValid(controller, config)
                if not isNativeCosmeticsControllerShape(controller) then
                    return false
                end
                if type(config) == 'table' and rawget(config, '_cosmetics') ~= controller then
                    return false
                end
                return true
            end

            local function getNativeCosmeticsMonotonicTime()
                if type(time) == 'function' then
                    local ok, value = pcall(time)
                    if ok and type(value) == 'number' then
                        return value
                    end
                end
                return os.clock()
            end

            function LuaHookCosmetics.ResolveNativeCosmeticsController(forceRefresh)
                local cached = LuaHookCosmeticsState.NativeCosmeticsController
                local cachedConfig = LuaHookCosmeticsState.NativeCosmeticsConfig
                local now = getNativeCosmeticsMonotonicTime()

                if not forceRefresh and nativeCosmeticsPairLooksValid(cached, cachedConfig) then
                    return cached
                end

                local lastScan = tonumber(LuaHookCosmeticsState.NativeCosmeticsControllerLastScan) or 0
                if not forceRefresh and now - lastScan < 1 then
                    return nil
                end
                LuaHookCosmeticsState.NativeCosmeticsControllerLastScan = now

                LuaHookCosmeticsState.NativeCosmeticsController = nil
                LuaHookCosmeticsState.NativeCosmeticsControllerSource = nil
                LuaHookCosmeticsState.NativeCosmeticsConfig = nil

                local env = ResolveGlobalEnv()
                local getgcFn = type(env) == 'table' and rawget(env, 'getgc') or nil
                if type(getgcFn) ~= 'function' then
                    getgcFn = rawget(_G, 'getgc')
                end
                if type(getgcFn) ~= 'function' then
                    return nil
                end

                local ok, objects = pcall(getgcFn, true)
                if not ok or type(objects) ~= 'table' then
                    return nil
                end

                local configs = {}
                local controllers = {}
                local roots = {}

                for _, object in ipairs(objects) do
                    if type(object) == 'table' then
                        if isNativeCosmeticsControllerShape(object) then
                            local score = 100
                            if rawget(object, '_runtimeEnabled') == true then
                                score = score + 3
                            end
                            controllers[#controllers + 1] = { object = object, score = score }
                        end

                        local linkedController = rawget(object, '_cosmetics')
                        if isNativeCosmeticsConfigShape(object, linkedController) then
                            local score = 130
                            if type(rawget(object, '_stateConfig')) == 'table' then
                                score = score + 2
                            end
                            if rawget(object, 'stateConfigLoaded') ~= nil then
                                score = score + 1
                            end
                            configs[#configs + 1] = {
                                config = object,
                                controller = linkedController,
                                score = score,
                            }
                        end

                        local rootController = rawget(object, 'cosmetics')
                        local rootConfig = rawget(object, 'cosmeticsConfig')
                        if type(rootController) == 'table'
                            and type(rootConfig) == 'table'
                            and isNativeCosmeticsControllerShape(rootController)
                            and isNativeCosmeticsConfigShape(rootConfig, rootController)
                            and rawget(rootConfig, '_cosmetics') == rootController then
                            local current = roots[rootController] or 0
                            roots[rootController] = current + 40
                        end
                    end
                end

                local bestPair, bestScore = nil, -math.huge
                for _, candidate in ipairs(configs) do
                    local score = candidate.score + (roots[candidate.controller] or 0)
                    if score > bestScore then
                        bestPair = candidate
                        bestScore = score
                    end
                end

                if bestPair then
                    LuaHookCosmeticsState.NativeCosmeticsController = bestPair.controller
                    LuaHookCosmeticsState.NativeCosmeticsControllerSource = 'GC:NativeCosmeticsConfigPair'
                    LuaHookCosmeticsState.NativeCosmeticsConfig = bestPair.config
                    LuaHookCosmeticsState.NativeCosmeticsControllerResolutionGeneration =
                        (LuaHookCosmeticsState.NativeCosmeticsControllerResolutionGeneration or 0) + 1
                    return bestPair.controller
                end

                local bestController, bestControllerScore = nil, -math.huge
                for _, candidate in ipairs(controllers) do
                    if candidate.score > bestControllerScore then
                        bestController = candidate.object
                        bestControllerScore = candidate.score
                    end
                end
                if bestController then
                    LuaHookCosmeticsState.NativeCosmeticsController = bestController
                    LuaHookCosmeticsState.NativeCosmeticsControllerSource = 'GC:NativeCosmeticsController'
                    LuaHookCosmeticsState.NativeCosmeticsControllerResolutionGeneration =
                        (LuaHookCosmeticsState.NativeCosmeticsControllerResolutionGeneration or 0) + 1
                    return bestController
                end
                return nil
            end

            local function normalizeNativeCosmeticValue(value)
                if value == nil or value == RIVALS_COSMETIC_UNSELECTED then
                    return nil
                end
                if value == RIVALS_COSMETIC_NONE then
                    return 'NONE_COSMETIC'
                end
                if value == RIVALS_COSMETIC_RANDOM then
                    return 'RANDOM_COSMETIC'
                end
                return value
            end

            local function cloneNativeSelection(value)
                if type(value) ~= 'table' then
                    return value
                end
                local clone = {}
                for key, child in pairs(value) do
                    if type(child) == 'table' then
                        local nested = {}
                        for nestedKey, nestedValue in pairs(child) do
                            nested[nestedKey] = nestedValue
                        end
                        clone[key] = nested
                    else
                        clone[key] = child
                    end
                end
                return clone
            end

            function LuaHookCosmetics.CaptureNativeSkinChangerSelection(controller, weaponName)
                if type(controller) ~= 'table' or type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                if LuaHookCosmeticsState.NativeSkinChangerOriginalSelections[weaponName] ~= nil then
                    return true
                end
                local getter = getMethodFromObject(controller, 'GetSkinChangerSelections')
                if type(getter) ~= 'function' then
                    return false
                end
                local ok, current = pcall(getter, controller, weaponName)
                if not ok then
                    return false
                end
                LuaHookCosmeticsState.NativeSkinChangerOriginalSelections[weaponName] = {
                    Exists = current ~= nil,
                    Value = cloneNativeSelection(current),
                }
                LuaHookCosmeticsState.NativeSkinChangerTouchedWeapons[weaponName] = true
                return true
            end

            local function restoreNativeSelectionKind(controller, weaponName, kind, original)
                local setter = getMethodFromObject(controller, 'SetSkinChangerChoice')
                if type(setter) ~= 'function' then
                    return false
                end
                local choice = { kind = kind }
                if kind == 'Wrap' then
                    choice.wrap = original and original.wrap or nil
                elseif kind == 'Skin' or kind == 'Charm' or kind == 'Finisher' then
                    local fieldName = kind == 'Skin' and 'skin'
                        or kind == 'Charm' and 'charm'
                        or 'finisher'
                    choice.name = original and original[fieldName] or nil
                else
                    return false
                end
                return pcall(setter, controller, weaponName, choice)
            end

            function LuaHookCosmetics.RestoreNativeSkinChanger()
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                if not isNativeCosmeticsControllerShape(controller) then
                    controller = LuaHookCosmetics.ResolveNativeCosmeticsController(true)
                end
                if type(controller) ~= 'table' then
                    LuaHookCosmeticsState.NativeSkinChangerOriginalSelections = {}
                    LuaHookCosmeticsState.NativeSkinChangerTouchedWeapons = {}
                    LuaHookCosmeticsState.NativeSkinChangerApplied = false
                    LuaHookCosmeticsState.NativeSkinChangerWasEnabled = nil
                    return false
                end

                local setter = getMethodFromObject(controller, 'SetSkinChangerChoice')
                local setEnabled = getMethodFromObject(controller, 'SetSkinChangerEnabled')
                if type(setter) ~= 'function' then
                    return false
                end

                for weaponName in pairs(LuaHookCosmeticsState.NativeSkinChangerTouchedWeapons) do
                    local snapshot = LuaHookCosmeticsState.NativeSkinChangerOriginalSelections[weaponName]
                    local original = type(snapshot) == 'table' and snapshot.Value or nil
                    restoreNativeSelectionKind(controller, weaponName, 'Skin', original)
                    restoreNativeSelectionKind(controller, weaponName, 'Wrap', original)
                    restoreNativeSelectionKind(controller, weaponName, 'Charm', original)
                    restoreNativeSelectionKind(controller, weaponName, 'Finisher', original)
                end

                if type(setEnabled) == 'function' and LuaHookCosmeticsState.NativeSkinChangerWasEnabled ~= nil then
                    pcall(setEnabled, controller, LuaHookCosmeticsState.NativeSkinChangerWasEnabled == true)
                end

                LuaHookCosmeticsState.NativeSkinChangerOriginalSelections = {}
                LuaHookCosmeticsState.NativeSkinChangerTouchedWeapons = {}
                LuaHookCosmeticsState.NativeSkinChangerApplied = false
                LuaHookCosmeticsState.NativeSkinChangerWasEnabled = nil
                return true
            end

            local function setNativeCosmeticChoice(controller, weaponName, kind, value, inverted)
                local setter = getMethodFromObject(controller, 'SetSkinChangerChoice')
                if type(setter) ~= 'function' then
                    return false
                end

                local normalized = normalizeNativeCosmeticValue(value)
                local choice = { kind = kind }
                if kind == 'Wrap' then
                    if normalized == nil or normalized == 'NONE_COSMETIC' then
                        choice.wrap = nil
                    else
                        choice.wrap = {
                            name = normalized,
                            inverted = inverted == true,
                        }
                    end
                elseif kind == 'Skin' or kind == 'Charm' or kind == 'Finisher' then
                    choice.name = normalized
                else
                    return false
                end

                return pcall(setter, controller, weaponName, choice)
            end

            function LuaHookCosmetics.ApplyNativeSkinChanger()
                -- Compatibility stub. The native SkinChanger layer is the custom-picker
                -- layer from luahook stuff.lua and must remain untouched.
                LuaHookCosmeticsState.NativeSkinChangerApplied = false
                return true
            end
            function LuaHookCosmetics.EnsureFinisherHook()
                local clientEntity = LuaHookCosmetics.ResolveClientEntityClass()
                if type(clientEntity) ~= 'table' then
                    return false
                end

                if LuaHookCosmeticsState.ClientEntityFinisherHooked then
                    local current = rawget(clientEntity, '_PlayFinisher')
                    if current == LuaHookCosmeticsState.ClientEntityPlayFinisherWrapper then
                        return true
                    end
                    LuaHookCosmetics.RestoreFinisherHook()
                end

                if rawget(clientEntity, '__LuaHookHookFinisherHooked') == true
                    and rawget(clientEntity, '__LuaHookHookOriginalPlayFinisher') ~= LuaHookCosmeticsState.OriginalClientEntityPlayFinisher then
                    return false
                end

                local _, replicateFromServer = resolveDirectMethodOwner(clientEntity, 'ReplicateFromServer')
                if type(replicateFromServer) ~= 'function'
                    or type(debug.getconstants) ~= 'function'
                    or type(debug.setconstant) ~= 'function' then
                    return false
                end

                local okConstants, constants = pcall(debug.getconstants, replicateFromServer)
                if not okConstants or type(constants) ~= 'table' then
                    return false
                end

                local constantIndex
                for index, value in pairs(constants) do
                    if value == '_PlayFinisher' then
                        constantIndex = index
                        break
                    end
                end
                if constantIndex == nil then
                    return false
                end

                local playOwner, originalPlayFinisher = resolveDirectMethodOwner(clientEntity, '_PlayFinisher')
                if type(playOwner) ~= 'table' or type(originalPlayFinisher) ~= 'function' then
                    return false
                end

                local sentinel = '_PlayFinisher\0LuaHook'
                local function wrapper(self, p3079, p3080, p3081, p3082)
                    local function callOriginal()
                        return originalPlayFinisher(self, p3079, p3080, p3081, p3082)
                    end

                    if not LuaHookCosmetics.IsEnabled()
                        or typeof(p3081) ~= 'Instance'
                        or not p3081:IsA('Player')
                        or p3081 ~= LP then
                        return callOriginal()
                    end

                    local finisherName = LuaHookCosmetics.ResolveSelectedPlaybackFinisherName()
                    if not LuaHookCosmetics.IsCosmeticValueSelected(finisherName) then
                        return callOriginal()
                    end

                    local model = rawget(self, 'Model')
                    if typeof(model) ~= 'Instance' or not model:IsA('Model') then
                        local okModel, modelValue = pcall(function() return self.Model end)
                        model = okModel and modelValue or nil
                    end
                    if typeof(model) ~= 'Instance' or not model:IsA('Model') then
                        return callOriginal()
                    end

                    local finishersFolder = LuaHookCosmetics.ResolveFinisherAssetsFolder()
                    local finisherModuleScript = finishersFolder and finishersFolder:FindFirstChild(finisherName)
                    if not finisherModuleScript then
                        return callOriginal()
                    end

                    local humanoid = model:FindFirstChildOfClass('Humanoid')
                    local root = model:FindFirstChild('HumanoidRootPart')
                    if not humanoid or not root then
                        return callOriginal()
                    end

                    local cloneOk, clone = pcall(function()
                        return model:Clone()
                    end)
                    if not cloneOk or typeof(clone) ~= 'Instance' or not clone:IsA('Model') then
                        return callOriginal()
                    end

                    local cloneHumanoid = clone:FindFirstChildOfClass('Humanoid')
                    local cloneRoot = clone:FindFirstChild('HumanoidRootPart')
                    if not cloneHumanoid or not cloneRoot then
                        pcall(function() clone:Destroy() end)
                        return callOriginal()
                    end

                    local originalLocalTransparency = {}
                    for _, descendant in ipairs(model:GetDescendants()) do
                        if descendant:IsA('BasePart') then
                            originalLocalTransparency[descendant] = descendant.LocalTransparencyModifier
                            pcall(function() descendant.LocalTransparencyModifier = 1 end)
                        end
                    end

                    pcall(function()
                        cloneRoot.AssemblyLinearVelocity = Vector3.zero
                        cloneHumanoid.Health = 0
                        clone:PivotTo(model:GetPivot())
                    end)

                    for _, part in ipairs(clone:GetDescendants()) do
                        if part:IsA('BasePart') then
                            pcall(function() part.CollisionGroup = 'Players' end)
                        end
                    end
                    clone.Parent = model.Parent

                    local restoreDone = false
                    local function restoreVisual()
                        if restoreDone then
                            return
                        end
                        restoreDone = true
                        for part, transparency in pairs(originalLocalTransparency) do
                            if part and part.Parent then
                                pcall(function() part.LocalTransparencyModifier = transparency end)
                            end
                        end
                    end

                    model.Destroying:Once(restoreVisual)
                    clone.Destroying:Once(restoreVisual)
                    task.delay(12, restoreVisual)

                    local requireOk, finisherModule = pcall(require, finisherModuleScript)
                    if not requireOk or type(finisherModule) ~= 'table'
                        or type(finisherModule.new) ~= 'function' then
                        restoreVisual()
                        pcall(function() clone:Destroy() end)
                        return callOriginal()
                    end

                    local constructorOk, finisherObject = pcall(
                        finisherModule.new,
                        cloneHumanoid,
                        p3080,
                        p3081
                    )
                    if not constructorOk or type(finisherObject) ~= 'table' then
                        restoreVisual()
                        pcall(function() clone:Destroy() end)
                        return callOriginal()
                    end

                    if type(finisherObject.SetSerial) == 'function' then
                        pcall(finisherObject.SetSerial, finisherObject, p3082)
                    end

                    local currentFinisher = rawget(self, '_current_finisher')
                    if type(currentFinisher) == 'table' and type(currentFinisher.Destroy) == 'function' then
                        pcall(currentFinisher.Destroy, currentFinisher)
                    end
                    rawset(self, '_current_finisher', finisherObject)

                    if type(finisherObject.PlayServer) == 'function' then
                        task.spawn(function()
                            pcall(finisherObject.PlayServer, finisherObject)
                        end)
                    end
                    if type(finisherObject.PlayClient) == 'function' then
                        task.spawn(function()
                            pcall(finisherObject.PlayClient, finisherObject)
                        end)
                    end

                    return nil
                end

                local previousConstant = constants[constantIndex]
                local okSet = pcall(debug.setconstant, replicateFromServer, constantIndex, sentinel)
                if not okSet then
                    return false
                end
                local verifyOk, verifyConstants = pcall(debug.getconstants, replicateFromServer)
                if not verifyOk or type(verifyConstants) ~= 'table'
                    or verifyConstants[constantIndex] ~= sentinel then
                    pcall(debug.setconstant, replicateFromServer, constantIndex, previousConstant)
                    return false
                end

                rawset(clientEntity, '__LuaHookHookOriginalPlayFinisher', originalPlayFinisher)
                rawset(clientEntity, '__LuaHookHookFinisherHooked', true)
                rawset(clientEntity, sentinel, wrapper)
                LuaHookCosmeticsState.HookedClientEntityClass = clientEntity
                LuaHookCosmeticsState.OriginalClientEntityPlayFinisher = originalPlayFinisher
                LuaHookCosmeticsState.ClientEntityPlayFinisherWrapper = wrapper
                LuaHookCosmeticsState.FinisherReplicateFromServerFunction = replicateFromServer
                LuaHookCosmeticsState.FinisherReplicateFromServerConstantIndex = constantIndex
                LuaHookCosmeticsState.FinisherReplicateFromServerOriginalConstant = previousConstant
                LuaHookCosmeticsState.FinisherHookSentinel = sentinel
                LuaHookCosmeticsState.ClientEntityFinisherHooked = true
                return true
            end
            function LuaHookCosmetics.RestoreFinisherHook()
                local clientEntity = LuaHookCosmeticsState.HookedClientEntityClass
                local originalPlayFinisher = LuaHookCosmeticsState.OriginalClientEntityPlayFinisher
                local wrappedPlayFinisher = LuaHookCosmeticsState.ClientEntityPlayFinisherWrapper
                local replicateFromServer = LuaHookCosmeticsState.FinisherReplicateFromServerFunction
                local constantIndex = LuaHookCosmeticsState.FinisherReplicateFromServerConstantIndex
                local originalConstant = LuaHookCosmeticsState.FinisherReplicateFromServerOriginalConstant
                local sentinel = LuaHookCosmeticsState.FinisherHookSentinel

                if type(replicateFromServer) == 'function'
                    and type(constantIndex) == 'number'
                    and originalConstant ~= nil
                    and type(debug.setconstant) == 'function'
                    and type(debug.getconstants) == 'function' then
                    local okConstants, constants = pcall(debug.getconstants, replicateFromServer)
                    if okConstants and type(constants) == 'table' then
                        if constants[constantIndex] == sentinel or constants[constantIndex] == originalConstant then
                            pcall(debug.setconstant, replicateFromServer, constantIndex, originalConstant)
                        end
                    end
                end

                if type(clientEntity) == 'table' and type(originalPlayFinisher) == 'function' then
                    local current = rawget(clientEntity, '_PlayFinisher')
                    if current == wrappedPlayFinisher then
                        pcall(function() rawset(clientEntity, '_PlayFinisher', originalPlayFinisher) end)
                    end
                    if sentinel ~= nil and rawget(clientEntity, sentinel) == wrappedPlayFinisher then
                        pcall(function() rawset(clientEntity, sentinel, nil) end)
                    end
                    if rawget(clientEntity, '__LuaHookHookOriginalPlayFinisher') == originalPlayFinisher then
                        pcall(function()
                            rawset(clientEntity, '__LuaHookHookOriginalPlayFinisher', nil)
                            rawset(clientEntity, '__LuaHookHookFinisherHooked', nil)
                        end)
                    end
                end

                LuaHookCosmeticsState.HookedClientEntityClass = nil
                LuaHookCosmeticsState.OriginalClientEntityPlayFinisher = nil
                LuaHookCosmeticsState.ClientEntityPlayFinisherWrapper = nil
                LuaHookCosmeticsState.FinisherReplicateFromServerFunction = nil
                LuaHookCosmeticsState.FinisherReplicateFromServerConstantIndex = nil
                LuaHookCosmeticsState.FinisherReplicateFromServerOriginalConstant = nil
                LuaHookCosmeticsState.FinisherHookSentinel = nil
                LuaHookCosmeticsState.ClientEntityFinisherHooked = false
                return true
            end
            function LuaHookCosmetics.QueueRuntimeApplyWhenReady()
                if LuaHookCosmeticsState.RuntimeApplyRetryPending then
                    return false
                end
                LuaHookCosmeticsState.RuntimeApplyRetryPending = true
                task.spawn(GuardLuaHookCallback('Cosmetics_WaitForReplicatedState', function()
                    while LuaHookCosmeticsState.RuntimeApplyRetryPending
                        and (LuaHookCosmetics.IsEnabled() or RivalsEmotes.IsEnabled())
                        and not ReplicatedStateReady do
                        task.wait(0.25)
                    end
                    LuaHookCosmeticsState.RuntimeApplyRetryPending = false
                    if (LuaHookCosmetics.IsEnabled() or RivalsEmotes.IsEnabled())
                        and ReplicatedStateReady then
                        LuaHookCosmetics.ApplyAll()
                        RivalsEmotes.ApplyAll()
                    end
                end))
                return true
            end
            function LuaHookCosmetics.ShouldUseCosmeticsRuntime()
                if not LuaHookCosmetics.IsEnabled() then
                    LuaHookCosmeticsState.RuntimeApplyRetryPending = false
                    return false
                end
                if not ReplicatedStateReady then
                    LuaHookCosmetics.QueueRuntimeApplyWhenReady()
                    return false
                end
                return true
            end
            function LuaHookCosmetics.SetConfigName(configName)
                if type(configName) == 'string' and configName ~= '' then
                    LuaHookCosmeticsState.CosmeticsConfigName = configName
                end
            end
            function RivalsEmotes.ResolveEmoteValues()
                local cachedEmoteValues = RivalsEmotes.Catalog.EmoteValues
                if cachedEmoteValues then
                    return cachedEmoteValues
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = {DEFAULT_RIVALS_COSMETIC_VALUE}
                if type(cosmetics) == 'table' then
                    local emoteNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if type(cosmeticData) == 'table' and cosmeticData.Type == 'Emote' then
                            if not LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                                emoteNames[#emoteNames + 1] = cosmeticName
                            end
                        end
                    end
                    table.sort(emoteNames)
                    for _, emoteName in ipairs(emoteNames) do
                        values[#values + 1] = emoteName
                    end
                end
                RivalsEmotes.Catalog.EmoteValues = values
                return values
            end
            function RivalsEmotes.IsCatalogEmoteName(emoteName)
                if not LuaHookCosmetics.IsCosmeticValueSelected(emoteName) then
                    return false
                end
                if LuaHookCosmetics.IsPlaceholderCatalogName(emoteName) then
                    return false
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local cosmeticData = type(cosmetics) == 'table' and cosmetics[emoteName] or nil
                return type(cosmeticData) == 'table' and cosmeticData.Type == 'Emote'
            end
            function RivalsEmotes.ResolveEmoteSlotCount()
                local constants = RivalsEmotes.ResolveConstants()
                if type(constants) == 'table' then
                    local count = tonumber(constants.MAX_EQUIPPABLE_EMOTES)
                    if count and count >= 1 then
                        return math.floor(count)
                    end
                end
                return 8
            end
            function RivalsEmotes.BuildEquippedEmoteData(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return nil
                end
                -- Native cosmetics.emotes resolver returns the minimal serial shape.
                return { Name = emoteName }
            end
            function RivalsEmotes.BuildUnlockedCosmeticInventory(baseInventory)
                local unlockedInventory = {}
                if type(baseInventory) == 'table' then
                    for key, value in pairs(baseInventory) do
                        unlockedInventory[key] = value
                    end
                end
                for _, emoteName in ipairs(RivalsEmotes.ResolveEmoteValues()) do
                    if LuaHookCosmetics.IsCosmeticValueSelected(emoteName) then
                        unlockedInventory[emoteName] = true
                    end
                end
                return unlockedInventory
            end
            function RivalsEmotes.ResolveRawCosmeticInventory()
                return LuaHookCosmetics.ResolveOriginalPlayerDataField('CosmeticInventory')
            end
            function RivalsEmotes.IsNaturallyOwnedEmote(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return false
                end
                local inventory = RivalsEmotes.ResolveRawCosmeticInventory()
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                if type(cosmeticLibrary) == 'table' and type(cosmeticLibrary.OwnsCosmetic) == 'function' then
                    local ok, owns = pcall(cosmeticLibrary.OwnsCosmetic, cosmeticLibrary, inventory, emoteName)
                    if ok then
                        return owns == true
                    end
                end
                return type(inventory) == 'table' and inventory[emoteName] ~= nil
            end
            function RivalsEmotes.ResolveEmoteController()
                local cachedEmoteController = RivalsEmotes.Catalog.EmoteController
                if cachedEmoteController then
                    return cachedEmoteController
                end
                local playerScripts = LuaHookCosmetics.ResolvePlayerScripts()
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local emoteControllerModule = controllers and controllers:FindFirstChild('EmoteController')
                if not emoteControllerModule then
                    return nil
                end
                local ok, emoteController = pcall(require, emoteControllerModule)
                if not ok or type(emoteController) ~= 'table' then
                    return nil
                end
                RivalsEmotes.Catalog.EmoteController = emoteController
                return emoteController
            end
            function RivalsEmotes.ResolveConstants()
                local cachedConstants = RivalsEmotes.Catalog.Constants
                if cachedConstants then
                    return cachedConstants
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local constantsModule = modules and modules:FindFirstChild('CONSTANTS')
                if not constantsModule then
                    return nil
                end
                local ok, constants = pcall(require, constantsModule)
                if not ok or type(constants) ~= 'table' then
                    return nil
                end
                RivalsEmotes.Catalog.Constants = constants
                return constants
            end
            function RivalsEmotes.ResolveCurrentData()
                local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                return playerDataController and playerDataController.CurrentData or nil
            end
            function RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                local cloned = {}
                if type(equippedEmotes) == 'table' then
                    for key, value in pairs(equippedEmotes) do
                        cloned[key] = value
                    end
                end
                return cloned
            end
            function RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData then
                    return nil
                end
                if type(currentData.Get) == 'function' then
                    local ok, equippedEmotes = pcall(function()
                        return currentData:Get('EquippedEmotes')
                    end)
                    if ok and type(equippedEmotes) == 'table' then
                        return equippedEmotes
                    end
                end
                local data = type(currentData.Data) == 'table' and currentData.Data or nil
                if not data then
                    return nil
                end
                if type(data.EquippedEmotes) ~= 'table' then
                    data.EquippedEmotes = {}
                end
                return data.EquippedEmotes
            end
            function RivalsEmotes.IsValidEquippedEmoteData(data)
                return type(data) == 'table' and LuaHookCosmetics.IsCosmeticValueSelected(data.Name)
            end
            function RivalsEmotes.ResolveSlotOptionId(slotIndex)
                local numericSlot = math.floor(tonumber(slotIndex) or 1)
                return string.format('P5EMOTE_SLOT%d', numericSlot)
            end
            function RivalsEmotes.ResolveSelectedEmoteForSlot(slotIndex)
                local numericSlot = math.floor(tonumber(slotIndex) or 0)
                if numericSlot < 1 then
                    return nil
                end

                -- Primary source: the actual in-game equipped emote slots.
                local order = LuaHookCosmeticsState.CosmeticMultiEmoteOrder
                local loadoutValue = type(order) == 'table' and order[numericSlot] or nil
                if RivalsEmotes.IsCatalogEmoteName(loadoutValue) then
                    return loadoutValue
                end

                -- Legacy compatibility: respect an explicitly-created slot option when
                -- an older saved config/UI is still present.
                local option = Options[RivalsEmotes.ResolveSlotOptionId(numericSlot)]
                local emoteName = option and option.Value or nil
                if RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return emoteName
                end
                return nil
            end
            local function cloneCosmeticSet(value)
                if type(value) ~= 'table' then
                    return nil
                end
                local cloned = {}
                for key, enabled in pairs(value) do
                    if enabled == true then
                        cloned[key] = true
                    end
                end
                return cloned
            end

            function LuaHookCosmetics.ResolveNativeCosmeticsConfig(forceRefresh)
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                local cached = LuaHookCosmeticsState.NativeCosmeticsConfig

                if type(controller) ~= 'table' then
                    controller = LuaHookCosmetics.ResolveNativeCosmeticsController(forceRefresh == true)
                end

                if nativeCosmeticsPairLooksValid(controller, cached)
                    and type(cached) == 'table'
                    and type(getMethodFromObject(cached, 'SetUnlockedTypes')) == 'function'
                    and type(getMethodFromObject(cached, 'SetUnlockedRarities')) == 'function' then
                    return cached
                end

                if type(controller) == 'table' then
                    local linked = rawget(controller, '__luahookCosmeticsConfig')
                    if isNativeCosmeticsConfigShape(linked, controller) then
                        LuaHookCosmeticsState.NativeCosmeticsConfig = linked
                        return linked
                    end
                end

                -- A controller can natively SetUnlockedTypes/SetUnlockedRarities without
                -- a separate cosmeticsConfig wrapper. Do not force another getgc scan on
                -- every ApplyAll call just to look for an optional wrapper. A forced scan is
                -- only useful during explicit re-discovery/recovery.
                if forceRefresh == true then
                    LuaHookCosmeticsState.NativeCosmeticsConfig = nil
                    LuaHookCosmetics.ResolveNativeCosmeticsController(true)
                    local resolvedController = LuaHookCosmeticsState.NativeCosmeticsController
                    local resolvedConfig = LuaHookCosmeticsState.NativeCosmeticsConfig
                    if nativeCosmeticsPairLooksValid(resolvedController, resolvedConfig)
                        and type(resolvedConfig) == 'table' then
                        return resolvedConfig
                    end
                end
                return nil
            end

            function LuaHookCosmetics.ResolveAllNativeCosmeticTypesAndRarities()
                local types = {}
                local rarities = {}
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                if type(cosmetics) ~= 'table' then
                    return nil, nil
                end

                for cosmeticName, cosmeticData in pairs(cosmetics) do
                    if type(cosmeticName) == 'string'
                        and type(cosmeticData) == 'table'
                        and not LuaHookCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                        local cosmeticType = cosmeticData.Type or cosmeticData.CosmeticType
                        if cosmeticType == 'Skin'
                            or cosmeticType == 'Wrap'
                            or cosmeticType == 'Charm'
                            or cosmeticType == 'Finisher'
                            or cosmeticType == 'Emote' then
                            types[cosmeticType] = true
                            local rarity = cosmeticData.Rarity
                            if type(rarity) == 'string' and rarity ~= '' then
                                rarities[rarity] = true
                            end
                        end
                    end
                end

                types.Skin = true
                types.Wrap = true
                types.Charm = true
                types.Finisher = true
                types.Emote = true

                if next(rarities) == nil then
                    return nil, nil
                end
                return types, rarities
            end

            function LuaHookCosmetics.ApplyNativeCosmeticsConfig()
                local controller = LuaHookCosmetics.ResolveNativeCosmeticsController()
                local config = LuaHookCosmetics.ResolveNativeCosmeticsConfig()
                if type(controller) ~= 'table' then
                    return false
                end

                -- Weapon switches can cause ApplyAll() to be called repeatedly. Native
                -- SetUnlockedTypes/SetUnlockedRarities both rebuild the entire cosmetic
                -- catalog and sync every item, so never repeat that work when our desired
                -- catalog gates are already active on the same native controller.
                if LuaHookCosmeticsState.NativeCosmeticsConfigApplied
                    and LuaHookCosmetics.NativeUnlockStateMatchesDesired() then
                    return true
                end

                local allTypes = LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes
                local allRarities = LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities
                if type(allTypes) ~= 'table' or type(allRarities) ~= 'table' then
                    allTypes, allRarities = LuaHookCosmetics.ResolveAllNativeCosmeticTypesAndRarities()
                end
                if type(allTypes) ~= 'table' or type(allRarities) ~= 'table' then
                    return false
                end

                if LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes == nil
                    or LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities == nil then
                    local originalTypes, originalRarities

                    -- The live catalog is authoritative at the moment unlock-all starts.
                    -- The saved cosmeticsConfig state may describe a preset rather than the
                    -- currently-applied catalog filters.
                    local catalog = rawget(controller, '_catalog')
                    if type(originalTypes) ~= 'table' and type(catalog) == 'table' then
                        local getTypes = getMethodFromObject(catalog, 'GetIncludedTypes')
                        if type(getTypes) == 'function' then
                            local okTypes, valueTypes = pcall(getTypes, catalog)
                            if okTypes then originalTypes = valueTypes end
                        end
                    end
                    if type(originalRarities) ~= 'table' and type(catalog) == 'table' then
                        local getRarities = getMethodFromObject(catalog, 'GetIncludedRarities')
                        if type(getRarities) == 'function' then
                            local okRarities, valueRarities = pcall(getRarities, catalog)
                            if okRarities then originalRarities = valueRarities end
                        end
                    end

                    if type(originalTypes) ~= 'table' or type(originalRarities) ~= 'table' then
                        local getState = type(config) == 'table'
                            and getMethodFromObject(config, 'GetStateConfigState') or nil
                        if type(getState) == 'function' then
                            local okState, state = pcall(getState, config)
                            if okState and type(state) == 'table' then
                                originalTypes = originalTypes or state.types
                                originalRarities = originalRarities or state.rarities
                            end
                        end
                    end
                    if type(originalTypes) ~= 'table' or type(originalRarities) ~= 'table' then
                        return false
                    end
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes = cloneCosmeticSet(originalTypes)
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities = cloneCosmeticSet(originalRarities)
                end

                local setterOwner = type(config) == 'table'
                    and type(getMethodFromObject(config, 'SetUnlockedTypes')) == 'function'
                    and config
                    or controller
                local setTypes = getMethodFromObject(setterOwner, 'SetUnlockedTypes')
                local setRarities = getMethodFromObject(setterOwner, 'SetUnlockedRarities')
                if type(setTypes) ~= 'function' or type(setRarities) ~= 'function' then
                    return false
                end

                local okTypes = pcall(setTypes, setterOwner, allTypes)
                if not okTypes then
                    return false
                end
                local okRarities = pcall(setRarities, setterOwner, allRarities)
                if not okRarities then
                    local originalTypes = LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes
                    if type(originalTypes) == 'table' then
                        pcall(setTypes, setterOwner, originalTypes)
                    end
                    return false
                end
                LuaHookCosmeticsState.NativeCosmeticsConfig = type(config) == 'table' and config or nil
                LuaHookCosmeticsState.NativeCosmeticsConfigSetterOwner = setterOwner
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes = cloneCosmeticSet(allTypes)
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities = cloneCosmeticSet(allRarities)
                LuaHookCosmeticsState.NativeCosmeticsConfigApplied = true
                return true
            end
            function LuaHookCosmetics.RestoreNativeCosmeticsConfig()
                if not LuaHookCosmeticsState.NativeCosmeticsConfigApplied then
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities = nil
                    return true
                end
                local owner = LuaHookCosmeticsState.NativeCosmeticsConfigSetterOwner
                    or LuaHookCosmeticsState.NativeCosmeticsConfig
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                if type(owner) ~= 'table' then
                    owner = LuaHookCosmetics.ResolveNativeCosmeticsConfig()
                end
                if type(owner) ~= 'table'
                    or type(getMethodFromObject(owner, 'SetUnlockedTypes')) ~= 'function'
                    or type(getMethodFromObject(owner, 'SetUnlockedRarities')) ~= 'function' then
                    owner = controller
                end

                local restoredTypes, restoredRarities = false, false
                if type(owner) == 'table' then
                    local setTypes = getMethodFromObject(owner, 'SetUnlockedTypes')
                    local setRarities = getMethodFromObject(owner, 'SetUnlockedRarities')
                    local originalTypes = LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes
                    local originalRarities = LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities
                    if type(setTypes) == 'function' and type(originalTypes) == 'table' then
                        restoredTypes = pcall(setTypes, owner, originalTypes)
                    end
                    if type(setRarities) == 'function' and type(originalRarities) == 'table' then
                        restoredRarities = pcall(setRarities, owner, originalRarities)
                    end
                end
                LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigApplied = false
                LuaHookCosmeticsState.NativeCosmeticsConfig = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigSetterOwner = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes = nil
                LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities = nil
                return restoredTypes and restoredRarities
            end
            local function nativeCosmeticSetMatches(actual, desired)
                if type(actual) ~= 'table' or type(desired) ~= 'table' then
                    return false
                end
                for key, enabled in pairs(desired) do
                    if enabled == true and actual[key] ~= true then
                        return false
                    end
                end
                for key, enabled in pairs(actual) do
                    if enabled == true and desired[key] ~= true then
                        return false
                    end
                end
                return true
            end

            function LuaHookCosmetics.NativeUnlockStateMatchesDesired()
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                local config = LuaHookCosmeticsState.NativeCosmeticsConfig
                if not nativeCosmeticsPairLooksValid(controller, config) then
                    return false
                end
                if rawget(controller, '_runtimeEnabled') ~= true then
                    return false
                end

                local isUnlockerEnabled = getMethodFromObject(controller, 'IsUnlockerEnabled')
                if type(isUnlockerEnabled) ~= 'function' then
                    return false
                end
                local okUnlocker, unlockerEnabled = pcall(isUnlockerEnabled, controller)
                if not okUnlocker or unlockerEnabled ~= true then
                    return false
                end

                local catalog = rawget(controller, '_catalog')
                if type(catalog) ~= 'table' then
                    return false
                end
                local getTypes = getMethodFromObject(catalog, 'GetIncludedTypes')
                local getRarities = getMethodFromObject(catalog, 'GetIncludedRarities')
                local desiredTypes = LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes
                local desiredRarities = LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities
                if type(getTypes) ~= 'function'
                    or type(getRarities) ~= 'function'
                    or type(desiredTypes) ~= 'table'
                    or type(desiredRarities) ~= 'table' then
                    return false
                end
                local okTypes, actualTypes = pcall(getTypes, catalog)
                local okRarities, actualRarities = pcall(getRarities, catalog)
                if not okTypes or not okRarities then
                    return false
                end
                return nativeCosmeticSetMatches(actualTypes, desiredTypes)
                    and nativeCosmeticSetMatches(actualRarities, desiredRarities)
            end

            function LuaHookCosmetics.ApplyNativeCosmeticsRuntime()
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                if type(controller) ~= 'table' then
                    controller = LuaHookCosmetics.ResolveNativeCosmeticsController()
                end
                if type(controller) ~= 'table' then
                    return false
                end

                -- A game reload can replace the native controller instance while leaving
                -- the old Lua table alive. Never carry restore snapshots from the old
                -- instance onto the new one.
                if LuaHookCosmeticsState.NativeCosmeticsSnapshotController ~= controller then
                    LuaHookCosmeticsState.NativeCosmeticsSnapshotController = controller
                    LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled = nil
                    LuaHookCosmeticsState.NativeUnlockerWasEnabled = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalTypes = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigOriginalRarities = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigDesiredTypes = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigDesiredRarities = nil
                    LuaHookCosmeticsState.NativeCosmeticsConfigApplied = false
                    LuaHookCosmeticsState.NativeCosmeticsConfigSetterOwner = nil
                    LuaHookCosmeticsState.NativeUnlockerApplied = false
                    LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied = false
                end

                -- Idempotent fast path: once native runtime + unlocker + catalog gates
                -- are active, weapon/viewmodel changes do not require a second rebuild.
                if LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied
                    and LuaHookCosmeticsState.NativeUnlockerApplied
                    and LuaHookCosmeticsState.NativeCosmeticsConfigApplied
                    and LuaHookCosmetics.NativeUnlockStateMatchesDesired() then
                    return true
                end
                local setRuntimeEnabled = getMethodFromObject(controller, 'SetRuntimeEnabled')
                local setUnlockerEnabled = getMethodFromObject(controller, 'SetUnlockerEnabled')
                local isUnlockerEnabled = getMethodFromObject(controller, 'IsUnlockerEnabled')
                if type(setRuntimeEnabled) ~= 'function'
                    or type(setUnlockerEnabled) ~= 'function' then
                    return false
                end

                if LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled == nil then
                    local runtimeEnabled = rawget(controller, '_runtimeEnabled')
                    if type(runtimeEnabled) == 'boolean' then
                        LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled = runtimeEnabled
                    else
                        LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled = false
                    end
                end

                if LuaHookCosmeticsState.NativeUnlockerWasEnabled == nil then
                    if type(isUnlockerEnabled) == 'function' then
                        local okUnlocker, currentUnlocker = pcall(isUnlockerEnabled, controller)
                        if okUnlocker then
                            LuaHookCosmeticsState.NativeUnlockerWasEnabled = currentUnlocker == true
                        end
                    end
                    if LuaHookCosmeticsState.NativeUnlockerWasEnabled == nil then
                        LuaHookCosmeticsState.NativeUnlockerWasEnabled = false
                    end
                end

                local okRuntime = pcall(setRuntimeEnabled, controller, true)
                if not okRuntime then
                    return false
                end
                LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied = true

                -- Expand the native catalog gates so the game's own Custom Loadout sees
                -- the complete Skin/Wrap/Charm/Finisher/Emote catalog.
                if not LuaHookCosmetics.ApplyNativeCosmeticsConfig() then
                    pcall(setRuntimeEnabled, controller, LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled == true)
                    LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied = false
                    return false
                end

                local unlockOk = pcall(setUnlockerEnabled, controller, true)
                if not unlockOk then
                    pcall(LuaHookCosmetics.RestoreNativeCosmeticsConfig)
                    pcall(setRuntimeEnabled, controller, LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled == true)
                    LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied = false
                    return false
                end
                LuaHookCosmeticsState.NativeUnlockerApplied = true
                return true
            end
            function LuaHookCosmetics.RestoreNativeCosmeticsRuntime()
                local controller = LuaHookCosmeticsState.NativeCosmeticsController
                if type(controller) ~= 'table' then
                    controller = LuaHookCosmetics.ResolveNativeCosmeticsController(true)
                end

                if type(controller) == 'table' and LuaHookCosmeticsState.NativeUnlockerApplied then
                    local setUnlockerEnabled = getMethodFromObject(controller, 'SetUnlockerEnabled')
                    if type(setUnlockerEnabled) == 'function' then
                        local previousUnlocker = LuaHookCosmeticsState.NativeUnlockerWasEnabled == true
                        pcall(setUnlockerEnabled, controller, previousUnlocker)
                    end
                end

                -- Restore the native catalog filters only after the Unlocker layer is no
                -- longer active, preventing a transient re-application against the loadout.
                pcall(LuaHookCosmetics.RestoreNativeCosmeticsConfig)

                if type(controller) == 'table' then
                    local setRuntimeEnabled = getMethodFromObject(controller, 'SetRuntimeEnabled')
                    if type(setRuntimeEnabled) == 'function' and LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied then
                        local previous = LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled == true
                        pcall(setRuntimeEnabled, controller, previous)
                    end
                end
                LuaHookCosmeticsState.NativeUnlockerWasEnabled = nil
                LuaHookCosmeticsState.NativeUnlockerApplied = false
                LuaHookCosmeticsState.NativeCosmeticsRuntimeWasEnabled = nil
                LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied = false
                LuaHookCosmeticsState.NativeCosmeticsSnapshotController = nil
                return true
            end
            function RivalsEmotes.ApplyConfiguredEmoteSlots()
                local controller = LuaHookCosmetics.ResolveNativeCosmeticsController()
                local setEmote = type(controller) == 'table'
                    and getMethodFromObject(controller, 'SetEmote') or nil
                if type(setEmote) == 'function' and LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied then
                    local touched = LuaHookCosmeticsState.NativeEmoteAppliedBySlot
                    if type(touched) ~= 'table' then
                        touched = {}
                        LuaHookCosmeticsState.NativeEmoteAppliedBySlot = touched
                    end
                    local allOk = true
                    local changed = false
                    local slotCount = RivalsEmotes.ResolveEmoteSlotCount()
                    for slotIndex = 1, slotCount do
                        local desired = RivalsEmotes.ResolveSelectedEmoteForSlot(slotIndex)
                        local previous = touched[slotIndex]
                        if desired ~= nil then
                            if previous ~= desired then
                                local ok = pcall(setEmote, controller, slotIndex, desired, nil)
                                if ok then
                                    touched[slotIndex] = desired
                                    changed = true
                                else
                                    allOk = false
                                end
                            end
                        elseif previous ~= nil then
                            -- nil removes only our native intent and lets the original
                            -- equipped emote surface through the native resolver.
                            local ok = pcall(setEmote, controller, slotIndex, nil, nil)
                            if ok then
                                touched[slotIndex] = nil
                                changed = true
                            else
                                allOk = false
                            end
                        end
                    end
                    return allOk
                end

                -- Fallback path for runtimes where the native cosmetics controller cannot be resolved.
                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData or type(equippedEmotes) ~= 'table' then
                    return false
                end
                local changed = false
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local emoteName = RivalsEmotes.ResolveSelectedEmoteForSlot(slotIndex)
                    if emoteName then
                        local slotKey = tostring(slotIndex)
                        local slotData = equippedEmotes[slotKey]
                        if not RivalsEmotes.IsValidEquippedEmoteData(slotData) or slotData.Name ~= emoteName then
                            if not LuaHookCosmeticsState.OriginalEquippedEmotes then
                                LuaHookCosmeticsState.OriginalEquippedEmotes = RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                            end
                            equippedEmotes[slotIndex] = nil
                            equippedEmotes[slotKey] = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                            changed = true
                        end
                    end
                end
                if changed and type(currentData.Replicate) == 'function' then
                    pcall(function() currentData:Replicate('EquippedEmotes') end)
                end
                return changed
            end
            function RivalsEmotes.SetEquippedEmote(slotKey, emoteName)
                local numericSlot = tonumber(slotKey)
                if not numericSlot then
                    return false
                end
                numericSlot = math.floor(numericSlot)
                if numericSlot < 1 or numericSlot > RivalsEmotes.ResolveEmoteSlotCount() then
                    return false
                end

                local controller = LuaHookCosmetics.ResolveNativeCosmeticsController()
                local setEmote = type(controller) == 'table'
                    and getMethodFromObject(controller, 'SetEmote') or nil
                if type(setEmote) == 'function' and LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied then
                    if emoteName ~= nil and not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                        return false
                    end
                    local ok = pcall(setEmote, controller, numericSlot, emoteName, nil)
                    if ok then
                        if type(LuaHookCosmeticsState.NativeEmoteAppliedBySlot) ~= 'table' then
                            LuaHookCosmeticsState.NativeEmoteAppliedBySlot = {}
                        end
                        LuaHookCosmeticsState.NativeEmoteAppliedBySlot[numericSlot] = emoteName
                        if type(LuaHookCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                            LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                        end
                    end
                    return ok
                end

                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData or type(equippedEmotes) ~= 'table' then
                    return false
                end
                if not LuaHookCosmeticsState.OriginalEquippedEmotes then
                    LuaHookCosmeticsState.OriginalEquippedEmotes = RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                end
                local normalizedSlotKey = tostring(numericSlot)
                local nextData = nil
                if LuaHookCosmetics.IsCosmeticValueSelected(emoteName) then
                    nextData = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                end
                equippedEmotes[numericSlot] = nil
                equippedEmotes[normalizedSlotKey] = nextData
                if type(currentData.Replicate) == 'function' then
                    pcall(function() currentData:Replicate('EquippedEmotes') end)
                end
                if type(LuaHookCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end
            function RivalsEmotes.RestoreEquippedEmotes()
                if LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied then
                    LuaHookCosmetics.RestoreNativeCosmeticsRuntime()
                    LuaHookCosmeticsState.NativeEmoteAppliedBySlot = {}
                    LuaHookCosmeticsState.OriginalEquippedEmotes = nil
                    return true
                end

                local originalEquippedEmotes = LuaHookCosmeticsState.OriginalEquippedEmotes
                if type(originalEquippedEmotes) ~= 'table' then
                    return false
                end
                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData or type(equippedEmotes) ~= 'table' then
                    LuaHookCosmeticsState.OriginalEquippedEmotes = nil
                    return false
                end
                for key in pairs(equippedEmotes) do
                    equippedEmotes[key] = nil
                end
                for key, value in pairs(originalEquippedEmotes) do
                    equippedEmotes[key] = value
                end
                LuaHookCosmeticsState.OriginalEquippedEmotes = nil
                LuaHookCosmeticsState.NativeEmoteAppliedBySlot = {}
                if type(currentData.Replicate) == 'function' then
                    pcall(function() currentData:Replicate('EquippedEmotes') end)
                end
                return true
            end
            function RivalsEmotes.ResolveLocalEntity()
                local fighter = ResolveLocalFighter()
                return fighter and fighter.Entity or nil
            end
            function RivalsEmotes.ShouldUseLocalPlayback(emoteName)
                return RivalsEmotes.IsEnabled()
                    and RivalsEmotes.IsCatalogEmoteName(emoteName)
                    and not RivalsEmotes.IsNaturallyOwnedEmote(emoteName)
            end
            function RivalsEmotes.PlayLocalEmoteByName(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return false
                end
                local entity = RivalsEmotes.ResolveLocalEntity()
                if type(entity) ~= 'table' or type(entity.PlayEmote) ~= 'function' then
                    return false
                end
                local emoteData = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                if type(emoteData) ~= 'table' then
                    return false
                end
                local ok = pcall(function()
                    entity:PlayEmote(emoteData)
                end)
                return ok == true
            end
            function RivalsEmotes.EnsureEmoteControllerHook()
                if LuaHookCosmeticsState.EmoteControllerHooked then
                    local emoteController = LuaHookCosmeticsState.HookedEmoteController
                    local equipWrapper = LuaHookCosmeticsState.EmoteControllerEquipWrapper
                    local useWrapper = LuaHookCosmeticsState.EmoteControllerUseWrapper
                    if type(emoteController) == 'table' and type(equipWrapper) == 'function'
                        and type(useWrapper) == 'function'
                        and rawget(emoteController, 'EquipEmote') == equipWrapper
                        and rawget(emoteController, 'UseEmoteByName') == useWrapper then
                        return true
                    end
                    if type(RivalsEmotes.RestoreEmoteControllerHook) == 'function' then pcall(RivalsEmotes.RestoreEmoteControllerHook) end
                end
                local emoteController = RivalsEmotes.ResolveEmoteController()
                if type(emoteController) ~= 'table' or type(emoteController.EquipEmote) ~= 'function' or type(emoteController.UseEmoteByName) ~= 'function' then
                    return false
                end
                local originalEquipEmote = emoteController.EquipEmote
                local originalUseEmoteByName = emoteController.UseEmoteByName
                local equipWrapper = function(self, slotKey, emoteName, ...)
                    if RivalsEmotes.IsEnabled() and not RivalsEmotes.IsNaturallyOwnedEmote(emoteName) then
                        if RivalsEmotes.SetEquippedEmote(slotKey, emoteName) then
                            return
                        end
                    end
                    return originalEquipEmote(self, slotKey, emoteName, ...)
                end
                local useWrapper = function(self, emoteName, ...)
                    if RivalsEmotes.ShouldUseLocalPlayback(emoteName) and RivalsEmotes.PlayLocalEmoteByName(emoteName) then
                        return
                    end
                    return originalUseEmoteByName(self, emoteName, ...)
                end
                emoteController.EquipEmote = equipWrapper
                emoteController.UseEmoteByName = useWrapper
                LuaHookCosmeticsState.HookedEmoteController = emoteController
                LuaHookCosmeticsState.OriginalEmoteControllerEquipEmote = originalEquipEmote
                LuaHookCosmeticsState.OriginalEmoteControllerUseEmoteByName = originalUseEmoteByName
                LuaHookCosmeticsState.EmoteControllerEquipWrapper = equipWrapper
                LuaHookCosmeticsState.EmoteControllerUseWrapper = useWrapper
                LuaHookCosmeticsState.EmoteControllerHooked = true
                return true
            end
            function RivalsEmotes.RestoreEmoteControllerHook()
                local emoteController = LuaHookCosmeticsState.HookedEmoteController
                local originalEquipEmote = LuaHookCosmeticsState.OriginalEmoteControllerEquipEmote
                local originalUseEmoteByName = LuaHookCosmeticsState.OriginalEmoteControllerUseEmoteByName
                local equipWrapper = LuaHookCosmeticsState.EmoteControllerEquipWrapper
                local useWrapper = LuaHookCosmeticsState.EmoteControllerUseWrapper
                if type(emoteController) == 'table' and type(originalEquipEmote) == 'function'
                    and rawget(emoteController, 'EquipEmote') == equipWrapper then
                    emoteController.EquipEmote = originalEquipEmote
                end
                if type(emoteController) == 'table' and type(originalUseEmoteByName) == 'function'
                    and rawget(emoteController, 'UseEmoteByName') == useWrapper then
                    emoteController.UseEmoteByName = originalUseEmoteByName
                end
                LuaHookCosmeticsState.HookedEmoteController = nil
                LuaHookCosmeticsState.OriginalEmoteControllerEquipEmote = nil
                LuaHookCosmeticsState.OriginalEmoteControllerUseEmoteByName = nil
                LuaHookCosmeticsState.EmoteControllerEquipWrapper = nil
                LuaHookCosmeticsState.EmoteControllerUseWrapper = nil
                LuaHookCosmeticsState.EmoteControllerHooked = false
                return true
            end
            function RivalsEmotes.ShouldUseRuntime()
                if not RivalsEmotes.IsEnabled() then
                    return false
                end
                if not ReplicatedStateReady then
                    LuaHookCosmetics.QueueRuntimeApplyWhenReady()
                    return false
                end
                return true
            end
            function RivalsEmotes.ApplyAll()
                if not RivalsEmotes.ShouldUseRuntime() then
                    return false
                end
                local playerDataOk, playerDataResult = pcall(LuaHookCosmetics.EnsurePlayerDataHook)
                if not playerDataOk or playerDataResult ~= true then
                    return false
                end

                local nativeController = LuaHookCosmetics.ResolveNativeCosmeticsController()
                if type(nativeController) == 'table'
                    and type(getMethodFromObject(nativeController, 'SetRuntimeEnabled')) == 'function' then
                    -- Unlock/runtime only. The game's current emote slots remain authoritative.
                    return LuaHookCosmetics.ApplyNativeCosmeticsRuntime() == true
                end

                -- No safe native emote runtime: leave the game's equipped emotes untouched.
                return true
            end
            function RivalsEmotes.RestoreAll()
                pcall(RivalsEmotes.RestoreEquippedEmotes)
                pcall(RivalsEmotes.RestoreEmoteControllerHook)
                if not LuaHookCosmetics.IsEnabled() then
                    pcall(LuaHookCosmetics.RestorePlayerDataHook)
                end
                return true
            end
            function LuaHookCosmetics.LoadSavedSelectionsFromConfig()
                local configName = LuaHookCosmeticsState.CosmeticsConfigName
                if type(configName) ~= 'string' or configName == '' then
                    return false
                end
                local configPath = ScriptPaths.config_path(configName)
                if not isfile(configPath) then
                    return false
                end
                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                local objects = decodeOk and type(decoded) == 'table' and decoded.objects or nil
                if type(objects) ~= 'table' then
                    return false
                end
                local loadedAny = false
                local loadedPreviewWeaponName = nil
                local hasNativeCosmeticState = false
                for _, object in ipairs(objects) do
                    if object and object.idx == RIVALS_FAVORITES_STATE_OPTION_ID
                        and type(object.value) == 'table'
                        and object.value.nativeVersion == 1 then
                        hasNativeCosmeticState = true
                        break
                    end
                end
                LuaHookCosmetics.RestoreAppliedCosmetics()
                LuaHookCosmeticsState.SelectedSkinByWeapon = {}
                LuaHookCosmeticsState.SelectedWrapByWeapon = {}
                LuaHookCosmeticsState.SelectedCharmByWeapon = {}
                LuaHookCosmeticsState.SelectedFinisherByWeapon = {}
                LuaHookCosmeticsState.SelectedWrapInvertedByWeapon = {}
                LuaHookCosmeticsState.StableRandomSelectionByWeapon = {}
                LuaHookCosmeticsState.FavoritedCosmeticsByWeapon = {}
                LuaHookCosmeticsState.OnlyUseFavoritesByWeapon = {}
                LuaHookCosmeticsState.NativeFavoritesSeeded = false
                LuaHookCosmeticsState.RankCharmOverridesBySeason = {}
                LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                for _, object in ipairs(objects) do
                    local optionId = object and object.idx or nil
                    local optionInfo = LuaHookCosmetics.ResolveCosmeticOptionInfo(optionId)
                    if optionInfo and hasNativeCosmeticState then
                        loadedPreviewWeaponName = loadedPreviewWeaponName or optionInfo.weaponName
                        if optionInfo.type == 'Toggle' then
                            LuaHookCosmetics.SetStoredSelection(optionInfo.weaponName, optionInfo.kind, object.value == true)
                        else
                            LuaHookCosmetics.SetStoredSelection(optionInfo.weaponName, optionInfo.kind, object.value)
                        end
                        loadedAny = true
                    elseif optionId == RIVALS_FAVORITES_STATE_OPTION_ID and hasNativeCosmeticState then
                        local favoritesState = LuaHookCosmetics.NormalizeFavoritesState(object.value)
                        LuaHookCosmeticsState.FavoritedCosmeticsByWeapon = favoritesState.favorites
                        LuaHookCosmeticsState.OnlyUseFavoritesByWeapon = favoritesState.onlyUse
                        LuaHookCosmeticsState.NativeFavoritesSeeded = type(object.value) == 'table'
                            and object.value.nativeVersion == 1
                            or next(favoritesState.favorites) ~= nil
                            or next(favoritesState.onlyUse) ~= nil
                        loadedAny = true
                    elseif optionId == LuaHookCosmetics.ResolveEditorOptionId('Weapon') then
                        LuaHookCosmetics.SetSelectedEditorWeapon(object.value)
                    elseif optionId == 'P5COS_STATE' and type(object.value) == 'table' then
                        local value = object.value
                        if type(value.selections) == 'table' then
                            LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon = LuaHookCosmetics.CloneSerializable(value.selections)
                        end
                        if type(value.orders) == 'table' then
                            LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon = LuaHookCosmetics.CloneSerializable(value.orders)
                        end
                        if type(value.emotes) == 'table' then
                            LuaHookCosmeticsState.CosmeticMultiEmotes = LuaHookCosmetics.CloneSerializable(value.emotes)
                        end
                        if type(value.emoteOrder) == 'table' then
                            LuaHookCosmeticsState.CosmeticMultiEmoteOrder = LuaHookCosmetics.CloneSerializable(value.emoteOrder)
                        end
                        if LuaHookCosmetics.IsKnownWeaponName(value.weapon) then
                            LuaHookCosmeticsState.SelectedEditorWeaponName = value.weapon
                            LuaHookCosmetics.SetPreviewWeaponName(value.weapon)
                        end
                        loadedAny = true
                    end
                end
                if loadedPreviewWeaponName then
                    LuaHookCosmeticsState.SelectedEditorWeaponName = loadedPreviewWeaponName
                    LuaHookCosmetics.SetPreviewWeaponName(loadedPreviewWeaponName)
                end
                LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                LuaHookCosmetics.SyncFavoriteEditorFromState()
                LuaHookCosmetics.SyncRankCharmEditorFromState()
                LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                pcall(LuaHookCosmetics.RefreshCosmeticMultiUi)
                return loadedAny
            end
            function LuaHookCosmetics.CaptureSavedSelectionsBeforeConfigSave()
                LuaHookCosmeticsState.SavedConfigCosmeticObjects = {}
                return false
            end
            function LuaHookCosmetics.ResolveSelectionConfigObjectsById()
                local objectsById = {}
                if LuaHookCosmeticsState.CosmeticsUiLoaded == true then
                    local uiWeapon = LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon()
                    if uiWeapon then
                        for _, kind in ipairs({'Skin', 'Wrap', 'Charm', 'Finisher'}) do
                            local optionId = ({
                                Skin = 'P5COS_SKIN',
                                Wrap = 'P5COS_WRAP',
                                Charm = 'P5COS_CHARM',
                                Finisher = 'P5COS_FINISHER',
                            })[kind]
                            local option = Options[optionId]
                            if option then
                                LuaHookCosmetics.SyncMultiSelectionState(kind, uiWeapon, option.Value, LuaHookCosmetics.ResolveMultiValues(kind, uiWeapon))
                            end
                        end
                        local emoteOption = Options.P5COS_EMOTE
                        if emoteOption then
                            LuaHookCosmetics.SyncMultiSelectionState('Emote', uiWeapon, emoteOption.Value, RivalsEmotes.ResolveEmoteValues())
                        end
                    end
                end
                for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    local skinValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                    if skinValue ~= nil then
                        local skinOptionId = LuaHookCosmetics.ResolveSkinOptionId(weaponName)
                        objectsById[skinOptionId] = {
                            idx = skinOptionId,
                            type = 'Dropdown',
                            value = skinValue,
                        }
                    end
                    local wrapValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                    if wrapValue ~= nil then
                        local wrapOptionId = LuaHookCosmetics.ResolveWrapOptionId(weaponName)
                        objectsById[wrapOptionId] = {
                            idx = wrapOptionId,
                            type = 'Dropdown',
                            value = wrapValue,
                        }
                    end
                    local charmValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                    if charmValue ~= nil then
                        local charmOptionId = LuaHookCosmetics.ResolveCharmOptionId(weaponName)
                        objectsById[charmOptionId] = {
                            idx = charmOptionId,
                            type = 'Dropdown',
                            value = charmValue,
                        }
                    end
                    local finisherValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                    if finisherValue ~= nil then
                        local finisherOptionId = LuaHookCosmetics.ResolveFinisherOptionId(weaponName)
                        objectsById[finisherOptionId] = {
                            idx = finisherOptionId,
                            type = 'Dropdown',
                            value = finisherValue,
                        }
                    end
                    local invertedValue = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                    if invertedValue ~= nil then
                        local invertedOptionId = LuaHookCosmetics.ResolveWrapInvertedOptionId(weaponName)
                        objectsById[invertedOptionId] = {
                            idx = invertedOptionId,
                            type = 'Toggle',
                            value = invertedValue == true,
                        }
                    end
                end
                local nativeFavoritesState = LuaHookCosmetics.ResolveFavoritesState()
                nativeFavoritesState.nativeVersion = 1
                objectsById[RIVALS_FAVORITES_STATE_OPTION_ID] = {
                    idx = RIVALS_FAVORITES_STATE_OPTION_ID,
                    type = 'CosmeticFavorites',
                    value = nativeFavoritesState,
                }
                if type(LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon) == 'table' then
                    objectsById.P5COS_STATE = {
                        idx = 'P5COS_STATE',
                        type = 'CosmeticMultiState',
                        value = {
                            weapon = LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon(),
                            selections = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon),
                            orders = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon),
                            emotes = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.CosmeticMultiEmotes),
                            emoteOrder = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.CosmeticMultiEmoteOrder),
                        },
                    }
                end
                return objectsById
            end
            function LuaHookCosmetics.SaveSelectionsToConfig()
                local configName = LuaHookCosmeticsState.CosmeticsConfigName
                if type(configName) ~= 'string' or configName == '' then
                    LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end
                local configPath = ScriptPaths.config_path(configName)
                if not isfile(configPath) then
                    LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end
                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                if not decodeOk or type(decoded) ~= 'table' then
                    LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end
                local existingObjects = type(decoded.objects) == 'table' and decoded.objects or {}
                local cosmeticObjectsById = {}
                for optionId, object in pairs(LuaHookCosmeticsState.SavedConfigCosmeticObjects or {}) do
                    cosmeticObjectsById[optionId] = LuaHookCosmetics.CloneConfigObject(object)
                end
                local selectedObjectsById = LuaHookCosmetics.ResolveSelectionConfigObjectsById()
                for optionId, object in pairs(selectedObjectsById) do
                    cosmeticObjectsById[optionId] = object
                end
                local mergedObjects = {}
                for _, object in ipairs(existingObjects) do
                    local optionId = object and object.idx or nil
                    if not LuaHookCosmetics.IsCosmeticOptionId(optionId) then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end
                local cosmeticOptionIds = {}
                for optionId in pairs(cosmeticObjectsById) do
                    cosmeticOptionIds[#cosmeticOptionIds + 1] = optionId
                end
                table.sort(cosmeticOptionIds)
                for _, optionId in ipairs(cosmeticOptionIds) do
                    local object = cosmeticObjectsById[optionId]
                    if object then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end
                decoded.objects = mergedObjects
                LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                return pcall(function()
                    writefile(configPath, HttpService:JSONEncode(decoded))
                end)
            end
            function LuaHookCosmetics.CloneSerializable(value, seen)
                if type(value) ~= 'table' then
                    return value
                end
                seen = seen or {}
                if seen[value] then
                    return nil
                end
                local clone = {}
                seen[value] = clone
                for key, child in pairs(value) do
                    local clonedChild = LuaHookCosmetics.CloneSerializable(child, seen)
                    if clonedChild ~= nil then
                        clone[key] = clonedChild
                    end
                end
                return clone
            end
            function LuaHookCosmetics.ResolveCosmeticPresetSettings(value)
                value = type(value) == 'table' and value or {}
                return {
                    selectedName = type(value.selectedName) == 'string' and value.selectedName or '',
                    autoLoad = value.autoLoad == true,
                    autoLoadName = type(value.autoLoadName) == 'string' and value.autoLoadName or '',
                    autoSave = value.autoSave == true,
                    autoSaveName = type(value.autoSaveName) == 'string' and value.autoSaveName or '',
                }
            end
            function LuaHookCosmetics.NormalizePresetSelectionTable(value, kind)
                local normalized = {}
                if type(value) ~= 'table' then
                    return normalized
                end
                for weaponName, selection in pairs(value) do
                    if LuaHookCosmetics.IsKnownWeaponName(weaponName) then
                        if kind == 'WrapInverted' then
                            normalized[weaponName] = selection == true
                        else
                            selection = LuaHookCosmetics.NormalizeSelectionValue(selection)
                            local values = LuaHookCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                            if LuaHookCosmetics.ResolveValidDropdownValue(selection, values) == selection then
                                normalized[weaponName] = selection
                            end
                        end
                    end
                end
                return normalized
            end
            function LuaHookCosmetics.ResolveCosmeticPresetEmotes()
                local emotes = {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local option = Options[RivalsEmotes.ResolveSlotOptionId(slotIndex)]
                    emotes[tostring(slotIndex)] = option and option.Value or DEFAULT_RIVALS_COSMETIC_VALUE
                end
                return emotes
            end
            function LuaHookCosmetics.NormalizeCosmeticPresetEmotes(value)
                local normalized = {}
                local available = RivalsEmotes.ResolveEmoteValues()
                value = type(value) == 'table' and value or {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local slotKey = tostring(slotIndex)
                    local emoteName = value[slotKey] or value[slotIndex] or DEFAULT_RIVALS_COSMETIC_VALUE
                    if LuaHookCosmetics.ResolveValidDropdownValue(emoteName, available) ~= emoteName then
                        emoteName = DEFAULT_RIVALS_COSMETIC_VALUE
                    end
                    normalized[slotKey] = emoteName
                end
                return normalized
            end
            function LuaHookCosmetics.BuildDefaultCosmeticPresetSnapshot()
                local emotes = {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    emotes[tostring(slotIndex)] = DEFAULT_RIVALS_COSMETIC_VALUE
                end
                return {
                    version = 1,
                    weaponCosmeticsEnabled = false,
                    emotesEnabled = false,
                    selectedWeapon = RIVALS_COSMETIC_ALL_WEAPONS,
                    skins = {},
                    wraps = {},
                    charms = {},
                    finishers = {},
                    wrapInverted = {},
                    favorites = { favorites = {}, onlyUse = {} },
                    rankCharmOverrides = {},
                    emotes = emotes,
                }
            end
            function LuaHookCosmetics.BuildCurrentCosmeticPresetSnapshot()
                return {
                    version = 1,
                    weaponCosmeticsEnabled = LuaHookCosmetics.IsEnabled(),
                    emotesEnabled = RivalsEmotes.IsEnabled(),
                    selectedWeapon = LuaHookCosmetics.ResolveSelectedEditorWeaponName(),
                    skins = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.SelectedSkinByWeapon),
                    wraps = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.SelectedWrapByWeapon),
                    charms = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.SelectedCharmByWeapon),
                    finishers = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.SelectedFinisherByWeapon),
                    wrapInverted = LuaHookCosmetics.CloneSerializable(LuaHookCosmeticsState.SelectedWrapInvertedByWeapon),
                    favorites = LuaHookCosmetics.ResolveFavoritesState(),
                    rankCharmOverrides = LuaHookCosmetics.NormalizeRankCharmOverrides(LuaHookCosmeticsState.RankCharmOverridesBySeason),
                    emotes = LuaHookCosmetics.ResolveCosmeticPresetEmotes(),
                }
            end
            function LuaHookCosmetics.NormalizeCosmeticPresetSnapshot(value)
                value = type(value) == 'table' and value or {}
                local favorites = LuaHookCosmetics.NormalizeFavoritesState(value.favorites)
                local selectedWeapon = LuaHookCosmetics.IsKnownEditorWeaponName(value.selectedWeapon)
                    and value.selectedWeapon or RIVALS_COSMETIC_ALL_WEAPONS
                return {
                    version = 1,
                    weaponCosmeticsEnabled = value.weaponCosmeticsEnabled == true,
                    emotesEnabled = value.emotesEnabled == true,
                    selectedWeapon = selectedWeapon,
                    skins = LuaHookCosmetics.NormalizePresetSelectionTable(value.skins, 'Skin'),
                    wraps = LuaHookCosmetics.NormalizePresetSelectionTable(value.wraps, 'Wrap'),
                    charms = LuaHookCosmetics.NormalizePresetSelectionTable(value.charms, 'Charm'),
                    finishers = LuaHookCosmetics.NormalizePresetSelectionTable(value.finishers, 'Finisher'),
                    wrapInverted = LuaHookCosmetics.NormalizePresetSelectionTable(value.wrapInverted, 'WrapInverted'),
                    favorites = favorites,
                    rankCharmOverrides = LuaHookCosmetics.NormalizeRankCharmOverrides(value.rankCharmOverrides),
                    emotes = LuaHookCosmetics.NormalizeCosmeticPresetEmotes(value.emotes),
                }
            end
            function LuaHookCosmetics.LoadCosmeticPresetStore()
                if LuaHookCosmeticsState.CosmeticPresetsLoaded then
                    return true
                end
                LuaHookCosmeticsState.CosmeticPresetsLoaded = true
                LuaHookCosmeticsState.CosmeticPresets = {}
                LuaHookCosmeticsState.CosmeticPresetSettings = LuaHookCosmetics.ResolveCosmeticPresetSettings(nil)
                if not isfile(LuaHookCosmetics.CosmeticPresetPath) then
                    return true
                end
                local readOk, raw = pcall(readfile, LuaHookCosmetics.CosmeticPresetPath)
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(raw)
                end)
                if not readOk or not decodeOk or type(decoded) ~= 'table' then
                    return false
                end
                for name, snapshot in pairs(type(decoded.presets) == 'table' and decoded.presets or {}) do
                    if type(name) == 'string' and name ~= '' and type(snapshot) == 'table' then
                        LuaHookCosmeticsState.CosmeticPresets[name] = LuaHookCosmetics.NormalizeCosmeticPresetSnapshot(snapshot)
                    end
                end
                local settings = LuaHookCosmetics.ResolveCosmeticPresetSettings(decoded.settings)
                for _, key in ipairs({'selectedName', 'autoLoadName', 'autoSaveName'}) do
                    if LuaHookCosmeticsState.CosmeticPresets[settings[key]] == nil then
                        settings[key] = ''
                    end
                end
                LuaHookCosmeticsState.CosmeticPresetSettings = settings
                return true
            end
            function LuaHookCosmetics.SaveCosmeticPresetStore()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local payload = {
                    version = 1,
                    presets = LuaHookCosmeticsState.CosmeticPresets,
                    settings = LuaHookCosmeticsState.CosmeticPresetSettings,
                }
                return pcall(function()
                    if not isfolder('LuaHook') then
                        makefolder('LuaHook')
                    end
                    writefile(LuaHookCosmetics.CosmeticPresetPath, HttpService:JSONEncode(payload))
                end)
            end
            function LuaHookCosmetics.ResolveCosmeticPresetNames()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local names = {}
                for name in pairs(LuaHookCosmeticsState.CosmeticPresets) do
                    names[#names + 1] = name
                end
                table.sort(names)
                return names
            end
            function LuaHookCosmetics.RefreshCosmeticPresetControls()
                local names = LuaHookCosmetics.ResolveCosmeticPresetNames()
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                for _, optionId in ipairs({'P5PRESET_SELECTED', 'P5PRESET_AUTOLOAD_NAME', 'P5PRESET_AUTOSAVE_NAME'}) do
                    local option = Options[optionId]
                    if option and type(option.SetValues) == 'function' then
                        option:SetValues(names)
                    end
                end
                local selectedOption = Options.P5PRESET_SELECTED
                if selectedOption and type(selectedOption.SetValue) == 'function' then
                    selectedOption:SetValue(settings.selectedName ~= '' and settings.selectedName or nil)
                end
                local autoLoadNameOption = Options.P5PRESET_AUTOLOAD_NAME
                if autoLoadNameOption and type(autoLoadNameOption.SetValue) == 'function' then
                    autoLoadNameOption:SetValue(settings.autoLoadName ~= '' and settings.autoLoadName or nil)
                end
                local autoSaveNameOption = Options.P5PRESET_AUTOSAVE_NAME
                if autoSaveNameOption and type(autoSaveNameOption.SetValue) == 'function' then
                    autoSaveNameOption:SetValue(settings.autoSaveName ~= '' and settings.autoSaveName or nil)
                end
                local autoLoadToggle = Toggles.P5PRESET_AUTOLOAD
                if autoLoadToggle and type(autoLoadToggle.SetValue) == 'function' then
                    autoLoadToggle:SetValue(settings.autoLoad)
                end
                local autoSaveToggle = Toggles.P5PRESET_AUTOSAVE
                if autoSaveToggle and type(autoSaveToggle.SetValue) == 'function' then
                    autoSaveToggle:SetValue(settings.autoSave)
                end
                LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                return names
            end
            function LuaHookCosmetics.SanitizeCosmeticPresetName(value)
                return type(value) == 'string' and (value:gsub('%s+', '')) or ''
            end
            function LuaHookCosmetics.CreateCosmeticPreset(name)
                LuaHookCosmetics.LoadCosmeticPresetStore()
                name = LuaHookCosmetics.SanitizeCosmeticPresetName(name)
                if name == '' or LuaHookCosmeticsState.CosmeticPresets[name] ~= nil then
                    return false
                end
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                LuaHookCosmeticsState.CosmeticPresets[name] = LuaHookCosmetics.BuildDefaultCosmeticPresetSnapshot()
                local previousSelected = settings.selectedName
                settings.selectedName = name
                if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                    LuaHookCosmeticsState.CosmeticPresets[name] = nil
                    settings.selectedName = previousSelected
                    return false
                end
                LuaHookCosmetics.RefreshCosmeticPresetControls()
                return true
            end
            function LuaHookCosmetics.SetSelectedCosmeticPreset(name)
                LuaHookCosmetics.LoadCosmeticPresetStore()
                if type(name) ~= 'string' or LuaHookCosmeticsState.CosmeticPresets[name] == nil then
                    return false
                end
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local previous = settings.selectedName
                settings.selectedName = name
                if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                    settings.selectedName = previous
                    LuaHookCosmetics.RefreshCosmeticPresetControls()
                    return false
                end
                return true
            end
            function LuaHookCosmetics.SaveSelectedCosmeticPreset()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local name = settings.selectedName
                if LuaHookCosmeticsState.CosmeticPresets[name] == nil then
                    return false
                end
                local previous = LuaHookCosmeticsState.CosmeticPresets[name]
                LuaHookCosmeticsState.CosmeticPresets[name] = LuaHookCosmetics.BuildCurrentCosmeticPresetSnapshot()
                if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                    LuaHookCosmeticsState.CosmeticPresets[name] = previous
                    return false
                end
                return true
            end
            function LuaHookCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
                snapshot = LuaHookCosmetics.NormalizeCosmeticPresetSnapshot(snapshot)
                local previousRefreshing = LuaHookCosmeticsState.RefreshingDropdownValues
                LuaHookCosmeticsState.ApplyingCosmeticPreset = true
                local ok, result = xpcall(function()
                    local cosmeticsToggle = Toggles.LH_P5S1T2
                    local emotesToggle = Toggles and Toggles.LH_P5S1T3 or nil
                    if cosmeticsToggle and type(cosmeticsToggle.SetValue) == 'function' then
                        cosmeticsToggle:SetValue(false)
                    end
                    if emotesToggle and type(emotesToggle.SetValue) == 'function' then
                        emotesToggle:SetValue(false)
                    end
                    LuaHookCosmetics.RestoreAppliedCosmetics()
                    LuaHookCosmeticsState.SelectedSkinByWeapon = snapshot.skins
                    LuaHookCosmeticsState.SelectedWrapByWeapon = snapshot.wraps
                    LuaHookCosmeticsState.SelectedCharmByWeapon = snapshot.charms
                    LuaHookCosmeticsState.SelectedFinisherByWeapon = snapshot.finishers
                    LuaHookCosmeticsState.SelectedWrapInvertedByWeapon = snapshot.wrapInverted
                    LuaHookCosmeticsState.FavoritedCosmeticsByWeapon = snapshot.favorites.favorites
                    LuaHookCosmeticsState.OnlyUseFavoritesByWeapon = snapshot.favorites.onlyUse
                    LuaHookCosmeticsState.RankCharmOverridesBySeason = snapshot.rankCharmOverrides
                    LuaHookCosmeticsState.StableRandomSelectionByWeapon = {}
                    LuaHookCosmeticsState.SelectedEditorWeaponName = snapshot.selectedWeapon
                    LuaHookCosmeticsState.RefreshingDropdownValues = LuaHookCosmeticsState.RefreshingDropdownValues + 1
                    for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                        local option = Options[RivalsEmotes.ResolveSlotOptionId(slotIndex)]
                        if option and type(option.SetValue) == 'function' then
                            option:SetValue(snapshot.emotes[tostring(slotIndex)])
                        end
                    end
                    LuaHookCosmeticsState.RefreshingDropdownValues = math.max(LuaHookCosmeticsState.RefreshingDropdownValues - 1, 0)
                    LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                    LuaHookCosmetics.SyncFavoriteEditorFromState()
                    LuaHookCosmetics.SyncRankCharmEditorFromState()
                    pcall(LuaHookCosmetics.UpdatePreviewViewport)
                    if cosmeticsToggle and type(cosmeticsToggle.SetValue) == 'function' then
                        cosmeticsToggle:SetValue(snapshot.weaponCosmeticsEnabled)
                    end
                    if emotesToggle and type(emotesToggle.SetValue) == 'function' then
                        emotesToggle:SetValue(snapshot.emotesEnabled)
                    end
                    LuaHookCosmetics.ApplyAll()
                    RivalsEmotes.ApplyAll()
                    return true
                end, function(err)
                    return debug.traceback(string.format('[Cosmetics_ApplyPreset] %s', tostring(err)), 2)
                end)
                LuaHookCosmeticsState.ApplyingCosmeticPreset = false
                LuaHookCosmeticsState.RefreshingDropdownValues = previousRefreshing
                if not ok then
                    error(result, 0)
                end
                return result == true
            end
            function LuaHookCosmetics.LoadSelectedCosmeticPreset()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local snapshot = LuaHookCosmeticsState.CosmeticPresets[settings.selectedName]
                if not snapshot then
                    return false
                end
                return LuaHookCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
            end
            function LuaHookCosmetics.DeleteSelectedCosmeticPreset()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local name = settings.selectedName
                local snapshot = LuaHookCosmeticsState.CosmeticPresets[name]
                if not snapshot then
                    return false
                end
                local previousSettings = LuaHookCosmetics.CloneSerializable(settings)
                LuaHookCosmeticsState.CosmeticPresets[name] = nil
                settings.selectedName = ''
                if settings.autoLoadName == name then
                    settings.autoLoadName = ''
                end
                if settings.autoSaveName == name then
                    settings.autoSaveName = ''
                end
                if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                    LuaHookCosmeticsState.CosmeticPresets[name] = snapshot
                    LuaHookCosmeticsState.CosmeticPresetSettings = previousSettings
                    return false
                end
                LuaHookCosmetics.RefreshCosmeticPresetControls()
                return true
            end
            function LuaHookCosmetics.SetCosmeticPresetSetting(key, value)
                LuaHookCosmetics.LoadCosmeticPresetStore()
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local previous = settings[key]
                if key == 'autoLoad' or key == 'autoSave' then
                    settings[key] = value == true
                elseif key == 'autoLoadName' or key == 'autoSaveName' then
                    if type(value) ~= 'string' or LuaHookCosmeticsState.CosmeticPresets[value] == nil then
                        return false
                    end
                    settings[key] = value
                else
                    return false
                end
                if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                    settings[key] = previous
                    LuaHookCosmetics.RefreshCosmeticPresetControls()
                    return false
                end
                return true
            end
            function LuaHookCosmetics.ApplyCosmeticPresetAutoLoad()
                LuaHookCosmetics.LoadCosmeticPresetStore()
                if LuaHookCosmeticsState.CosmeticPresetAutoLoadApplied then
                    return false
                end
                LuaHookCosmeticsState.CosmeticPresetAutoLoadApplied = true
                local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                local snapshot = settings.autoLoad and LuaHookCosmeticsState.CosmeticPresets[settings.autoLoadName] or nil
                if not snapshot then
                    return false
                end
                settings.selectedName = settings.autoLoadName
                LuaHookCosmetics.RefreshCosmeticPresetControls()
                return LuaHookCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
            end
            function LuaHookCosmetics.QueueCosmeticPresetAutoSave()
                if LuaHookCosmeticsState.ApplyingCosmeticPreset
                    or LuaHookCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                LuaHookCosmeticsState.CosmeticPresetSaveToken = LuaHookCosmeticsState.CosmeticPresetSaveToken + 1
                local token = LuaHookCosmeticsState.CosmeticPresetSaveToken
                task.defer(GuardLuaHookCallback('Cosmetics_PresetAutoSave', function()
                    if token ~= LuaHookCosmeticsState.CosmeticPresetSaveToken
                        or LuaHookCosmeticsState.ApplyingCosmeticPreset then
                        return
                    end
                    LuaHookCosmetics.LoadCosmeticPresetStore()
                    local settings = LuaHookCosmeticsState.CosmeticPresetSettings
                    local name = settings.autoSave and settings.autoSaveName or ''
                    if LuaHookCosmeticsState.CosmeticPresets[name] == nil then
                        return
                    end
                    local previous = LuaHookCosmeticsState.CosmeticPresets[name]
                    LuaHookCosmeticsState.CosmeticPresets[name] = LuaHookCosmetics.BuildCurrentCosmeticPresetSnapshot()
                    if not LuaHookCosmetics.SaveCosmeticPresetStore() then
                        LuaHookCosmeticsState.CosmeticPresets[name] = previous
                    end
                end))
                return true
            end
            function LuaHookCosmetics.ResolveSkinSourceModel(weaponName, skinName)
                if type(weaponName) ~= 'string' or weaponName == '' or not LuaHookCosmetics.IsCosmeticValueSelected(skinName) then
                    return nil
                end
                local cacheKey = string.format('SkinSource_%s_%s', weaponName, skinName)
                local cachedSkinSource = LuaHookCosmetics.Catalog[cacheKey]
                if cachedSkinSource and cachedSkinSource.Parent then
                    return cachedSkinSource
                end
                local cosmeticLibrary = LuaHookCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local cosmeticData = type(cosmetics) == 'table' and cosmetics[skinName] or nil
                if not cosmeticData or cosmeticData.Type ~= 'Skin' or cosmeticData.ItemName ~= weaponName then
                    return nil
                end
                local viewModelsRoot = LuaHookCosmetics.ResolveViewModelsRoot()
                if not viewModelsRoot then
                    return nil
                end
                local folderName = cosmeticData.Folder
                if type(folderName) == 'string' and folderName ~= '' then
                    local folder = viewModelsRoot:FindFirstChild(folderName)
                    local folderSource = folder and folder:FindFirstChild(skinName, true)
                    if folderSource and LuaHookCosmetics.IsModelContainer(folderSource) then
                        LuaHookCosmetics.Catalog[cacheKey] = folderSource
                        return folderSource
                    end
                end
                local sourceModel = viewModelsRoot:FindFirstChild(skinName, true)
                if sourceModel and LuaHookCosmetics.IsModelContainer(sourceModel) then
                    LuaHookCosmetics.Catalog[cacheKey] = sourceModel
                    return sourceModel
                end
                return nil
            end
            function LuaHookCosmetics.ClonePreviewObject(instance, previewName)
                if not instance then
                    return nil
                end
                if instance:IsA('Model') or instance:IsA('BasePart') then
                    local clone = LuaHookCosmetics.SafeClone(instance)
                    if not clone then
                        return nil
                    end
                    clone.Name = previewName or clone.Name
                    LuaHookCosmetics.AnchorPreviewDescendants(clone)
                    if not LuaHookCosmetics.HasRenderableDescendant(clone) then
                        clone:Destroy()
                        return nil
                    end
                    return clone
                end
                if instance:IsA('Folder') then
                    local previewModel = Instance.new('Model')
                    previewModel.Name = previewName or instance.Name
                    for _, child in ipairs(instance:GetChildren()) do
                        local childClone = LuaHookCosmetics.SafeClone(child)
                        if childClone then
                            childClone.Parent = previewModel
                        end
                    end
                    if #previewModel:GetChildren() > 0 and LuaHookCosmetics.HasRenderableDescendant(previewModel) then
                        LuaHookCosmetics.AnchorPreviewDescendants(previewModel)
                        return previewModel
                    end
                    previewModel:Destroy()
                end
                return nil
            end
            function LuaHookCosmetics.BuildPreviewModel(weaponName)
                local previewWeaponName = type(weaponName) == 'string' and weaponName ~= '' and weaponName or LuaHookCosmetics.ResolvePreviewWeaponName()
                local selectedSkinName = previewWeaponName and LuaHookCosmetics.ResolveSelectedSkinName(previewWeaponName) or nil
                local skinSelectionValue = previewWeaponName and LuaHookCosmetics.ResolveSkinSelectionValue(previewWeaponName) or nil
                local previewSource = nil
                if selectedSkinName then
                    previewSource = LuaHookCosmetics.ResolveSkinSourceModel(previewWeaponName, selectedSkinName)
                elseif skinSelectionValue == RIVALS_COSMETIC_NONE then
                    previewSource = LuaHookCosmetics.ResolveDefaultWeaponTemplate(previewWeaponName)
                end
                previewSource = previewSource or (previewWeaponName and LuaHookCosmetics.ResolveWeaponTemplate(previewWeaponName) or nil)
                local previewModel = LuaHookCosmetics.ClonePreviewObject(previewSource, previewWeaponName and string.format('Preview_%s', previewWeaponName) or 'Preview')
                if not previewModel then
                    previewModel = Instance.new('Part')
                    previewModel.Name = 'PreviewPlaceholder'
                    previewModel.Anchored = true
                    previewModel.CanCollide = false
                    previewModel.Transparency = 1
                    previewModel.Size = Vector3.new(1, 1, 1)
                end
                return previewModel
            end
            function LuaHookCosmetics.ResolvePreviewViewportModel()
                local viewportModel = LuaHookCosmeticsState.PreviewViewportModel
                if viewportModel and viewportModel:IsA('Model') then
                    return viewportModel
                end
                viewportModel = Instance.new('Model')
                viewportModel.Name = 'RIVALS_CosmeticsPreview'
                LuaHookCosmeticsState.PreviewViewportModel = viewportModel
                return viewportModel
            end
            function LuaHookCosmetics.CopyPreviewModelIntoViewportModel(targetModel, sourceModel)
                if not targetModel or not targetModel:IsA('Model') or not sourceModel then
                    return false
                end
                local stagedModel = Instance.new('Model')
                stagedModel.Name = sourceModel.Name
                if sourceModel:IsA('BasePart') then
                    local childClone = LuaHookCosmetics.SafeClone(sourceModel)
                    if childClone then
                        childClone.Parent = stagedModel
                    end
                elseif sourceModel:IsA('Model') or sourceModel:IsA('Folder') then
                    for _, child in ipairs(sourceModel:GetChildren()) do
                        local childClone = LuaHookCosmetics.SafeClone(child)
                        if childClone then
                            childClone.Parent = stagedModel
                        end
                    end
                end
                LuaHookCosmetics.AnchorPreviewDescendants(stagedModel)
                if not LuaHookCosmetics.HasVisibleRenderableDescendant(stagedModel) then
                    stagedModel:Destroy()
                    return false
                end
                targetModel.Name = stagedModel.Name
                for _, child in ipairs(targetModel:GetChildren()) do
                    pcall(function()
                        child:Destroy()
                    end)
                end
                for _, child in ipairs(stagedModel:GetChildren()) do
                    child.Parent = targetModel
                end
                stagedModel:Destroy()
                LuaHookCosmetics.AnchorPreviewDescendants(targetModel)
                return true
            end
            function LuaHookCosmetics.BuildPreviewViewportModel()
                local viewportModel = LuaHookCosmetics.ResolvePreviewViewportModel()
                local previewModel = LuaHookCosmetics.BuildPreviewModel(LuaHookCosmetics.ResolvePreviewWeaponName())
                if previewModel and LuaHookCosmetics.HasVisibleRenderableDescendant(previewModel) then
                    LuaHookCosmetics.CopyPreviewModelIntoViewportModel(viewportModel, previewModel)
                end
                if previewModel then
                    pcall(function()
                        previewModel:Destroy()
                    end)
                end
                return viewportModel
            end
            function LuaHookCosmetics.ResolveFirstPersonFolder()
                local viewModels = Workspace:FindFirstChild('ViewModels')
                return viewModels and viewModels:FindFirstChild('FirstPerson') or nil
            end
            function LuaHookCosmetics.ResolveFirstPersonModels(weaponName)
                local models = {}
                local firstPerson = LuaHookCosmetics.ResolveFirstPersonFolder()
                if not firstPerson then
                    return models
                end
                local nameNeedle = type(weaponName) == 'string' and weaponName ~= '' and string.format(' - %s - ', weaponName) or nil
                for _, child in ipairs(firstPerson:GetChildren()) do
                    if child:IsA('Model') and (not nameNeedle or child.Name:find(nameNeedle, 1, true)) then
                        models[#models + 1] = child
                    end
                end
                return models
            end
            function LuaHookCosmetics.ResolveWrapProperties(model)
                local originalWrapProperties = LuaHookCosmeticsState.OriginalWrapProperties[model]
                if originalWrapProperties then
                    return originalWrapProperties
                end
                local wrapController = LuaHookCosmetics.ResolveWrapController()
                if not wrapController then
                    return nil
                end
                originalWrapProperties = wrapController:RecordOriginalWrapProperties(model)
                LuaHookCosmeticsState.OriginalWrapProperties[model] = originalWrapProperties
                return originalWrapProperties
            end
            function LuaHookCosmetics.ApplyWrapToModel(model, wrapName, inverted)
                local wrapController = LuaHookCosmetics.ResolveWrapController()
                if not wrapController or not model then
                    return false
                end
                local originalWrapProperties = LuaHookCosmetics.ResolveWrapProperties(model)
                if not originalWrapProperties then
                    return false
                end
                if LuaHookCosmetics.IsCosmeticValueSelected(wrapName) then
                    wrapController:ApplyWrap(originalWrapProperties, {
                        Name = wrapName,
                        Inverted = inverted == true,
                    })
                else
                    wrapController:ResetWrap(originalWrapProperties)
                end
                return true
            end
            function LuaHookCosmetics.ResolveWorldItemOwnerAndName(instance)
                if not instance then
                    return nil, nil
                end
                local attributeOwner = nil
                local placedByUserId = instance:GetAttribute('PlacedByUserID')
                if type(placedByUserId) == 'number' then
                    attributeOwner = Players:GetPlayerByUserId(placedByUserId)
                end
                local objectId = instance:GetAttribute('ObjectID')
                if type(objectId) ~= 'string' then
                    return attributeOwner, nil
                end
                local fighterController = ResolveFighterController()
                local objects = fighterController and fighterController.Objects or nil
                if type(objects) ~= 'table' then
                    return attributeOwner, nil
                end
                local ok, objectOwner, itemName = pcall(function()
                    for _, fighter in pairs(objects) do
                        local items = fighter and fighter.Items or nil
                        if type(items) == 'table' then
                            for _, item in pairs(items) do
                                local data = item and item.Data or nil
                                local itemObjectId = data and data.ObjectID or ReadItemValue(item, 'ObjectID')
                                if itemObjectId == objectId then
                                    local itemName = (data and data.Name)
                                        or item.Name
                                        or ReadItemValue(item, 'Name')
                                    return fighter.Player, itemName
                                end
                            end
                        end
                    end
                    return nil, nil
                end)
                if not ok then
                    return attributeOwner, nil
                end
                return attributeOwner or objectOwner, itemName
            end
            function LuaHookCosmetics.ResolveSpawnedCosmeticAssetFolder(folderName)
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                if not playerScripts then
                    return nil
                end
                if folderName == 'SmokeClouds' then
                    local modules = playerScripts:FindFirstChild('Modules')
                    return modules and modules:FindFirstChild('SmokeClouds') or nil
                end
                local assets = playerScripts:FindFirstChild('Assets')
                local misc = assets and assets:FindFirstChild('Misc') or nil
                return misc and misc:FindFirstChild(folderName) or nil
            end
            function LuaHookCosmetics.HasSpawnedCosmeticAsset(folderName, skinName)
                if not LuaHookCosmetics.IsCosmeticValueSelected(skinName) then
                    return false
                end
                local folder = LuaHookCosmetics.ResolveSpawnedCosmeticAssetFolder(folderName)
                return folder ~= nil and folder:FindFirstChild(skinName) ~= nil
            end
            function LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, tagName)
                local collectionService = game:GetService('CollectionService')
                if not instance or not instance.Parent or not collectionService:HasTag(instance, tagName) then
                    return false
                end
                local retagToken = {}
                LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] = retagToken
                collectionService:RemoveTag(instance, tagName)
                local readdDelay = tagName == 'FireHitbox' and 1.8 or 0
                local function readdTag()
                    if LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] ~= retagToken then
                        return
                    end
                    if instance.Parent and not collectionService:HasTag(instance, tagName) then
                        collectionService:AddTag(instance, tagName)
                    end
                end
                if readdDelay > 0 then
                    task.delay(readdDelay, readdTag)
                else
                    readdTag()
                end
                task.delay(readdDelay + 0.5, function()
                    if LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] == retagToken then
                        LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] = nil
                    end
                end)
                return true
            end
            function LuaHookCosmetics.CaptureJumpPadOriginalProperty(entry, descendant)
                if not descendant or entry.OriginalProperties[descendant] ~= nil then
                    return
                end
                local properties = nil
                if descendant:IsA('BasePart') then
                    properties = {
                        Transparency = descendant.Transparency,
                        CastShadow = descendant.CastShadow,
                    }
                    descendant.Transparency = 1
                    descendant.CastShadow = false
                elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                    properties = { Transparency = descendant.Transparency }
                    descendant.Transparency = 1
                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('Trail') or descendant:IsA('Beam') then
                    properties = { Enabled = descendant.Enabled }
                    descendant.Enabled = false
                elseif descendant:IsA('Sound') then
                    properties = { Volume = descendant.Volume }
                    descendant.Volume = 0
                end
                if properties then
                    entry.OriginalProperties[descendant] = properties
                end
            end
            function LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                local entry = LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance]
                if not entry then
                    return
                end
                if entry.ChildAdded then
                    pcall(function()
                        entry.ChildAdded:Disconnect()
                    end)
                end
                for _, model in ipairs(entry.WrapTargets or {}) do
                    pcall(LuaHookCosmetics.ApplyWrapToModel, model, nil)
                end
                if entry.Kind == 'FireHitbox' then
                    pcall(function()
                        instance:SetAttribute('ViewModelName', entry.OriginalViewModelName)
                    end)
                    LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, 'FireHitbox')
                elseif entry.Kind == 'SmokeCloud' then
                    pcall(function()
                        instance.Name = entry.OriginalName
                    end)
                    LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, 'SmokeCloud')
                elseif entry.Kind == 'JumpPadHitbox' then
                    for child in pairs(entry.CustomChildren or {}) do
                        pcall(function()
                            child:Destroy()
                        end)
                    end
                    for descendant, properties in pairs(entry.OriginalProperties or {}) do
                        pcall(function()
                            for propertyName, value in pairs(properties) do
                                descendant[propertyName] = value
                            end
                        end)
                    end
                    pcall(function()
                        instance:SetAttribute('ViewModelName', entry.OriginalViewModelName)
                        instance:SetAttribute('SoundID', entry.OriginalSoundID)
                        instance:SetAttribute('SoundVolume', entry.OriginalSoundVolume)
                    end)
                end
                LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] = nil
            end
            function LuaHookCosmetics.WaitForLocalWorldItem(instance, requireItemName, token)
                local expiresAt = os.clock() + 3
                repeat
                    if not instance.Parent
                        or LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token then
                        return nil
                    end
                    local owner, itemName = LuaHookCosmetics.ResolveWorldItemOwnerAndName(instance)
                    if owner then
                        if owner ~= LP then
                            return nil
                        end
                        if not requireItemName or type(itemName) == 'string' then
                            return itemName or true
                        end
                    end
                    task.wait(0.1)
                until os.clock() >= expiresAt
                return nil
            end
            function LuaHookCosmetics.ApplyFireHitboxCosmetic(instance)
                if not instance or LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                task.spawn(GuardLuaHookCallback('Cosmetics_ApplyFireHitbox', function()
                    local itemName = LuaHookCosmetics.WaitForLocalWorldItem(instance, true, token)
                    if type(itemName) ~= 'string' or not LuaHookCosmetics.IsEnabled() then
                        return
                    end
                    local skinName = LuaHookCosmetics.ResolveSelectedSkinName(itemName)
                    local wrapName = LuaHookCosmetics.ResolveSelectedWrapName(itemName)
                    local hasSkin = LuaHookCosmetics.HasSpawnedCosmeticAsset('FireHitboxes', skinName)
                    if not hasSkin and not wrapName then
                        return
                    end
                    local entry = {
                        Kind = 'FireHitbox',
                        OriginalViewModelName = instance:GetAttribute('ViewModelName'),
                        WrapTargets = {},
                    }
                    LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry
                    if hasSkin then
                        instance:SetAttribute('ViewModelName', skinName)
                    end
                    if wrapName then
                        local expectedVisualName = hasSkin and skinName or (entry.OriginalViewModelName or 'Default')
                        local inverted = LuaHookCosmetics.ResolveWrapInvertedValue(itemName)
                        entry.ChildAdded = Workspace.ChildAdded:Connect(GuardLuaHookCallback('Cosmetics_FireHitboxVisualAdded', function(child)
                            if LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] ~= entry
                                or LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token
                                or not child:IsA('Model')
                                or child.Name ~= expectedVisualName then
                                return
                            end
                            local primary = child:FindFirstChild('Primary')
                            local pivotOk, pivot = pcall(child.GetPivot, child)
                            if not primary or not primary:IsA('BasePart') or not pivotOk
                                or (pivot.Position - instance.Position).Magnitude > 0.5
                                or (primary.Size - instance.Size).Magnitude > 0.01 then
                                return
                            end
                            if LuaHookCosmetics.ApplyWrapToModel(child, wrapName, inverted) then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                if entry.ChildAdded then
                                    entry.ChildAdded:Disconnect()
                                    entry.ChildAdded = nil
                                end
                            end
                        end))
                        task.delay(2.5, function()
                            if LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] == entry and entry.ChildAdded then
                                entry.ChildAdded:Disconnect()
                                entry.ChildAdded = nil
                            end
                        end)
                    end
                    LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, 'FireHitbox')
                end))
            end
            function LuaHookCosmetics.ApplySmokeCloudCosmetic(instance)
                if not instance or LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                local skinName = LuaHookCosmetics.ResolveSelectedSkinName('Smoke Grenade')
                if not LuaHookCosmetics.HasSpawnedCosmeticAsset('SmokeClouds', skinName) then
                    return
                end
                task.spawn(GuardLuaHookCallback('Cosmetics_ApplySmokeCloud', function()
                    if not LuaHookCosmetics.WaitForLocalWorldItem(instance, false, token)
                        or not LuaHookCosmetics.IsEnabled() then
                        return
                    end
                    local entry = {
                        Kind = 'SmokeCloud',
                        OriginalName = instance.Name,
                        WrapTargets = {},
                    }
                    LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry
                    instance.Name = skinName
                    LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, 'SmokeCloud')
                end))
            end
            function LuaHookCosmetics.ApplyJumpPadCosmetic(instance)
                if not instance or LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                local skinName = LuaHookCosmetics.ResolveSelectedSkinName('Jump Pad')
                local wrapName = LuaHookCosmetics.ResolveSelectedWrapName('Jump Pad')
                local hasSkin = LuaHookCosmetics.HasSpawnedCosmeticAsset('JumpPads', skinName)
                if not hasSkin and not wrapName then
                    return
                end
                task.spawn(GuardLuaHookCallback('Cosmetics_ApplyJumpPad', function()
                    if not LuaHookCosmetics.WaitForLocalWorldItem(instance, false, token)
                        or not LuaHookCosmetics.IsEnabled() then
                        return
                    end
                    task.wait(0.35)
                    if not instance.Parent
                        or LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token then
                        return
                    end
                    local entry = {
                        Kind = 'JumpPadHitbox',
                        OriginalViewModelName = instance:GetAttribute('ViewModelName'),
                        OriginalSoundID = instance:GetAttribute('SoundID'),
                        OriginalSoundVolume = instance:GetAttribute('SoundVolume'),
                        OriginalChildren = setmetatable({}, { __mode = 'k' }),
                        OriginalProperties = setmetatable({}, { __mode = 'k' }),
                        CustomChildren = setmetatable({}, { __mode = 'k' }),
                        WrapTargets = {},
                        CaptureCustomChildren = false,
                        ChildAdded = nil,
                    }
                    LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry
                    for _, child in ipairs(instance:GetChildren()) do
                        entry.OriginalChildren[child] = true
                        if child:IsA('Model') then
                            if hasSkin then
                                for _, descendant in ipairs(child:GetDescendants()) do
                                    LuaHookCosmetics.CaptureJumpPadOriginalProperty(entry, descendant)
                                end
                            elseif wrapName then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                LuaHookCosmetics.ApplyWrapToModel(child, wrapName, LuaHookCosmetics.ResolveWrapInvertedValue('Jump Pad'))
                            end
                        elseif hasSkin and child:IsA('Sound') then
                            LuaHookCosmetics.CaptureJumpPadOriginalProperty(entry, child)
                        end
                    end
                    if not hasSkin then
                        if #entry.WrapTargets == 0 then
                            LuaHookCosmeticsState.SpawnedWorldCosmeticEntries[instance] = nil
                        end
                        return
                    end
                    entry.ChildAdded = instance.ChildAdded:Connect(GuardLuaHookCallback('Cosmetics_JumpPadChildAdded', function(child)
                        if not entry.CaptureCustomChildren or entry.OriginalChildren[child] then
                            return
                        end
                        if child:IsA('Model') or child:IsA('Sound') then
                            entry.CustomChildren[child] = true
                            if child:IsA('Model') and wrapName then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                task.defer(LuaHookCosmetics.ApplyWrapToModel, child, wrapName, LuaHookCosmetics.ResolveWrapInvertedValue('Jump Pad'))
                            end
                        end
                    end))
                    entry.CaptureCustomChildren = true
                    instance:SetAttribute('ViewModelName', skinName)
                    LuaHookCosmetics.RefreshSpawnedCosmeticTag(instance, 'JumpPadHitbox')
                    task.wait(0.35)
                    entry.CaptureCustomChildren = false
                end))
            end
            function LuaHookCosmetics.BindSpawnedWorldCosmetics()
                if not Connections or not LuaHookCosmetics.IsEnabled() then
                    return
                end
                local collectionService = game:GetService('CollectionService')
                local definitions = {
                    { Tag = 'FireHitbox', Apply = LuaHookCosmetics.ApplyFireHitboxCosmetic },
                    { Tag = 'SmokeCloud', Apply = LuaHookCosmetics.ApplySmokeCloudCosmetic },
                    { Tag = 'JumpPadHitbox', Apply = LuaHookCosmetics.ApplyJumpPadCosmetic },
                }
                for _, definition in ipairs(definitions) do
                    local tagName = definition.Tag
                    local apply = definition.Apply
                    Connections:register('Cosmetics_' .. tagName .. 'Added', collectionService:GetInstanceAddedSignal(tagName):Connect(GuardLuaHookCallback('Cosmetics_' .. tagName .. 'Added', apply)))
                    Connections:register('Cosmetics_' .. tagName .. 'Removed', collectionService:GetInstanceRemovedSignal(tagName):Connect(GuardLuaHookCallback('Cosmetics_' .. tagName .. 'Removed', function(instance)
                        if LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                            return
                        end
                        LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                        LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                    end)))
                    for _, instance in ipairs(collectionService:GetTagged(tagName)) do
                        apply(instance)
                    end
                end
            end
            function LuaHookCosmetics.RestoreSpawnedWorldCosmetics()
                if Connections then
                    Connections:disconnect({
                        'Cosmetics_FireHitboxAdded',
                        'Cosmetics_FireHitboxRemoved',
                        'Cosmetics_SmokeCloudAdded',
                        'Cosmetics_SmokeCloudRemoved',
                        'Cosmetics_JumpPadHitboxAdded',
                        'Cosmetics_JumpPadHitboxRemoved',
                    })
                end
                for instance in pairs(LuaHookCosmeticsState.SpawnedWorldCosmeticEntries) do
                    LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                    LuaHookCosmetics.RestoreSpawnedWorldCosmetic(instance)
                end
            end
            function LuaHookCosmetics.RestoreWorldTripmine(tripmine)
                local entry = LuaHookCosmeticsState.WorldTripmineEntries[tripmine]
                if not entry then
                    return
                end
                if entry.DescendantAdded then
                    pcall(function()
                        entry.DescendantAdded:Disconnect()
                    end)
                end
                if entry.WrapTarget then
                    pcall(LuaHookCosmetics.ApplyWrapToModel, entry.WrapTarget, nil)
                end
                for descendant, properties in pairs(entry.OriginalProperties) do
                    if descendant then
                        pcall(function()
                            for propertyName, value in pairs(properties) do
                                descendant[propertyName] = value
                            end
                        end)
                    end
                end
                if entry.Clone then
                    pcall(function()
                        entry.Clone:Destroy()
                    end)
                end
                LuaHookCosmeticsState.WorldTripmineEntries[tripmine] = nil
            end
            function LuaHookCosmetics.HideWorldTripmineDescendant(entry, descendant)
                if not descendant
                    or descendant == entry.Hitbox
                    or descendant:IsDescendantOf(entry.Hitbox)
                    or (entry.Clone and (descendant == entry.Clone or descendant:IsDescendantOf(entry.Clone))) then
                    return
                end
                local properties = nil
                if descendant:IsA('BasePart') then
                    properties = {
                        Transparency = descendant.Transparency,
                        CastShadow = descendant.CastShadow,
                    }
                    descendant.Transparency = 1
                    descendant.CastShadow = false
                elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                    properties = { Transparency = descendant.Transparency }
                    descendant.Transparency = 1
                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('Trail') or descendant:IsA('Beam') then
                    properties = { Enabled = descendant.Enabled }
                    descendant.Enabled = false
                end
                if properties and entry.OriginalProperties[descendant] == nil then
                    entry.OriginalProperties[descendant] = properties
                end
            end
            function LuaHookCosmetics.ApplyWorldTripmineNow(tripmine, hitbox, skinName, wrapName, inverted)
                if not tripmine.Parent
                    or tonumber(tripmine:GetAttribute('PlacedByUserID')) ~= LP.UserId
                    or not LuaHookCosmetics.IsEnabled() then
                    return false
                end
                local entry = {
                    Clone = nil,
                    Hitbox = hitbox,
                    WrapTarget = tripmine,
                    OriginalProperties = setmetatable({}, { __mode = 'k' }),
                    DescendantAdded = nil,
                }
                LuaHookCosmeticsState.WorldTripmineEntries[tripmine] = entry
                if skinName then
                    local sourceModel = LuaHookCosmetics.ResolveSkinSourceModel('Subspace Tripmine', skinName)
                    local clone = LuaHookCosmetics.ClonePreviewObject(sourceModel, '__LuaHookHookTripmineSkin')
                    if clone then
                        entry.Clone = clone
                        entry.WrapTarget = clone
                        pcall(function()
                            clone:PivotTo(hitbox.CFrame)
                        end)
                        clone.Parent = tripmine
                        for _, descendant in ipairs(clone:GetDescendants()) do
                            if descendant:IsA('BasePart') then
                                descendant.Anchored = false
                                descendant.CanCollide = false
                                descendant.CanTouch = false
                                descendant.CanQuery = false
                                descendant.Massless = true
                                local weld = Instance.new('WeldConstraint')
                                weld.Part0 = hitbox
                                weld.Part1 = descendant
                                weld.Parent = descendant
                            end
                        end
                        for _, descendant in ipairs(tripmine:GetDescendants()) do
                            LuaHookCosmetics.HideWorldTripmineDescendant(entry, descendant)
                        end
                        entry.DescendantAdded = tripmine.DescendantAdded:Connect(GuardLuaHookCallback('Cosmetics_TripmineDescendantAdded', function(descendant)
                            LuaHookCosmetics.HideWorldTripmineDescendant(entry, descendant)
                        end))
                    end
                end
                if wrapName then
                    LuaHookCosmetics.ApplyWrapToModel(entry.WrapTarget, wrapName, inverted)
                end
                return entry.Clone ~= nil or wrapName ~= nil
            end
            function LuaHookCosmetics.ApplyWorldTripmine(tripmine)
                if not tripmine then
                    return
                end
                LuaHookCosmetics.RestoreWorldTripmine(tripmine)
                LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] = (LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                local token = LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine]
                local skinName = LuaHookCosmetics.ResolveSelectedSkinName('Subspace Tripmine')
                local wrapName = LuaHookCosmetics.ResolveSelectedWrapName('Subspace Tripmine')
                if not skinName and not wrapName then
                    return
                end
                local inverted = LuaHookCosmetics.ResolveWrapInvertedValue('Subspace Tripmine')
                task.spawn(GuardLuaHookCallback('Cosmetics_ApplyWorldTripmine', function()
                    local hitbox = tripmine:WaitForChild('Hitbox', 5)
                    if not hitbox
                        or LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] ~= token then
                        return
                    end
                    LuaHookCosmetics.ApplyWorldTripmineNow(tripmine, hitbox, skinName, wrapName, inverted)
                end))
            end
            function LuaHookCosmetics.BindWorldTripmines()
                if not Connections or not LuaHookCosmetics.IsEnabled() then
                    return
                end
                local collectionService = game:GetService('CollectionService')
                Connections:register('Cosmetics_SubspaceTripmineAdded', collectionService:GetInstanceAddedSignal('SubspaceTripmine'):Connect(GuardLuaHookCallback('Cosmetics_SubspaceTripmineAdded', LuaHookCosmetics.ApplyWorldTripmine)))
                Connections:register('Cosmetics_SubspaceTripmineRemoved', collectionService:GetInstanceRemovedSignal('SubspaceTripmine'):Connect(GuardLuaHookCallback('Cosmetics_SubspaceTripmineRemoved', function(tripmine)
                    LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] = (LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                    LuaHookCosmetics.RestoreWorldTripmine(tripmine)
                end)))
                for _, tripmine in ipairs(collectionService:GetTagged('SubspaceTripmine')) do
                    LuaHookCosmetics.ApplyWorldTripmine(tripmine)
                end
            end
            function LuaHookCosmetics.RestoreWorldTripmines()
                if Connections then
                    Connections:disconnect({
                        'Cosmetics_SubspaceTripmineAdded',
                        'Cosmetics_SubspaceTripmineRemoved',
                    })
                end
                for tripmine in pairs(LuaHookCosmeticsState.WorldTripmineEntries) do
                    LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] = (LuaHookCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                    LuaHookCosmetics.RestoreWorldTripmine(tripmine)
                end
            end
            function LuaHookCosmetics.ResolveWrapTargetsForWeapon(weaponName)
                local targets = {}
                local seenTargets = {}
                for _, model in ipairs(LuaHookCosmetics.ResolveFirstPersonModels(weaponName)) do
                    if seenTargets[model] ~= true then
                        seenTargets[model] = true
                        targets[#targets + 1] = model
                    end
                end
                return targets
            end
            function LuaHookCosmetics.CaptureOriginalItemCosmetics(item)
                if type(item) ~= 'table' or LuaHookCosmeticsState.OriginalInjectedItemCosmetics[item] then
                    return
                end
                LuaHookCosmeticsState.OriginalInjectedItemCosmetics[item] = {
                    Skin = item.Skin ~= nil and item.Skin or ReadItemValue(item, 'Skin'),
                    Wrap = item.Wrap ~= nil and item.Wrap or ReadItemValue(item, 'Wrap'),
                    Charm = item.Charm ~= nil and item.Charm or ReadItemValue(item, 'Charm'),
                    Finisher = item.Finisher ~= nil and item.Finisher or ReadItemValue(item, 'Finisher'),
                }
            end
            function LuaHookCosmetics.ResolveSelectedCosmeticApplyData(weaponName, kind, existingData)
                local selectionValue = nil
                if kind == 'Skin' then
                    selectionValue = LuaHookCosmetics.ResolveSkinSelectionValue(weaponName)
                elseif kind == 'Wrap' then
                    selectionValue = LuaHookCosmetics.ResolveWrapSelectionValue(weaponName)
                elseif kind == 'Charm' then
                    selectionValue = LuaHookCosmetics.ResolveCharmSelectionValue(weaponName)
                elseif kind == 'Finisher' then
                    selectionValue = LuaHookCosmetics.ResolveFinisherSelectionValue(weaponName)
                else
                    return nil, false
                end
                if LuaHookCosmetics.IsCosmeticValueSelected(selectionValue) then
                    local data = LuaHookCosmetics.BuildCosmeticData(existingData, selectionValue, kind)
                    if kind == 'Wrap' then
                        data.Inverted = LuaHookCosmetics.ResolveWrapInvertedValue(weaponName) == true
                    elseif kind == 'Charm' then
                        data = LuaHookCosmetics.PatchRankCharmPayload(data) or data
                    end
                    return data, true
                end
                if selectionValue == RIVALS_COSMETIC_NONE then
                    return nil, true
                end
                if kind == 'Charm' then
                    local patchedCharm = LuaHookCosmetics.PatchRankCharmPayload(existingData)
                    if patchedCharm then
                        return patchedCharm, true
                    end
                end
                return nil, false
            end
            function LuaHookCosmetics.InjectWeaponData(weaponName)
                local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                local currentData = playerDataController and playerDataController.CurrentData or nil
                if type(weaponName) ~= 'string' or weaponName == '' or not currentData or type(currentData.Get) ~= 'function' then
                    return false
                end
                local ok, inventory = pcall(function()
                    return currentData:Get('WeaponInventory')
                end)
                if not ok or type(inventory) ~= 'table' then
                    return false
                end
                for _, item in pairs(inventory) do
                    if type(item) == 'table' and item.Name == weaponName then
                        local changed = false
                        local skinData, shouldSetSkin = LuaHookCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Skin', item.Skin)
                        if shouldSetSkin then
                            LuaHookCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Skin = skinData
                            changed = true
                        end
                        local wrapData, shouldSetWrap = LuaHookCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Wrap', item.Wrap)
                        if shouldSetWrap then
                            LuaHookCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Wrap = wrapData
                            changed = true
                        end
                        local charmData, shouldSetCharm = LuaHookCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Charm', item.Charm)
                        if shouldSetCharm then
                            LuaHookCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Charm = charmData
                            changed = true
                        end
                        local finisherData, shouldSetFinisher = LuaHookCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Finisher', item.Finisher)
                        if shouldSetFinisher then
                            LuaHookCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Finisher = finisherData
                            changed = true
                        end
                        if changed and type(currentData.Replicate) == 'function' then
                            pcall(function()
                                currentData:Replicate('WeaponInventory')
                            end)
                        end
                        return changed
                    end
                end
                return false
            end
            function LuaHookCosmetics.InjectAllWeaponData()
                local injected = false
                for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    injected = LuaHookCosmetics.InjectWeaponData(weaponName) or injected
                end
                return injected
            end
            function LuaHookCosmetics.EncodeGameTable(value)
                local encoded = {}
                for key, entry in pairs(value) do
                    local encodedKey = type(key) == 'string' and LuaHookCosmetics.EncodeGameKey(key) or key
                    encoded[encodedKey] = entry
                end
                return encoded
            end
            function LuaHookCosmetics.ResolveClientItemForWeapon(weaponName)
                local fighter = ResolveLocalFighter()
                if type(fighter) ~= 'table' then
                    return nil, nil
                end
                local equippedItem = rawget(fighter, 'EquippedItem')
                if type(equippedItem) == 'table' and rawget(equippedItem, 'Name') == weaponName then
                    return equippedItem, fighter
                end
                for _, fieldName in ipairs({'Loadout', 'Slots', 'Items', 'EquippedItems'}) do
                    local items = rawget(fighter, fieldName)
                    if type(items) == 'table' then
                        for _, item in pairs(items) do
                            if type(item) == 'table' and rawget(item, 'Name') == weaponName then
                                return item, fighter
                            end
                        end
                    end
                end
                return nil, fighter
            end
            function LuaHookCosmetics.RunAtIdentity2(callback)
                local previousIdentity = type(getthreadidentity) == 'function' and getthreadidentity() or nil
                if type(setthreadidentity) == 'function' then
                    setthreadidentity(2)
                end
                local results = table.pack(pcall(callback))
                if previousIdentity ~= nil and type(setthreadidentity) == 'function' then
                    setthreadidentity(previousIdentity)
                end
                if not results[1] then
                    return false, results[2]
                end
                return true, unpack(results, 2, results.n)
            end
            function LuaHookCosmetics.BuildViewModelSelectionSignature(weaponName, selection)
                if type(selection) ~= 'table' then
                    return weaponName .. '|restore'
                end
                local wrap = selection.wrap
                return table.concat({
                    weaponName,
                    tostring(selection.skin),
                    tostring(type(wrap) == 'table' and wrap.name or nil),
                    tostring(type(wrap) == 'table' and wrap.inverted == true or false),
                    tostring(selection.charm),
                }, '|')
            end
            function LuaHookCosmetics.ReloadWeaponViewModel(weaponName, force, restoreOnly)
                local item, fighter = LuaHookCosmetics.ResolveClientItemForWeapon(weaponName)
                local viewModel = type(item) == 'table' and rawget(item, 'ViewModel') or nil
                local viewModelData = type(viewModel) == 'table' and rawget(viewModel, 'Data') or nil
                if type(item) ~= 'table' or type(viewModel) ~= 'table' or type(viewModelData) ~= 'table' then
                    return false
                end
                local selection = restoreOnly == true and nil or LuaHookCosmetics.BuildLuaHookItemSelection(weaponName)
                local signature = LuaHookCosmetics.BuildViewModelSelectionSignature(weaponName, selection)
                local appliedSelection = LuaHookCosmeticsState.ViewModelSelectionSignatureByItem[item]
                if force ~= true and type(appliedSelection) == 'table'
                    and appliedSelection.Signature == signature
                    and appliedSelection.ViewModel == viewModel then
                    return true
                end
                if type(selection) == 'table' then
                    LuaHookCosmetics.EnsureClientItemRestoreData(LP, weaponName, viewModelData)
                end
                local restoreData = LuaHookCosmetics.GetClientItemRestoreData(LP, weaponName)
                local nextData
                if type(selection) == 'table' then
                    nextData = LuaHookCosmetics.ApplyLuaHookViewModelSelection(
                        weaponName,
                        { Name = weaponName },
                        selection
                    )
                else
                    nextData = type(restoreData) == 'table' and table.clone(restoreData) or table.clone(viewModelData)
                end
                local clientViewModel = LuaHookCosmetics.ResolveClientViewModelClass()
                local destroy = type(clientViewModel) == 'table' and clientViewModel.Destroy or nil
                if type(destroy) ~= 'function' then
                    return false
                end
                LuaHookCosmetics.RunAtIdentity2(function()
                    destroy(viewModel)
                end)
                local createViewModel = item._CreateViewModel
                if type(createViewModel) ~= 'function' then
                    return false
                end
                local info = LuaHookCosmetics.EncodeGameTable({
                    Data = LuaHookCosmetics.EncodeGameTable(nextData),
                })
                local created, newViewModel = LuaHookCosmetics.RunAtIdentity2(function()
                    return createViewModel(item, info)
                end)
                if not created or type(newViewModel) ~= 'table' then
                    return false
                end
                rawset(item, 'ViewModel', newViewModel)
                local getArmsData = type(fighter) == 'table' and fighter.GetArmsData or nil
                local setArmsData = newViewModel.SetArmsData
                local equip = newViewModel.Equip
                local armsData = nil
                if type(getArmsData) == 'function' then
                    armsData = table.pack(getArmsData(fighter))
                end
                LuaHookCosmetics.RunAtIdentity2(function()
                    if type(setArmsData) == 'function' and armsData ~= nil then
                        setArmsData(newViewModel, unpack(armsData, 1, armsData.n))
                    end
                    if type(equip) == 'function' then
                        equip(newViewModel, true)
                    end
                end)
                local spring = rawget(newViewModel, '_equip_spring')
                if type(spring) == 'table' then
                    rawset(spring, '_position0', 0)
                    rawset(spring, '_velocity0', 0)
                end
                LuaHookCosmeticsState.ViewModelSelectionSignatureByItem[item] = {
                    Signature = signature,
                    ViewModel = newViewModel,
                }
                return true
            end
            function LuaHookCosmetics.RestoreWeaponViewModels()
                local byWeapon = LuaHookCosmeticsState.ClientItemRestoreData[LP]
                if type(byWeapon) == 'table' then
                    for weaponName in pairs(byWeapon) do
                        LuaHookCosmetics.ReloadWeaponViewModel(weaponName, true, true)
                    end
                end
                LuaHookCosmeticsState.ClientItemRestoreData = {}
                LuaHookCosmeticsState.ViewModelSelectionSignatureByItem = setmetatable({}, { __mode = 'k' })
                return true
            end
            function LuaHookCosmetics.ApplyActiveWeaponCosmetics()
                if LuaHookCosmetics.ResolveNativeCosmeticsController() then
                    return true
                end
                local fighter = ResolveLocalFighter()
                local item = fighter and fighter.EquippedItem or nil
                local weaponName = item and item.Name or nil
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                return LuaHookCosmetics.ReloadWeaponViewModel(weaponName)
            end
            function LuaHookCosmetics.ApplySelectedWeaponCosmetics()
                if LuaHookCosmetics.ApplyNativeSkinChanger() then
                    return true
                end
                local applied = false
                for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    if LuaHookCosmetics.BuildLuaHookItemSelection(weaponName) ~= nil then
                        applied = LuaHookCosmetics.ReloadWeaponViewModel(weaponName) or applied
                    end
                end
                return applied
            end
            function LuaHookCosmetics.RestoreInjectedWeaponData()
                local restored = false
                for item, original in pairs(LuaHookCosmeticsState.OriginalInjectedItemCosmetics) do
                    if type(item) == 'table' and type(original) == 'table' then
                        item.Skin = original.Skin
                        item.Wrap = original.Wrap
                        item.Charm = original.Charm
                        item.Finisher = original.Finisher
                        if type(item.Set) == 'function' then
                            pcall(item.Set, item, 'Skin', original.Skin)
                            pcall(item.Set, item, 'Wrap', original.Wrap)
                            pcall(item.Set, item, 'Charm', original.Charm)
                            pcall(item.Set, item, 'Finisher', original.Finisher)
                        end
                        local viewModel = rawget(item, 'ViewModel')
                        if type(viewModel) == 'table' then
                            if type(viewModel.SetSkin) == 'function' then
                                pcall(viewModel.SetSkin, viewModel, original.Skin)
                            end
                            if type(viewModel.SetWrap) == 'function' then
                                pcall(viewModel.SetWrap, viewModel, original.Wrap)
                            end
                            if type(viewModel.SetCharm) == 'function' then
                                pcall(viewModel.SetCharm, viewModel, original.Charm)
                            end
                            if type(viewModel._UpdateSkin) == 'function' then
                                pcall(viewModel._UpdateSkin, viewModel)
                            end
                            if type(viewModel._UpdateWrap) == 'function' then
                                pcall(viewModel._UpdateWrap, viewModel)
                            end
                            if type(viewModel._UpdateCharm) == 'function' then
                                pcall(viewModel._UpdateCharm, viewModel)
                            end
                        end
                        restored = true
                    end
                end
                LuaHookCosmeticsState.OriginalInjectedItemCosmetics = setmetatable({}, { __mode = 'k' })
                if restored then
                    local playerDataController = LuaHookCosmetics.ResolvePlayerDataController()
                    local currentData = playerDataController and playerDataController.CurrentData or nil
                    if currentData and type(currentData.Replicate) == 'function' then
                        pcall(function()
                            currentData:Replicate('WeaponInventory')
                        end)
                    end
                end
                return restored
            end
            function LuaHookCosmetics.ApplyWraps()
                for _, weaponName in ipairs(LuaHookCosmetics.ResolveWeaponNames()) do
                    local selectedWrapName = LuaHookCosmetics.ResolveSelectedWrapName(weaponName)
                    local inverted = LuaHookCosmetics.ResolveWrapInvertedValue(weaponName)
                    for _, target in ipairs(LuaHookCosmetics.ResolveWrapTargetsForWeapon(weaponName)) do
                        pcall(function()
                            LuaHookCosmetics.ApplyWrapToModel(target, selectedWrapName, inverted)
                        end)
                    end
                end
            end
            function LuaHookCosmetics.UpdatePreviewViewport()
                local previewViewport = Options.LH_P5S3V1
                if not previewViewport or type(previewViewport.SetObject) ~= 'function' then
                    return false
                end
                local previewWeaponName = LuaHookCosmetics.ResolvePreviewWeaponName()
                local previewModel = LuaHookCosmetics.BuildPreviewModel(previewWeaponName)
                if not previewModel then
                    return false
                end
                if not LuaHookCosmetics.HasVisibleRenderableDescendant(previewModel) then
                    pcall(function()
                        previewModel:Destroy()
                    end)
                    return false
                end
                local viewportModel = LuaHookCosmetics.ResolvePreviewViewportModel()
                local copiedPreview = LuaHookCosmetics.CopyPreviewModelIntoViewportModel(viewportModel, previewModel)
                pcall(function()
                    previewModel:Destroy()
                end)
                if not copiedPreview then
                    return false
                end
                if previewViewport.Object ~= viewportModel then
                    local previousObject = previewViewport.Object
                    local viewportParent = nil
                    pcall(function()
                        viewportParent = previousObject and previousObject.Parent or nil
                    end)
                    if viewportParent and viewportModel.Parent ~= viewportParent then
                        pcall(function()
                            viewportModel.Parent = viewportParent
                        end)
                    end
                    if previousObject and previousObject ~= viewportModel then
                        pcall(function()
                            previousObject.Parent = nil
                        end)
                    end
                    previewViewport.Object = viewportModel
                end
                if type(previewViewport.Focus) == 'function' then
                    pcall(function()
                        previewViewport:Focus()
                    end)
                end
                return true
            end
            function LuaHookCosmetics.RefreshDropdownOptions()
                if LuaHookCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                local ok, result = xpcall(function()
                    local synced = LuaHookCosmetics.SyncActiveWeaponEditorFromState()
                    LuaHookCosmetics.SyncFavoriteEditorFromState()
                    LuaHookCosmetics.SyncRankCharmEditorFromState()
                    LuaHookCosmetics.RefreshCosmeticPresetControls()
                    return synced
                end, function(err)
                    return debug.traceback(string.format('[Cosmetics_RefreshDropdownOptions] %s', tostring(err)), 2)
                end)
                if not ok then
                    error(result, 0)
                end
                return result == true
            end
            function LuaHookCosmetics.BindFirstPersonModels()
                -- Native Custom Loadout is authoritative in Unlock-Only mode. No custom
                -- first-person ChildAdded watcher is needed, and installing one would
                -- cause ApplyAll() on every weapon model replacement.
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    if Connections then
                        pcall(Connections.disconnect, Connections, {'Cosmetics_FirstPersonChildAdded'})
                    end
                    LuaHookCosmeticsState.BoundFirstPersonModels = false
                    LuaHookCosmeticsState.BindingFirstPersonModels = false
                    return true
                end
                if LuaHookCosmeticsState.BoundFirstPersonModels then
                    return true
                end
                if LuaHookCosmeticsState.BindingFirstPersonModels then
                    return true
                end
                LuaHookCosmeticsState.BindingFirstPersonModels = true
                local bindingToken = LuaHookCosmeticsState.PendingApplyToken
                task.spawn(GuardLuaHookCallback('Cosmetics_BindFirstPersonModels', function()
                    local ok = xpcall(function()
                        local viewModels = Workspace:WaitForChild('ViewModels', 10)
                        if not viewModels then
                            error('ViewModels not available within 10 seconds')
                        end
                        local firstPerson = viewModels:WaitForChild('FirstPerson', 10)
                        if not firstPerson then
                            error('FirstPerson not available within 10 seconds')
                        end
                        if LuaHookCosmeticsState.PendingApplyToken ~= bindingToken
                            or LuaHookCosmetics.IsEnabled() ~= true then
                            return
                        end
                        local connection = firstPerson.ChildAdded:Connect(GuardLuaHookCallback('Cosmetics_FirstPersonChildAdded', function(child)
                            if not child or not child:IsA('Model') then
                                return
                            end
                            task.defer(function()
                                LuaHookCosmetics.ApplyAll()
                            end)
                        end))
                        Connections:register('Cosmetics_FirstPersonChildAdded', connection)
                        LuaHookCosmeticsState.BoundFirstPersonModels = true
                        if #firstPerson:GetChildren() > 0 then
                            task.defer(function()
                                LuaHookCosmetics.ApplyAll()
                            end)
                        end
                    end, function(e)
                        return debug.traceback('[Cosmetics_BindFirstPersonModels] ' .. tostring(e), 2)
                    end)
                    LuaHookCosmeticsState.BindingFirstPersonModels = false
                    if not ok then
                        LuaHookCosmeticsState.BoundFirstPersonModels = false
                    end
                end))
                return true
            end
            function LuaHookCosmetics.RestoreAppliedCosmetics()
                LuaHookCosmetics.StopCurrentLoadoutWatcher()
                pcall(LuaHookCosmetics.RestoreNativeCosmeticsRuntime)
                LuaHookCosmeticsState.PendingApplyToken = LuaHookCosmeticsState.PendingApplyToken + 1
                LuaHookCosmeticsState.BindingFirstPersonModels = false
                if Connections then
                    Connections:disconnect({'Cosmetics_FirstPersonChildAdded'})
                end
                LuaHookCosmeticsState.BoundFirstPersonModels = false
                LuaHookCosmeticsState.RuntimeApplyRetryPending = false
                if type(LuaHookCosmetics.RestoreSpawnedWorldCosmetics) == 'function' then
                    pcall(LuaHookCosmetics.RestoreSpawnedWorldCosmetics)
                end
                if type(LuaHookCosmetics.RestoreWorldTripmines) == 'function' then
                    pcall(LuaHookCosmetics.RestoreWorldTripmines)
                end
                for model in pairs(LuaHookCosmeticsState.OriginalWrapProperties) do
                    LuaHookCosmetics.ApplyWrapToModel(model, nil)
                end
                LuaHookCosmeticsState.OriginalWrapProperties = setmetatable({}, { __mode = 'k' })
                RivalsEmotes.RestoreEquippedEmotes()
                if type(LuaHookCosmetics.RestoreWeaponViewModels) == 'function' then pcall(LuaHookCosmetics.RestoreWeaponViewModels) end
                LuaHookCosmetics.RestoreInjectedWeaponData()
                LuaHookCosmeticsState.PendingSkinSelectionByWeapon = {}
                LuaHookCosmeticsState.PendingWrapSelectionByWeapon = {}
                LuaHookCosmeticsState.PendingCharmSelectionByWeapon = {}
                LuaHookCosmeticsState.PendingFinisherSelectionByWeapon = {}
                LuaHookCosmeticsState.WorldTripmineEntries = setmetatable({}, { __mode = 'k' })
                LuaHookCosmeticsState.WorldTripmineApplyTokens = setmetatable({}, { __mode = 'k' })
                LuaHookCosmeticsState.SpawnedWorldCosmeticEntries = setmetatable({}, { __mode = 'k' })
                LuaHookCosmeticsState.SpawnedWorldCosmeticApplyTokens = setmetatable({}, { __mode = 'k' })
                LuaHookCosmeticsState.SpawnedWorldCosmeticRetagging = setmetatable({}, { __mode = 'k' })
                LuaHookCosmetics.RestoreUnlockedOwnershipHooks()
                if type(LuaHookCosmetics.RestorePlayerDataHook) == 'function' then pcall(LuaHookCosmetics.RestorePlayerDataHook) end
                pcall(LuaHookCosmetics.RestoreNativeSkinChanger)
                LuaHookCosmetics.RestoreNativeUiBindings()
                LuaHookCosmetics.RestoreClientViewModelHook()
                pcall(LuaHookCosmetics.RestoreFinisherHook)
                RivalsEmotes.RestoreEmoteControllerHook()
                pcall(LuaHookCosmetics.RefreshNativeCosmeticsScene)
                return true
            end
