                LuaHookCosmetics.RestoreAppliedCosmetics()
                LuaHookCosmeticsState.PreviewWeaponName = nil
                LuaHookCosmeticsState.SelectedEditorWeaponName = nil
                LuaHookCosmeticsState.SelectedSkinByWeapon = {}
                LuaHookCosmeticsState.SelectedWrapByWeapon = {}
                LuaHookCosmeticsState.SelectedCharmByWeapon = {}
                LuaHookCosmeticsState.SelectedFinisherByWeapon = {}
                LuaHookCosmeticsState.SelectedWrapInvertedByWeapon = {}
