                    (LuaHookCosmeticsState.NativeCosmeticsControllerResolutionGeneration or 0) + 1
                LuaHookCosmeticsState.NativeCosmeticsSnapshotController = nil
                LuaHookCosmeticsState.UnlockOnlyMode = true
