                LuaHookCosmeticsState.NativeSkinChangerWasEnabled = nil
                LuaHookCosmeticsState.NativeSkinChangerOriginalSelections = {}
                LuaHookCosmeticsState.NativeSkinChangerTouchedWeapons = {}
                LuaHookCosmeticsState.NativeSkinChangerApplied = false
                LuaHookCosmeticsState.RankCharmOverridesBySeason = {}
                LuaHookCosmeticsState.SelectedRankCharmSeason = nil
                LuaHookCosmeticsState.PendingApplyToken = 0
                LuaHookCosmeticsState.RuntimeApplyRetryPending = false
                LuaHookCosmeticsState.SavedConfigCosmeticObjects = nil
                LuaHookCosmeticsState.CosmeticPresetsLoaded = false
                LuaHookCosmeticsState.CosmeticPresets = {}
                LuaHookCosmeticsState.CosmeticPresetSettings = {}
                LuaHookCosmeticsState.CosmeticPresetAutoLoadApplied = false
                LuaHookCosmeticsState.CosmeticPresetSaveToken = LuaHookCosmeticsState.CosmeticPresetSaveToken + 1
                LuaHookCosmeticsState.ApplyingCosmeticPreset = false
                LuaHookCosmeticsState.LastApplyResults = {}
                LuaHookCosmeticsState.CosmeticsUiLoaded = false
                LuaHookCosmeticsState.CosmeticsUiLoading = false
                LuaHookCosmeticsState.CosmeticsConfigName = nil
                LuaHookCosmeticsState.NativeUnlockedInventory = nil
                LuaHookCosmetics.RestoreDirectDataHooks()
                LuaHookCosmeticsState.UnlockedOwnershipHooks = {}
                LuaHookCosmeticsState.NativeCosmeticSlotConnections = setmetatable({}, { __mode = 'k' })
                LuaHookCosmeticsState.NativeFavoritesSeeded = false
                LuaHookCosmeticsState.NativeSaveToken = LuaHookCosmeticsState.NativeSaveToken + 1
                if LuaHookCosmeticsState.PreviewViewportModel then
                    pcall(function()
                        LuaHookCosmeticsState.PreviewViewportModel:Destroy()
                    end)
                end
                LuaHookCosmeticsState.PreviewViewportModel = nil
                LuaHookCosmeticsState.BoundFirstPersonModels = false
                LuaHookCosmeticsState.BindingFirstPersonModels = false
                LuaHookCosmeticsState.ClientItemHookProxy = nil
                LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon = { Skin = {}, Wrap = {}, Charm = {}, Finisher = {} }
                LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon = { Skin = {}, Wrap = {}, Charm = {}, Finisher = {} }
                LuaHookCosmeticsState.CosmeticMultiEmotes = {}
                LuaHookCosmeticsState.CosmeticMultiEmoteOrder = {}
                LuaHookCosmeticsState.CosmeticUiRefreshing = 0
                LuaHookCosmeticsState.CosmeticUiBound = false
                LuaHookCosmeticsState.CurrentLoadoutWatcherRunning = false
                LuaHookCosmeticsState.CurrentLoadoutWatcherToken = (LuaHookCosmeticsState.CurrentLoadoutWatcherToken or 0) + 1
            end
            function LuaHookCosmetics.ApplyAll()
                if not LuaHookCosmetics.ShouldUseCosmeticsRuntime() then
                    return false
                end

                -- Unlock-only semantics: do not choose or override any equipped cosmetic.
                LuaHookCosmeticsState.UnlockOnlyMode = true
                LuaHookCosmeticsState.NativeUnlockedInventory = nil
                if LuaHookCosmeticsState.BoundFirstPersonModels and Connections then
                    pcall(Connections.disconnect, Connections, {'Cosmetics_FirstPersonChildAdded'})
                    LuaHookCosmeticsState.BoundFirstPersonModels = false
                end

                -- ApplyAll is intentionally called from several lifecycle points. For the
                -- unlock-only path it must become a cheap no-op after the first successful
                -- native installation; rebuilding the catalog on every weapon switch is the
                -- main source of the observed FPS drop.
                if LuaHookCosmeticsState.NativeCosmeticsRuntimeApplied
                    and LuaHookCosmeticsState.NativeUnlockerApplied
                    and LuaHookCosmeticsState.NativeCosmeticsConfigApplied
                    and LuaHookCosmetics.NativeUnlockStateMatchesDesired() then
                    LuaHookCosmeticsState.LastApplyResults = {
                        ApplyNativeCosmeticsRuntime = true,
                        IdempotentFastPath = true,
                    }
                    return true
                end

                local results = {}
                local function safeApply(name, fn)
                    if type(fn) ~= 'function' then
                        results[name] = false
                        return false
                    end
                    local ok, result = pcall(fn)
                    local success = ok and result ~= false
                    results[name] = success
                    return success
                end

                local nativeController = LuaHookCosmetics.ResolveNativeCosmeticsController()
                if nativeController then
                    results.ApplyNativeCosmeticsRuntime = safeApply(
                        'ApplyNativeCosmeticsRuntime',
                        LuaHookCosmetics.ApplyNativeCosmeticsRuntime
                    )
                    if results.ApplyNativeCosmeticsRuntime ~= true then
                        LuaHookCosmeticsState.LastApplyResults = results
                        return false
                    end
                else
                    -- Fallback only: grant catalog ownership without writing loadout choices.
                    results.EnsurePlayerDataHook = safeApply(
                        'EnsurePlayerDataHook',
                        LuaHookCosmetics.EnsurePlayerDataHook
                    )
                    results.BuildNativeUnlockedInventory = safeApply(
                        'BuildNativeUnlockedInventory',
                        LuaHookCosmetics.BuildNativeUnlockedInventory
                    )
                    results.EnsureUnlockedOwnershipHooks = safeApply(
                        'EnsureUnlockedOwnershipHooks',
                        LuaHookCosmetics.EnsureUnlockedOwnershipHooks
                    )
                    if results.EnsurePlayerDataHook ~= true
                        or results.BuildNativeUnlockedInventory ~= true
                        or results.EnsureUnlockedOwnershipHooks ~= true then
                        LuaHookCosmeticsState.LastApplyResults = results
                        return false
                    end
                end

                -- Deliberately omitted: selection sync, SkinChanger, Emote SetEmote,
                -- Finisher hooks, ViewModel cosmetic writers, Wrap writers, loadout watcher,
                -- and cosmetic-preset auto-apply. The game Custom Loadout stays authoritative.
                LuaHookCosmeticsState.LastApplyResults = results
                return true
            end
            function LuaHookCosmetics.ApplyPendingSelection(previewWeaponName, skinName, wrapName, charmName, finisherName)
                local previousSkinName = nil
                local previousWrapName = nil
                local previousCharmName = nil
                local previousFinisherName = nil
                local hasWeapon = type(previewWeaponName) == 'string' and previewWeaponName ~= ''
                if hasWeapon then
                    previousSkinName = LuaHookCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName]
                    previousWrapName = LuaHookCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName]
                    previousCharmName = LuaHookCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName]
                    previousFinisherName = LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName]
                    if skinName ~= nil then
                        LuaHookCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = skinName
                    end
                    if wrapName ~= nil then
                        LuaHookCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = wrapName
                    end
                    if charmName ~= nil then
                        LuaHookCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = charmName
                    end
                    if finisherName ~= nil then
                        LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = finisherName
                    end
                    LuaHookCosmetics.SetPreviewWeaponName(previewWeaponName)
                end
                local previewOk, previewResult = pcall(LuaHookCosmetics.UpdatePreviewViewport)
                if hasWeapon then
                    LuaHookCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = previousSkinName
                    LuaHookCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = previousWrapName
                    LuaHookCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = previousCharmName
                    LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = previousFinisherName
                end
                LuaHookCosmeticsState.PendingApplyToken = LuaHookCosmeticsState.PendingApplyToken + 1
                local pendingApplyToken = LuaHookCosmeticsState.PendingApplyToken
                task.defer(GuardLuaHookCallback('Cosmetics_ApplyPendingSelection_ApplyAll', function()
                    if LuaHookCosmeticsState.PendingApplyToken ~= pendingApplyToken then
                        return nil
                    end
                    if hasWeapon then
                        if skinName ~= nil then
                            LuaHookCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = skinName
                        end
                        if wrapName ~= nil then
                            LuaHookCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = wrapName
                        end
                        if charmName ~= nil then
                            LuaHookCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = charmName
                        end
                        if finisherName ~= nil then
                            LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = finisherName
                        end
                    end
                    local applyResult = LuaHookCosmetics.ApplyAll()
                    if hasWeapon then
                        LuaHookCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = previousSkinName
                        LuaHookCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = previousWrapName
                        LuaHookCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = previousCharmName
                        LuaHookCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = previousFinisherName
                    end
                    return applyResult
                end))
                if not previewOk then
                    error(previewResult, 0)
                end
                return previewOk
            end
            -- Full cosmetic UI bridge: multi-select pools + deterministic active selection.
            function LuaHookCosmetics.ResolveMultiMap(value)
                local map = {}
                if type(value) ~= 'table' then
                    return map
                end
                local arrayLike = true
                for k, v in pairs(value) do
                    if type(k) ~= 'number' then
                        arrayLike = false
                        break
                    end
                    if v ~= nil and type(v) ~= 'string' and type(v) ~= 'boolean' then
                        arrayLike = false
                        break
                    end
                end
                if arrayLike then
                    for _, name in ipairs(value) do
                        if type(name) == 'string' and name ~= '' then
                            map[name] = true
                        end
                    end
                else
                    for name, selected in pairs(value) do
                        if type(name) == 'string' and selected == true then
                            map[name] = true
                        end
                    end
                end
                return map
            end

            function LuaHookCosmetics.ResolveMultiValues(kind, weaponName)
                if kind == 'Skin' then
                    return LuaHookCosmetics.ResolveBaseSelectionValues(weaponName, 'Skin') or {}
                elseif kind == 'Wrap' then
                    return LuaHookCosmetics.ResolveWrapValues() or {}
                elseif kind == 'Charm' then
                    return LuaHookCosmetics.ResolveCharmValues() or {}
                elseif kind == 'Finisher' then
                    return LuaHookCosmetics.ResolveFinisherValues() or {}
                elseif kind == 'Emote' then
                    return RivalsEmotes.ResolveEmoteValues() or {}
                end
                return {}
            end

            function LuaHookCosmetics.ResolveMultiStored(kind, weaponName)
                if kind == 'Emote' then
                    return LuaHookCosmeticsState.CosmeticMultiEmotes
                end
                local byWeapon = LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon[kind]
                if type(byWeapon) ~= 'table' then
                    byWeapon = {}
                    LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon[kind] = byWeapon
                end
                local selected = byWeapon[weaponName]
                if type(selected) ~= 'table' then
                    selected = {}
                    byWeapon[weaponName] = selected
                end
                return selected
            end

            function LuaHookCosmetics.ResolveMultiOrder(kind, weaponName)
                if kind == 'Emote' then
                    return LuaHookCosmeticsState.CosmeticMultiEmoteOrder
                end
                local byWeapon = LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon[kind]
                if type(byWeapon) ~= 'table' then
                    byWeapon = {}
                    LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon[kind] = byWeapon
                end
                local order = byWeapon[weaponName]
                if type(order) ~= 'table' then
                    order = {}
                    byWeapon[weaponName] = order
                end
                return order
            end

            function LuaHookCosmetics.SyncMultiSelectionState(kind, weaponName, rawValue, allowedValues)
                local selectedMap = LuaHookCosmetics.ResolveMultiMap(rawValue)
                local storedMap = LuaHookCosmetics.ResolveMultiStored(kind, weaponName)
                local order = LuaHookCosmetics.ResolveMultiOrder(kind, weaponName)
                local nextOrder = {}
                local seen = {}

                for _, name in ipairs(order) do
                    if selectedMap[name] == true and not seen[name] then
                        nextOrder[#nextOrder + 1] = name
                        seen[name] = true
                    end
                end

                for _, name in ipairs(allowedValues or {}) do
                    if selectedMap[name] == true and not seen[name] then
                        nextOrder[#nextOrder + 1] = name
                        seen[name] = true
                    end
                end

                for name in pairs(storedMap) do
                    storedMap[name] = nil
                end
                for name in pairs(selectedMap) do
                    storedMap[name] = true
                end
                for i = #order, 1, -1 do
                    order[i] = nil
                end
                for i, name in ipairs(nextOrder) do
                    order[i] = name
                end
                return nextOrder
            end

            function LuaHookCosmetics.ResolveFirstMultiSelection(kind, weaponName)
                local values = LuaHookCosmetics.ResolveMultiValues(kind, weaponName)
                local selected = LuaHookCosmetics.ResolveMultiStored(kind, weaponName)
                local order = LuaHookCosmetics.ResolveMultiOrder(kind, weaponName)
                for _, preferred in ipairs(order) do
                    if selected[preferred] == true then
                        return preferred
                    end
                end
                for _, candidate in ipairs(values) do
                    if selected[candidate] == true then
                        return candidate
                    end
                end
                return nil
            end

            function LuaHookCosmetics.BuildMultiDefaultValue(kind, weaponName)
                local values = LuaHookCosmetics.ResolveMultiValues(kind, weaponName)
                local selected = LuaHookCosmetics.ResolveMultiStored(kind, weaponName)
                local order = LuaHookCosmetics.ResolveMultiOrder(kind, weaponName)
                local map = {}
                local hasStored = false
                for _, name in ipairs(order) do
                    if type(name) == 'string' and selected[name] == true then
                        map[name] = true
                        hasStored = true
                    end
                end
                if not hasStored then
                    if kind == 'Emote' then
                        -- Seed the multi-select from the native equipped emote slots on first load.
                        -- This keeps the UI in sync without inventing or reordering slots.
                        local currentData = RivalsEmotes.ResolveCurrentData()
                        local equipped = RivalsEmotes.ResolveEquippedEmotes(currentData)
                        local slotCount = RivalsEmotes.ResolveEmoteSlotCount()
                        if type(equipped) == 'table' then
                            for slot = 1, slotCount do
                                local entry = equipped[slot] or equipped[tostring(slot)]
                                local current = nil
                                if type(entry) == 'table' then
                                    current = entry.Name or entry.name or entry[1]
                                elseif type(entry) == 'string' then
                                    current = entry
                                end
                                if type(current) == 'string'
                                    and RivalsEmotes.IsCatalogEmoteName(current)
                                    and LuaHookCosmetics.ResolveValidDropdownValue(current, values) == current then
                                    map[current] = true
                                    if not LuaHookCosmeticsState.CosmeticMultiEmotes[current] then
                                        local order = LuaHookCosmeticsState.CosmeticMultiEmoteOrder
                                        local already = false
                                        for _, existing in ipairs(order) do
                                            if existing == current then already = true break end
                                        end
                                        if not already then
                                            order[#order + 1] = current
                                        end
                                        LuaHookCosmeticsState.CosmeticMultiEmotes[current] = true
                                    end
                                end
                            end
                        end
                    else
                        local current = LuaHookCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                        if type(current) == 'string' and LuaHookCosmetics.ResolveValidDropdownValue(current, values) == current then
                            map[current] = true
                        end
                    end
                end
                local ordered = {}
                local orderedSeen = {}
                if kind == 'Emote' then
                    for _, name in ipairs(order) do
                        if map[name] == true and not orderedSeen[name] then
                            ordered[#ordered + 1] = name
                            orderedSeen[name] = true
                        end
                    end
                end
                for _, name in ipairs(values) do
                    if map[name] == true and not orderedSeen[name] then
                        ordered[#ordered + 1] = name
                        orderedSeen[name] = true
                    end
                end
                return ordered
            end

            function LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon()
                local option = Options.P5COS_WEAPON
                local weaponName = option and option.Value or nil
                if LuaHookCosmetics.IsKnownWeaponName(weaponName) then
                    return weaponName
                end
                local selected = LuaHookCosmetics.ResolveSelectedEditorWeaponName()
                if LuaHookCosmetics.IsKnownWeaponName(selected) then
                    return selected
                end
                local preview = LuaHookCosmetics.ResolvePreviewWeaponName()
                if LuaHookCosmetics.IsKnownWeaponName(preview) then
                    return preview
                end
                return LuaHookCosmetics.ResolveWeaponNames()[1]
            end

            function LuaHookCosmetics.ApplyCosmeticMultiUi()
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    return false
                end
                if LuaHookCosmeticsState.CosmeticUiRefreshing > 0 then
                    return false
                end
                if not LuaHookCosmetics.IsEnabled() then
                    return false
                end
                local weaponName = LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon()
                if not weaponName then
                    return false
                end

                local kindMap = {
                    Skin = 'P5COS_SKIN',
                    Wrap = 'P5COS_WRAP',
                    Charm = 'P5COS_CHARM',
                    Finisher = 'P5COS_FINISHER',
                }
                for kind, optionId in pairs(kindMap) do
                    local option = Options[optionId]
                    local values = LuaHookCosmetics.ResolveMultiValues(kind, weaponName)
                    local rawValue = option and option.Value or {}
                    LuaHookCosmetics.SyncMultiSelectionState(kind, weaponName, rawValue, values)
                    local active = LuaHookCosmetics.ResolveFirstMultiSelection(kind, weaponName)
                    LuaHookCosmetics.SetStoredSelection(weaponName, kind, active)
                end

                local emoteOption = Options.P5COS_EMOTE
                local emoteValues = RivalsEmotes.ResolveEmoteValues()
                LuaHookCosmetics.SyncMultiSelectionState(
                    'Emote',
                    weaponName,
                    emoteOption and emoteOption.Value or {},
                    emoteValues
                )

                if not ReplicatedStateReady then
                    LuaHookCosmetics.QueueRuntimeApplyWhenReady()
                    return false
                end

                -- Rebuild the runtime cleanly first so every cosmetic type shares the
                -- same original-state snapshot and no previous hook survives a switch.
                LuaHookCosmetics.RestoreAppliedCosmetics()
                LuaHookCosmetics.ApplyAll()

                -- Emotes are slot-based rather than weapon-based; native SetEmote consumes
                -- the multi-selection order on the same apply pass.
                LuaHookCosmetics.SetSelectedEditorWeapon(weaponName)
                return true
            end

            function LuaHookCosmetics.RefreshCosmeticMultiUi()
                if LuaHookCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                local weaponName = LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon()
                if not weaponName then
                    return false
                end
                local previous = LuaHookCosmeticsState.CosmeticUiRefreshing
                LuaHookCosmeticsState.CosmeticUiRefreshing = previous + 1
                local ok, err = xpcall(function()
                    local weaponOption = Options.P5COS_WEAPON
                    if weaponOption and type(weaponOption.SetValues) == 'function' then
                        pcall(function() weaponOption:SetValues(LuaHookCosmetics.ResolveWeaponNames()) end)
                    end
                    if weaponOption and type(weaponOption.SetValue) == 'function' then
                        pcall(function() weaponOption:SetValue(weaponName) end)
                    end

                    local kinds = {
                        { kind = 'Skin', id = 'P5COS_SKIN' },
                        { kind = 'Wrap', id = 'P5COS_WRAP' },
                        { kind = 'Charm', id = 'P5COS_CHARM' },
                        { kind = 'Finisher', id = 'P5COS_FINISHER' },
                        { kind = 'Emote', id = 'P5COS_EMOTE' },
                    }
                    for _, spec in ipairs(kinds) do
                        local option = Options[spec.id]
                        local values = LuaHookCosmetics.ResolveMultiValues(spec.kind, weaponName)
                        if option then
                            if type(option.SetValues) == 'function' then
                                pcall(function() option:SetValues(values) end)
                            end
                            if type(option.SetValue) == 'function' then
                                local defaults = LuaHookCosmetics.BuildMultiDefaultValue(spec.kind, weaponName)
                                pcall(function() option:SetValue(defaults) end)
                            end
                        end
                    end
                end, function(e)
                    return debug.traceback('[Cosmetics_MultiUI_Refresh] ' .. tostring(e), 2)
                end)
                LuaHookCosmeticsState.CosmeticUiRefreshing = previous
                if not ok then
                    return false, err
                end
                return true
            end

            function LuaHookCosmetics.ClearCosmeticMultiUi()
                if LuaHookCosmeticsState.UnlockOnlyMode == true then
                    return false
                end
                local weaponName = LuaHookCosmetics.ResolveCurrentCosmeticUiWeapon()
                if not weaponName then
                    return false
                end
                for _, kind in ipairs({'Skin', 'Wrap', 'Charm', 'Finisher'}) do
                    local byWeapon = LuaHookCosmeticsState.CosmeticMultiSelectionsByWeapon[kind]
                    if type(byWeapon) == 'table' then byWeapon[weaponName] = {} end
                    local orders = LuaHookCosmeticsState.CosmeticMultiSelectionOrderByWeapon[kind]
                    if type(orders) == 'table' then orders[weaponName] = {} end
                    LuaHookCosmetics.SetStoredSelection(weaponName, kind, nil)
                end
                LuaHookCosmeticsState.CosmeticMultiEmotes = {}
                LuaHookCosmeticsState.CosmeticMultiEmoteOrder = {}
                local emoteOption = Options.P5COS_EMOTE
                LuaHookCosmeticsState.CosmeticUiRefreshing = LuaHookCosmeticsState.CosmeticUiRefreshing + 1
                if emoteOption and type(emoteOption.SetValue) == 'function' then
                    pcall(function() emoteOption:SetValue({}) end)
                end
                LuaHookCosmeticsState.CosmeticUiRefreshing = math.max(LuaHookCosmeticsState.CosmeticUiRefreshing - 1, 0)

                LuaHookCosmetics.RestoreAppliedCosmetics()
                LuaHookCosmetics.ApplyAll()
                LuaHookCosmetics.RefreshCosmeticMultiUi()
                return true
            end

