    local ffaStatusLabel = drDep:AddLabel('Mode: Checking...')
    local ffaStatusGeneration = (State.RageAutoCollectStatusGeneration or 0) + 1
    State.RageAutoCollectStatusGeneration = ffaStatusGeneration
    task.spawn(function()
        while State.RageAutoCollectStatusGeneration == ffaStatusGeneration do
            task.wait(1.5)
