local LuaHookRuntimeLifecycle = {}
            function LuaHookRuntimeLifecycle.ResetState()
                pcall(Rage.unload)
                stopUnderground()
                LuaHookRuntime.WorldVisuals.Destroy()
                LuaHookRuntime.ViewmodelVisuals.Destroy()
                LuaHookRuntime.NativeRemovals.Destroy()
                LuaHookRuntime.Movement.Destroy()
                LuaHookRuntime.DeviceSpoof.Destroy()
                LuaHookRuntime.PlayerSpoofer.Destroy()
                LuaHookRuntime.AnimationPlayer.Destroy()
                LuaHookRuntime.MovementRecorder.Destroy()
                LuaHookRuntime.ResetAutoRespawnState()
                LuaHookRuntime.CombatFeedback.Destroy()
                LuaHookRuntime.ResetLuaHookCosmetics()
                LuaHookWeaponState.RestoreHooks()
                LuaHookAimRuntime.ResetAimbotRuntimeState()
                LuaHookAimRuntime.ResetTriggerbotReactionState()
                LuaHookAimRuntime.ResetCameraAimRandomState()
                LuaHookRuntime.ResetFlickbot()
                LuaHookRuntime.ResetAutoLoadoutState()
                LuaHookRuntime.ResetAutoBanState()
                State.RageAutoCollectStatusGeneration = (State.RageAutoCollectStatusGeneration or 0) + 1
                LuaHookRuntime.ResetTripmineAutomation()
                LocalPickupObserver.ResetDropTracking()
                AimbotTriggerbotLastShotAt = 0
                MeleeFastFire.LastShotAt = 0
                LuaHookRuntime.DestroyAimbotStatusNotification()
                AimbotInputState.LeftMouse = false
                AimbotInputState.RightMouse = false
                AimbotInputState.TouchCount = 0
                AimbotFovCircle.Visible = false
                pcall(function() AimbotFovCircle:Remove() end)
                DestroyAllESP()
                LuaHookWorldESP.DestroyAllThrowable()
                LuaHookWorldESP.DestroyAllHazard()
                LuaHookWorldESP.DestroyAllSoundVisualizer()
                DestroyRuntimeIssueNotification()
            end
            function LuaHookRuntimeLifecycle.RegisterPlayerLifecycle()
                LuaHookRuntime.NextESPReconcileAt = 0
                if EspRenderSettings.Enabled then
                    ReconcileESPPlayers()
                end
                Library:GiveSignal(Players.PlayerRemoving:Connect(GuardLuaHookCallback('Player_Removing', function(player)
                    DestroyESP(player)
                end)))
                EnsureWeaponInfoTracking()
            end
            function LuaHookRuntimeLifecycle.RegisterWorldLifecycle()
                for _, child in ipairs(Workspace:GetChildren()) do
                    LuaHookWorldESP.RegisterThrowable(child)
                    LocalPickupObserver.ObserveDrop(child)
                end
                Connections:register('Throwable_Added', Workspace.ChildAdded:Connect(GuardLuaHookCallback('Throwable_Added', LuaHookWorldESP.RegisterThrowable)))
                Connections:register('Throwable_Removed', Workspace.ChildRemoved:Connect(GuardLuaHookCallback('Throwable_Removed', LuaHookWorldESP.DestroyThrowable)))
                Connections:register('PickupDrop_Added', Workspace.ChildAdded:Connect(GuardLuaHookCallback('PickupDrop_Added', LocalPickupObserver.ObserveDrop)))
                Connections:register('PickupDrop_Removed', Workspace.ChildRemoved:Connect(GuardLuaHookCallback('PickupDrop_Removed', LocalPickupObserver.UnobserveDrop)))
                for _, descendant in ipairs(Workspace:GetDescendants()) do
                    LuaHookWorldESP.RegisterHazard(descendant)
                end
                Connections:register('Hazard_Added', Workspace.DescendantAdded:Connect(GuardLuaHookCallback('Hazard_Added', LuaHookWorldESP.RegisterHazard)))
                Connections:register('Hazard_Removed', Workspace.DescendantRemoving:Connect(GuardLuaHookCallback('Hazard_Removed', LuaHookWorldESP.DestroyHazard)))
                LuaHookWorldESP.SetSoundVisualizerEnabled(Toggles.LH_P1S3T1 and Toggles.LH_P1S3T1.Value == true)
                LuaHookRuntime.BindTripmineAutomation()
            end
            function LuaHookRuntimeLifecycle.RegisterInputLifecycle()
                Connections:register('Aimbot_InputBegan', UserInputService.InputBegan:Connect(GuardLuaHookCallback('Aimbot_InputBegan', function(input, gameProcessed)
                    if gameProcessed then
                        return
                    end
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = true
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = true
                    end
                end)))
                Connections:register('Aimbot_InputEnded', UserInputService.InputEnded:Connect(GuardLuaHookCallback('Aimbot_InputEnded', function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = false
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = false
                    end
                end)))
